window.HADITH_DATA['abudawud'][40]=[[4351,4351,4351,"। ইকরিমাহ (রহঃ) সূত্রে বর্ণিত। আলী (রাঃ) কিছু সংখ্যক মুরতাদকে আগুনে পুড়িয়ে হত্যা করেন। ইবনু আব্বাস (রাঃ) তা জানতে পেরে বলেন, আমি কিন্তু রাসূলুল্লাহ সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম-এর বাণী অনুসরণ করে এদের আগুনে পুড়িয়ে হত্যা করতাম না। কেননা রাসূলুল্লাহ সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম বলেছেনঃ তোমরা কাউকে আল্লাহর শাস্তির উপকরণ দ্বারা শাস্তি দিও না। তবে আমি রাসূলুল্লাহ সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম-এর বক্তব্য মোতাবেক এদের মৃত্যুদন্ড দিতাম। কারণ, রাসূলুল্লাহ সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম বলেছেনঃ যে ব্যক্তি নিজের ধর্ম (ইসলাম) পরিবর্তন করে তোমরা তাকে হত্যা করো। ইবনু আব্বাস (রাঃ) বর্ণিত এ হাদীস শুনে আলী (রাঃ) বলেন, আহ! ইবনু আব্বাস (রাঃ) সত্য বলেছেন।[1] সহীহ।","حَدَّثَنَا أَحْمَدُ بْنُ مُحَمَّدِ بْنِ حَنْبَلٍ، حَدَّثَنَا إِسْمَاعِيلُ بْنُ إِبْرَاهِيمَ، أَخْبَرَنَا أَيُّوبُ، عَنْ عِكْرِمَةَ، أَنَّ عَلِيًّا، عَلَيْهِ السَّلاَمُ أَحْرَقَ نَاسًا ارْتَدُّوا عَنِ الإِسْلاَمِ فَبَلَغَ ذَلِكَ ابْنَ عَبَّاسٍ فَقَالَ لَمْ أَكُنْ لأَحْرِقَهُمْ بِالنَّارِ إِنَّ رَسُولَ اللَّهِ صلى الله عليه وسلم قَالَ ‏\"‏ لاَ تُعَذِّبُوا بِعَذَابِ اللَّهِ ‏\"‏ ‏.‏ وَكُنْتُ قَاتِلَهُمْ بِقَوْلِ رَسُولِ اللَّهِ صلى الله عليه وسلم فَإِنَّ رَسُولَ اللَّهِ صلى الله عليه وسلم قَالَ ‏\"‏ مَنْ بَدَّلَ دِينَهُ فَاقْتُلُوهُ ‏\"‏ ‏.‏ فَبَلَغَ ذَلِكَ عَلِيًّا عَلَيْهِ السَّلاَمُ فَقَالَ وَيْحَ ابْنَ عَبَّاسٍ ‏.‏","‘Ikrimah said:‘Ali burned some people who retreated from Islam. When Ibn ‘Abbas was informed of it, he said: If it had been I, I would not have burned them, for the Messenger of Allah (ﷺ) said: Do not inflict Allah’s punishment on anyone, but would have had killed them on account of the statement of the Messenger of Allah (ﷺ). The Apostle said: Kill those who change their religion. When ‘Ali was informed about it he said: How truly Ibn ‘Abbas said","","Sahih"],[4352,4352,4352,"। আব্দুল্লাহ (রাঃ) সূত্রে বর্ণিত। তিনি বলেন, রাসূলুল্লাহ সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম বলেছেনঃ যে কোনো মুসলিম সাক্ষ্য দেয় যে, আল্লাহ ছাড়া কোনো ইলাহ নেই আর আমি আল্লাহর রাসূল, তাকে হত্যা করা বৈধ নয় যদি না সে তিনটি অপরাধের কোনো একটি করে থাকে; (১) বিবাহিত ব্যক্তি যেনা করলে; (২) কেউ কাউকে হত্যা করলে তার বিনিময়ে হত্যা এবং (৩) সমাজের ঐক্য বিনষ্টকারী মুরতাদ।[1] সহীহ।","حَدَّثَنَا عَمْرُو بْنُ عَوْنٍ، أَخْبَرَنَا أَبُو مُعَاوِيَةَ، عَنِ الأَعْمَشِ، عَنْ عَبْدِ اللَّهِ بْنِ مُرَّةَ، عَنْ مَسْرُوقٍ، عَنْ عَبْدِ اللَّهِ، قَالَ قَالَ رَسُولُ اللَّهِ صلى الله عليه وسلم ‏ \"‏ لاَ يَحِلُّ دَمُ رَجُلٍ مُسْلِمٍ يَشْهَدُ أَنْ لاَ إِلَهَ إِلاَّ اللَّهُ وَأَنِّي رَسُولُ اللَّهِ إِلاَّ بِإِحْدَى ثَلاَثٍ الثَّيِّبُ الزَّانِي وَالنَّفْسُ بِالنَّفْسِ وَالتَّارِكُ لِدِينِهِ الْمُفَارِقُ لِلْجَمَاعَةِ ‏\"‏ ‏.‏","Abd Allah (b. Mas`ud) reported the Messenger of Allah (peace be upon him) as saying:The blood of a Muslim man who testifies that there is no god but Allah and that I am the Messenger of Allah should not be lawfully shed but only for one of three reasons: married fornicator, soul for soul, and one who deserts his religion separating himself from the community","","Sahih"],[4353,4353,4353,"। আয়িশাহ (রাঃ) সূত্রে বর্ণিত। তিনি বলেন, রাসূলুল্লাহ সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম বলেছেনঃ যে কোনো মুসলিম ব্যক্তি সাক্ষ্য দেয়- আল্লাহ ছাড়া কোনো ইলাহ নেই এবং মুহাম্মাদ সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম আল্লাহর রাসূল, তাকে হত্যা করা বৈধ নয় তিনটি অপরাধের যে কোনো একটিতে লিপ্ত না হলেঃ (১) বিবাহিত লোক ব্যভিচার করলে তাকে পাথর মেরে হত্যা করবে, (২) আল্লাহ এবং তাঁর রাসূলের বিরুদ্ধে বিদ্রোহ করলে তাকে মৃত্যুদন্ড দেয়া হবে অথবা ফাঁসি কাষ্ঠে ঝুলানো হবে অথবা তাকে দেশ থেকে নির্বাসন দেয়া হবে, (৩) আর কাউকে হত্যা করলৈ তার বিনিময়ে কিসাসস্বরূপ তাকেও হত্যা করা যাবে।[1] সহীহ।","حَدَّثَنَا مُحَمَّدُ بْنُ سِنَانٍ الْبَاهِلِيُّ، حَدَّثَنَا إِبْرَاهِيمُ بْنُ طَهْمَانَ، عَنْ عَبْدِ الْعَزِيزِ بْنِ رُفَيْعٍ، عَنْ عُبَيْدِ بْنِ عُمَيْرٍ، عَنْ عَائِشَةَ، رضى الله عنها قَالَتْ قَالَ رَسُولُ اللَّهِ صلى الله عليه وسلم ‏ \"‏ لاَ يَحِلُّ دَمُ امْرِئٍ مُسْلِمٍ يَشْهَدُ أَنْ لاَ إِلَهَ إِلاَّ اللَّهُ وَأَنَّ مُحَمَّدًا رَسُولُ اللَّهِ إِلاَّ بِإِحْدَى ثَلاَثٍ رَجُلٌ زَنَى بَعْدَ إِحْصَانٍ فَإِنَّهُ يُرْجَمُ وَرَجُلٌ خَرَجَ مُحَارِبًا لِلَّهِ وَرَسُولِهِ فَإِنَّهُ يُقْتَلُ أَوْ يُصْلَبُ أَوْ يُنْفَى مِنَ الأَرْضِ أَوْ يَقْتُلُ نَفْسًا فَيُقْتَلُ بِهَا ‏\"‏ ‏.‏","Narrated Aisha, Ummul Mu'minin: The Messenger of Allah (ﷺ) Said: The blood of a Muslim man who testifies that there is no god but Allah and that Muhammad is Allah's Apostle should not lawfully be shed except only for one of three reasons: a man who committed fornication after marriage, in which case he should be stoned; one who goes forth to fight with Allah and His Apostle, in which case he should be killed or crucified or exiled from the land; or one who commits murder for which he is killed","","Sahih"],[4354,4354,4354,"। আবূ বুরদাহ (রহঃ) বলেন, আবূ মূসা (রাঃ) বলেছেন, একদা আমি আশ্আরী গোত্রের দু’ জন লোককে সঙ্গে নিয়ে নবী সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম-এর নিকট যাই। তাদের একজন আমার ডানপাশে এবং অপরজন বামপাশে ছিলো। তারা উভয়ে নবী সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম-এর নিকট চাকুরী (সরকারী পদ) চাইলো। তিনি নীরব রইলেন। অতঃপর তিনি বললেনঃ হে আবূ মূসা অথবা হে আব্দুল্লাহ ইবনু কাইস! তুমি কি বলো? আমি বললাম, সেই পবিত্র সত্তার কসম, যিনি আপনাকে সত্যসহ পাঠিয়েছেন! এরা এদের মনের উদ্দেশ্য সম্পর্কে আমাকে অবহিত করেনি এবং আমি জানতাম না যে, তারা চাকুরী চাইবে। আবূ মূসা বলেন, আমি তাঁর ঠোঁটের নীচে মেসওয়াকের দিকে তাকিয়ে দেখলাম, তা যেন ফুলে আছে। তিনি বললেনঃ যে ব্যক্তি সরকারী পদে নিয়োগের প্রার্থনা করে আমরা তাকে কখনো তাতে নিয়োগ করি না। তুমি বরং চলে যাও হে আবূ মূসা! অথবা হে আব্দুল্লাহ ইবনু কাইস! অতঃপর তিনি তাকে ইয়ামেনে পাঠিয়ে দেন এবং তার পরে মু‘আয ইবনু জাবাল (রাঃ)-কে পাঠালেন। বর্ণনাকারী বলেন, মু‘আয (রাঃ) তার নিকট পৌঁছলে তিনি বললেন, নেমে আসুন এবং তার জন্য একটা বালিশ পেতে দিলেন। তার নিকট ছিলো একটা বাঁধা লোক। তিনি প্রশ্ন করলেন, লোকটি কে? তিনি বললেন, লোকটা ছিলো ইয়াহুদী, পরে ইসলাম গ্রহণ করে। পরে আবারো সে তার খারাপ ধর্মে ফিরে যায়। মু‘আয (রাঃ) বলেন, আল্লাহ ও তাঁর রাসূলের ফায়সালা মোতাবেক তাকে হত্যা না করা পর্যন্ত আমি বসবো না। তিনি বলেন, হ্যাঁ, আপনি বসুন। মু‘আয (রাঃ) বলেন, আল্লাহ ও তাঁর রাসূলের ফায়সালা মোতাবেক তাকে হত্যা না করা পর্যন্ত আমিও বসবো না। একথা তিনি তিনবার বলেন। অতঃপর তার হুকুমে তাকে হত্যা করা হলো। পরে তারা দু’ জন রাত জেগে ইবাদাত করা প্রসঙ্গে আলোচনা করেন। তাদের একজন মু‘আয ইবনু জাবাল (রাঃ) বলেন, আমি তো রাতে ঘুমাই ও জেগে ইবাদাত করি, অথবা দাঁড়িয়ে ইবাদাত করি, ঘুমাই এবং ইবাদাতের মধ্যে আমি যা কামনা করি, ঘুমের মধ্যেও তাই কামনা করি।[1] সহীহ।","حَدَّثَنَا أَحْمَدُ بْنُ حَنْبَلٍ، وَمُسَدَّدٌ، قَالاَ حَدَّثَنَا يَحْيَى بْنُ سَعِيدٍ، - قَالَ مُسَدَّدٌ - حَدَّثَنَا قُرَّةُ بْنُ خَالِدٍ، قَالَ حَدَّثَنَا حُمَيْدُ بْنُ هِلاَلٍ، حَدَّثَنَا أَبُو بُرْدَةَ، قَالَ قَالَ أَبُو مُوسَى أَقْبَلْتُ إِلَى النَّبِيِّ صلى الله عليه وسلم وَمَعِي رَجُلاَنِ مِنَ الأَشْعَرِيِّينَ أَحَدُهُمَا عَنْ يَمِينِي وَالآخَرُ عَنْ يَسَارِي فَكِلاَهُمَا سَأَلَ الْعَمَلَ وَالنَّبِيُّ صلى الله عليه وسلم سَاكِتٌ فَقَالَ ‏\"‏ مَا تَقُولُ يَا أَبَا مُوسَى ‏\"‏ ‏.‏ أَوْ ‏\"‏ يَا عَبْدَ اللَّهِ بْنَ قَيْسٍ ‏\"‏ ‏.‏ قُلْتُ وَالَّذِي بَعَثَكَ بِالْحَقِّ مَا أَطْلَعَانِي عَلَى مَا فِي أَنْفُسِهِمَا وَمَا شَعَرْتُ أَنَّهُمَا يَطْلُبَانِ الْعَمَلَ ‏.‏ قَالَ وَكَأَنِّي أَنْظُرُ إِلَى سِوَاكِهِ تَحْتَ شَفَتِهِ قَلَصَتْ قَالَ ‏\"‏ لَنْ نَسْتَعْمِلَ - أَوْ لاَ نَسْتَعْمِلُ - عَلَى عَمَلِنَا مَنْ أَرَادَهُ وَلَكِنِ اذْهَبْ أَنْتَ يَا أَبَا مُوسَى أَوْ يَا عَبْدَ اللَّهِ بْنَ قَيْسٍ ‏\"‏ ‏.‏ فَبَعَثَهُ عَلَى الْيَمَنِ ثُمَّ أَتْبَعَهُ مُعَاذَ بْنَ جَبَلٍ قَالَ فَلَمَّا قَدِمَ عَلَيْهِ مُعَاذٌ قَالَ انْزِلْ ‏.‏ وَأَلْقَى لَهُ وِسَادَةً فَإِذَا رَجُلٌ عِنْدَهُ مُوثَقٌ قَالَ مَا هَذَا قَالَ هَذَا كَانَ يَهُودِيًّا فَأَسْلَمَ ثُمَّ رَاجَعَ دِينَهُ دِينَ السُّوءِ ‏.‏ قَالَ لاَ أَجْلِسُ حَتَّى يُقْتَلَ قَضَاءُ اللَّهِ وَرَسُولِهِ ‏.‏ قَالَ اجْلِسْ نَعَمْ ‏.‏ قَالَ لاَ أَجْلِسُ حَتَّى يُقْتَلَ قَضَاءُ اللَّهِ وَرَسُولِهِ ‏.‏ ثَلاَثَ مَرَّاتٍ فَأَمَرَ بِهِ فَقُتِلَ ثُمَّ تَذَاكَرَا قِيَامَ اللَّيْلِ فَقَالَ أَحَدُهُمَا مُعَاذُ بْنُ جَبَلٍ أَمَّا أَنَا فَأَنَامُ وَأَقُومُ - أَوْ أَقُومُ وَأَنَامُ - وَأَرْجُو فِي نَوْمَتِي مَا أَرْجُو فِي قَوْمَتِي ‏.‏","Abu Burdah said on the authority of Abu Musa :I went to the Prophet (ﷺ) while two men who were Ash’ arIs were with me. One of them was on my right and the other on my left side. Bothe of them asked him for employment. The prophet (ﷺ) was silent. He asked : What do you say Abu Musa, or ‘Abd Allah b. Qais (Abu Musa’s name)? I replied: By him who has sent you with truth, they did not inform me of what they had in their hearts, and I did not know that they would ask for an employment. He said : I have the scene before my eyes that he had his toothstick below his lip which receded. He (the prophet) said: We will never or will not put in charge of our work anyone who asks for it. But go, ye, Abu Musa, or ‘Abd Allah b. Qais. He then sent him as a Governor of the Yemen, After him he sent Muadh b. Jabal. When Muadh came to him, he said: come down , and he put a cushion for him. He saw that a man was chained with him. He asked : What is this? He replied: He was a Jew and he accepted Islam. He then converted to his religion, an evil religion. He said: I will not sit until he is killed according to the decision of Allah and his Apostle (ﷺ). He said: Yes, be seated. He said: I will not sit until he is killed according to the decision of Allah and his Apostle (peace be upon him). He said it three times. He then commanded for it and he was killed. Both of them then discussed the question of prayer and vigilance at night. One of them, probably Muadh, said : So far as I am concerned, I sleep and I keep vigilance: I keep vigilance and I sleep: I hope for the same reward for my sleep as for my vigilance","","Sahih"],[4355,4355,4355,"। আূ মূসা (রাঃ) সূত্রে বর্ণিত। তিনি বলেন, আমি ইয়ামেনে অবস্থানকালে মু‘আয (রাঃ) আমার নিকট আসলেন। একটি লোক ইয়াহুদী ছিলো, সে মুসলিম হয়ে আবার ইসলাম ত্যাগ করে মুরতাদ হয়ে যায়। মু‘আয (রাঃ) এসে বলেন, একে হত্যা না করা পর্যন্ত আমি আমার জন্তুযান থেকে নামবো না। অতঃপর তাকে হত্যা করা হলো। তালহা ও বুরাইদাহ উভয়ের একজন বলেন, হত্যা করার পূর্বে তাকে ইসলামে ফিরে আসার আহবান জানানো হয়েছিল।[1] সহীহ।","حَدَّثَنَا الْحَسَنُ بْنُ عَلِيٍّ، حَدَّثَنَا الْحِمَّانِيُّ، - يَعْنِي عَبْدَ الْحَمِيدِ بْنَ عَبْدِ الرَّحْمَنِ - عَنْ طَلْحَةَ بْنِ يَحْيَى، وَبُرَيْدِ بْنِ عَبْدِ اللَّهِ بْنِ أَبِي بُرْدَةَ، عَنْ أَبِي بُرْدَةَ، عَنْ أَبِي مُوسَى، قَالَ قَدِمَ عَلَىَّ مُعَاذٌ وَأَنَا بِالْيَمَنِ، وَرَجُلٌ، كَانَ يَهُودِيًّا فَأَسْلَمَ فَارْتَدَّ عَنِ الإِسْلاَمِ، فَلَمَّا قَدِمَ مُعَاذٌ قَالَ لاَ أَنْزِلُ عَنْ دَابَّتِي حَتَّى يُقْتَلَ ‏.‏ فَقُتِلَ ‏.‏ قَالَ أَحَدُهُمَا وَكَانَ قَدِ اسْتُتِيبَ قَبْلَ ذَلِكَ ‏.‏","Narrated Mu'adh ibn Jabal: AbuMusa said: Mu'adh came to me when I was in the Yemen. A man who was Jew embraced Islam and then retreated from Islam. When Mu'adh came, he said: I will not come down from my mount until he is killed. He was then killed. One of them said: He was asked to repent before that","","Sahih"],[4356,4356,4356,"। একই ঘটনা প্রসঙ্গে আবূ বুরদাহ (রহঃ) সূত্রে বর্ণিত হাদীসে তিনি বলেনঃ আবূ মূসার নিকট ইসলাম ত্যাগী একটি লোককে নিয়ে আসা হলো। তিনি তাকে বিশ দিন অথবা এর কাছাকাছি সময় পর্যন্ত ইসলামে ফিরে আসার আহবান জানান। অতঃপর মু‘আয (রাঃ) এসেও তাকে আহবান জানালেন; কিন্তু সে অস্বীকার করলো। সুতরাং তাকে হত্যা করা হলো। ইমাম আবূ দাঊদ (রহঃ) বরেন, আবূ বুরদাহ থেকে আব্দুল মালিক উমাইরের বর্ণিত হাদীসে ইসলামে ফিরে আসার কথা উল্লেখ নেই। আর ইবনু ফুদাইল শাইবানীর সূত্রে সাঈদ ইবনু আবূ বুরদাহ থেকে তার পিতা আবূ মূসা সূত্রে বর্ণনা করেছেন। তাতেও ইসলামে ‘ফিরে আসার’ জন্য আহবান করার কথা উল্লেখ নেই।[1] সনদ সহীহ।","حَدَّثَنَا مُحَمَّدُ بْنُ الْعَلاَءِ، حَدَّثَنَا حَفْصٌ، حَدَّثَنَا الشَّيْبَانِيُّ، عَنْ أَبِي بُرْدَةَ، بِهَذِهِ الْقِصَّةِ قَالَ فَأُتِيَ أَبُو مُوسَى بِرَجُلٍ قَدِ ارْتَدَّ عَنِ الإِسْلاَمِ، فَدَعَاهُ عِشْرِينَ لَيْلَةً أَوْ قَرِيبًا مِنْهَا فَجَاءَ مُعَاذٌ فَدَعَاهُ فَأَبَى فَضُرِبَ عُنُقُهُ ‏.‏ قَالَ أَبُو دَاوُدَ وَرَوَاهُ عَبْدُ الْمَلِكِ بْنُ عُمَيْرٍ عَنْ أَبِي بُرْدَةَ لَمْ يَذْكُرْ الاِسْتِتَابَةَ وَرَوَاهُ ابْنُ فُضَيْلٍ عَنِ الشَّيْبَانِيِّ عَنْ سَعِيدِ بْنِ أَبِي بُرْدَةَ عَنْ أَبِيهِ عَنْ أَبِي مُوسَى وَلَمْ يَذْكُرْ فِيهِ الاِسْتِتَابَةَ ‏.‏","Abu Burdah said:A man who turned back from Islam was brought to Abu Musa. He invited him to repent for twenty days or about so. Muadh then came and invited him (to embrace Islam) but he refused. So he was beheaded","","Sahih Isnaad"],[4357,4357,4357,"। কাসিম (রহঃ) সূত্রে অনুরূপ ঘটনা বর্ণিত। তিনি বলেন, তাকে হত্যা না করা পর্যন্ত তিনি (মু‘আয) অবতরণ করেননি। আর তাকে ইসলামে ফিরে আসার আহবানও করা হয়নি।[1] সনদ দুর্বল।","حَدَّثَنَا ابْنُ مُعَاذٍ، حَدَّثَنَا أَبِي، حَدَّثَنَا الْمَسْعُودِيُّ، عَنِ الْقَاسِمِ، بِهَذِهِ الْقِصَّةِ قَالَ فَلَمْ يَنْزِلْ حَتَّى ضُرِبَ عُنُقُهُ وَمَا اسْتَتَابَهُ ‏.‏","The tradition mention above has also been transmitted by Abu Musa through a different chain if narrators. But there is no mention of demand of repentance","","Daif Isnaad"],[4358,4358,4358,"। ইবনু আব্বাস (রাঃ) সূত্রে বর্ণিত। তিনি বলেন, আব্দুল্লাহ ইবনু সা‘দ ইবনু আসুস সারহ রাসূলুল্লাহ সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম-এর (ওয়াহী) লেখকদের অন্তর্ভুক্ত ছিলো। শয়তান তাকে পথভ্রষ্ট করে এবং সে কাফিরদের সঙ্গে মিশে যায়। মক্কা বিজয়ের দিন রাসূলুল্লাহ সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম তাকে হত্যা করার আদেশ দিলেন। কিন্তু উসমান ইবনু আফফান (রাঃ) তার জন্য নিরাপত্তা প্রার্থনা করলে রাসূলুল্লাহ সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম তাকে নিরাপত্তা প্রদান করেন।[1] সনদ হাসান।","حَدَّثَنَا أَحْمَدُ بْنُ مُحَمَّدٍ الْمَرْوَزِيُّ، حَدَّثَنَا عَلِيُّ بْنُ الْحُسَيْنِ بْنِ وَاقِدٍ، عَنْ أَبِيهِ، عَنْ يَزِيدَ النَّحْوِيِّ، عَنْ عِكْرِمَةَ، عَنِ ابْنِ عَبَّاسٍ، قَالَ كَانَ عَبْدُ اللَّهِ بْنُ سَعْدِ بْنِ أَبِي سَرْحٍ يَكْتُبُ لِرَسُولِ اللَّهِ صلى الله عليه وسلم فَأَزَلَّهُ الشَّيْطَانُ فَلَحِقَ بِالْكُفَّارِ فَأَمَرَ بِهِ رَسُولُ اللَّهِ صلى الله عليه وسلم أَنْ يُقْتَلَ يَوْمَ الْفَتْحِ فَاسْتَجَارَ لَهُ عُثْمَانُ بْنُ عَفَّانَ فَأَجَارَهُ رَسُولُ اللَّهِ صلى الله عليه وسلم ‏.‏","Narrated Abdullah ibn Abbas: Abdullah ibn AbuSarh used to write (the revelation) for the Messenger of Allah (ﷺ). Satan made him slip, and he joined the infidels. The Messenger of Allah (ﷺ) commanded to kill him on the day of Conquest (of Mecca). Uthman ibn Affan sought protection for him. The Messenger of Allah (ﷺ) gave him protection","","Hasan Isnaad"],[4359,4359,4359,"। সা‘দ (রাঃ) সূত্রে বর্ণিত। তিনি বলেন, মক্কা বিজয়ের দিন আব্দুল্লাহ ইবনু সা‘দ ইবনু আবূ সারহ উসমান ইবনু আফফান (রাঃ)-এর নিকট আত্মগোপন করে। তিনি তাকে নিয়ে এসে নবী সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম-এর সামনে দাঁড় করিয়ে বলেন, হে আল্লাহর রাসূল! আব্দুল্লাহকে বাই‘আত করুন। তিনি (সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম) মাথা উঠিয়ে তিনবার তার দিকে তাকান এবং প্রতিবারই বাই‘আত করতে অস্বীকৃতি জানান। তিনবারের পর তাকে বাই‘আত করেন। অতঃপর তিনি সাহাবীদের দিকে ফিরে বলেনঃ তোমাদের মধ্যে কি সঠিক নির্দেশ উপলদ্ধি করার মতো কেউ ছিলো না, যে এর সমানে গিয়ে দাঁড়াতো; আর যখন দেখতো আমি তার বাই‘আত গ্রহণ না করার জন্য হাত গুটিয়ে নিচ্ছি, তখন সে তাকে হত্যা করতো? সাহাবীরা বললেন, হে আল্লাহর রাসূল! আমরা আপনার মনের ইচ্ছা উপলদ্ধি করতে পারিনি। আপনি কেন আমাদের চোখ দিয়ে ইশারা করলেন না? তিনি বললেনঃ কোনো নবীর পক্ষে চোখের খেয়ানতকারী হওয়া শোভা পায় না।[1] সহীহ।","حَدَّثَنَا عُثْمَانُ بْنُ أَبِي شَيْبَةَ، حَدَّثَنَا أَحْمَدُ بْنُ الْمُفَضَّلِ، حَدَّثَنَا أَسْبَاطُ بْنُ نَصْرٍ، قَالَ زَعَمَ السُّدِّيُّ عَنْ مُصْعَبِ بْنِ سَعْدٍ، عَنْ سَعْدٍ، قَالَ لَمَّا كَانَ يَوْمُ فَتْحِ مَكَّةَ اخْتَبَأَ عَبْدُ اللَّهِ بْنُ سَعْدِ بْنِ أَبِي سَرْحٍ عِنْدَ عُثْمَانَ بْنِ عَفَّانَ فَجَاءَ بِهِ حَتَّى أَوْقَفَهُ عَلَى النَّبِيِّ صلى الله عليه وسلم فَقَالَ يَا رَسُولَ اللَّهِ بَايِعْ عَبْدَ اللَّهِ ‏.‏ فَرَفَعَ رَأْسَهُ فَنَظَرَ إِلَيْهِ ثَلاَثًا كُلُّ ذَلِكَ يَأْبَى فَبَايَعَهُ بَعْدَ ثَلاَثٍ ثُمَّ أَقْبَلَ عَلَى أَصْحَابِهِ فَقَالَ ‏\"‏ أَمَا كَانَ فِيكُمْ رَجُلٌ رَشِيدٌ يَقُومُ إِلَى هَذَا حَيْثُ رَآنِي كَفَفْتُ يَدِي عَنْ بَيْعَتِهِ فَيَقْتُلَهُ ‏\"‏ ‏.‏ فَقَالُوا مَا نَدْرِي يَا رَسُولَ اللَّهِ مَا فِي نَفْسِكَ أَلاَّ أَوْمَأْتَ إِلَيْنَا بِعَيْنِكَ قَالَ ‏\"‏ إِنَّهُ لاَ يَنْبَغِي لِنَبِيٍّ أَنْ تَكُونَ لَهُ خَائِنَةُ الأَعْيُنِ ‏\"‏ ‏.‏","Narrated Sa'd ibn AbuWaqqas: On the day of the conquest of Mecca, Abdullah ibn Sa'd ibn AbuSarh hid himself with Uthman ibn Affan. He brought him and made him stand before the Prophet (ﷺ), and said: Accept the allegiance of Abdullah, Messenger of Allah! He raised his head and looked at him three times, refusing him each time, but accepted his allegiance after the third time. Then turning to his companions, he said: Was not there a wise man among you who would stand up to him when he saw that I had withheld my hand from accepting his allegiance, and kill him? They said: We did not know what you had in your heart, Messenger of Allah! Why did you not give us a signal with your eye? He said: It is not advisable for a Prophet to play deceptive tricks with the eyes","","Sahih"],[4360,4360,4360,"। জারীর (রাঃ) সূত্রে বর্ণিত। তিনি বলেন, আমি নবী সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম-কে বলতে শুনেছিঃ ক্রীতদাস পলায়ন করে যদি মুশরিক হয়ে যায়, তবে তাকে হত্যা করা বৈধ।[1] দুর্বল।","حَدَّثَنَا قُتَيْبَةُ بْنُ سَعِيدٍ، حَدَّثَنَا حُمَيْدُ بْنُ عَبْدِ الرَّحْمَنِ، عَنْ أَبِيهِ، عَنْ أَبِي إِسْحَاقَ، عَنِ الشَّعْبِيِّ، عَنْ جَرِيرٍ، قَالَ سَمِعْتُ النَّبِيَّ صلى الله عليه وسلم يَقُولُ ‏ \"‏ إِذَا أَبَقَ الْعَبْدُ إِلَى الشِّرْكِ فَقَدْ حَلَّ دَمُهُ ‏\"‏ ‏.‏","Jarir reported the prophet (ﷺ) as saying:When a slave runs away and reverts to polytheism, he may lawfully be killed","","Daif"],[4361,4361,4361,"। ইবনু আব্বাস (রাঃ) সূত্রে বর্ণিত। জনৈক অন্ধ লোকের একটি উম্মু ওয়ালাদ’ ক্রীতদাসী ছিলো। সে নবী সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম-কে গালি দিতো এবং তাঁর সম্পর্কে মন্দ কথা বলতো। অন্ধ লোকটি তাকে নিষেধ করা সত্ত্বেও সে বিরত হতো না। সে তাকে ভৎর্সনা করতো; কিন্তু তাতেও সে বিরত হতো না। এক রাতে সে যখন নবী সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম-কে গালি দিতে শুরু করলো এবং তাঁর সম্পর্কে মন্দ কথা বলতে লাগলো, সে একটি একটি ধারালো ছোরা নিয়ে তার পেটে ঢুকিয়ে তাতে চোপ দিয়ে তাহেত্যা করলো। তার দু’ পায়ের মাঝখানে একটি শিশু পতিত হয়ে রক্তে রঞ্জিত হলো। ভোরবেলা নবী সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম ঘটনাটি অবহিত হয়ে লোকজনকে সমবেত করে বলেনঃ আমি আল্লাহর কসম করে বলছিঃ যে ব্যক্তি একাজ করেছে, সে যদি না দাঁড়ায় তবে তার উপর আমার অধিকার আছে। একথা শুনে অন্ধ লোকটি মানুষের ভিড় ঠেলে কাঁপতে কাঁপতে সামনে অগ্রসর হয়ে নবী সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম-এর সামনে এসে বসে বললো, হে আল্লাহর রাসূল! আমি সেই নিহত দাসীর মনিব। সে আপনাকে গালাগালি করতো এবং আপনার সম্পর্কে অপমানজনক কথা বলতো। আমি নিষেধ করতাম; কিন্তু সে বিরত হতো না। আমি তাকে ধমক দিতাম; কিন্তু সে তাতেও বিরত হতো না। তার গর্ভজাত মুক্তার মতো আমার দু’টি ছেলে আছে, আর সে আমার খুব প্রিয়পাত্রী ছিলো। গত রাতে সে আপনাকে গালাগালি শুরু করে এবং আপনার সম্পর্কে অপমানজনক কথা বললে, আমি তখন একটি ধারালো ছুরি নিয়ে তার পেটে স্থাপন করে তাতে চাপ দিয়ে তাকে হত্যা করে ফেলি। নবী সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম বলেনঃ তোমরা সাক্ষী থাকো, তার রক্ত বৃথা গেলো।[1] সহীহ।","حَدَّثَنَا عَبَّادُ بْنُ مُوسَى الْخُتَّلِيُّ، أَخْبَرَنَا إِسْمَاعِيلُ بْنُ جَعْفَرٍ الْمَدَنِيُّ، عَنْ إِسْرَائِيلَ، عَنْ عُثْمَانَ الشَّحَّامِ، عَنْ عِكْرِمَةَ، قَالَ حَدَّثَنَا ابْنُ عَبَّاسٍ، أَنَّ أَعْمَى، كَانَتْ لَهُ أُمُّ وَلَدٍ تَشْتُمُ النَّبِيَّ صلى الله عليه وسلم وَتَقَعُ فِيهِ فَيَنْهَاهَا فَلاَ تَنْتَهِي وَيَزْجُرُهَا فَلاَ تَنْزَجِرُ - قَالَ - فَلَمَّا كَانَتْ ذَاتَ لَيْلَةٍ جَعَلَتْ تَقَعُ فِي النَّبِيِّ صلى الله عليه وسلم وَتَشْتِمُهُ فَأَخَذَ الْمِغْوَلَ فَوَضَعَهُ فِي بَطْنِهَا وَاتَّكَأَ عَلَيْهَا فَقَتَلَهَا فَوَقَعَ بَيْنَ رِجْلَيْهَا طِفْلٌ فَلَطَخَتْ مَا هُنَاكَ بِالدَّمِ فَلَمَّا أَصْبَحَ ذُكِرَ ذَلِكَ لِرَسُولِ اللَّهِ صلى الله عليه وسلم فَجَمَعَ النَّاسَ فَقَالَ ‏\"‏ أَنْشُدُ اللَّهَ رَجُلاً فَعَلَ مَا فَعَلَ لِي عَلَيْهِ حَقٌّ إِلاَّ قَامَ ‏\"‏ ‏.‏ فَقَامَ الأَعْمَى يَتَخَطَّى النَّاسَ وَهُوَ يَتَزَلْزَلُ حَتَّى قَعَدَ بَيْنَ يَدَىِ النَّبِيِّ صلى الله عليه وسلم فَقَالَ يَا رَسُولَ اللَّهِ أَنَا صَاحِبُهَا كَانَتْ تَشْتِمُكَ وَتَقَعُ فِيكَ فَأَنْهَاهَا فَلاَ تَنْتَهِي وَأَزْجُرُهَا فَلاَ تَنْزَجِرُ وَلِي مِنْهَا ابْنَانِ مِثْلُ اللُّؤْلُؤَتَيْنِ وَكَانَتْ بِي رَفِيقَةً فَلَمَّا كَانَتِ الْبَارِحَةَ جَعَلَتْ تَشْتِمُكَ وَتَقَعُ فِيكَ فَأَخَذْتُ الْمِغْوَلَ فَوَضَعْتُهُ فِي بَطْنِهَا وَاتَّكَأْتُ عَلَيْهَا حَتَّى قَتَلْتُهَا ‏.‏ فَقَالَ النَّبِيُّ صلى الله عليه وسلم ‏\"‏ أَلاَ اشْهَدُوا أَنَّ دَمَهَا هَدَرٌ ‏\"‏ ‏.‏","Narrated Abdullah Ibn Abbas: A blind man had a slave-mother who used to abuse the Prophet (ﷺ) and disparage him. He forbade her but she did not stop. He rebuked her but she did not give up her habit. One night she began to slander the Prophet (ﷺ) and abuse him. So he took a dagger, placed it on her belly, pressed it, and killed her. A child who came between her legs was smeared with the blood that was there. When the morning came, the Prophet (ﷺ) was informed about it. He assembled the people and said: I adjure by Allah the man who has done this action and I adjure him by my right to him that he should stand up. Jumping over the necks of the people and trembling the man stood up. He sat before the Prophet (ﷺ) and said: Messenger of Allah! I am her master; she used to abuse you and disparage you. I forbade her, but she did not stop, and I rebuked her, but she did not abandon her habit. I have two sons like pearls from her, and she was my companion. Last night she began to abuse and disparage you. So I took a dagger, put it on her belly and pressed it till I killed her. Thereupon the Prophet (ﷺ) said: Oh be witness, no retaliation is payable for her blood","","Sahih"],[4362,4362,4362,"। আলী (রাঃ) সূত্রে বর্ণিত। এক ইয়াহুদী মহিলা নবী সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম-কে গালাগালি করতো এবং তাঁর সম্পর্কে মন্দ কথা বলতো। একদা জনৈক ব্যক্তি তাকে গলা টিপে হত্যা করে। রাসূলুল্লাহ সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম তার রক্ত বাতিল বলে ঘোষণা করেন।[1] সনদ দুর্বলঃ ইরওয়া হা/ ১২৫১।","حَدَّثَنَا عُثْمَانُ بْنُ أَبِي شَيْبَةَ، وَعَبْدُ اللَّهِ بْنُ الْجَرَّاحِ، عَنْ جَرِيرٍ، عَنْ مُغِيرَةَ، عَنِ الشَّعْبِيِّ، عَنْ عَلِيٍّ، رَضِيَ اللَّهُ عَنْهُ أَنَّ يَهُودِيَّةً، كَانَتْ تَشْتِمُ النَّبِيَّ صلى الله عليه وسلم وَتَقَعُ فِيهِ فَخَنَقَهَا رَجُلٌ حَتَّى مَاتَتْ فَأَبْطَلَ رَسُولُ اللَّهِ صلى الله عليه وسلم دَمَهَا ‏.‏","Narrated Ali ibn AbuTalib: A Jewess used to abuse the Prophet (ﷺ) and disparage him. A man strangled her till she died. The Messenger of Allah (ﷺ) declared that no recompense was payable for her blood","","Daif Isnaad"],[4363,4363,4363,"। আবূ বারযাহ (রাঃ) সূত্রে বর্ণিত। তিনি বলেন, একদা আমি আবূ বাকর (রাঃ)-এর নিকট উপস্থিত ছিলাম। তখন তিনি একটি লোকের প্রতি খুবই ক্রোধান্বিত হলেন। আমি তাকে বললাম, হে রাসূলুল্লাহ সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম-এর খলীফাহ! আমাকে অনুমতি দিন, তাকে হত্যা করি। তিনি বলেন, আমার একথায় তার ক্রোধ দূর হলো। তিনি উঠে বাড়ির ভেতরে চলে গেলেন। অতঃপর তিনি লোক পাঠিয়ে আমাকে (ডেকে নিয়ে) র্প্রশ্ন করেন, তুমি এইমাত্র কি বলেছ? আমি বললাম, আমাকে অনুমতি দিন, আমি তাকে হত্যা করি। তিনি প্রশ্ন করেন, আমি যদি তোমাকে আদেশ করতাম, তুমি কি তাই করতে? আমি বললাম, হ্যাঁ। তিনি বললেন, না আল্লাহর কসম! মুহাম্মাদ সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম-এর পরে অন্য কোনো মানবের এ অধিকার নেই। ইমাম আবূ দাঊদ (রহঃ) বলেন, এই মূল পাঠ বর্ণনাকারী ইয়াযীদের। আহমাদ ইবনু হাম্বাল (রহঃ) বলেন, অর্থাৎ নবী সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম যে তিনটি অপরাধের কোনটিতে লিপ্ত ব্যক্তিকে হত্যা করার কথা বলেছেন, তাদের ছাড়া অন্য কাউকে হত্যা করা আবূ বাকরের জন্য বৈধ নয়ঃ কেউ ধর্ম ত্যাগ করলে, বিবাহিত ব্যক্তি যিনা করলে এবং নিরপরাধ ব্যক্তির হত্যাকারী। তবে নবী সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম-এর হত্যা করার কর্তৃত্ব ছিলো।[1] সহীহ।","حَدَّثَنَا مُوسَى بْنُ إِسْمَاعِيلَ، حَدَّثَنَا حَمَّادٌ، عَنْ يُونُسَ، عَنْ حُمَيْدِ بْنِ هِلاَلٍ، عَنِ النَّبِيِّ صلى الله عليه وسلم ح وَحَدَّثَنَا هَارُونُ بْنُ عَبْدِ اللَّهِ، وَنُصَيْرُ بْنُ الْفَرَجِ، قَالاَ حَدَّثَنَا أَبُو أُسَامَةَ، عَنْ يَزِيدَ بْنِ زُرَيْعٍ، عَنْ يُونُسَ بْنِ عُبَيْدٍ، عَنْ حُمَيْدِ بْنِ هِلاَلٍ، عَنْ عَبْدِ اللَّهِ بْنِ مُطَرِّفٍ، عَنْ أَبِي بَرْزَةَ، قَالَ كُنْتُ عِنْدَ أَبِي بَكْرٍ رَضِيَ اللَّهُ عَنْهُ فَتَغَيَّظَ عَلَى رَجُلٍ فَاشْتَدَّ عَلَيْهِ فَقُلْتُ تَأْذَنُ لِي يَا خَلِيفَةَ رَسُولِ اللَّهِ صلى الله عليه وسلم أَضْرِبُ عُنُقَهُ قَالَ فَأَذْهَبَتْ كَلِمَتِي غَضَبَهُ فَقَامَ فَدَخَلَ فَأَرْسَلَ إِلَىَّ فَقَالَ مَا الَّذِي قُلْتَ آنِفًا قُلْتُ ائْذَنْ لِي أَضْرِبْ عُنُقَهُ ‏.‏ قَالَ أَكُنْتَ فَاعِلاً لَوْ أَمَرْتُكَ قُلْتُ نَعَمْ ‏.‏ قَالَ لاَ وَاللَّهِ مَا كَانَتْ لِبَشَرٍ بَعْدَ مُحَمَّدٍ صلى الله عليه وسلم ‏.‏ قَالَ أَبُو دَاوُدَ هَذَا لَفْظُ يَزِيدَ قَالَ أَحْمَدُ بْنُ حَنْبَلٍ أَىْ لَمْ يَكُنْ لأَبِي بَكْرٍ أَنْ يَقْتُلَ رَجُلاً إِلاَّ بِإِحْدَى الثَّلاَثِ الَّتِي قَالَهَا رَسُولُ اللَّهِ صلى الله عليه وسلم كُفْرٌ بَعْدَ إِيمَانٍ أَوْ زِنًا بَعْدَ إِحْصَانٍ أَوْ قَتْلُ نَفْسٍ بِغَيْرِ نَفْسٍ وَكَانَ لِلنَّبِيِّ صلى الله عليه وسلم أَنْ يَقْتُلَ ‏.‏","Narrated AbuBakr: AbuBarzah said: I was with AbuBakr. He became angry at a man and uttered hot words. I said: Do you permit me, Caliph of the Messenger of Allah (ﷺ), that I cut off his neck? These words of mine removed his anger; he stood and went in. He then sent for me and said: What did you say just now? I said: (I had said:) Permit me that I cut off his neck. He said: Would you do it if I ordered you? I said: Yes. He said: No, I swear by Allah, this is not allowed for any man after Muhammad (ﷺ). Abu Dawud said: This is Yazid's version. Ahmad bin Hanbal said: That is, Abu Bakr has no powers to slay a man except for three reasons which the Messenger of Allah (ﷺ) had mentioned: disbelief after belief, fornication after marriage, or killing a man without (murdering) any man by him. The Prophet (ﷺ) had powers to kill","","Sahih"],[4364,4364,4364,"। আনাস ইবনু মালিক (রাঃ) সূত্রে বর্ণিত। উকল অথবা উরাইনাহ গোত্রের কিছু লোক রাসূলুল্লাহ সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম-এর নিকট আসলো। মদীনায় বসবাস তাদের পক্ষে অনুপযোগী হওয়ায় রাসূলুল্লাহ সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম তাদেরকে উটের পালের নিকট গিয়ে এগুলোর পেশাব ও দুধ পান করতে আদেশ দেন। অতএব তারা সেখানে চলে গেলো। পরে তারা সুস্থ হয়ে রাসূলুল্লাহ সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম-এর রাখালকে হত্যা করে এবং উট পালকে তাড়িয়ে নিয়ে যায়। দিনের প্রথমভাগে এ খবর নবী সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম-এর নিকট পৌঁছে। নবী সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম তাদের পিছনে লোক পাঠান। উঠন্ত বেলায় তাদের ধরে নিয়ে আসা হয়। তাঁর আদেশে তাদের হাত-পা কাটা হয় এবং লৌহ শলাকা তাদের চোখে বিদ্ধ করে উত্তপ্ত রোদে ফেলে রাখা হয়। তারা পানি চাইলেও তা দেয়া হয়নি। আবূ কিলাবাহ বলেন, এরা এমন একটি গোত্রের, যারা চুরি করেছে, হত্যা করেছে, ঈমান আনার পর কুফরী করেছে এবং সর্বোপরি আল্লাহ ও তাঁর রাসূলের বিরুদ্ধে বিদ্রোহ করেছে।[1] সহীহ।","حَدَّثَنَا سُلَيْمَانُ بْنُ حَرْبٍ، حَدَّثَنَا حَمَّادٌ، عَنْ أَيُّوبَ، عَنْ أَبِي قِلاَبَةَ، عَنْ أَنَسِ بْنِ مَالِكٍ، أَنَّ قَوْمًا، مِنْ عُكْلٍ - أَوْ قَالَ مِنْ عُرَيْنَةَ - قَدِمُوا عَلَى رَسُولِ اللَّهِ صلى الله عليه وسلم فَاجْتَوَوُا الْمَدِينَةَ فَأَمَرَ لَهُمْ رَسُولُ اللَّهِ صلى الله عليه وسلم بِلِقَاحٍ وَأَمَرَهُمْ أَنْ يَشْرَبُوا مِنْ أَبْوَالِهَا وَأَلْبَانِهَا فَانْطَلَقُوا فَلَمَّا صَحُّوا قَتَلُوا رَاعِيَ رَسُولِ اللَّهِ صلى الله عليه وسلم وَاسْتَاقُوا النَّعَمَ فَبَلَغَ النَّبِيَّ صلى الله عليه وسلم خَبَرُهُمْ مِنْ أَوَّلِ النَّهَارِ فَأَرْسَلَ النَّبِيُّ صلى الله عليه وسلم فِي آثَارِهِمْ فَمَا ارْتَفَعَ النَّهَارُ حَتَّى جِيءَ بِهِمْ فَأَمَرَ بِهِمْ فَقُطِعَتْ أَيْدِيهِمْ وَأَرْجُلُهُمْ وَسُمِّرَ أَعْيُنُهُمْ وَأُلْقُوا فِي الْحَرَّةِ يَسْتَسْقُونَ فَلاَ يُسْقَوْنَ ‏.‏ قَالَ أَبُو قِلاَبَةَ فَهَؤُلاَءِ قَوْمٌ سَرَقُوا وَقَتَلُوا وَكَفَرُوا بَعْدَ إِيمَانِهِمْ وَحَارَبُوا اللَّهَ وَرَسُولَهُ ‏.‏","Anas b. Malik said:Some people of ‘Ukl or ‘Urainah’ came to the Messenger of Allah (ﷺ) and found Madinah unhealthy. So the Messenger of Allah (ﷺ) ordered them to go to the camels (of the sadaqah) and ordered them to drink some of their urine and milk. They went there when they became well, they killed the herdsman of the Messenger of Allah (ﷺ) and drove off the camels. The news about them reached the prophet (ﷺ) early in the morning. So he sent people in pursuit of them, and they were brought when they day had risen high. He ordered and their hands and feet were cut off and nails were drawn into their eyes, and they were thrown out of Harrah. They begged for water but were not supplied water. Abu Qilabah said: They were people who had stolen, killed, apostatized after their faith and fought against Allah and his Apostle (ﷺ)","","Sahih"],[4365,4365,4365,"। আইয়ূব (রহঃ) সূত্রে অনুরূপ হাদীস বর্ণিত। বর্ণনাকারী বলেন, তাঁর (সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম) আদেশে লৌহ শলাকা উত্তপ্ত করা হয়, তাদের চোখে ফুঁড়ে দেয়া হয়, হাত-পা কেটে দেয়া হয় এবং তাদের রক্তপ্রবাহ বন্ধ করেননি।[1] সহীহ।","حَدَّثَنَا مُوسَى بْنُ إِسْمَاعِيلَ، حَدَّثَنَا وُهَيْبٌ، عَنْ أَيُّوبَ، بِإِسْنَادِهِ بِهَذَا الْحَدِيثِ قَالَ فِيهِ فَأَمَرَ بِمَسَامِيرَ فَأُحْمِيَتْ فَكَحَلَهُمْ وَقَطَّعَ أَيْدِيَهُمْ وَأَرْجُلَهُمْ وَمَا حَسَمَهُمْ ‏.‏","The tradition mentioned above has also been transmitted by the narrator Ayyub through different chain. This version has :So he (the prophet) order nails to be heated and had them blinded with them, and he had their hands and feet cut off, and did not cauterise them to stop the flow of blood","","Sahih"],[4366,4366,4366,"। আনাস ইবনু মালিক (রাঃ) সূত্রে অনুরূপ হাদীস বর্ণিত। তিনি তাতে বলেনঃ অতঃপর রাসূলুল্লাহ সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম তাদের অনুসন্ধানে পদচিহ্ন বিশারদ একদল লোক পাঠালেন। পরে তাদেরকে ধরে নিয়ে আসা হলো। এ সম্পর্কে মহান আল্লাহ এ আয়াত নাযিল করেনঃ ‘‘যারা আল্লাহ ও তাঁর রাসূলের বিরুদ্ধে বিদ্রোহ করে আর পৃথিবীতে অশান্তি সৃষ্টি করে বেড়ায়, তাদের শাস্তি হলো, তাদের হত্যা করা হবে অথবা শূলে চড়ানো হবে অথবা তাদের একদিকের হাত এবং অপরদিকের পা কেটে ফেলা হবে অথবা ভূ-পৃষ্ঠ থেকে নির্বাসিত (কারাগারে আবদ্ধ) করা হবে। এটাই তাদের ইহকালের অপমান, আর পরকালে তাদের কঠোর শাস্তি ভোগ করতে হবে’’ (সূরা আল-মায়িদাহ)।[1] সহীহ।","حَدَّثَنَا مُحَمَّدُ بْنُ الصَّبَّاحِ بْنِ سُفْيَانَ، قَالَ أَخْبَرَنَا ح، وَحَدَّثَنَا عَمْرُو بْنُ عُثْمَانَ، حَدَّثَنَا الْوَلِيدُ، عَنِ الأَوْزَاعِيِّ، عَنْ يَحْيَى، - يَعْنِي ابْنَ أَبِي كَثِيرٍ - عَنْ أَبِي قِلاَبَةَ، عَنْ أَنَسِ بْنِ مَالِكٍ، بِهَذَا الْحَدِيثِ قَالَ فِيهِ فَبَعَثَ رَسُولُ اللَّهِ صلى الله عليه وسلم فِي طَلَبِهِمْ قَافَةً فَأُتِيَ بِهِمْ ‏.‏ قَالَ فَأَنْزَلَ اللَّهُ تَبَارَكَ وَتَعَالَى فِي ذَلِكَ ‏{‏ إِنَّمَا جَزَاءُ الَّذِينَ يُحَارِبُونَ اللَّهَ وَرَسُولَهُ وَيَسْعَوْنَ فِي الأَرْضِ فَسَادًا ‏}‏ الآيَةَ ‏.‏","The tradition mentioned above has also been transmitted by Anas. B. Malik through a different chain of narrators. This version says :The Messenger of Allah (ﷺ) sent some people who were experts in tracking in pursuit of them and they were brought (to him). Allah , the Exalted, then revealed the verse about it : “ The punishment of those who wage war against Allah and his Apostle and strive for mischief through the land","","Sahih"],[4367,4367,4367,"। আনাস ইবনু মালিক (রাঃ) সূত্রে বর্ণিত। তিনি এ হাদীস প্রসঙ্গে বলেন, বিপরীত দিক থেকে তাদের হাত-পা কর্তন করা হয়। হাদীসের প্রথমাংশে তিনি বলেন, তারা উট ছিনতাই করে এবং ইসলাম ধর্ম ত্যাগ করে। আনাস (রাঃ) বলেন, আমি তাদের একজনকে পিপাসার যন্ত্রণায় মুখ দিয়ে কামড়াতে দেখেছি। অবশেষে তারা মারা যায়।[1] সহীহ।","حَدَّثَنَا مُوسَى بْنُ إِسْمَاعِيلَ، حَدَّثَنَا حَمَّادٌ، أَخْبَرَنَا ثَابِتٌ، وَقَتَادَةُ، وَحُمَيْدٌ، عَنْ أَنَسِ بْنِ مَالِكٍ، ذَكَرَ هَذَا الْحَدِيثَ قَالَ أَنَسٌ فَلَقَدْ رَأَيْتُ أَحَدَهُمْ يَكْدِمُ الأَرْضَ بِفِيهِ عَطَشًا حَتَّى مَاتُوا ‏.‏","The tradition mentioned above has also been transmitted by Anas. B. Malik through a different chain of narrators. This version has :Anas said : I saw one of them biting the earth with this mouth (teeth) on account of thirst and this they died","","Sahih"],[4368,4368,4368,"। আনাস ইবনু মালিক (রাঃ) সূত্রে অনুরূপ হাদীস বর্ণিত। এতে আরো আছেঃ অতঃপর তিনি অঙ্গহানি নিষেধ করে। এ বর্ণনায় ‘বিপরীত দিক থেকে’ কথাটুকুর উল্লেখ নেই। আনাস (রাঃ) থেকে অন্যান্য বর্ণনাকারীও এ অংশটুকুও উল্লেখ করেননি। আমি হাম্মাদ ইবনু সালামাহর হাদীস ব্যতীত আর কারোর বর্ণনায় ‘বিপরীত দিক থেকে তাদের হাত-পা কাটার কথা’ পাইনি।[1] সহীহ।","حَدَّثَنَا مُحَمَّدُ بْنُ بَشَّارٍ، حَدَّثَنَا ابْنُ أَبِي عَدِيٍّ، عَنْ هِشَامٍ، عَنْ قَتَادَةَ، عَنْ أَنَسِ بْنِ مَالِكٍ، بِهَذَا الْحَدِيثِ نَحْوَهُ زَادَ ثُمَّ نَهَى عَنِ الْمُثْلَةِ وَلَمْ يَذْكُرْ مِنْ خِلاَفٍ ‏.‏ وَرَوَاهُ شُعْبَةُ عَنْ قَتَادَةَ وَسَلاَّمِ بْنِ مِسْكِينٍ عَنْ ثَابِتٍ جَمِيعًا عَنْ أَنَسٍ لَمْ يَذْكُرَا مِنْ خِلاَفٍ ‏.‏ وَلَمْ أَجِدْ فِي حَدِيثِ أَحَدٍ قَطَعَ أَيْدِيَهُمْ وَأَرْجُلَهُمْ مِنْ خِلاَفٍ ‏.‏ إِلاَّ فِي حَدِيثِ حَمَّادِ بْنِ سَلَمَةَ ‏.‏","A similar tradition has also been transmitted by Anas bin Malik through a different chain of narrators. This version adds:He then forbade disfiguring. This version does not mention the words “ from opposite sides” . This tradition has been narrated by Shu’bah from Qatadah and Salam bin Miskin from Thabit on the authority of Anas. They did not mention the words “from opposite side”. I did not find these words “their hands and feet were cut off from opposite sides”. In any version except in the version of Hammad bin Salamah","","Sahih"],[4369,4369,4369,"। ইবনু উমার (রাঃ) সূত্রে বর্ণিত। একদল লোক নবী সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম-এর উট লুট করে নিয়ে যায়, ইসলাম ধর্ম ত্যাগ করে মুরতাদ হয়ে যায় এবং নবী সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম-এর একজন ঈমানদার রাখালকে হত্যা করে। অতঃপর তিনি তাদের পিছনে লোক পাঠান! তাদের ধরে নিয়ে আসা হলে তিনি তাদের হাত-পা কেটে দেন এবং চোখ উপড়ে ফেলেন। ইবনু উমার বলেন, এদের সম্পর্কে ‘মুহারাবার’ আয়াত (৫ঃ ৩৩) নাযিল হয়। হাজ্জাজ যখন আনাস ইবনু মালিক (রাঃ)-কে এদের সম্পর্কে প্রশ্ন করেন, তখন তিনি এদের সম্পর্কিত হাদীস বর্ণনা করেন।[1] হাসান সহীহ।","حَدَّثَنَا أَحْمَدُ بْنُ صَالِحٍ، حَدَّثَنَا عَبْدُ اللَّهِ بْنُ وَهْبٍ، أَخْبَرَنِي عَمْرٌو، عَنْ سَعِيدِ بْنِ أَبِي هِلاَلٍ، عَنْ أَبِي الزِّنَادِ، عَنْ عَبْدِ اللَّهِ بْنِ عُبَيْدِ اللَّهِ، - قَالَ أَحْمَدُ هُوَ يَعْنِي عَبْدَ اللَّهِ بْنَ عُبَيْدِ اللَّهِ بْنِ عُمَرَ بْنِ الْخَطَّابِ - عَنِ ابْنِ عُمَرَ أَنَّ نَاسًا أَغَارُوا عَلَى إِبِلِ النَّبِيِّ صلى الله عليه وسلم فَاسْتَاقُوهَا وَارْتَدُّوا عَنِ الإِسْلاَمِ وَقَتَلُوا رَاعِيَ رَسُولِ اللَّهِ صلى الله عليه وسلم مُؤْمِنًا فَبَعَثَ فِي آثَارِهِمْ فَأُخِذُوا فَقَطَعَ أَيْدِيَهُمْ وَأَرْجُلَهُمْ وَسَمَلَ أَعْيُنَهُمْ ‏.‏ قَالَ وَنَزَلَتْ فِيهِمْ آيَةُ الْمُحَارَبَةِ وَهُمُ الَّذِينَ أَخْبَرَ عَنْهُمْ أَنَسُ بْنُ مَالِكٍ الْحَجَّاجَ حِينَ سَأَلَهُ ‏.‏","Narrated Abdullah ibn Umar: Some people raided the camels of the Prophet (ﷺ), drove them off, and apostatised. They killed the herdsman of the Messenger of Allah (ﷺ) who was a believer. He (the Prophet) sent (people) in pursuit of them and they were caught. He had their hands and feet cut off, and their eyes put out. The verse regarding fighting against Allah and His Prophet (ﷺ) was then revealed. These were the people about whom Anas ibn Malik informed al-Hajjaj when he asked him","","Hasan Sahih"],[4370,4370,4370,"। আবুয-যিনাদ (রহঃ) সূত্রে বর্ণিত। যারা রাসূলুল্লাহ সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম-এর উট চুরি করেছিল তিনি তাদের হাত-পা কাটলে এবং আগুন দিয়ে তাদের চোখ উৎপাটন করলে আল্লাহ তাঁর প্রতি অসন্তুষ্টি প্রকাশ করেন এবং আয়াত নাযিল করেনঃ ‘‘যারা আল্লাহ ও তাঁর রাসূলের বিরুদ্ধে যুদ্ধ করে এবং পৃথিবীতে ধ্বংসাত্মক কাজ করে বেড়ায় তাদের শাস্তি এই যে, তাদের হত্যা করা হবে অথবা শূলি বিদ্ধ করা হবে...’’ (সূরা আল-মায়িদাহঃ ৩৩)।[1] দুর্বল।","حَدَّثَنَا أَحْمَدُ بْنُ عَمْرِو بْنِ السَّرْحِ، أَخْبَرَنَا ابْنُ وَهْبٍ، أَخْبَرَنِي اللَّيْثُ بْنُ سَعْدٍ، عَنْ مُحَمَّدِ بْنِ الْعَجْلاَنِ، عَنْ أَبِي الزِّنَادِ، أَنَّ رَسُولَ اللَّهِ صلى الله عليه وسلم لَمَّا قَطَعَ الَّذِينَ سَرَقُوا لِقَاحَهُ وَسَمَلَ أَعْيُنَهُمْ بِالنَّارِ عَاتَبَهُ اللَّهُ تَعَالَى فِي ذَلِكَ فَأَنْزَلَ اللَّهُ تَعَالَى ‏{‏ إِنَّمَا جَزَاءُ الَّذِينَ يُحَارِبُونَ اللَّهَ وَرَسُولَهُ وَيَسْعَوْنَ فِي الأَرْضِ فَسَادًا أَنْ يُقَتَّلُوا أَوْ يُصَلَّبُوا ‏}‏ الآيَةَ ‏.‏","Narrated AbuzZinad: When the Messenger of Allah (ﷺ) cut off (the hands and feet of) those who had stolen his camels and he had their eyes put out by fire (heated nails), Allah reprimanded him on that (action), and Allah, the Exalted, revealed: \"The punishment of those who wage war against Allah and His Apostle and strive with might and main for mischief through the land is execution or crucifixion","","Daif"],[4371,4371,4371,"। মুহাম্মাদ ইবনু সীরীন (রহঃ) সূত্রে বর্ণিত। তিনি বলেন, আনাস (রাঃ) বর্ণিত হাদীসের ঘটনাটি ঘটেছিল আয়াত নাযিল হওয়ার পূর্বে।[1] দুর্বল মাওকুফ।","حَدَّثَنَا مُحَمَّدُ بْنُ كَثِيرٍ، قَالَ أَخْبَرَنَا ح، وَحَدَّثَنَا مُوسَى بْنُ إِسْمَاعِيلَ، حَدَّثَنَا هَمَّامٌ، عَنْ قَتَادَةَ، عَنْ مُحَمَّدِ بْنِ سِيرِينَ، قَالَ كَانَ هَذَا قَبْلَ أَنْ تَنْزِلَ الْحُدُودُ يَعْنِي حَدِيثَ أَنَسٍ ‏.‏","Muhammad bin Sirin said :This happened before the prescribed punishments(hudud) were revealed, meaning the tradition of Anas","","Daif Muquf"],[4372,4372,4372,"। ইবনু আব্বাস (রাঃ) সূত্রে বর্ণিত। তিনি বলেন, ‘‘যারা আল্লাহ ও তাঁর রাসূলের বিরুদ্ধে যুদ্ধ করে আর জমিনে অশান্তি সৃষ্টি করে বেড়ায়, তাদের শাস্তি হলোঃ তাদের হত্যা করা হবে অথবা শূলে চড়ানো হবে অথবা তাদের একদিকের হাত ও অপর দিকের পা কেটে ফেলা হবে অথবা জমিন থেকে নির্বাসিত হবে ... নিশ্চয়ই আল্লাহ ক্ষমাশীল ও করুণাময়’’ (সূরা আল-মায়িদাহঃ ৩৩-৩৪)- আয়াত দু’টি মুশরিকদের সম্পর্কে নাযিল হয়েছে। তবে তাদের মধ্যে কেউ যদি তওবা করে ফিরে আসে তাকে নিয়ন্ত্রণে আনার পূর্বে তার উপর নির্ধারিত শান্তি বাস্তবায়নে কোনো বাঁধা থাকবে না।[1] হাসান।","حَدَّثَنَا أَحْمَدُ بْنُ مُحَمَّدِ بْنِ ثَابِتٍ، حَدَّثَنَا عَلِيُّ بْنُ حُسَيْنٍ، عَنْ أَبِيهِ، عَنْ يَزِيدَ النَّحْوِيِّ، عَنْ عِكْرِمَةَ، عَنِ ابْنِ عَبَّاسٍ، قَالَ ‏{‏ إِنَّمَا جَزَاءُ الَّذِينَ يُحَارِبُونَ اللَّهَ وَرَسُولَهُ وَيَسْعَوْنَ فِي الأَرْضِ فَسَادًا أَنْ يُقَتَّلُوا أَوْ يُصَلَّبُوا أَوْ تُقَطَّعَ أَيْدِيهِمْ وَأَرْجُلُهُمْ مِنْ خِلاَفٍ أَوْ يُنْفَوْا مِنَ الأَرْضِ ‏}‏ إِلَى قَوْلِهِ ‏{‏ غَفُورٌ رَحِيمٌ ‏}‏ نَزَلَتْ هَذِهِ الآيَةُ فِي الْمُشْرِكِينَ فَمَنْ تَابَ مِنْهُمْ قَبْلَ أَنْ يُقْدَرَ عَلَيْهِ لَمْ يَمْنَعْهُ ذَلِكَ أَنْ يُقَامَ فِيهِ الْحَدُّ الَّذِي أَصَابَهُ ‏.‏","Narrated Abdullah ibn Abbas: The verse \"The punishment of those who wage war against Allah and His Apostle, and strive with might and main for mischief through the land is execution, or crucifixion, or the cutting off of hands and feet from opposite side or exile from the land...most merciful\" was revealed about polytheists. If any of them repents before they are arrested, it does not prevent from inflicting on him the prescribed punishment which he deserves","","Hasan"],[4373,4373,4373,"। আয়িশাহ (রাঃ) সূত্রে বর্ণিত। জনৈকা মাখযুমী মহিলার চুরি সংক্রান্ত অপরাধ কুরাইশদের দুশ্চিন্তাগ্রস্ত করে তুললে তারা বললো, এ ব্যাপারে রাসূলুল্লাহ সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম-এর সঙ্গে কে আলোচনা করবে? তারা বললো, নবী সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম-এর প্রিয় পাত্র উসামা ইবনু যায়িদই এ প্রসঙ্গে কথা বলতে সাহস করতে পারে। অতঃপর উসামা রাসূলুল্লাহ সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম-এর নিকট একথা বলাতে তিনি (সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম) বলেনঃ হে উসামা! তুমি কি মহান আল্লাহর নির্ধারিত শাস্তি মওকুফের সুপারিশ করছো? অতঃপর তিনি ভাষণ দিতে দাঁড়িয়ে বলেনঃ তোমাদের পূর্ববর্তী জাতির এজন্য ধ্বংস হয়েছে যে, তাদের মধ্যকার মর্যাদাশীল কেউ চুরি করলে তারা তাকে ছেড়ে দিতো, আর তাদের দুর্বল কেউ চুরি করলে তার উপর শাস্তি বাস্তবায়িত করতো। আমি আমার আল্লাহর কসম করে বলছি! মুহাম্মাদের কন্যা ফাতিমাহও যদি চুরি করতো, তাহলে অবশ্যই আমি তার হাত কাটতাম।[1] সহীহ।","حَدَّثَنَا يَزِيدُ بْنُ خَالِدِ بْنِ عَبْدِ اللَّهِ بْنِ مَوْهَبٍ الْهَمْدَانِيُّ، قَالَ حَدَّثَنِي ح، وَحَدَّثَنَا قُتَيْبَةُ بْنُ سَعِيدٍ الثَّقَفِيُّ، حَدَّثَنَا اللَّيْثُ، عَنِ ابْنِ شِهَابٍ، عَنْ عُرْوَةَ، عَنْ عَائِشَةَ، رضى الله عنها أَنَّ قُرَيْشًا، أَهَمَّهُمْ شَأْنُ الْمَرْأَةِ الْمَخْزُومِيَّةِ الَّتِي سَرَقَتْ فَقَالُوا مَنْ يُكَلِّمُ فِيهَا تَعْنِي رَسُولَ اللَّهِ صلى الله عليه وسلم ‏.‏ قَالُوا وَمَنْ يَجْتَرِئُ إِلاَّ أُسَامَةُ بْنُ زَيْدٍ حِبُّ رَسُولِ اللَّهِ صلى الله عليه وسلم فَكَلَّمَهُ أُسَامَةُ فَقَالَ رَسُولُ اللَّهِ صلى الله عليه وسلم ‏\"‏ يَا أُسَامَةُ أَتَشْفَعُ فِي حَدٍّ مِنْ حُدُودِ اللَّهِ ‏\"‏ ‏.‏ ثُمَّ قَامَ فَاخْتَطَبَ فَقَالَ ‏\"‏ إِنَّمَا هَلَكَ الَّذِينَ مِنْ قَبْلِكُمْ أَنَّهُمْ كَانُوا إِذَا سَرَقَ فِيهِمُ الشَّرِيفُ تَرَكُوهُ وَإِذَا سَرَقَ فِيهِمُ الضَّعِيفُ أَقَامُوا عَلَيْهِ الْحَدَّ وَايْمُ اللَّهِ لَوْ أَنَّ فَاطِمَةَ بِنْتَ مُحَمَّدٍ سَرَقَتْ لَقَطَعْتُ يَدَهَا ‏\"‏ ‏.‏","‘A’ishah said:The Quraish were anxious about the Makhzumi woman who had committed theft, They said : Who will speak to the Messenger of Allah(ﷺ) about her ? Then they said: Who will be bold enough for it but Uasmah bin Zaid, the prophet’s (ﷺ) friend! So Usamah spoke to him, and the Messenger of Allah(ﷺ) said : Are you interceding regarding one of the punishments prescribed by Allah ? He then got up and gave an address, saying : What destroyed your predecessors was just that when a person of rank among them committed a theft, They left him alone , and when a weak one of them committed a theft, they inflicted the prescribed punishment on him . I swear by Allah that if Fatimah daughter of Muhammad should steal, I would have her hand cut off","","Sahih"],[4374,4374,4374,"। আয়িশাহ (রাঃ) সূত্রে বর্ণিত। তিনি বলেন, জনৈক মাখযুমী মহিলা জিনিসপত্র ধার নিয়ে পরে তা অস্বীকার করতো। নবী সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম তার হাত কাটার আদেশ দিলেন। অতঃপর লাইস বর্ণিত হাদীসের অনুরূপ। বর্ণনাকারী বলেন, অতঃপর নবী সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম তার হাত কেটে দেন। ইমাম আবূ দাঊদ (রহঃ) বলেন, ইবনু ওয়াহব এ হাদীস ইউনুসের সূত্রে যুহরী থেকে বর্ণনা করে বলেনঃ নবী সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম-এর মক্কা বিজয়কালে জনৈক মহিলা চুরি করে। লাইস ইউনুসের সূত্রে এবং ইবনু শিহাব সূত্রে এ হাদীস বর্ণনা করে বলেন, জনৈক মহিলা ধার নিতো। মাস‘ঊদ ইবনুল আসওয়াদ নিজস্ব সনদে নবী সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম থেকে এর সমার্থক হাদীস বর্ণনা করে বলেনঃ মহিলাটি রাসূলুল্লাহ সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম-এর ঘর থেকে একটি মকমলের চাদর চুরি করে। ইমাম আবূ দাঊদ (রহঃ) বলেন, আবুয যুবায়র (রহঃ) এবং জাবির (রাঃ) থেকে বর্ণনা করেন যে, জনৈক নারী চুরি করে। অতঃপর সে রাসূলুল্লাহ সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম-এর কন্যা যাইনাব (রাঃ)-এর মাধ্যমে মুক্তি চায়। হাদীসে বাকী অংশে ধার নেয়া অথবা চুরি করার কথা উল্লেখ আছে।[1]’ সহীহ।","حَدَّثَنَا عَبَّاسُ بْنُ عَبْدِ الْعَظِيمِ، وَمُحَمَّدُ بْنُ يَحْيَى، قَالاَ حَدَّثَنَا عَبْدُ الرَّزَّاقِ، أَخْبَرَنَا مَعْمَرٌ، عَنِ الزُّهْرِيِّ، عَنْ عُرْوَةَ، عَنْ عَائِشَةَ، رضى الله عنها قَالَتْ كَانَتِ امْرَأَةٌ مَخْزُومِيَّةٌ تَسْتَعِيرُ الْمَتَاعَ وَتَجْحَدُهُ فَأَمَرَ النَّبِيُّ صلى الله عليه وسلم بِقَطْعِ يَدِهَا وَقَصَّ نَحْوَ حَدِيثِ اللَّيْثِ قَالَ فَقَطَعَ النَّبِيُّ صلى الله عليه وسلم يَدَهَا ‏.‏ قَالَ أَبُو دَاوُدَ رَوَى ابْنُ وَهْبٍ هَذَا الْحَدِيثَ عَنْ يُونُسَ عَنِ الزُّهْرِيِّ وَقَالَ فِيهِ كَمَا قَالَ اللَّيْثُ إِنَّ امْرَأَةً سَرَقَتْ فِي عَهْدِ النَّبِيِّ صلى الله عليه وسلم فِي غَزْوَةِ الْفَتْحِ ‏.‏ وَرَوَاهُ اللَّيْثُ عَنْ يُونُسَ عَنِ ابْنِ شِهَابٍ بِإِسْنَادِهِ فَقَالَ اسْتَعَارَتِ امْرَأَةٌ ‏.‏ وَرَوَى مَسْعُودُ بْنُ الأَسْوَدِ عَنِ النَّبِيِّ صلى الله عليه وسلم نَحْوَ هَذَا الْخَبَرِ قَالَ سُرِقَتْ قَطِيفَةٌ مِنْ بَيْتِ رَسُولِ اللَّهِ صلى الله عليه وسلم ‏.‏ قَالَ أَبُو دَاوُدَ وَرَوَاهُ أَبُو الزُّبَيْرِ عَنْ جَابِرٍ أَنَّ امْرَأَةً سَرَقَتْ فَعَاذَتْ بِزَيْنَبَ بِنْتِ رَسُولِ اللَّهِ صلى الله عليه وسلم ‏.‏","’A’ishah said:A Makhzumi woman used to borrow goods and deny having received them, so the prophet (ﷺ) gave orders that her hand should be cut off. The narrator than transmitted the rest of the tradition like that of al-laith, saying : So the prophet (ﷺ) had her hand cut off. Abu dawud said: Ibn Wahb transmitted this tradition from Yunus on the authority of al-Zuhri, and in this version he said al-Laith has said: A woman committed theft during the lifetime of the Prophet (ﷺ) on the occasion of the Conquest (of Mecca). It has been transmitted by al-Laith from Yunus on the authority of Ibn Shihab through his chain of narrators. He said in this version: A woman borrowed goods. Mas'ud bin al-Aswad also transmitted a similar tradition from the Prophet (ﷺ) and said: A velvet was stolen from the house of the Messenger of Allah (ﷺ). Abu Dawud said: Abu al-Zubair reported on the authority of Jabir: A woman committed theft and took refuge with Zainab daughter of Prophet (ﷺ)","","Sahih"],[4375,4375,4375,"। আয়িশাহ (রাঃ) সূত্রে বর্ণিত। তিনি বলেন, রাসূলুল্লাহ সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম বলেছেনঃ তোমরা উত্তম গুণাবলীর অধিকারী লোকদের পদস্খলন (ছোটখাট ত্রুটি) এড়িয়ে যাও, হদ্দের অপরাধ ব্যতীত।[1] সহীহ।","حَدَّثَنَا جَعْفَرُ بْنُ مُسَافِرٍ، وَمُحَمَّدُ بْنُ سُلَيْمَانَ الأَنْبَارِيُّ، قَالاَ أَخْبَرَنَا ابْنُ أَبِي فُدَيْكٍ، عَنْ عَبْدِ الْمَلِكِ بْنِ زَيْدٍ، - نَسَبَهُ جَعْفَرٌ إِلَى سَعِيدِ بْنِ زَيْدِ بْنِ عَمْرِو بْنِ نُفَيْلٍ - عَنْ مُحَمَّدِ بْنِ أَبِي بَكْرٍ، عَنْ عَمْرَةَ، عَنْ عَائِشَةَ، رضى الله عنها قَالَتْ قَالَ رَسُولُ اللَّهِ صلى الله عليه وسلم ‏ \"‏ أَقِيلُوا ذَوِي الْهَيْئَاتِ عَثَرَاتِهِمْ إِلاَّ الْحُدُودَ ‏\"‏ ‏.‏","Narrated Aisha, Ummul Mu'minin: The Messenger of Allah (ﷺ) Said: Forgive the people of good qualities their slips, but not faults to which prescribed penalties apply","","Sahih"],[4376,4376,4376,"। আব্দুল্লাহ ইবনু আমর ইবনুল আস (রাঃ) সূত্রে বর্ণিত। রাসূলুল্লাহ সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম বলেনঃ তোমরা আপোষে তোমাদের মধ্যে সংঘটিত হাদ্দ সংশ্লিষ্ট অপরাধ গোপন রাখো। অন্যথায় তা আমার নিকট পৌঁছলে তার শাস্তি বাস্তবায়িত হবেই।[1] সহীহ।","حَدَّثَنَا سُلَيْمَانُ بْنُ دَاوُدَ الْمَهْرِيُّ، أَخْبَرَنَا ابْنُ وَهْبٍ، قَالَ سَمِعْتُ ابْنَ جُرَيْجٍ، يُحَدِّثُ عَنْ عَمْرِو بْنِ شُعَيْبٍ، عَنْ أَبِيهِ، عَنْ عَبْدِ اللَّهِ بْنِ عَمْرِو بْنِ الْعَاصِ، أَنَّ رَسُولَ اللَّهِ صلى الله عليه وسلم قَالَ ‏ \"‏ تَعَافَوُا الْحُدُودَ فِيمَا بَيْنَكُمْ فَمَا بَلَغَنِي مِنْ حَدٍّ فَقَدْ وَجَبَ ‏\"‏ ‏.‏","Narrated Abdullah ibn Amr ibn al-'As: The Prophet (ﷺ) said: Forgive the infliction of prescribed penalties among yourselves, for any prescribed penalty of which I hear must be carried out","","Sahih"],[4377,4377,4377,"। ইয়াযীদ ইবনু সুআইম (রাঃ) থেকে তার পিতার সূত্রে বর্ণিত। মাঈয নামক জনৈক ব্যক্তি নবী সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম-এর নিকট এসে চার বার (যেনার কথা) স্বীকার করে। সুতরাং তিনি তাকে পাথর মেরে হত্যা করার আদেশ দেন। আর তিনি হাজ্জালকে বলেন, তুমি যদি এটা তোমার কাপড় দিয়ে ঢেকে রাখতে, তাহলে তোমার কল্যাণ হতো।[1] দুর্বল।","حَدَّثَنَا مُسَدَّدٌ، حَدَّثَنَا يَحْيَى، عَنْ سُفْيَانَ، عَنْ زَيْدِ بْنِ أَسْلَمَ، عَنْ يَزِيدَ بْنِ نُعَيْمٍ، عَنْ أَبِيهِ، أَنَّ مَاعِزًا، أَتَى النَّبِيَّ صلى الله عليه وسلم فَأَقَرَّ عِنْدَهُ أَرْبَعَ مَرَّاتٍ فَأَمَرَ بِرَجْمِهِ وَقَالَ لِهَزَّالٍ ‏ \"‏ لَوْ سَتَرْتَهُ بِثَوْبِكَ كَانَ خَيْرًا لَكَ ‏\"‏ ‏.‏","Narrated Nu'aym: Ma'iz came to the Prophet (ﷺ) and admitted (having committed adultery) four times in his presence so he ordered him to be stoned to death, but said to Huzzal: If you had covered him with your garment, it would have been better for you","","Daif"],[4378,4378,4378,"। ইবনুল মুনকাদির (রহঃ) সূত্রে বর্ণিত। হাজ্জাল মাঈযকে নবী সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম-এর নিকট এস (তার অপরাধের কথা) তাঁকে অবহিত করতে আদেশ দেন।[1] যঈফ মুরসাল।","حَدَّثَنَا مُحَمَّدُ بْنُ عُبَيْدٍ، حَدَّثَنَا حَمَّادُ بْنُ زَيْدٍ، حَدَّثَنَا يَحْيَى، عَنِ ابْنِ الْمُنْكَدِرِ، أَنَّ هَزَّالاً، أَمَرَ مَاعِزًا أَنْ يَأْتِيَ النَّبِيَّ صلى الله عليه وسلم فَيُخْبِرَهُ ‏.‏","Ibn al-Muakadir said:Huzzal had ordered Ma’iz to go to the prophet (ﷺ) and tell him(about his having committed adultery)","","Daif"],[4379,4379,4379,"। আলকামাহ ইবনু ওয়াইল (রহঃ) থেকে তার পিতার সূত্রে বর্ণিত। নবী সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম-এর যুগে জনৈকা মহিলা সালাত আদায়ের উদ্দেশ্যে যাচ্ছিল। পথিমধ্যে এক ব্যক্তি তাকে নাগালে পেয়ে তার উপর চেপে বসে তাকে ধর্ষণ করে। সে চিৎকার দিলে লোকটি সরে পড়ে। এ সময় অপর এক ব্যক্তি তার পাশ দিয়ে যাচ্ছিল। সে (ভুলবশত) বললো, এ লোকটি আমার সঙ্গে এরূপ এরূপ করেছে। এ সময় মুহাজিরদের একটি দল এ পথ দিয়ে যাচ্ছিলেন। স্ত্রীলোকটি বললো, এ লোকটি অমার সঙ্গে এরূপ করেছে। অতএব যার সম্পর্কে মহিলাটি অভিযোগ করেছে তারা দ্রুত এগিয়ে লোকটিকে ধরলো। অতঃপর তারা তাকে তার নিকট নিয়ে আসলে সে বললো, হ্যাঁ, এ সেই ব্যক্তি। তারা তাকে নিয়ে রাসূলুল্লাহ সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম-এর নিকট উপস্থিত হলেন। তিনি তার সম্পর্কে ফায়সালা করতেই আসল অপরাধী দাঁড়িয়ে বললো, হে আল্লাহ রাসূল! আমিই অপরাধী। তিনি ধর্ষিতা মহিলাটিকে বললেনঃ তুমি চলে যাও, আল্লাহ তোমাকে ক্ষমা করেছেন আর নির্দোষ ব্যক্তি সম্পর্কে উত্তম কথা বললেন। যে ধর্ষনের অপরাধী তার ব্যাপারে তিনি বললেনঃ তোমরা একে পাথর মারো। তিনি (সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম) বললেনঃ সে এমন তওবা করেছে যে, মদীনাবাসী যদি এরূফ তওবা করে, তবে তাদের পক্ষ থেকে তা অবশ্যই কবূল হবে।[1] হাসান, এ কথাটি বাদেঃ ‘‘তোমরা একে পাথর মারো।’’ অগ্রাধিকারযোগ্য কথা হলো, তাকে পাথর মারা হয়নি।","حَدَّثَنَا مُحَمَّدُ بْنُ يَحْيَى بْنِ فَارِسٍ، حَدَّثَنَا الْفِرْيَابِيُّ، حَدَّثَنَا إِسْرَائِيلُ، حَدَّثَنَا سِمَاكُ بْنُ حَرْبٍ، عَنْ عَلْقَمَةَ بْنِ وَائِلٍ، عَنْ أَبِيهِ، أَنَّ امْرَأَةً، خَرَجَتْ عَلَى عَهْدِ النَّبِيِّ صلى الله عليه وسلم تُرِيدُ الصَّلاَةَ فَتَلَقَّاهَا رَجُلٌ فَتَجَلَّلَهَا فَقَضَى حَاجَتَهُ مِنْهَا فَصَاحَتْ وَانْطَلَقَ فَمَرَّ عَلَيْهَا رَجُلٌ فَقَالَتْ إِنَّ ذَاكَ فَعَلَ بِي كَذَا وَكَذَا وَمَرَّتْ عِصَابَةٌ مِنَ الْمُهَاجِرِينَ فَقَالَتْ إِنَّ ذَلِكَ الرَّجُلَ فَعَلَ بِي كَذَا وَكَذَا ‏.‏ فَانْطَلَقُوا فَأَخَذُوا الرَّجُلَ الَّذِي ظَنَّتْ أَنَّهُ وَقَعَ عَلَيْهَا فَأَتَوْهَا بِهِ فَقَالَتْ نَعَمْ هُوَ هَذَا ‏.‏ فَأَتَوْا بِهِ النَّبِيَّ صلى الله عليه وسلم فَلَمَّا أَمَرَ بِهِ قَامَ صَاحِبُهَا الَّذِي وَقَعَ عَلَيْهَا فَقَالَ يَا رَسُولَ اللَّهِ أَنَا صَاحِبُهَا ‏.‏ فَقَالَ ‏\"‏ اذْهَبِي فَقَدْ غَفَرَ اللَّهُ لَكِ ‏\"‏ ‏.‏ وَقَالَ لِلرَّجُلِ قَوْلاً حَسَنًا ‏.‏ قَالَ أَبُو دَاوُدَ يَعْنِي الرَّجُلَ الْمَأْخُوذَ وَقَالَ لِلرَّجُلِ الَّذِي وَقَعَ عَلَيْهَا ‏\"‏ ارْجُمُوهُ ‏\"‏ ‏.‏ فَقَالَ ‏\"‏ لَقَدْ تَابَ تَوْبَةً لَوْ تَابَهَا أَهْلُ الْمَدِينَةِ لَقُبِلَ مِنْهُمْ ‏\"‏ ‏.‏ قَالَ أَبُو دَاوُدَ رَوَاهُ أَسْبَاطُ بْنُ نَصْرٍ أَيْضًا عَنْ سِمَاكٍ ‏.‏","Narrated Wa'il ibn Hujr: When a woman went out in the time of the Prophet (ﷺ) for prayer, a man attacked her and overpowered (raped) her. She shouted and he went off, and when a man came by, she said: That (man) did such and such to me. And when a company of the Emigrants came by, she said: That man did such and such to me. They went and seized the man whom they thought had had intercourse with her and brought him to her. She said: Yes, this is he. Then they brought him to the Messenger of Allah (ﷺ). When he (the Prophet) was about to pass sentence, the man who (actually) had assaulted her stood up and said: Messenger of Allah, I am the man who did it to her. He (the Prophet) said to her: Go away, for Allah has forgiven you. But he told the man some good words (AbuDawud said: meaning the man who was seized), and of the man who had had intercourse with her, he said: Stone him to death. He also said: He has repented to such an extent that if the people of Medina had repented similarly, it would have been accepted from them. Abu Dawud said: Asbat bin Nasr has also transmitted it from Simak","","Hasan"],[4380,4380,4380,"। আবূ উমাইয়্যাহ আল-মাখযুমী (রাঃ) সূত্রে বর্ণিত। একদা নবী সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম-এর নিকট একটি চোর ধরে আনা হলো। সে অপরাধের কথা স্বীকার করেছে কিন্তু তার নিকট কোনো মাল পাওয়া যায়নি। রাসূলুল্লাহ সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম বললেনঃ আমার মনে হয় তুমি চুরি করনি। সে বললো, হ্যাঁ, আমি চুরি করেছি। তিনি দু’ বার অথবা তিনবার তার নিকট একথার পুনরাবৃত্তি করলেন, কিন্তু সে বারবার একই উত্তর দিলো। অতঃপর তিনি আদেশ করলে তার হাত কেটে তাকে আনা হলে তিনি বললেনঃ আল্লাহর কাছে ক্ষমা প্রার্থনা করো এবং তাঁর নিকট তওবা করো। সে বললো, আমি আল্লাহর নিকট ক্ষমা চাচ্ছি এবং তওবা করছি। অতঃপর তিনি তিনবার বলেনঃ হে আল্লাহ! তুমি তার তওবা কবূল করো।[1] দুর্বল।","حَدَّثَنَا مُوسَى بْنُ إِسْمَاعِيلَ، حَدَّثَنَا حَمَّادٌ، عَنْ إِسْحَاقَ بْنِ عَبْدِ اللَّهِ بْنِ أَبِي طَلْحَةَ، عَنْ أَبِي الْمُنْذِرِ، مَوْلَى أَبِي ذَرٍّ عَنْ أَبِي أُمَيَّةَ الْمَخْزُومِيِّ، أَنَّ النَّبِيَّ صلى الله عليه وسلم أُتِيَ بِلِصٍّ قَدِ اعْتَرَفَ اعْتِرَافًا وَلَمْ يُوجَدْ مَعَهُ مَتَاعٌ فَقَالَ رَسُولُ اللَّهِ صلى الله عليه وسلم ‏\"‏ مَا إِخَالُكَ سَرَقْتَ ‏\"‏ ‏.‏ قَالَ بَلَى ‏.‏ فَأَعَادَ عَلَيْهِ مَرَّتَيْنِ أَوْ ثَلاَثًا فَأَمَرَ بِهِ فَقُطِعَ وَجِيءَ بِهِ فَقَالَ ‏\"‏ اسْتَغْفِرِ اللَّهَ وَتُبْ إِلَيْهِ ‏\"‏ ‏.‏ فَقَالَ أَسْتَغْفِرُ اللَّهَ وَأَتُوبُ إِلَيْهِ فَقَالَ ‏\"‏ اللَّهُمَّ تُبْ عَلَيْهِ ‏\"‏ ‏.‏ ثَلاَثًا ‏.‏ قَالَ أَبُو دَاوُدَ رَوَاهُ عَمْرُو بْنُ عَاصِمٍ عَنْ هَمَّامٍ عَنْ إِسْحَاقَ بْنِ عَبْدِ اللَّهِ قَالَ عَنْ أَبِي أُمَيَّةَ رَجُلٍ مِنَ الأَنْصَارِ عَنِ النَّبِيِّ صلى الله عليه وسلم ‏.‏","Narrated AbuUmayyah al-Makhzumi: A thief who had accepted (having committed theft) was brought to the Prophet (ﷺ), but no good were found with him. The Messenger of Allah (ﷺ), said to him: I do not think you have stolen. He said: Yes, I have. He repeated it twice or thrice. So he gave orders. His hand was cut off and he was then brought to him. He said: Ask Allah's pardon and turn to Him in repentance. He said: I ask Allah's pardon and turn to Him in repentance. He (the Prophet) then said: O Allah, accept his repentance. Abu Dawud said: It has been transmitted by 'Amr b. Asim, from Hammam, from Ishaq b. 'Abd Allah from Abu Ummayyah, a man of the Ansar from the Prophet (ﷺ)","","Daif"],[4381,4381,4381,"। আবূ উমামাহ (রাঃ) সূত্রে বর্ণিত। একদা এক ব্যক্তি রাসূলুল্লাহ সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম-এর নিকট এসে বললো, হে আল্লাহর রাসূল! আমি হদ্দযোগ্য অপরাধ করেছি। কাজেই আমাকে শাস্তি দিন। তিনি প্রশ্ন করলেনঃ তুমি আসার সময় উযু করেছো কি? সে বললো, হ্যাঁ। তিনি আবার প্রশ্ন করলেনঃ আমরা সালাত আদায়ের সময় তুমি কি আমাদের সঙ্গে সালাত আদায় করেছো? সে বললো, হ্যাঁ। তিনি বললেনঃ চলে যাও, নিশ্চয়ই আল্লাহ তোমার অপরাধ ক্ষমা করেছেন।[1] সহীহ।","حَدَّثَنَا مَحْمُودُ بْنُ خَالِدٍ، حَدَّثَنَا عُمَرُ بْنُ عَبْدِ الْوَاحِدِ، عَنِ الأَوْزَاعِيِّ، قَالَ حَدَّثَنِي أَبُو عَمَّارٍ، حَدَّثَنِي أَبُو أُمَامَةَ، أَنَّ رَجُلاً، أَتَى النَّبِيَّ صلى الله عليه وسلم فَقَالَ يَا رَسُولَ اللَّهِ إِنِّي أَصَبْتُ حَدًّا فَأَقِمْهُ عَلَىَّ ‏.‏ قَالَ ‏\"‏ تَوَضَّأْتَ حِينَ أَقْبَلْتَ ‏\"‏ ‏.‏ قَالَ نَعَمْ ‏.‏ قَالَ ‏\"‏ هَلْ صَلَّيْتَ مَعَنَا حِينَ صَلَّيْنَا ‏\"‏ ‏.‏ قَالَ نَعَمْ ‏.‏ قَالَ ‏\"‏ اذْهَبْ فَإِنَّ اللَّهَ تَعَالَى قَدْ عَفَا عَنْكَ ‏\"‏ ‏.‏","Abu ‘Umamah said :A man came to the prophet (ﷺ) and said : Messenger of Allah ! I have committed a crime which involves prescribed punishment so inflict it on me . He said : Have you not performed ablution when you came? He said : Yes, He said: Have you not prayed with us when we prayed ? He said : Yes .He then said : Go off, for Allah, the Exalted, forgave you","","Sahih"],[4382,4382,4382,"। আযহাব ইবনু আব্দুল্লাহ আল-হারাযী (রাঃ) সূত্রে বর্ণিত। কিলা‘আ এলাকার কিছু লোকের মাল চুরি হলে তারা একদল তাঁতীর বিরুদ্ধে অভিযোগ করলো। অতঃপর তারা নবী সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম-এর সাহাবী নু‘মান ইবনু বশীরের নিকট (ঐ অভিযুক্তদের) নিয়ে এলো। তিনি তাদের কয়েক দিন আটকে রাখার পর ছেড়ে দেন। অভিযোগকারীরা এসে নু‘মান (রাঃ)-কে বললো, মারধর ও তদন্ত ছাড়াই আপনি তাদের ছেড়ে দিলেন? নু‘মান (রাঃ) বললেন, তোমরা কি চাও? তোমরা যদি চাও আমি তোমাদের মারধর করি। আর তাতে যদি তোমাদের মাল উদ্ধার হয় তবে তো ভালো। অন্যথায় আমি তাদের পিঠে যেরূপ আঘাত করবো, সেরূপ আঘাত তোমাদের পিঠেও করবো। তারা বললো, এটা কি আপনার ফায়সালা? তিনি বললেন, এটা আল্লাহ ও রাসূলুল্লাহ সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম-এর ফায়সালা। ইমাম আবূ দাঊদ (রহঃ) বলেন, এ কথার দ্বারা তিনি তাদেরকে সতর্ক করেছেন। অর্থাৎ স্বেচ্ছায় স্বীকার করার পরই প্রহার করা যেতে পারে।[1] হাসান।","حَدَّثَنَا عَبْدُ الْوَهَّابِ بْنُ نَجْدَةَ، حَدَّثَنَا بَقِيَّةُ، حَدَّثَنَا صَفْوَانُ، حَدَّثَنَا أَزْهَرُ بْنُ عَبْدِ اللَّهِ الْحَرَازِيُّ، أَنَّ قَوْمًا، مِنَ الْكَلاَعِيِّينَ سُرِقَ لَهُمْ مَتَاعٌ فَاتَّهَمُوا أُنَاسًا مِنَ الْحَاكَةِ فَأَتَوُا النُّعْمَانَ بْنَ بَشِيرٍ صَاحِبَ النَّبِيِّ صلى الله عليه وسلم فَحَبَسَهُمْ أَيَّامًا ثُمَّ خَلَّى سَبِيلَهُمْ فَأَتَوُا النُّعْمَانَ فَقَالُوا خَلَّيْتَ سَبِيلَهُمْ بِغَيْرِ ضَرْبٍ وَلاَ امْتِحَانٍ ‏.‏ فَقَالَ النُّعْمَانُ مَا شِئْتُمْ إِنْ شِئْتُمْ أَنْ أَضْرِبَهُمْ فَإِنْ خَرَجَ مَتَاعُكُمْ فَذَاكَ وَإِلاَّ أَخَذْتُ مِنْ ظُهُورِكُمْ مِثْلَ مَا أَخَذْتُ مِنْ ظُهُورِهِمْ ‏.‏ فَقَالُوا هَذَا حُكْمُكَ فَقَالَ هَذَا حُكْمُ اللَّهِ وَحُكْمُ رَسُولِهِ صلى الله عليه وسلم ‏.‏ قَالَ أَبُو دَاوُدَ إِنَّمَا أَرْهَبَهُمْ بِهَذَا الْقَوْلِ أَىْ لاَ يَجِبُ الضَّرْبُ إِلاَّ بَعْدَ الاِعْتِرَافِ ‏.‏","Azhar ibn Abdullah al-Harari said:Some goods of the people of Kila' were stolen. They accused some men of the weavers (of theft). They came to an-Nu'man ibn Bashir, the companion of the Prophet (ﷺ). He confined them for some days and then set them free. They came to an-Nu'man and said: You have set them free without beating and investigation. An-Nu'man said: What do you want? You want me to beat them. If your goods are found with them, then it is all right; otherwise, I shall take (retaliation) from your back as I have taken from their backs. They asked: Is this your decision? He said: This is the decision of Allah and His Apostle (ﷺ). Abu Dawud said: By this statement he frightened them ; that is, beating is not necessary except after acknowledgement","","Hasan"],[4383,4383,4383,"। আয়িশাহ (রাঃ) সূত্রে বর্ণিত। নবী সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম এক দীনারের এক-চতুর্থাংশ বা এর চাইতে বেশী চুরির অপরাধে চোরের হাত কাটতেন।[1] সহীহ।","حَدَّثَنَا أَحْمَدُ بْنُ مُحَمَّدِ بْنِ حَنْبَلٍ، حَدَّثَنَا سُفْيَانُ، عَنِ الزُّهْرِيِّ، قَالَ سَمِعْتُهُ مِنْهُ، عَنْ عَمْرَةَ، عَنْ عَائِشَةَ، رضى الله عنها أَنَّ النَّبِيَّ صلى الله عليه وسلم كَانَ يَقْطَعُ فِي رُبْعِ دِينَارٍ فَصَاعِدًا ‏.‏","‘A’ishah said:The prophet (ﷺ) used to cut off a thief’s hand for a quarter of a dinar and upwards","","Sahih"],[4384,4384,4384,"। আয়িশাহ (রাঃ) সূত্রে বর্ণিত। নবী সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম বলেনঃ দীনারের এক-চতুর্থাংশ অথবা এর চেয়ে বেশী পরিমাণ সম্পদ চুরির দায়ে চোরের হাত কাটা হবে। আহমাদ ইবনু সালিহ বলেন, দীনারের এক-চতুর্থাংশ বা এর চেয়ে বেশী সম্পদ চুরির অপরাধে হাত কাটা যায়।।[1] সহীহ।","حَدَّثَنَا أَحْمَدُ بْنُ صَالِحٍ، وَوَهْبُ بْنُ بَيَانٍ، قَالاَ حَدَّثَنَا ح، وَحَدَّثَنَا ابْنُ السَّرْحِ، قَالَ أَخْبَرَنَا ابْنُ وَهْبٍ، أَخْبَرَنِي يُونُسُ، عَنِ ابْنِ شِهَابٍ، عَنْ عُرْوَةَ، وَعَمْرَةَ، عَنْ عَائِشَةَ، رضى الله عنها عَنِ النَّبِيِّ صلى الله عليه وسلم قَالَ ‏ \"‏ تُقْطَعُ يَدُ السَّارِقِ فِي رُبْعِ دِينَارٍ فَصَاعِدًا ‏\"‏ ‏.‏ قَالَ أَحْمَدُ بْنُ صَالِحٍ الْقَطْعُ فِي رُبْعِ دِينَارٍ فَصَاعِدًا ‏.‏","‘A’ishah reported the prophet (ﷺ) as saying :A thief’s hand should be cut off for a quarter of a dinar and upwards. Ahmed b. Salih said: The amputation (of a thief’s hand) is for a quarter of a dinar and upwards","","Sahih"],[4385,4385,4385,"। ইবনু উমার (রাঃ) সূত্রে বর্ণিত। রাসূলুল্লাহ সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম তিন দিরহাম মূল্যের বর্ম চুরির দায়ে চোরের হাত কেটেছেন।[1] সহীহ।","حَدَّثَنَا عَبْدُ اللَّهِ بْنُ مَسْلَمَةَ، حَدَّثَنَا مَالِكٌ، عَنْ نَافِعٍ، عَنِ ابْنِ عُمَرَ، أَنَّ رَسُولَ اللَّهِ صلى الله عليه وسلم قَطَعَ فِي مِجَنٍّ ثَمَنُهُ ثَلاَثَةُ دَرَاهِمَ ‏.‏","Ibn ‘Umar’ said:The Messenger of Allah (ﷺ) had thief’s hand cut off for a shield worth three dirhams","","Sahih"],[4386,4386,4386,"। আব্দুল্লাহ ইবনু উমার (রাঃ) সূত্রে বর্ণিত। নবী সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম এমন এক চোরের হাত কেটেছেন, যে মহিলাদের জন্য নির্দিষ্ট স্থান থেকে তিন দিরহাম মূল্যের একটি বর্ম চুরি করেছিল।[1] সহীহ।","حَدَّثَنَا أَحْمَدُ بْنُ حَنْبَلٍ، حَدَّثَنَا عَبْدُ الرَّزَّاقِ، أَخْبَرَنَا ابْنُ جُرَيْجٍ، أَخْبَرَنِي إِسْمَاعِيلُ بْنُ أُمَيَّةَ، أَنَّ نَافِعًا، مَوْلَى عَبْدِ اللَّهِ بْنِ عُمَرَ حَدَّثَهُ أَنَّ عَبْدَ اللَّهِ بْنَ عُمَرَ حَدَّثَهُمْ أَنَّ النَّبِيَّ صلى الله عليه وسلم قَطَعَ يَدَ رَجُلٍ سَرَقَ تُرْسًا مِنْ صُفَّةِ النِّسَاءِ ثَمَنُهُ ثَلاَثَةُ دَرَاهِمَ ‏.‏","Narrated Abdullah ibn Umar: The Prophet (ﷺ) had a man's hand cut off who had stolen from the place reserved for women a shield whose price was three dirhams","","Sahih"],[4387,4387,4387,"। ইবনু আব্বাস (রাঃ) সূত্রে বর্ণিত। তিনি বলেন, রাসূলুল্লাহ সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম এক দীনার অথবা দশ দিরহাম মূল্যের বর্ম চুরির অপরাধে এক ব্যক্তির হাত কেটেছেন।[1] শায।","حَدَّثَنَا عُثْمَانُ بْنُ أَبِي شَيْبَةَ، وَمُحَمَّدُ بْنُ أَبِي السَّرِيِّ الْعَسْقَلاَنِيُّ، - وَهَذَا لَفْظُهُ وَهُوَ أَتَمُّ - قَالاَ حَدَّثَنَا ابْنُ نُمَيْرٍ عَنْ مُحَمَّدِ بْنِ إِسْحَاقَ عَنْ أَيُّوبَ بْنِ مُوسَى عَنْ عَطَاءٍ عَنِ ابْنِ عَبَّاسٍ قَالَ قَطَعَ رَسُولُ اللَّهِ صلى الله عليه وسلم يَدَ رَجُلٍ فِي مِجَنٍّ قِيمَتُهُ دِينَارٌ أَوْ عَشْرَةُ دَرَاهِمَ ‏.‏ قَالَ أَبُو دَاوُدَ رَوَاهُ مُحَمَّدُ بْنُ سَلَمَةَ وَسَعْدَانُ بْنُ يَحْيَى عَنِ ابْنِ إِسْحَاقَ بِإِسْنَادِهِ ‏.‏","Narrated Abdullah ibn Abbas: The Messenger of Allah (ﷺ) had a man's hand cut off for (stealing) a shield whose price was a dinar or ten dirhams. Abu Dawud said: Muhammad bin Salamah and Sa'dan bin Yahya have transmitted it from Ibn Ishaq through his chain of narrators","","Daif"],[4388,4388,4388,"। মুহাম্মাদ ইবনু ইয়াহইয়া ইবনু হাব্বান (রাঃ) সূত্রে বর্ণিত। একদা একটি গোলাম এক ব্যক্তির বাগান থেকে খেজুরের চারা চুরি করে এনে তার মনিবের বাগানে রোপণ করে। চারাগাছের মালিক তা খুঁজতে খুঁজতে পেয়ে যায় এবং এ গোলামের ব্যাপারে তৎকালীন মদীনার গভর্নর মাওয়ান ইবনুল হাকামের কাছে বিচার প্রার্থী হয়। মারওয়ান গোলামটিকে বন্দী করে রাখেন এবং তার হাত কাটতে মনস্থ করেন। অতঃপর গোলামটির মনিব রাফি‘ ইবনু খাদীজ (রাঃ)-এর নিকট গিয়ে এ ব্যাপারে প্রশ্ন করলে তিনি তার নিকট বর্ণনা করেন যে, তিনি রাসূলুল্লাহ সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম-কে বলতে শুনেছেনঃ ফল আর খেজুরের চারা চুরির অপরাধে হাত কাটা যাবে না। লোকটি বললো, মারওয়ান তো আমার গোলামকে ধরে রেখেছেন আর তার হাত কাটতে চাচ্ছেন। আমি চাই, আপনি আমার সাথে তার নিকট গিয়ে রাসূলুল্লাহ সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম-এর নিকট এ ব্যাপারে যা শুনেছেন, তা তাকে জানাবেন। অতঃপর রাফি‘ ইবনু খাদীজ (রাঃ) তার সঙ্গে মারওয়ান ইবনু হাকামের নিকট গিয়ে বলেন, আমি রাসূলুল্লাহ সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম-কে বলতে শুনেছিঃ ‘ফল আর খেজুরের চারা চুরির অপরাধে হাত কাটা যাবে না।’ অতঃপর মারওয়ানের আদেশে গোলামটিকে ছেড়ে দেয়া হয়।[1] সহীহ।","حَدَّثَنَا عَبْدُ اللَّهِ بْنُ مَسْلَمَةَ، عَنْ مَالِكِ بْنِ أَنَسٍ، عَنْ يَحْيَى بْنِ سَعِيدٍ، عَنْ مُحَمَّدِ بْنِ يَحْيَى بْنِ حَبَّانَ، أَنَّ عَبْدًا، سَرَقَ وَدِيًّا مِنْ حَائِطِ رَجُلٍ فَغَرَسَهُ فِي حَائِطِ سَيِّدِهِ فَخَرَجَ صَاحِبُ الْوَدِيِّ يَلْتَمِسُ وَدِيَّهُ فَوَجَدَهُ فَاسْتَعْدَى عَلَى الْعَبْدِ مَرْوَانَ بْنَ الْحَكَمِ وَهُوَ أَمِيرُ الْمَدِينَةِ يَوْمَئِذٍ فَسَجَنَ مَرْوَانُ الْعَبْدَ وَأَرَادَ قَطْعَ يَدِهِ فَانْطَلَقَ سَيِّدُ الْعَبْدِ إِلَى رَافِعِ بْنِ خَدِيجٍ فَسَأَلَهُ عَنْ ذَلِكَ فَأَخْبَرَهُ أَنَّهُ سَمِعَ رَسُولَ اللَّهِ صلى الله عليه وسلم يَقُولُ ‏\"‏ لاَ قَطْعَ فِي ثَمَرٍ وَلاَ كَثَرٍ ‏\"‏ ‏.‏ فَقَالَ الرَّجُلُ إِنَّ مَرْوَانَ أَخَذَ غُلاَمِي وَهُوَ يُرِيدُ قَطْعَ يَدِهِ وَأَنَا أُحِبُّ أَنْ تَمْشِيَ مَعِي إِلَيْهِ فَتُخْبِرَهُ بِالَّذِي سَمِعْتَ مِنْ رَسُولِ اللَّهِ صلى الله عليه وسلم فَمَشَى مَعَهُ رَافِعُ بْنُ خَدِيجٍ حَتَّى أَتَى مَرْوَانَ بْنَ الْحَكَمِ فَقَالَ لَهُ رَافِعٌ سَمِعْتُ رَسُولَ اللَّهِ صلى الله عليه وسلم يَقُولُ ‏\"‏ لاَ قَطْعَ فِي ثَمَرٍ وَلاَ كَثَرٍ ‏\"‏ ‏.‏ فَأَمَرَ مَرْوَانُ بِالْعَبْدِ فَأُرْسِلَ ‏.‏ قَالَ أَبُو دَاوُدَ الْكَثَرُ الْجُمَّارُ ‏.‏","Narrated Rafi' ibn Khadij: Muhammad ibn Yahya ibn Hibban said: A slave stole a plant of a palm-tree from the orchard of a man and planted it in the orchard of his master. The owner of the plant went out in search of the plant and he found it. He solicited help against the slave from Marwan ibn al-Hakam who was the Governor of Medina at that time. Marwan confined the slave and intended to cut off his hand. The slave's master went to Rafi' ibn Khadij and asked him about it. He told him that he had heard the Messenger of Allah (ﷺ) say: The hand is not to be cut off for taking fruit or the pith of the palm-tree. The man then said: Marwan has seized my slave and wants to cut off his hand. I wish you to go with me to him and tell him that which you have heard from the Messenger of Allah (ﷺ). So Rafi' ibn Khadij went with him and came to Marwan ibn al-Hakam. Rafi' said to him: I heard the Messenger of Allah (ﷺ) say: The hand is not to be cut off for taking fruit or the pith of the palm-tree. So Marwan gave orders to release the slave and then he was released. Abu Dawud said: Kathar means pith of the palm-tree","","Sahih"],[4389,4389,4389,"। উপরোক্ত হাদীস বর্ণনা প্রসঙ্গে মুহাম্মাদ ইবনু ইয়াহইয়া ইবনু হাব্বান (রহঃ) বলেন, মারওয়ান তাকে কয়েকটি বেত্রাঘাত করে ছেড়ে দেন।[1] শায।","حَدَّثَنَا مُحَمَّدُ بْنُ عُبَيْدٍ، حَدَّثَنَا حَمَّادٌ، حَدَّثَنَا يَحْيَى، عَنْ مُحَمَّدِ بْنِ يَحْيَى بْنِ حَبَّانَ، بِهَذَا الْحَدِيثِ قَالَ فَجَلَدَهُ مَرْوَانُ جَلَدَاتٍ وَخَلَّى سَبِيلَهُ ‏.‏","This tradition has also been transmitted by Muhammad bin Yahya bin Hibban through a different chain of narrators. This version adds :Marwan gave him some lashes and let him go","","Shadh"],[4390,4390,4390,"। আমর ইবনু শু‘আইব (রহঃ) থেকে পর্যায়ক্রমে তার পিতা ও তার দাদা আব্দুল্লাহ ইবনু আমর ইবনুল আস (রাঃ) সূত্রে বর্ণিত। একদা রাসূলুল্লাহ সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম-কে গাছে ঝুলন্ত ফল সম্পর্কে প্রশ্ন করা হলে তিনি বলেনঃ কোনো ক্ষুধার্ত লোক তা খেলে এবং কাপড়ে বেধে নিয়ে না গেলে তার কোনো অপরাধ নেই। কিন্তু কেউ যদি কাপড়ে বেধে তা থেকে কিছু নিয়ে যায় তবে তাকে এর দ্বিগুণ জরিমানা দিতে হবে এবং শাস্তিও ভোগ করতে হবে। আর কেউ যদি এমন স্থান থেকে তা চুরি করে, যেখানে ফল শুকানোর জন্য রাখা হয়েছে, আর চুরিকৃত ফলের মূল্য একটি বর্মের মূল্যের সমপরিমাণ হয়, তবে তার হাত কাটা যাবে। কেউ উপরোক্ত মূল্যের কম পরিমাণ চুরি করলে তাকে দ্বিগুণ জরিমানা করা হবে এবং তাকে শাস্তিও দেয়া হবে। ইমাম আবূ দাঊদ (রহঃ) বলেন, খেজুর শুকানোর স্থানকে ‘জারীন’ বলা হয়।[1] হাসান।","حَدَّثَنَا قُتَيْبَةُ بْنُ سَعِيدٍ، حَدَّثَنَا اللَّيْثُ، عَنِ ابْنِ عَجْلاَنَ، عَنْ عَمْرِو بْنِ شُعَيْبٍ، عَنْ أَبِيهِ، عَنْ جَدِّهِ عَبْدِ اللَّهِ بْنِ عَمْرِو بْنِ الْعَاصِ، عَنْ رَسُولِ اللَّهِ صلى الله عليه وسلم أَنَّهُ سُئِلَ عَنِ الثَّمَرِ الْمُعَلَّقِ فَقَالَ ‏ \"‏ مَنْ أَصَابَ بِفِيهِ مِنْ ذِي حَاجَةٍ غَيْرَ مُتَّخِذٍ خُبْنَةً فَلاَ شَىْءَ عَلَيْهِ وَمَنْ خَرَجَ بِشَىْءٍ مِنْهُ فَعَلَيْهِ غَرَامَةُ مِثْلَيْهِ وَالْعُقُوبَةُ وَمَنْ سَرَقَ مِنْهُ شَيْئًا بَعْدَ أَنْ يُئْوِيَهُ الْجَرِينُ فَبَلَغَ ثَمَنَ الْمِجَنِّ فَعَلَيْهِ الْقَطْعُ وَمَنْ سَرَقَ دُونَ ذَلِكَ فَعَلَيْهِ غَرَامَةُ مِثْلَيْهِ وَالْعُقُوبَةُ ‏\"‏ ‏.‏ قَالَ أَبُو دَاوُدَ الْجَرِينُ الْجُوخَانُ ‏.‏","Narrated Abdullah ibn Amr ibn al-'As: The Messenger of Allah (ﷺ) was asked about fruit which was bung up and said: If a needy person takes some with his mouth and does not take a supply away in his garment, there is nothing on him, but he who carries any of it is to be fined twice the value and punished, and he who steals any of it after it has been put in the place where dates are dried to have his hand cut off if their value reaches the value of a shield. If he steals a thing less in value than it, he is to be find twice the value and punished. Abu Dawud said: Jarin means the place where dates are dried","","Hasan"],[4391,4391,4391,"। জাবির ইবনু আব্দুল্লাহ (রাঃ) সূত্রে বর্ণিত। রাসূলুল্লাহ সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম বলেনঃ লুণ্ঠনকারীর হাত কাটা যাবে না। যে ব্যক্তি দিবালোকে লুণ্ঠন করে সে আমাদের অন্তর্ভুক্ত নয়।[1] সহীহ।","حَدَّثَنَا نَصْرُ بْنُ عَلِيٍّ، أَخْبَرَنَا مُحَمَّدُ بْنُ بَكْرٍ، حَدَّثَنَا ابْنُ جُرَيْجٍ، قَالَ قَالَ أَبُو الزُّبَيْرِ قَالَ جَابِرُ بْنُ عَبْدِ اللَّهِ قَالَ رَسُولُ اللَّهِ صلى الله عليه وسلم ‏ \"‏ لَيْسَ عَلَى الْمُنْتَهِبِ قَطْعٌ وَمَنِ انْتَهَبَ نُهْبَةً مَشْهُورَةً فَلَيْسَ مِنَّا ‏\"‏ ‏.‏","Narrated Jabir ibn Abdullah: The Prophet (ﷺ) said: Cutting of hand is not to be inflicted on one who plunders, but he who plunders conspicuously does not belong to us","","Sahih"],[4392,4392,4392,"। একই সূত্রে জাবির (রাঃ) বলেন, রাসূলুল্লাহ সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম বলেছেনঃ প্রতারকের হাত কাটা যাবে না।[1] সহীহ।","وَبِهَذَا الإِسْنَادِ قَالَ قَالَ رَسُولُ اللَّهِ صلى الله عليه وسلم ‏ \"‏ لَيْسَ عَلَى الْخَائِنِ قَطْعٌ ‏\"‏ ‏.‏","Narrated Jabir ibn Abdullah: He also said through this chain: The Messenger of Allah (ﷺ) said: Cutting of the hand is not to be inflicted on one who is treacherous","","Sahih"],[4393,4393,4393,"। জাবির (রাঃ) থেকে নবী সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম-এর সূত্রে অনুরূপ হাদীস বর্ণিত। তাতে আরো রয়েছেঃ লুণ্ঠনকারীর হাত কাটা যাবে না। ইমাম আবূ দাঊদ (রহঃ) বলেন, ইবনু জুরাইজ উপরোক্ত হাদীসদ্বয় আবুয-যুবায়র থেকে শুনেননি। আমি আহমাদ ইবনু হাম্বাল (রহঃ) থেকে জেনেছি, তিনি বলেছেন, ইবনু জুরাইজ উপরোক্ত হাদীসদ্বয় ইয়াসীন আয-যাইয়াতের কাছে শুনেছেন। ইমাম আবূ দাঊদ (রহঃ) বলেন, মুগীরাহ ইবনু মুসলিম হাদীসদ্বয় আবূ-যুবায়র (রাঃ) থেকে নবী সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম-এর সূত্রে বর্ণনা করেছেন।[1] সহীহ।","حَدَّثَنَا نَصْرُ بْنُ عَلِيٍّ، أَخْبَرَنَا عِيسَى بْنُ يُونُسَ، عَنِ ابْنِ جُرَيْجٍ، عَنْ أَبِي الزُّبَيْرِ، عَنْ جَابِرٍ، عَنِ النَّبِيِّ صلى الله عليه وسلم بِمِثْلِهِ زَادَ ‏ \"‏ وَلاَ عَلَى الْمُخْتَلِسِ قَطْعٌ ‏\"‏ ‏.‏ قَالَ أَبُو دَاوُدَ هَذَانِ الْحَدِيثَانِ لَمْ يَسْمَعْهُمَا ابْنُ جُرَيْجٍ مِنْ أَبِي الزُّبَيْرِ وَبَلَغَنِي عَنْ أَحْمَدَ بْنِ حَنْبَلٍ أَنَّهُ قَالَ إِنَّمَا سَمِعَهُمَا ابْنُ جُرَيْجٍ مِنْ يَاسِينَ الزَّيَّاتِ ‏.‏ قَالَ أَبُو دَاوُدَ وَقَدْ رَوَاهُمَا الْمُغِيرَةُ بْنُ مُسْلِمٍ عَنْ أَبِي الزُّبَيْرِ عَنْ جَابِرٍ عَنِ النَّبِيِّ صلى الله عليه وسلم ‏.‏","The tradition mentioned above has also been transmitted by Jabir through a different chain of narrators. This version adds :Cutting of the hand is not be inflicted on one who snatches something. Abu Dawud said : Ibn Juraij did not hear these two traditions from Abu al-Zubair, I have been informed by Ahmad. B. Hanbal saving : Ibn Juraij heard them from Yasin al-Zayyat. Aby Dawud said: Al-Mughirah b. Muslim has transmitted it from Abu al-Zubair from Jabir From the prophet(ﷺ)","","Sahih"],[4394,4394,4394,"। সাফওয়ান ইবনু উমাইয়্যাহ (রাঃ) সূত্রে বর্ণিত। তিনি বলেন, একদা আমি তিরিশ দিরহাম মূল্যের আমার একটি চাদরে মসজিদে ঘুমিয়েছিলাম। অতঃপর এক ব্যক্তি এসে আমার কাছ থেকে সেটা টেনে নিয়ে যায়। তাকে হাতে নাতে ধরে নবী সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম-এর আসা হলে তিনি তার হাত কাটার আদেশ দিলেন। বর্ণনাকারী বলেন, আমি তাঁর নিকট হাযির হয়ে বললাম, মাত্র ত্রিশটি দিরহামের কারণে আপনি তার হাত কাটবেন? আমি তার নিটক এটা বাকীতে বিক্রি করছি। তিনি বললেনঃ তুমি তাকে আমার নিকট নিয়ে আসার পূর্বে তা করলে না কেন? ইমাম আবূ দাঊদ (রহঃ) বলেন, যায়িদাহ সিমাকের সূত্রে জুআইদ ইবনু হুযাইর থেকে এ হাদীস বর্ণনা করে বলেন, সাফওয়ান ঘুমিয়েছিলেন। তাউস ও মুজাহিদ এ হাদীস বর্ণনা করে বলেন, তিনি ঘুমন্ত ছিলেন। চোর এসে তার মাথার নীচ থেকে চাঁদরটি চুরি করে নিয়ে যায়। আবূ সালামাহ ইবনু আব্দুর রাহমান এ হাদীস বর্ণনা করে বলেন, চোরটি তার মাথার নীচ থেকে চাদরটা টান দিয়ে নিয়ে যায়। তিনি জাগ্রত হয়ে চিৎকার দেন এবং তাকে ধরে ফেলা হয়। যুহরী (রহঃ) সাফওয়ান ইবনু আব্দুল্লাহ থেকে বর্ণনা করে বলেন, তার চাদরটাকে তিনি বালিশ বানিয়ে মাথার নীচে রেখে মসজিদে ঘুমান। এ সময় এক চোর এসে তার চাদরটা হস্তগত করে। তিনি তাকে ধরে নবী সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম-এর নিকট নিয়ে আসেন।[1] সহীহ।","حَدَّثَنَا مُحَمَّدُ بْنُ يَحْيَى بْنِ فَارِسٍ، حَدَّثَنَا عَمْرُو بْنُ حَمَّادِ بْنِ طَلْحَةَ، حَدَّثَنَا أَسْبَاطٌ، عَنْ سِمَاكِ بْنِ حَرْبٍ، عَنْ حُمَيْدِ ابْنِ أُخْتِ، صَفْوَانَ عَنْ صَفْوَانَ بْنِ أُمَيَّةَ، قَالَ كُنْتُ نَائِمًا فِي الْمَسْجِدِ عَلَى خَمِيصَةٍ لِي ثَمَنُ ثَلاَثِينَ دِرْهَمًا فَجَاءَ رَجُلٌ فَاخْتَلَسَهَا مِنِّي فَأُخِذَ الرَّجُلُ فَأُتِيَ بِهِ رَسُولُ اللَّهِ صلى الله عليه وسلم فَأَمَرَ بِهِ لِيُقْطَعَ ‏.‏ قَالَ فَأَتَيْتُهُ فَقُلْتُ أَنَقْطَعُهُ مِنْ أَجْلِ ثَلاَثِينَ دِرْهَمًا أَنَا أَبِيعُهُ وَأُنْسِئُهُ ثَمَنَهَا قَالَ ‏ \"‏ فَهَلاَّ كَانَ هَذَا قَبْلَ أَنْ تَأْتِيَنِي بِهِ ‏\"‏ ‏.‏ قَالَ أَبُو دَاوُدَ وَرَوَاهُ زَائِدَةُ عَنْ سِمَاكٍ عَنْ جُعَيْدِ بْنِ جُحَيْرٍ قَالَ نَامَ صَفْوَانُ ‏.‏ وَرَوَاهُ مُجَاهِدٌ وَطَاوُسٌ أَنَّهُ كَانَ نَائِمًا فَجَاءَ سَارِقٌ فَسَرَقَ خَمِيصَةً مِنْ تَحْتِ رَأْسِهِ ‏.‏ وَرَوَاهُ أَبُو سَلَمَةَ بْنُ عَبْدِ الرَّحْمَنِ قَالَ فَاسْتَلَّهُ مِنْ تَحْتِ رَأْسِهِ فَاسْتَيْقَظَ فَصَاحَ بِهِ فَأُخِذَ ‏.‏ وَرَوَاهُ الزُّهْرِيُّ عَنْ صَفْوَانَ بْنِ عَبْدِ اللَّهِ قَالَ فَنَامَ فِي الْمَسْجِدِ وَتَوَسَّدَ رِدَاءَهُ فَجَاءَهُ سَارِقٌ فَأَخَذَ رِدَاءَهُ فَأُخِذَ السَّارِقُ فَجِيءَ بِهِ إِلَى النَّبِيِّ صلى الله عليه وسلم ‏.‏","Narrated Safwan bin Umayyah: I was sleeping in the mosque on a cloak mine whose price was thirty dirhams. A man came and pinched it away from me. The man was seized and brought to the Messenger of Allah (ﷺ). He ordered that his hand should be cut off. I came to him and said: Do you cut off only for thirty dirhams ? I sell it to him and make the payment of its price a loan ? He said: Why did you not do so before bringing him to me ? Abu Dawud said: Za'idah has also transmitted it from Simak from Ju'ayd ibn Hujayr. He said: Safwan slept. Mujahid and Tawus said: While he was sleeping a thief came and stole the cloak from beneath his head. The version of AbuSalamah ibn AbdurRahman has: He snatched it away from beneath his head and he awoke. He cried and he (the thief) was seized. Az-Zuhri narrated from Safwan ibn Abdullah. His version has: He slept in the mosque and used his cloak as pillow. A thief came and took his cloak. The thief was seized and brought to the Prophet (ﷺ)","","Sahih"],[4395,4395,4395,"। ইবনু উমার (রাঃ) সূত্রে বর্ণিত। জনৈকা মাখযূমী মহিলা বিভিন্ন জিনিস ধার নিয়ে পরে তা অস্বীকার করতো। নবী সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম-এর নির্দেশে তার হাত কেটে দেয়া হয়। ইমাম আবূ দাঊদ (রহঃ) বলেন, জুরাইরিয়া নাফি‘ থেকে ইবনু উমার অথবা সাফিয়্যাহ বিনতু আবূ উবাইদ সূত্রে বর্ণনা করেনঃ নবী সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম ভাষণ দিতে দাঁড়িয়ে বলেনঃ এমন কোনো মহিলা আছে কি যে আল্লাহ ও তাঁর রাসূলের নিকট তওবা করবে? একথা তিনি তিনবার বলেন। তখন ঐ মহিলাটি সেখানে উপস্থিত ছিলো; কিন্তু সে দাঁড়ায়নি এবং কথাও বলেনি। ইমাম আবূ দাঊদ (রহঃ) বলেন, ইবনু গানাজ নাফি‘র সূত্রে সাফিয়্যাহ বিনতু আবূ উবাইদ সূত্রে এ হাদীস বর্ণনা করে বলেনঃ মহিলাটির বিরুদ্ধে সাক্ষ্য দেয়া হয়।[1] সহীহ।","حَدَّثَنَا الْحَسَنُ بْنُ عَلِيٍّ، وَمَخْلَدُ بْنُ خَالِدٍ، - الْمَعْنَى - قَالاَ حَدَّثَنَا عَبْدُ الرَّزَّاقِ، أَخْبَرَنَا مَعْمَرٌ، - قَالَ مَخْلَدٌ عَنْ مَعْمَرٍ، - عَنْ أَيُّوبَ، عَنْ نَافِعٍ، عَنِ ابْنِ عُمَرَ، أَنَّ امْرَأَةً، مَخْزُومِيَّةً كَانَتْ تَسْتَعِيرُ الْمَتَاعَ وَتَجْحَدُهُ فَأَمَرَ النَّبِيُّ صلى الله عليه وسلم بِهَا فَقُطِعَتْ يَدُهَا ‏.‏ قَالَ أَبُو دَاوُدَ رَوَاهُ جُوَيْرِيَةُ عَنْ نَافِعٍ عَنِ ابْنِ عُمَرَ أَوْ عَنْ صَفِيَّةَ بِنْتِ أَبِي عُبَيْدٍ زَادَ فِيهِ وَأَنَّ النَّبِيَّ صلى الله عليه وسلم قَامَ خَطِيبًا فَقَالَ ‏ \"‏ هَلْ مِنِ امْرَأَةٍ تَائِبَةٍ إِلَى اللَّهِ عَزَّ وَجَلَّ وَرَسُولِهِ ‏\"‏ ‏.‏ ثَلاَثَ مَرَّاتٍ وَتِلْكَ شَاهِدَةٌ فَلَمْ تَقُمْ وَلَمْ تَتَكَلَّمْ ‏.‏ قَالَ أَبُو دَاوُدَ وَرَوَاهُ ابْنُ غَنْجٍ عَنْ نَافِعٍ عَنْ صَفِيَّةَ بِنْتِ أَبِي عُبَيْدٍ قَالَ فِيهِ فَشَهِدَ عَلَيْهَا ‏.‏","Ibn ‘Umar said:A Makhzuml woman used to borrow goods and deny having received them, so the prophet (ﷺ) gave orders and her hand was cut off. Abu Dawud said: Juwairiyyah has transmitted it from Nafi from Ibn ‘Umar or from Safiyyah daughter of Abu ‘Ubaid. This version adds: The prophet (ﷺ) got up and gave an address saying : Is there any woman who repents to Allah, the Exalted, and to his Apostle? He said it three times, That( woman) was present there but she did not get up and speak. Ibn Ghunj transmitted it from Nafi from Safiyyah daughter of Abu ‘Ubaid. This version has : He witnessed to her","","Sahih"],[4396,4396,4396,"। আয়িশাহ (রাঃ) সূত্রে বর্ণিত। এক অপরিচিত মহিলা কিছু পরিচিত লোকের নামে অলংকার ধার নেয়। অতঃপর সে এগুলো বিক্রি করে দেয়। তাকে ধরে নিয়ে নবী সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম-এর নিকট হাযির করা হয়। তিনি তার হাত কাটার নির্দেশ দেন। এ সেই মহিলা যার জন্য উসামাহ ইবনু যায়িদ (রাঃ) সুপারিশ করেছিলেন। আর রাসূলুল্লাহ সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম তার ব্যাপারে যা বলার বলেছিলেন।[1] সহীহ।","حَدَّثَنَا مُحَمَّدُ بْنُ يَحْيَى بْنِ فَارِسٍ، حَدَّثَنَا أَبُو صَالِحٍ، عَنِ اللَّيْثِ، قَالَ حَدَّثَنِي يُونُسُ، عَنِ ابْنِ شِهَابٍ، قَالَ كَانَ عُرْوَةُ يُحَدِّثُ أَنَّ عَائِشَةَ رضى الله عنها قَالَتِ اسْتَعَارَتِ امْرَأَةٌ - تَعْنِي - حُلِيًّا عَلَى أَلْسِنَةِ أُنَاسٍ يُعْرَفُونَ وَلاَ تُعْرَفُ هِيَ فَبَاعَتْهُ فَأُخِذَتْ فَأُتِيَ بِهَا النَّبِيُّ صلى الله عليه وسلم فَأَمَرَ بِقَطْعِ يَدِهَا وَهِيَ الَّتِي شَفَعَ فِيهَا أُسَامَةُ بْنُ زَيْدٍ وَقَالَ فِيهَا رَسُولُ اللَّهِ صلى الله عليه وسلم مَا قَالَ ‏.‏","Narrated Aisha, Ummul Mu'minin: A woman borrowed jewellery through some known persons and she herself was unknown. She then sold them. She was seized and brought to the Prophet (ﷺ). He gave orders that her hand should be cut off. It is this woman about whom Usamah interceded and of her the Messenger of Allah (ﷺ) said whatever he said","","Sahih"],[4397,4397,4397,"। আয়িশাহ (রাঃ) সূত্রে বর্ণিত। তিনি বলেন, মাখযূম গোত্রের এক মহিলা জিনিসপত্র ধার নেয়ার পর তা অস্বীকার করতো। নবী সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম তার হাত কাটতে নির্দেশ দেন। ইবনু শিহাব থেকে বর্ণিত এই হাদীসে আরো আছেঃ অতঃপর নবী সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম তার হাত কেটে দেন।[1] সহীহ।","حَدَّثَنَا عَبَّاسُ بْنُ عَبْدِ الْعَظِيمِ، وَمُحَمَّدُ بْنُ يَحْيَى، قَالاَ حَدَّثَنَا عَبْدُ الرَّزَّاقِ، أَخْبَرَنَا مَعْمَرٌ، عَنِ الزُّهْرِيِّ، عَنْ عُرْوَةَ، عَنْ عَائِشَةَ، قَالَتْ كَانَتِ امْرَأَةٌ مَخْزُومِيَّةٌ تَسْتَعِيرُ الْمَتَاعَ وَتَجْحَدُهُ فَأَمَرَ النَّبِيُّ صلى الله عليه وسلم بِقَطْعِ يَدِهَا وَقَصَّ نَحْوَ حَدِيثِ قُتَيْبَةَ عَنِ اللَّيْثِ عَنِ ابْنِ شِهَابٍ زَادَ فَقَطَعَ النَّبِيُّ صلى الله عليه وسلم يَدَهَا ‏.‏","‘A’ishah said :A Makhzuml woman used to borrow goods and deny having received them. The prophet (ﷺ) gave orders that her hand should be cut off. He (the narrator) then narrated the tradition similar to the one transmitted by Qutaibah from al-Laith from Ibn Shahib. This version adds: The prophet(ﷺ) had her hand cut off","ইবনু শিহাব","Sahih"],[4398,4398,4398,"। আয়িশাহ (রাঃ) সূত্রে বর্ণিত। রাসূলুল্লাহ সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম বলেনঃ তিন ধরণের লোকের উপর থেকে কলম উঠিয়ে নেয়া হয়েছেঃ (১) নিদ্রিত ব্যক্তি, যতক্ষণ না জাগ্রত হয়, (২) অসুস্থ (পাগল) ব্যক্তি, যতক্ষণ না আরোগ্য লাভ করে এবং (৩) অপ্রাপ্ত বয়স্ক বালক, যতক্ষণ না বালেগ হয়।[1] সহীহ।","حَدَّثَنَا عُثْمَانُ بْنُ أَبِي شَيْبَةَ، حَدَّثَنَا يَزِيدُ بْنُ هَارُونَ، أَخْبَرَنَا حَمَّادُ بْنُ سَلَمَةَ، عَنْ حَمَّادٍ، عَنْ إِبْرَاهِيمَ، عَنِ الأَسْوَدِ، عَنْ عَائِشَةَ، رضى الله عنها أَنَّ رَسُولَ اللَّهِ صلى الله عليه وسلم قَالَ ‏ \"‏ رُفِعَ الْقَلَمُ عَنْ ثَلاَثَةٍ عَنِ النَّائِمِ حَتَّى يَسْتَيْقِظَ وَعَنِ الْمُبْتَلَى حَتَّى يَبْرَأَ وَعَنِ الصَّبِيِّ حَتَّى يَكْبَرَ ‏\"‏ ‏.‏","Narrated Aisha, Ummul Mu'minin: The Messenger of Allah (ﷺ) said: There are three (persons) whose actions are not recorded: a sleeper till he awakes, an idiot till he is restored to reason, and a boy till he reaches puberty","","Sahih"],[4399,4399,4399,"। ইবনু আব্বাস (রাঃ) সূত্রে বর্ণিত। তিনি বলেন, একদা যেনার অপরাধে জনৈকা উম্মাদিনীকে ধরে এনে উমার (রাঃ)-এর নিকট হাযির করা হয়। তিনি এ ব্যাপারে লোকদের সঙ্গে পরামর্শ করে তাকে পাথর মেরে হত্যা করার নির্দেশ দেন। এ সময় আলী (রাঃ) তার পাশ দিয়ে যাচ্ছিলেন। তিনি প্রশ্ন করলেন এর কি হয়েছে? উপস্থিত লোকেরা বললো, সে অমুক গোত্রের উম্মাদিনী (পাগল মহিলা), সে যেনা করেছে। উমার (রাঃ) তাকে পাথর মেরে হত্যা করার আদেশ দিয়েছেন। বর্ণনাকারী বলেন, তিনি বললেন, তোমরা তাকে নিয়ে ফিরে যাও। অতঃপর তিনি উমারের নিকট এসে বললে, হে আমীরুল মু‘মিনীন! আপনি কি জানেন না, তিন ধরণের লোকের উপর থেকে কলম উঠিয়ে নেয়া হয়েছেঃ (১) পাগল, যতক্ষণ না সুস্থ হয়, (২) নিদ্রিত ব্যক্তি, যতক্ষণ না জাগ্রত হয় এবং (৩) নাবালেগ শিশু, যতক্ষণ না বালেগ হবে। তিনি বললেন, হ্যাঁ। আলী (রাঃ) বলেন, তাহলে তাকে পাথর মারা হবে কেন? তিনি বলেন, কোনো কারণ নেই। আলী (রাঃ) বলেন, তবে তাকে ছেড়ে দিন। বর্ণনাকারী বলেন, তিনি তাকে ছেড়ে দিলেন এবং ‘আল্লাহু আকবার’ ধ্বনি উচ্চারণ করলেন।[1] সহীহ।","حَدَّثَنَا عُثْمَانُ بْنُ أَبِي شَيْبَةَ، حَدَّثَنَا جَرِيرٌ، عَنِ الأَعْمَشِ، عَنْ أَبِي ظَبْيَانَ، عَنِ ابْنِ عَبَّاسٍ، قَالَ أُتِيَ عُمَرُ بِمَجْنُونَةٍ قَدْ زَنَتْ فَاسْتَشَارَ فِيهَا أُنَاسًا فَأَمَرَ بِهَا عُمَرُ أَنْ تُرْجَمَ فَمُرَّ بِهَا عَلَى عَلِيِّ بْنِ أَبِي طَالِبٍ رِضْوَانُ اللَّهِ عَلَيْهِ فَقَالَ مَا شَأْنُ هَذِهِ قَالُوا مَجْنُونَةُ بَنِي فُلاَنٍ زَنَتْ فَأَمَرَ بِهَا عُمَرُ أَنْ تُرْجَمَ ‏.‏ قَالَ فَقَالَ ارْجِعُوا بِهَا ثُمَّ أَتَاهُ فَقَالَ يَا أَمِيرَ الْمُؤْمِنِينَ أَمَا عَلِمْتَ أَنَّ الْقَلَمَ قَدْ رُفِعَ عَنْ ثَلاَثَةٍ عَنِ الْمَجْنُونِ حَتَّى يَبْرَأَ وَعَنِ النَّائِمِ حَتَّى يَسْتَيْقِظَ وَعَنِ الصَّبِيِّ حَتَّى يَعْقِلَ قَالَ بَلَى ‏.‏ قَالَ فَمَا بَالُ هَذِهِ تُرْجَمُ قَالَ لاَ شَىْءَ ‏.‏ قَالَ فَأَرْسِلْهَا ‏.‏ قَالَ فَأَرْسَلَهَا ‏.‏ قَالَ فَجَعَلَ يُكَبِّرُ ‏.‏","Narrated Ali ibn AbuTalib: Ibn Abbas said: A lunatic woman who had committed adultery was brought to Umar. He consulted the people and ordered that she should be stoned. Ali ibn AbuTalib passed by and said: What is the matter with this (woman)? They said: This is a lunatic woman belonging to a certain family. She has committed adultery. Umar has given orders that she should be stoned. He said: Take her back. He then came to him and said: Commander of the Faithful, do you not know that there are three people whose actions are not recorded: a lunatic till he is restored to reason, a sleeper till he awakes, and a boy till he reaches puberty? He said: Yes. He then asked: Why is it that this woman is being stoned? He said: There is nothing. He then said: Let her go. He (Umar) let her go and began to utter: Allah is most great","","Sahih"],[4400,4400,4400,"। আ‘মাশ (রহঃ) সূত্রে অনুরূপ হাদীস বর্ণিত। এতে রয়েছেঃ তিনি বলেন, নাবালেগ যতক্ষণ না বুদ্ধিমান হবে। তিনি বলেনঃ পাগল যতক্ষণ না সুস্থ জ্ঞানসম্পন্ন হবে। বর্ণনাকারী বলেন, উমার (রাঃ) ‘আল্লাহু আকবার’ ধ্বনি দিতে থাকেন।[1] সহীহ।","حَدَّثَنَا يُوسُفُ بْنُ مُوسَى، حَدَّثَنَا وَكِيعٌ، عَنِ الأَعْمَشِ، نَحْوَهُ وَقَالَ أَيْضًا حَتَّى يَعْقِلَ ‏.‏ وَقَالَ وَعَنِ الْمَجْنُونِ حَتَّى يُفِيقَ ‏.‏ قَالَ فَجَعَلَ عُمَرُ يُكَبِّرُ ‏.‏","A similar tradition has also been transmitted by al-A’mash through a different chain of narrators. He also said :“... . Till he reaches puberty , and a lunatic till he is restored to consciousness.” ‘Umar then began to utter: Allah is most great","","Sahih"],[4401,4401,4401,"। ইবনু আব্বাস (রাঃ) সূত্রে বর্ণিত। তিনি বলেন, একদা আলী ইবনু আবূ তালিব (রাঃ)-এর পাশ দিয়ে যাওয়া ... অতঃপর উসমান ইবনু অবূ শাইরাহ বর্ণিত হাদীসের সমার্থবোধক হাদীস বর্ণিত। তিনি বলেন, আপনার কি মনে নেই, রাসূলুল্লাহ সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম বলেছেনঃ তিন প্রকার লোকের উপর থেকে কলম তুলে রাখা হয়েছেঃ (১) নির্বোধ পাগল, যতক্ষণ না সুস্থ হয়, (২) নিদ্রিত ব্যক্তি, যতক্ষণ না জাগ্রত হয় এবং (৩) নাবালেগ শিশু, যতক্ষণ না প্রাপ্তবয়স্ক হয়। একথা শুনে উমার (রাঃ) বলেন, আপনি সত্যিই বলেছেন। বর্ণনাকারী বলেন, অতঃপর তিনি দন্ডিতাকে ছেড়ে দিলেন।[1] সহীহ।","حَدَّثَنَا ابْنُ السَّرْحِ، أَخْبَرَنَا ابْنُ وَهْبٍ، أَخْبَرَنِي جَرِيرُ بْنُ حَازِمٍ، عَنْ سُلَيْمَانَ بْنِ مِهْرَانَ، عَنْ أَبِي ظَبْيَانَ، عَنِ ابْنِ عَبَّاسٍ، قَالَ مُرَّ عَلَى عَلِيِّ بْنِ أَبِي طَالِبٍ رضى الله عنه بِمَعْنَى عُثْمَانَ ‏.‏ قَالَ أَوَمَا تَذْكُرُ أَنَّ رَسُولَ اللَّهِ صلى الله عليه وسلم قَالَ ‏ \"‏ رُفِعَ الْقَلَمُ عَنْ ثَلاَثَةٍ عَنِ الْمَجْنُونِ الْمَغْلُوبِ عَلَى عَقْلِهِ حَتَّى يُفِيقَ وَعَنِ النَّائِمِ حَتَّى يَسْتَيْقِظَ وَعَنِ الصَّبِيِّ حَتَّى يَحْتَلِمَ ‏\"‏ ‏.‏ قَالَ صَدَقْتَ قَالَ فَخَلَّى عَنْهَا سَبِيلَهَا ‏.‏","Narrated Ali ibn AbuTalib: Ibn Abbas said: A lunatic woman passed by Ali ibn AbuTalib. He then mentioned the rest of the tradition to the same effect as Uthman mentioned. This version has: Do you not remember that the Messenger of Allah (ﷺ) has said: There are three whose actions are not recorded: a lunatic whose mind is deranged till he is restored to consciousness, a sleeper till he awakes, and a boy till he reaches puberty?","","Sahih"],[4402,4402,4402,"। আবূ যিবয়ান (রহঃ) সূত্রে বর্ণিত। তিনি বলেন, হান্নাদ আল-জানবী বলেছেনঃ একদা এক যেনাকারিনীকে উমার (রাঃ)-এর নিকট হাযির করা হলে তিনি তাকে পাথর মেরে হত্যার আদেশ দেন। এ সময় আলী (রাঃ) ঐ পথ দিয়ে যাওয়ার সময় তাকে ছেড়ে দিলেন। উমার (রাঃ) এ সংবাদ পেয়ে আলী (রাঃ)-কে ডেকে পাঠান। আলী (রাঃ) তার নিকট এসে বলেন, হে আমীরুল মু‘মিনীন! আপনি নিশ্চয়ই জানেন যে, রাসূলুল্লাহ সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম বলেছেনঃ তিন প্রকার লোকের উপর থেকে কলম তুলে রাখা হয়েছেঃ (১) নাবালেগ, যতক্ষণ না বালেগ হয়, (২) নিদ্রিত ব্যক্তি, যতক্ষণ না জাগ্রত হয় এবং (৩) পাগল, যতক্ষণ না সুস্থ হয়। আর এ তো অমুক গোত্রের পাগলিনী। সে যা করেছে, সম্ভবত উম্মাদ অবস্থায় তা করেছে। বর্ণনাকারী বলেন। উমার (রাঃ) বলেন, আমার বিষয়টি জানা নেই। অতঃপর আলী (রাঃ) বলেন, আমিও জানতাম না।[1] সহীহঃ এ কথাটি বাদেঃ ‘‘সম্ভবত উম্মাদ অবস্থায়...।’’","حَدَّثَنَا هَنَّادٌ، عَنْ أَبِي الأَحْوَصِ، ح وَحَدَّثَنَا عُثْمَانُ بْنُ أَبِي شَيْبَةَ، حَدَّثَنَا جَرِيرٌ، - الْمَعْنَى - عَنْ عَطَاءِ بْنِ السَّائِبِ، عَنْ أَبِي ظَبْيَانَ، - قَالَ هَنَّادٌ - الْجَنْبِيِّ قَالَ أُتِيَ عُمَرُ بِامْرَأَةٍ قَدْ فَجَرَتْ فَأَمَرَ بِرَجْمِهَا فَمَرَّ عَلِيٌّ رضى الله عنه فَأَخَذَهَا فَخَلَّى سَبِيلَهَا فَأُخْبِرَ عُمَرُ قَالَ ادْعُوا لِي عَلِيًّا ‏.‏ فَجَاءَ عَلِيٌّ رضى الله عنه فَقَالَ يَا أَمِيرَ الْمُؤْمِنِينَ لَقَدْ عَلِمْتَ أَنَّ رَسُولَ اللَّهِ صلى الله عليه وسلم قَالَ ‏ \"‏ رُفِعَ الْقَلَمُ عَنْ ثَلاَثَةٍ عَنِ الصَّبِيِّ حَتَّى يَبْلُغَ وَعَنِ النَّائِمِ حَتَّى يَسْتَيْقِظَ وَعَنِ الْمَعْتُوهِ حَتَّى يَبْرَأَ ‏\"‏ ‏.‏ وَإِنَّ هَذِهِ مَعْتُوهَةُ بَنِي فُلاَنٍ لَعَلَّ الَّذِي أَتَاهَا أَتَاهَا وَهِيَ فِي بَلاَئِهَا ‏.‏ قَالَ فَقَالَ عُمَرُ لاَ أَدْرِي ‏.‏ فَقَالَ عَلِيٌّ عَلَيْهِ السَّلاَمُ وَأَنَا لاَ أَدْرِي ‏.‏","Narrated Ali ibn AbuTalib: AbuZubyan said: A woman who had committed adultery was brought to Umar. He gave orders that she should be stoned. Ali passed by just then. He seized her and let her go. Umar was informed of it. He said: Ask Ali to come to me. Ali came to him and said: Commander of the Faithful, you know that the Messenger of Allah (ﷺ) said: There are three (people) whose actions are not recorded: A boy till he reaches puberty, a sleeper till he awakes, a lunatic till he is restored to reason. This is an idiot (mad) woman belonging to the family of so and so. Someone might have done this action with her when she suffered the fit of lunacy. Umar said: I do not know. Ali said: I do not know","","Sahih"],[4403,4403,4403,"। আলী (রাঃ) সূত্রে বর্ণিত। নবী সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম বলেনঃ তিন ধরণের লোকের উপর থেকে কলম উঠিয়ে নেয়া হয়েছেঃ (১) ঘুমন্ত ব্যক্তি, যতক্ষণ না জাগ্রত হয়, (২) নাবালেগ, যতক্ষণ না সে বালেগ হয় এবং (৩) পাগল, যতক্ষণ না জ্ঞানসম্পন্ন হয়। ইমাম আবূ দাঊদ (রহঃ) বলেন, ইবনু জুরাইজ পর্যায়ক্রমে কাসমম ইবনু ইয়াযীদ থেকে আলী (রাঃ) থেকে নবী সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম-এর সূত্রে এ হাদীস বর্ণনা করেন। তাতে 'বার্ধক্যজনিত কারণে নিস্তেজ বুদ্ধিসম্পন্ন ব্যক্তি' কথাটুকু রয়েছে।[1] সহীহ।","حَدَّثَنَا مُوسَى بْنُ إِسْمَاعِيلَ، حَدَّثَنَا وُهَيْبٌ، عَنْ خَالِدٍ، عَنْ أَبِي الضُّحَى، عَنْ عَلِيٍّ، عَلَيْهِ السَّلاَمُ عَنِ النَّبِيِّ صلى الله عليه وسلم قَالَ ‏\"‏ رُفِعَ الْقَلَمُ عَنْ ثَلاَثَةٍ عَنِ النَّائِمِ حَتَّى يَسْتَيْقِظَ وَعَنِ الصَّبِيِّ حَتَّى يَحْتَلِمَ وَعَنِ الْمَجْنُونِ حَتَّى يَعْقِلَ ‏\"‏ ‏.‏ قَالَ أَبُو دَاوُدَ رَوَاهُ ابْنُ جُرَيْجٍ عَنِ الْقَاسِمِ بْنِ يَزِيدَ عَنْ عَلِيٍّ رضى الله عنه عَنِ النَّبِيِّ صلى الله عليه وسلم زَادَ فِيهِ ‏\"‏ وَالْخَرِفِ ‏\"‏ ‏.‏","Narrated Ali ibn AbuTalib: The Prophet (ﷺ) said: There are three (persons) whose actions are not recorded: a sleeper till he awakes, a boy till he reaches puberty, and a lunatic till he comes to reason. Abu Dawud said: Ibn Juraij has transmitted it from Al-Qasim b. Yazid on the authority of 'Ali from the Prophet (ﷺ). This version adds: \"and an old man who is feeble-minded","","Sahih"],[4404,4404,4404,"। আতিয়্যাহ আল-কুরাযী (রহঃ) সূত্রে বর্ণিত। তিনি বলেন, আমি বনী কুরাইযার বন্দীদের অন্তর্ভুক্ত ছিলাম। তারা দেখতো, যার নাভীর নীচে চুল উঠেছে তাকে হত্যা করা হতো; আর যার উঠেনি, তাকে হত্যা করা হতো না। আর আমি তাদের অন্তর্ভুক্ত ছিলাম, যাদের তা উঠেনি।[1] সহীহ।","حَدَّثَنَا مُحَمَّدُ بْنُ كَثِيرٍ، أَخْبَرَنَا سُفْيَانُ، أَخْبَرَنَا عَبْدُ الْمَلِكِ بْنُ عُمَيْرٍ، حَدَّثَنِي عَطِيَّةُ الْقُرَظِيُّ، قَالَ كُنْتُ مِنْ سَبْىِ بَنِي قُرَيْظَةَ فَكَانُوا يَنْظُرُونَ فَمَنْ أَنْبَتَ الشَّعْرَ قُتِلَ وَمَنْ لَمْ يُنْبِتْ لَمْ يُقْتَلْ فَكُنْتُ فِيمَنْ لَمْ يُنْبِتْ ‏.‏","Narrated Atiyyah al-Qurazi: I was among the captives of Banu Qurayzah. They (the Companions) examined us, and those who had begun to grow hair (pubes) were killed, and those who had not were not killed. I was among those who had not grown hair","","Sahih"],[4405,4405,4405,"। আব্দুল মালিক ইবনু উমাইর (রহঃ) সূত্রে অনুরূপ হাদীস বর্ণিত। আতিয়্যাহ (রাঃ) বলেন, তারা (মুসলিমরা) আমার নাভীর নীচ অনাবৃত করে দেখলো যে, চুল উঠেনি। সুতরাং তারা আমাকে বন্দীদের অন্তর্ভুক্ত করলো।[1] সহীহ।","حَدَّثَنَا مُسَدَّدٌ، حَدَّثَنَا أَبُو عَوَانَةَ، عَنْ عَبْدِ الْمَلِكِ بْنِ عُمَيْرٍ، بِهَذَا الْحَدِيثِ قَالَ فَكَشَفُوا عَانَتِي فَوَجَدُوهَا لَمْ تَنْبُتْ فَجَعَلُونِي فِي السَّبْىِ ‏.‏","The tradition mentioned above has also been transmitted by ‘Abd al- Malik b. ‘Umar through a different chain of narrators. This version has:They uncovered my private parts, and when they found that the hair had not begun to grow they put me among the captives","","Sahih"],[4406,4406,4406,"। ইবনু উমার (রাঃ) সূত্রে বর্ণিত। উহুদ যুদ্ধের সময় তাকে নবী সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম-এর নিকট হাযির করা হয়। তখন তিনি চৌদ্দ বছরের বালক ছিলেন। তিনি তাকে অনুমতি দেননি। আবার খন্দক যুদ্ধের সময়ও তাকে হাযির করা হয়, তখন তিনি ছিলেন পনের বছরের তরুণ। তখন তিনি তাকে (যুদ্ধ করার) অনুমতি দেন।[1] সহীহ।","حَدَّثَنَا أَحْمَدُ بْنُ حَنْبَلٍ، حَدَّثَنَا يَحْيَى، عَنْ عُبَيْدِ اللَّهِ، قَالَ أَخْبَرَنِي نَافِعٌ، عَنِ ابْنِ عُمَرَ، أَنَّ النَّبِيَّ صلى الله عليه وسلم عُرِضَهُ يَوْمَ أُحُدٍ وَهُوَ ابْنُ أَرْبَعَ عَشْرَةَ سَنَةً فَلَمْ يُجِزْهُ وَعُرِضَهُ يَوْمَ الْخَنْدَقِ وَهُوَ ابْنُ خَمْسَ عَشْرَةَ سَنَةً فَأَجَازَهُ ‏.‏","Ibn ‘Umar said:He was presented before the prophet (ﷺ) on the day of Uhd when he was fourteen years old, but he did not allow him (to participate in the battle). He was again presented before him on the day of Khandaq when he was fifteen years old, Then he allowed him","","Sahih"],[4407,4407,4407,"। উবাইদুল্লাহ ইবনু উমার (রাঃ) সূত্রে বর্ণিত। তিনি বলেন, নাফি‘ (রহঃ) বলেছেন, আমি এ হাদীস উমার ইবনু আব্দুর আযীয (রহঃ)-এর নিকট বর্ণনা করলে তিনি বলেন, এ বয়সটাই নাবালেগ ও সাবালেগের মধ্যকার সীমারেখা।[1] সহীহ।","حَدَّثَنَا عُثْمَانُ بْنُ أَبِي شَيْبَةَ، حَدَّثَنَا ابْنُ إِدْرِيسَ، عَنْ عُبَيْدِ اللَّهِ بْنِ عُمَرَ، قَالَ قَالَ نَافِعٌ حَدَّثْتُ بِهَذَا الْحَدِيثِ، عُمَرَ بْنَ عَبْدِ الْعَزِيزِ فَقَالَ إِنَّ هَذَا الْحَدُّ بَيْنَ الصَّغِيرِ وَالْكَبِيرِ ‏.‏","Nafi ‘said:When I mentioned this tradition to ‘Umar.b.’Abd al-Aziz he said : This prescribed punishment is between the minor and the major","","Sahih"],[4408,4408,4408,"। জুনাদাহ ইবনু আবূ উমাইয়্যাহ (রহঃ) সূত্রে বর্ণিত। তিনি বলেন, আমরা বুসর ইবনু আরতাত (রাঃ)-এর সাথে নৌযুদ্ধে ছিলাম। এ সময় মিসদার নামক এক চোরকে ধরে তার নিকট হাযির করা হলো। সে একটি উষ্ট্রী চুরি করেছিল। তিনি বললেন, আমি রাসূলুল্লাহ সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম-কে বলতে শুনেছিঃ সফরে হাত কাটা যাবে না। অন্যথায় আমি অবশ্যই এর হাত কেটে দিতাম।[1] সহীহ।","حَدَّثَنَا أَحْمَدُ بْنُ صَالِحٍ، حَدَّثَنَا ابْنُ وَهْبٍ، أَخْبَرَنِي حَيْوَةُ بْنُ شُرَيْحٍ، عَنْ عَيَّاشِ بْنِ عَبَّاسٍ الْقِتْبَانِيِّ، عَنْ شُيَيْمِ بْنِ بَيْتَانَ، وَيَزِيدَ بْنِ صُبْحٍ الأَصْبَحِيِّ، عَنْ جُنَادَةَ بْنِ أَبِي أُمَيَّةَ، قَالَ كُنَّا مَعَ بُسْرِ بْنِ أَرْطَاةَ فِي الْبَحْرِ فَأُتِيَ بِسَارِقٍ يُقَالُ لَهُ مِصْدَرٌ قَدْ سَرَقَ بُخْتِيَّةً فَقَالَ قَدْ سَمِعْتُ رَسُولَ اللَّهِ صلى الله عليه وسلم يَقُولُ ‏ \"‏ لاَ تُقْطَعُ الأَيْدِي فِي السَّفَرِ ‏\"‏ ‏.‏ وَلَوْلاَ ذَلِكَ لَقَطَعْتُهُ ‏.‏","Narrated Busr ibn Artat: Junadah ibn AbuUmayyah said: We were with Busr ibn Artat on the sea (on an expedition). A thief called Misdar who had stolen a bukhti she-camel was brought. He said: I heard the Messenger of Allah (ﷺ) say: Hands are not to be cut off during a warlike expedition. Had it not been so, I would have cut it off","","Sahih"],[4409,4409,4409,"। আবূ যার (রাঃ) সূত্রে বর্ণিত। তিনি বলেন, রাসূলুল্লাহ সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম আমাকে ডেকে বললেন, হে আবূ যার! আমি বললাম, হে আল্লাহর রাসূল! আমি আপনার সৌভাগ্যপূর্ণ দরবারে উপস্থিত। তিনি বললেনঃ তুমি কী করবে যখন মানুষ মৃত্যুমুখে পতিত হবে এবং তখন একটি ঘর অর্থাৎ কবরের ক্রয়মূল্য হবে একটি ক্রীতদাসের মূল্যের সমান? আমি বললাম, আল্লাহ ও তাঁর রাসূলই ভালো জানেন অথবা আল্লাহ ও তাঁর রাসূল আমার জন্য যা পছন্দ করেন। তিনি বললেনঃ তুমি তখন ধৈর্য ধরবে। ইমাম আবূ দাঊদ (রহঃ) বলেন, হাম্মাদ ইবনু আবূ সুলাইমান বলেছেন, কাফন চোরের হাত কাটতে হবে; কেননা সে মৃত ব্যক্তির ঘরে হানা দেয়।[1] সহীহ।","حَدَّثَنَا مُسَدَّدٌ، حَدَّثَنَا حَمَّادُ بْنُ زَيْدٍ، عَنْ أَبِي عِمْرَانَ، عَنِ الْمُشَعَّثِ بْنِ طَرِيفٍ، عَنْ عَبْدِ اللَّهِ بْنِ الصَّامِتِ، عَنْ أَبِي ذَرٍّ، قَالَ قَالَ لِي رَسُولُ اللَّهِ صلى الله عليه وسلم ‏\"‏ يَا أَبَا ذَرٍّ ‏\"‏ ‏.‏ قُلْتُ لَبَّيْكَ يَا رَسُولَ اللَّهِ وَسَعْدَيْكَ ‏.‏ فَقَالَ ‏\"‏ كَيْفَ أَنْتَ إِذَا أَصَابَ النَّاسَ مَوْتٌ يَكُونُ الْبَيْتُ فِيهِ بِالْوَصِيفِ ‏\"‏ ‏.‏ يَعْنِي الْقَبْرَ ‏.‏ قُلْتُ اللَّهُ وَرَسُولُهُ أَعْلَمُ أَوْ مَا خَارَ اللَّهُ لِي وَرَسُولُهُ ‏.‏ قَالَ ‏\"‏ عَلَيْكَ بِالصَّبْرِ ‏\"‏ ‏.‏ أَوْ قَالَ ‏\"‏ تَصْبِرُ ‏\"‏ ‏.‏ قَالَ أَبُو دَاوُدَ قَالَ حَمَّادُ بْنُ أَبِي سُلَيْمَانَ يُقْطَعُ النَّبَّاشُ لأَنَّهُ دَخَلَ عَلَى الْمَيِّتِ بَيْتَهُ ‏.‏","Narrated AbuDharr: The Messenger of Allah (ﷺ) said to me: O AbuDharr: I replied: At your service and at your pleasure, Messenger of Allah! He said: how will you do when death smites people, and a house, meaning a grave, will cost as much as a slave. I said: Allah and His Apostle know best, or he said: What Allah and His Apostle choose for me. He said: Show endurance, or he said: You may show endurance. Abu Dawud said: Hammad b. Abi Sulaiman said: The hand of one who rifles a grave should be cut off because he had entered the deceased's house","","Sahih"],[4410,4410,4410,"। জাবির ইবনু আব্দুল্লাহ (রাঃ) সূত্রে বর্ণিত। তিনি বলেন, একদা নবী সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম-এর নিকট এক চোরকে ধরে আনা হলে তিনি বলেনঃ তোমরা একে হত্যা করো। তারা বললেন, হে আল্লাহর রাসূল! সে চুরি করেছে। তিনি বললেনঃ এর হাত কেটে দাও। বর্ণনাকারী বলেন, তার হাত কেটে দেয়া হলো। অতঃপর তাকে দ্বিতীয়বার তাঁর নিকট ধরে আনা হলে তিনি বলেনঃ তোমরা একে হত্যা করো। তারা বললেন, হে আল্লাহ রাসূল! সে তো চুরি করেছে। তিনি আদেশ দিলেন, তোমরা এর অপর হাত কেটে দাও। বর্ণনাকারী বলেন, তার হাত কেটে দেয়া হলো। তৃতীয়াবার তাকে তাঁর নিকট ধরে আনা হলে তিনি বলেনঃ তোমরা একে হত্যা করো। তারা বললেন, হে আল্লাহর রাসূল! সে তো চুরি করেছে। তিনি বললেনঃ তাহলে তোমরা তার অঙ্গ (এক পা) কেটে দাও। বর্ণনাকারী বলেন, এবার তার পা কাটা হলো। অতঃপর চতুর্থবার তাকে ধরে আনা হলে তিনি তাকে হত্যা করার আদেশ দেন। লোকেরা বললো, হে আল্লাহর রাসূল! সে তো চুরি করেছে। তিনি বললেনঃ তাহলে তারে (আরেক পা) কেটে দাও। বর্ণনাকারী বলেন, এবারত তার অপর পা কাটা হলো। অতঃপর পঞ্চমবার তাকে ধরে আনা হলে তিনি (সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম) তাকে হত্যা করার আদেশ দেন। জাবির (রাঃ) বলেন, অতএব আমরা তাকে নিয়ে গিয়ে হত্যা করলাম এবং হেঁচড়িয়ে টেনে নিয়ে একটি কূপে ফেলে দিয়ে তার উপর পাথরচাপা দিলাম।[1] হাসান।","حَدَّثَنَا مُحَمَّدُ بْنُ عَبْدِ اللَّهِ بْنِ عُبَيْدِ بْنِ عَقِيلٍ الْهِلاَلِيُّ، حَدَّثَنَا جَدِّي، عَنْ مُصْعَبِ بْنِ ثَابِتِ بْنِ عَبْدِ اللَّهِ بْنِ الزُّبَيْرِ، عَنْ مُحَمَّدِ بْنِ الْمُنْكَدِرِ، عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ، قَالَ جِيءَ بِسَارِقٍ إِلَى النَّبِيِّ صلى الله عليه وسلم فَقَالَ ‏\"‏ اقْتُلُوهُ ‏\"‏ ‏.‏ فَقَالُوا يَا رَسُولَ اللَّهِ إِنَّمَا سَرَقَ ‏.‏ فَقَالَ ‏\"‏ اقْطَعُوهُ ‏\"‏ ‏.‏ قَالَ فَقُطِعَ ثُمَّ جِيءَ بِهِ الثَّانِيَةَ فَقَالَ ‏\"‏ اقْتُلُوهُ ‏\"‏ ‏.‏ فَقَالُوا يَا رَسُولَ اللَّهِ إِنَّمَا سَرَقَ ‏.‏ فَقَالَ ‏\"‏ اقْطَعُوهُ ‏\"‏ ‏.‏ قَالَ فَقُطِعَ ثُمَّ جِيءَ بِهِ الثَّالِثَةَ فَقَالَ ‏\"‏ اقْتُلُوهُ ‏\"‏ ‏.‏ فَقَالُوا يَا رَسُولَ اللَّهِ إِنَّمَا سَرَقَ ‏.‏ قَالَ ‏\"‏ اقْطَعُوهُ ‏\"‏ ‏.‏ ثُمَّ أُتِيَ بِهِ الرَّابِعَةَ فَقَالَ ‏\"‏ اقْتُلُوهُ ‏\"‏ ‏.‏ فَقَالُوا يَا رَسُولَ اللَّهِ إِنَّمَا سَرَقَ ‏.‏ قَالَ ‏\"‏ اقْطَعُوهُ ‏\"‏ ‏.‏ فَأُتِيَ بِهِ الْخَامِسَةَ فَقَالَ ‏\"‏ اقْتُلُوهُ ‏\"‏ ‏.‏ قَالَ جَابِرٌ فَانْطَلَقْنَا بِهِ فَقَتَلْنَاهُ ثُمَّ اجْتَرَرْنَاهُ فَأَلْقَيْنَاهُ فِي بِئْرٍ وَرَمَيْنَا عَلَيْهِ الْحِجَارَةَ ‏.‏","Narrated Jabir ibn Abdullah: A thief was brought to the Prophet (ﷺ). He said: Kill him. The people said: He has committed theft, Messenger of Allah! Then he said: Cut off his hand. So his (right) hand was cut off. He was brought a second time and he said: Kill him. The people said: He has committed theft, Messenger of Allah! Then he said: Cut off his foot. So his (left) foot was cut off. He was brought a third time and he said: Kill him. The people said: He has committed theft, Messenger of Allah! So he said: Cut off his hand. (So his (left) hand was cut off.) He was brought a fourth time and he said: Kill him. The people said: He has committed theft, Messenger of Allah! So he said: Cut off his foot. So his (right) foot was cut off. He was brought a fifth time and he said: Kill him. So we took him away and killed him. We then dragged him and cast him into a well and threw stones over him","","Hasan"],[4411,4411,4411,"। আব্দুর রাহমান ইবনু মুহাইরিম (রহঃ) সূত্রে বর্ণিত। তিনি বলেন, আমরা ফাদালাহ ইবনু উবাইদ (রাঃ)-কে বললাম, চোরের কাটা হাত গর্দানের সঙ্গে বেঁধে দেয়া কি সুন্নাত? তিনি বললেন, একদা রাসূলুল্লাহ সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম-এর নিকট এক চোরকে নিয়ে আসা হলে তার হাত কাটা হয় এবং তাঁর নির্দেশমত তা গর্দানের সঙ্গে বেঁধে দেয়া হয়।[1] দুর্বল।","حَدَّثَنَا قُتَيْبَةُ بْنُ سَعِيدٍ، حَدَّثَنَا عُمَرُ بْنُ عَلِيٍّ، حَدَّثَنَا الْحَجَّاجُ، عَنْ مَكْحُولٍ، عَنْ عَبْدِ الرَّحْمَنِ بْنِ مُحَيْرِيزٍ، قَالَ سَأَلْنَا فَضَالَةَ بْنَ عُبَيْدٍ عَنْ تَعْلِيقِ الْيَدِ، فِي الْعُنُقِ لِلسَّارِقِ أَمِنَ السُّنَّةِ هُوَ قَالَ أُتِيَ رَسُولُ اللَّهِ صلى الله عليه وسلم بِسَارِقٍ فَقُطِعَتْ يَدُهُ ثُمَّ أُمِرَ بِهَا فَعُلِّقَتْ فِي عُنُقِهِ ‏.‏","Abd al-Rahman b. Muhariz said: We asked Fadalah b. 'Ubaid about the hanging the (amputated) hand on the neck of a thief whether it was a sunnan. He said: A thief was brought to the Messenger of Allah (ﷺ) and his hand was cut off. Thereafter he commanded for it, and it was hung on his neck","","Daif"],[4412,4412,4412,"। আবূ হুরাইরাহ (রাঃ) সূত্রে বর্ণিত। তিনি বলেন, রাসূলুল্লাহ সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম বলেছেনঃ দাস যদি চুরি করে তবে তাকে এক নাশ্ অর্থাৎ বিশ দিরহামের বিনিময়ে হলেও বিক্রি করে দাও।[1] দুর্বল।","حَدَّثَنَا مُوسَى، - يَعْنِي ابْنَ إِسْمَاعِيلَ - حَدَّثَنَا أَبُو عَوَانَةَ، عَنْ عُمَرَ بْنِ أَبِي سَلَمَةَ، عَنْ أَبِيهِ، عَنْ أَبِي هُرَيْرَةَ، قَالَ قَالَ رَسُولُ اللَّهِ صلى الله عليه وسلم ‏ \"‏ إِذَا سَرَقَ الْمَمْلُوكُ فَبِعْهُ وَلَوْ بِنَشٍّ ‏\"‏ ‏.‏","Narrated AbuHurayrah: The Prophet (ﷺ) as saying: When a slave steals, sell him, even though it be for half an uqiyah","","Daif"],[4413,4413,4413,"। ইবনু আব্বাস (রাঃ) সূত্রে বর্ণিত। তিনি বলেন, আল্লাহর বাণীঃ ‘‘তোমাদের স্ত্রীদের মধ্যে যারা অশ্লীল কাজ করে, তবে তোমাদের মধ্য থেকে চার ব্যক্তিকে তাদের উপর সাক্ষী দাঁড় করাও। অতঃপর তারা সাক্ষ্য দিলে তাদেরকে ঘরে আবদ্ধ করে রাখো, যতক্ষণ না মৃত্যু তাদের অবসান ঘটায় অথবা আল্লাহ তাদের জন্য অন্য কোনো পথ বের করেন’’ (সূরা আন-নিসাঃ ১৫)। মেয়েদের সম্পর্কে একথা বলে পুরুষদের সম্পর্কে আলোচনা করেছেন, অতঃপর উভয়ের সম্পর্কে একত্রে আলোচনা করেছেনঃ ‘‘আর তোমাদের মধ্যে দু’ জন নারী-পুরুষ যদি এ অশ্লীল কাজ করে, তবে তাদের শাসন করো। অনন্তর তারা যদি তওবা করে এবং নিজেদেরকে সংশোধন করে নেয়, তবে তাদেরকে ছেড়ে দাও।’’ (সূরা আন-নিসাঃ ১৬)। উপরোক্ত আয়াতের নির্দেশ ‘বেত্রাঘাত’ সংক্রান্ত আয়াত দ্বারা রহিত হয়েছে। অতএব আল্লাহর বাণীঃ ‘‘ব্যভিচারিনী এবং ব্যভিচারী, তাদের প্রত্যেককে একশো বেত্রাঘাত করো।’’ (সূরা আন-নূরঃ ২)।[1] সনদ হাসান।","حَدَّثَنَا أَحْمَدُ بْنُ مُحَمَّدِ بْنِ ثَابِتٍ الْمَرْوَزِيُّ، حَدَّثَنِي عَلِيُّ بْنُ الْحُسَيْنِ، عَنْ أَبِيهِ، عَنْ يَزِيدَ النَّحْوِيِّ، عَنْ عِكْرِمَةَ، عَنِ ابْنِ عَبَّاسٍ، قَالَ ‏{‏ وَاللاَّتِي يَأْتِينَ الْفَاحِشَةَ مِنْ نِسَائِكُمْ فَاسْتَشْهِدُوا عَلَيْهِنَّ أَرْبَعَةً مِنْكُمْ فَإِنْ شَهِدُوا فَأَمْسِكُوهُنَّ فِي الْبُيُوتِ حَتَّى يَتَوَفَّاهُنَّ الْمَوْتُ أَوْ يَجْعَلَ اللَّهُ لَهُنَّ سَبِيلاً ‏}‏ وَذَكَرَ الرَّجُلَ بَعْدَ الْمَرْأَةِ ثُمَّ جَمَعَهُمَا فَقَالَ ‏{‏ وَاللَّذَانِ يَأْتِيَانِهَا مِنْكُمْ فَآذُوهُمَا فَإِنْ تَابَا وَأَصْلَحَا فَأَعْرِضُوا عَنْهُمَا ‏}‏ فَنَسَخَ ذَلِكَ بِآيَةِ الْجَلْدِ فَقَالَ ‏{‏ الزَّانِيَةُ وَالزَّانِي فَاجْلِدُوا كُلَّ وَاحِدٍ مِنْهُمَا مِائَةَ جَلْدَةٍ ‏}‏ ‏.‏","Ibn ‘Abbas said:The Qur’anic verse goes: “If any of your woman are guilty of lewdness, take the evidence of four (reliable) witnesses from amongst you against them, and if they testify, Confine them to houses until death do chain them or Allah ordains for them some (other) way. Allah then mentioned man after woman and combined them in another verse : “If two men among you are guilty of lewdness, punish them both. If they repent and amend, leave them alone. This command was abrogated by the verse relating to flogging : “The woman and the man guilty of adultery or fornication – flog each of them with one hundred stripes","","Hasan Isnaad"],[4414,4414,4414,"। মুজাহিদ (রহঃ) সূত্রে বর্ণিত। তিনি বলেন, আল্লাহর বাণী, ‘আস-সাবীল’ অর্থাৎ হাদ্দ। সুফিয়ান (রহঃ) বলেন, ‘ফাআযূহুমা’ অর্থ অবিবাহিতের শাস্তি এবং ‘ফাআমসিকূহুন্না ফিল বুয়ূত’ অর্থ বিবাহিতের শাস্তি।[1] হাসান মাকতূ।","حَدَّثَنَا أَحْمَدُ بْنُ مُحَمَّدِ بْنِ ثَابِتٍ، حَدَّثَنَا مُوسَى، - يَعْنِي ابْنَ مَسْعُودٍ - عَنْ شِبْلٍ، عَنِ ابْنِ أَبِي نَجِيحٍ، عَنْ مُجَاهِدٍ، قَالَ السَّبِيلُ الْحَدُّ قَالَ سُفْيَانُ ‏{‏ فَآذُوهُمَا ‏}‏ الْبِكْرَانِ ‏{‏ فَأَمْسِكُوهُنَّ فِي الْبُيُوتِ ‏}‏ الثَّيِّبَاتِ ‏.‏","Mujahid said:“Apponting a way in the verse (iv.15) means prescribed punishment. Sufiyan said: “Punish them “refers to unmarried, and “confine them to houses” refers to the women who are married","","Hasan Maqtu"],[4415,4415,4415,"। উবাদাহ ইবনু সামিত (রাঃ) সূত্রে বর্ণিত। তিনি বলেন, রাসূলুল্লাহ সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম বলেছেনঃ তোমরা আমার থেকে গ্রহণ করো। আল্লাহ তাদের জন্য বিধান দিয়েছেনঃ বিবাহিত পুরুষ ও বিবাহিতা নারী অপরাধী প্রমাণিত হলে, তাদের শাস্তি হলো একশো বেত্রাঘাত ও পাথর নিক্ষেপে হত্যা করা। আর অবিবাহিত পুরুষ ও অবিবাহিতা নারীর শাস্তি হলো একশো বেত্রাঘাত ও এক বছরের নির্বাসন।[1] সহীহ।","حَدَّثَنَا مُسَدَّدٌ، حَدَّثَنَا يَحْيَى، عَنْ سَعِيدِ بْنِ أَبِي عَرُوبَةَ، عَنْ قَتَادَةَ، عَنِ الْحَسَنِ، عَنْ حِطَّانَ بْنِ عَبْدِ اللَّهِ الرَّقَاشِيِّ، عَنْ عُبَادَةَ بْنِ الصَّامِتِ، قَالَ قَالَ رَسُولُ اللَّهِ صلى الله عليه وسلم ‏ \"‏ خُذُوا عَنِّي خُذُوا عَنِّي قَدْ جَعَلَ اللَّهُ لَهُنَّ سَبِيلاً الثَّيِّبُ بِالثَّيِّبِ جَلْدُ مِائَةٍ وَرَمْىٌ بِالْحِجَارَةِ وَالْبِكْرُ بِالْبِكْرِ جَلْدُ مِائَةٍ وَنَفْىُ سَنَةٍ ‏\"‏ ‏.‏","‘Ubadah b. al-Samit reported the Messenger of Allah(ﷺ) as sayings:Receive my teachings, receive my teachings. Allah has appointed a way for those women. If the parties have been married, they shall receive a hundred lashes and stoned to death. If the parties are unmarried, they shall receive a hundred lashes and banished for a year","","Sahih"],[4416,4416,4416,"। ইয়াহইয়াহ সূত্রে উপরোক্ত হাদীসের সমার্থবোধক হাদীস বর্ণিত। এতে রয়েছেঃ তাদের শাস্তি হলো একশো বেত্রাঘাত ও পাথর নিক্ষেপে হত্যা করা।[1] সহীহ।","حَدَّثَنَا وَهْبُ بْنُ بَقِيَّةَ، وَمُحَمَّدُ بْنُ الصَّبَّاحِ بْنِ سُفْيَانَ، قَالاَ حَدَّثَنَا هُشَيْمٌ، عَنْ مَنْصُورٍ، عَنِ الْحَسَنِ، بِإِسْنَادِ يَحْيَى وَمَعْنَاهُ قَالاَ ‏ \"‏ جَلْدُ مِائَةٍ وَالرَّجْمُ ‏\"‏ ‏.‏","A similar tradition has been transmitted by al-Hasan through a chain of Yahya and to the same effect. This version adds:They shall receive a hundred lashes and toned to death","","Sahih"],[4417,4417,4417,"। উবাদাহ ইবনু সামিত (রাঃ) থেকে নবী সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম সূত্রে অনুরূপ হাদীস বর্ণিত। লোকজন সা‘দ ইবনু উবাদাহ (রাঃ)-কে বললো, হে সাবিতের পিতা! হাদ্দ সংক্রান্ত আয়াত নাযিল হয়েছে। অতএব আপনি যদি আপনার স্ত্রীর সঙ্গে কোনো পুরুষ লোককে দেখতে পান তাহলে আপনি কি করবেন? তিনি বলেন, আমি তরবারির আঘাতে উভয়কে নিস্তব্ধ করে দিতাম। আমি কি যাবো এবং চারজন সাক্ষী একত্র করবো, আর এ সুযোগে তারা তাদের অপকর্ম সেরে নিবে? অতএব তারা গিয়ে রাসূলুল্লাহ সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম-এর নিকট একত্র হয়ে বললো, হে আল্লাহর রাসূল! আপনি কি সাবিতের পিতাকে দেখেননি, তিনি এই এই কথা বলেছেন। রাসূলুল্লাহ সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম বললেনঃ তরবারিই যথেষ্ট সাক্ষী। অতঃপর তিনি বলেন, না না, আমি আশঙ্কা করি যে, কোনো উন্মত্ত ও আত্মমর্যাদাবোধ সম্পন্ন লোকই এ পদ্ধতি অনুসরণ করতে পারে। আরেক বর্ণনায় রয়েছেঃ এক ব্যক্তি তার স্ত্রীর ক্রীতদাসীর সঙ্গে সংগমে লিপ্ত হয়।’ ইমাম আবূ দাঊদ (রহঃ) বলেন, আল-ফাদল ইবনু দালহাম হাদীসের হাফিয নন। তিনি ওয়াসিত অঞ্চলের কসাই ছিলেন।[1] দুর্বলঃ যঈফাহ হা/ ২৩৪১।","حَدَّثَنَا مُحَمَّدُ بْنُ عَوْفٍ الطَّائِيُّ، حَدَّثَنَا الرَّبِيعُ بْنُ رَوْحِ بْنِ خُلَيْدٍ، حَدَّثَنَا مُحَمَّدُ بْنُ خَالِدٍ، - يَعْنِي الْوَهْبِيَّ - حَدَّثَنَا الْفَضْلُ بْنُ دَلْهَمٍ، عَنِ الْحَسَنِ، عَنْ سَلَمَةَ بْنِ الْمُحَبَّقِ، عَنْ عُبَادَةَ بْنِ الصَّامِتِ، عَنِ النَّبِيِّ صلى الله عليه وسلم بِهَذَا الْحَدِيثِ فَقَالَ نَاسٌ لِسَعْدِ بْنِ عُبَادَةَ يَا أَبَا ثَابِتٍ قَدْ نَزَلَتِ الْحُدُودُ لَوْ أَنَّكَ وَجَدْتَ مَعَ امْرَأَتِكَ رَجُلاً كَيْفَ كُنْتَ صَانِعًا قَالَ كُنْتُ ضَارِبَهُمَا بِالسَّيْفِ حَتَّى يَسْكُتَا أَفَأَنَا أَذْهَبُ فَأَجْمَعُ أَرْبَعَةَ شُهَدَاءَ فَإِلَى ذَلِكَ قَدْ قَضَى الْحَاجَةَ ‏.‏ فَانْطَلَقُوا فَاجْتَمَعُوا عِنْدَ رَسُولِ اللَّهِ صلى الله عليه وسلم فَقَالُوا يَا رَسُولَ اللَّهِ أَلَمْ تَرَ إِلَى أَبِي ثَابِتٍ قَالَ كَذَا وَكَذَا فَقَالَ رَسُولُ اللَّهِ صلى الله عليه وسلم ‏\"‏ كَفَى بِالسَّيْفِ شَاهِدًا ‏\"‏ ‏.‏ ثُمَّ قَالَ ‏\"‏ لاَ لاَ أَخَافُ أَنْ يَتَتَايَعَ فِيهَا السَّكْرَانُ وَالْغَيْرَانُ ‏\"‏ ‏.‏ قَالَ أَبُو دَاوُدَ رَوَى وَكِيعٌ أَوَّلَ هَذَا الْحَدِيثِ عَنِ الْفَضْلِ بْنِ دَلْهَمٍ عَنِ الْحَسَنِ عَنْ قَبِيصَةَ بْنِ حُرَيْثٍ عَنْ سَلَمَةَ بْنِ الْمُحَبَّقِ عَنِ النَّبِيِّ صلى الله عليه وسلم ‏.‏ وَإِنَّمَا هَذَا إِسْنَادُ حَدِيثِ ابْنِ الْمُحَبَّقِ أَنَّ رَجُلاً وَقَعَ عَلَى جَارِيَةِ امْرَأَتِهِ ‏.‏ قَالَ أَبُو دَاوُدَ الْفَضْلُ بْنُ دَلْهَمٍ لَيْسَ بِالْحَافِظِ كَانَ قَصَّابًا بِوَاسِطَ ‏.‏","Narrated Ubadah ibn as-Samit: The tradition mentioned above (No. 4401) has also been transmitted by Ubadah ibn as-Samit through a different chain of narrators. This version has: The people said to Sa'd ibn Ubadah: AbuThabit, the prescribed punishments have been revealed: if you find a man with your wife, what will you do? He said: I shall strike them with a sword so much that they become silent (i.e. die). Should I go and gather four witnesses? Until that (time) the need would be fulfilled. So they went away and gathered with the Messenger of Allah (ﷺ) and said: Messenger of Allah! did you not see AbuThabit. He said so-and-so. The Messenger of Allah (ﷺ) said: The sword is a sufficient witness. He then said: No, no, a furious and a jealous man may follow this course. Abu Dawud said: This tradition has been transmitted by Waki' from al-Fadl b. Dilham from al-Hasan, from Qabisah b. Huraith, from Salamah b. al-Muhabbaq, from the Prophet (ﷺ). And this is the chain of the tradition narrated by Ibn al-Muhabbaq to the effect that a man had sexual intercourse with a slave girl of his wife. Abu Dawud said: Al-Fadl b. Dilham was not the memoriser of traditions. He was a butcher in Wasit","","Daif"],[4418,4418,4418,"। আব্দুল্লাহ ইবনু আব্বাস (রাঃ) সূত্রে বর্ণিত। উমার ইবনুল খাত্তাব (রাঃ) তার ভাষণে বলেন, নিশ্চয়ই আল্লাহ মুহাম্মাদ সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম-কে সত্য দীনসহ পাঠিয়েছেন এবং তাঁর উপর কিতাব নাযিল করেছেন। আর তিনি তাঁর উপর যা নাযিল করেছেন, রজম সংক্রান্ত আয়াত তার অন্তর্ভুক্ত। আমরা তা পাঠ করেছি এবং সংরক্ষণ করেছি। রাসূলুল্লাহ সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম রজম করেছেন আর আমরাও তাঁর পরে রজম করেছি। তবে আমার আশঙ্কা হচ্ছে, কাল প্রবাহের দীর্ঘতায় কেউ হয় তো বলবে, আমরা তো আল্লাহর নাযিলকৃত তিাবে রজমের আয়াত পাইনি। ফলে তারা আল্লাহর নাযিলকৃত একটা ফরজ পরিত্যাগ করে পথভ্রষ্ট হবে। জেনে রাখো বিবাহিত নারী-পুরুষ ব্যভিচারের অপরাধে দায়ী প্রমাণিত হলে অথবা অন্তঃসত্তা হলে অথবা স্বীকারোক্তি করলে তাদেরকে রজম করা অবধারিত। আল্লাহর কসম! লোকেরা যদি একথা না বলতো যে, উমার আল্লাহর কিতাবে কিছু বর্ধিত করেছেন। তাহলে আমি অবশ্যই এ আয়াত লিখে দিতাম।[1] সহীহ।","حَدَّثَنَا عَبْدُ اللَّهِ بْنُ مُحَمَّدٍ النُّفَيْلِيُّ، حَدَّثَنَا هُشَيْمٌ، حَدَّثَنَا الزُّهْرِيُّ، عَنْ عُبَيْدِ اللَّهِ بْنِ عَبْدِ اللَّهِ بْنِ عُتْبَةَ، عَنْ عَبْدِ اللَّهِ بْنِ عَبَّاسٍ، أَنَّ عُمَرَ، - يَعْنِي ابْنَ الْخَطَّابِ - رضى الله عنه خَطَبَ فَقَالَ إِنَّ اللَّهَ بَعَثَ مُحَمَّدًا صلى الله عليه وسلم بِالْحَقِّ وَأَنْزَلَ عَلَيْهِ الْكِتَابَ فَكَانَ فِيمَا أَنْزَلَ عَلَيْهِ آيَةُ الرَّجْمِ فَقَرَأْنَاهَا وَوَعَيْنَاهَا وَرَجَمَ رَسُولُ اللَّهِ صلى الله عليه وسلم وَرَجَمْنَا مِنْ بَعْدِهِ وَإِنِّي خَشِيتُ - إِنْ طَالَ بِالنَّاسِ الزَّمَانُ - أَنْ يَقُولَ قَائِلٌ مَا نَجِدُ آيَةَ الرَّجْمِ فِي كِتَابِ اللَّهِ فَيَضِلُّوا بِتَرْكِ فَرِيضَةٍ أَنْزَلَهَا اللَّهُ تَعَالَى فَالرَّجْمُ حَقٌّ عَلَى مَنْ زَنَى مِنَ الرِّجَالِ وَالنِّسَاءِ إِذَا كَانَ مُحْصَنًا إِذَا قَامَتِ الْبَيِّنَةُ أَوْ كَانَ حَمْلٌ أَوِ اعْتِرَافٌ وَايْمُ اللَّهِ لَوْلاَ أَنْ يَقُولَ النَّاسُ زَادَ عُمَرُ فِي كِتَابِ اللَّهِ عَزَّ وَجَلَّ لَكَتَبْتُهَا ‏.‏","‘Abd Allah b. ‘Abbas said:‘Umar b. al-Khattab gave an address saying: Allah sent Muhammad (ﷺ) with truth and sent down the Books of him, and the verse of stoning was included in what He sent down to him. We read it and memorized it. The Messenger of Allah (ﷺ) had people stoned to death and we have done it also since his death. I am afraid the people might say with the passage of time: We do not find the verse of stoning in the Books of Allah, and thus they stray by abandoning a duty which Allah had received. Stoning is a duty laid down (by Allah) for married men and women who commit fornication when proof is established, or if there is pregnancy, or a confession. I swear by Allah, had it not been so that the people might say: ‘Umar made an addition to Allah’s Book, I would have written it (there)","","Sahih"],[4419,4419,4419,"। ইয়াযীদ ইবনু সু‘আইম ইবনু হায্‌যাল (রহঃ) থেকে তার পিতার সূত্রে বর্ণিত। তিনি বলেন, মাঈয ইবনু মালিক ইয়াতিম ছিলো। সে আমার পিতার তত্ত্বাবধানে ছিলো। সে এক গোত্রের জনৈক বাঁদীর সঙ্গে সঙ্গম করে। আমার পিতা তাকে বলেন, তুমি রাসূলুল্লাহ সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম-এর নিকট যাও এবং তাঁকে তোমার কৃতকর্মের ব্যাপারে জানাও। তিনি হয় তো তোমার জন্য ক্ষমা চাইবেন। বস্তুতঃ এর দ্বারা তিনি তার অপরাধ থেকে মুক্তির সন্ধানই চেয়েছেন। বর্ণনাকারী বলেন, অতঃপর সে তাঁর নিকট এসে বললো, হে আল্লাহর রাসূল! আমি তো যেনা করেছি; সুতরাং আমার উপর আল্লাহর নির্ধারিত শাস্তি বাস্তবায়িত করুন। তিনি তার থেকে মুখ ফিরিয়ে নিলেন। সে পুনরায় বললো, হে আল্লাহর রাসূল! আমি তো যেনা করেছি; আমার উপর আল্লাহর কিতাব বাস্তবায়িত করুন। তিনি তার থেকে মুখ ফিরিয়ে নিলেন। সে আবারো বললো, হে আল্লাহর রাসূল! আমি তো যেনা করেছি; আমার উপর আল্লাহর কিতাব বাস্তবায়িত করুন। একথা সে চারবার বলার পর নবী সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম বললেনঃ তুমি তো চারবার একথা বললেন, তা কার সঙ্গে? সে বললো, অমুক নারীর সঙ্গে। তিনি প্রশ্ন করলেনঃ তুমি কি তার সঙ্গে শুয়েছ? সে বললো, হ্যাঁ। তিনি আবারো প্রশ্ন করলেনঃ তুমি কি তার শরীরে শরীর মিশিয়েছ? সে বললো, হ্যাঁ। তিনি পুনরায় প্রশ্ন করলেনঃ তুমি কি তার সঙ্গে সঙ্গম করেছো? সে বললো, হ্যাঁ। বর্ণনাকারী বলেন, অতঃপর তাকে আল-হাররা এলাকায় নিয়ে যাওয়া হলো। যখন তাকে পাথর মারা শুরু হলো, সে আঘাতের চোটে আতঙ্কিত হলো এবং দ্রুত দৌঁড়াতে লাগলো। আব্দুল্লাহ ইবনু উনাইস (রাঃ) এমতাবস্থায় তার সাক্ষাৎ পেলেন যে, তাকে পাথর মারার জন্য নিয়োজিত ব্যক্তিগণ তাকে ধরতে অপারগ হলো। তিনি উটের সামনের পায়ের হাড় তুলে তার দিকে নিক্ষেপ করেন এবং তাতে সে নিহত হয়। অতঃপর তিনি নবী সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম-এর নিকট এসে এ ঘটনা ব্যক্ত করেন। তিনি বললেনঃ তোমরা তাকে ছেড়ে দিলে না কেন? সে হয় তো তওবা করতো, আর আল্লাহ তার তওবা কবূল করতেন।[1] সহীহঃ এ কথাটি বাদেঃ (... لعله أن)","حَدَّثَنَا مُحَمَّدُ بْنُ سُلَيْمَانَ الأَنْبَارِيُّ، حَدَّثَنَا وَكِيعٌ، عَنْ هِشَامِ بْنِ سَعْدٍ، قَالَ حَدَّثَنِي يَزِيدُ بْنُ نُعَيْمِ بْنِ هَزَّالٍ، عَنْ أَبِيهِ، قَالَ كَانَ مَاعِزُ بْنُ مَالِكٍ يَتِيمًا فِي حِجْرِ أَبِي ‏.‏ فَأَصَابَ جَارِيَةً مِنَ الْحَىِّ فَقَالَ لَهُ أَبِي ائْتِ رَسُولَ اللَّهِ صلى الله عليه وسلم فَأَخْبِرْهُ بِمَا صَنَعْتَ لَعَلَّهُ يَسْتَغْفِرُ لَكَ وَإِنَّمَا يُرِيدُ بِذَلِكَ رَجَاءَ أَنْ يَكُونَ لَهُ مَخْرَجًا فَأَتَاهُ فَقَالَ يَا رَسُولَ اللَّهِ إِنِّي زَنَيْتُ فَأَقِمْ عَلَىَّ كِتَابَ اللَّهِ ‏.‏ فَأَعْرَضَ عَنْهُ فَعَادَ فَقَالَ يَا رَسُولَ اللَّهِ إِنِّي زَنَيْتُ فَأَقِمْ عَلَىَّ كِتَابَ اللَّهِ ‏.‏ حَتَّى قَالَهَا أَرْبَعَ مِرَارٍ ‏.‏ قَالَ صلى الله عليه وسلم ‏\"‏ إِنَّكَ قَدْ قُلْتَهَا أَرْبَعَ مَرَّاتٍ فَبِمَنْ ‏\"‏ ‏.‏ قَالَ بِفُلاَنَةَ ‏.‏ قَالَ ‏\"‏ هَلْ ضَاجَعْتَهَا ‏\"‏ ‏.‏ قَالَ نَعَمْ ‏.‏ قَالَ ‏\"‏ هَلْ بَاشَرْتَهَا ‏\"‏ ‏.‏ قَالَ نَعَمْ ‏.‏ قَالَ ‏\"‏ هَلْ جَامَعْتَهَا ‏\"‏ ‏.‏ قَالَ نَعَمْ ‏.‏ قَالَ فَأَمَرَ بِهِ أَنْ يُرْجَمَ فَأُخْرِجَ بِهِ إِلَى الْحَرَّةِ ‏.‏ فَلَمَّا رُجِمَ فَوَجَدَ مَسَّ الْحِجَارَةِ جَزِعَ فَخَرَجَ يَشْتَدُّ فَلَقِيَهُ عَبْدُ اللَّهِ بْنُ أُنَيْسٍ وَقَدْ عَجَزَ أَصْحَابُهُ فَنَزَعَ لَهُ بِوَظِيفِ بَعِيرٍ فَرَمَاهُ بِهِ فَقَتَلَهُ ثُمَّ أَتَى النَّبِيَّ صلى الله عليه وسلم فَذَكَرَ ذَلِكَ لَهُ فَقَالَ ‏\"‏ هَلاَّ تَرَكْتُمُوهُ لَعَلَّهُ أَنْ يَتُوبَ فَيَتُوبَ اللَّهُ عَلَيْهِ ‏\"‏ ‏.‏","Narrated Nu'aym ibn Huzzal: Yazid ibn Nu'aym ibn Huzzal, on his father's authority said: Ma'iz ibn Malik was an orphan under the protection of my father. He had illegal sexual intercourse with a slave-girl belonging to a clan. My father said to him: Go to the Messenger of Allah (ﷺ) and inform him of what you have done, for he may perhaps ask Allah for your forgiveness. His purpose in that was simply a hope that it might be a way of escape for him. So he went to him and said: Messenger of Allah! I have committed fornication, so inflict on me the punishment ordained by Allah. He (the Prophet) turned away from him, so he came back and said: Messenger of Allah! I have committed fornication, so inflict on me the punishment ordained by Allah. He (again) turned away from him, so he came back and said: Messenger of Allah! I have committed fornication, so inflict on me the punishment ordained by Allah. When he uttered it four times, the Messenger of Allah (ﷺ) said: You have said it four times. With whom did you commit it? He replied: With so and so. He asked: Did you lie down with her? He replied: Yes. He asked: Had your skin been in contact with hers? He replied. Yes. He asked: Did you have intercourse with her? He said: Yes. So he (the Prophet) gave orders that he should be stoned to death. He was then taken out to the Harrah, and while he was being stoned he felt the effect of the stones and could not bear it and fled. But Abdullah ibn Unays encountered him when those who had been stoning him could not catch up with him. He threw the bone of a camel's foreleg at him, which hit him and killed him. They then went to the Prophet (ﷺ) and reported it to him. He said: Why did you not leave him alone. Perhaps he might have repented and been forgiven by Allah","","Sahih"],[4420,4420,4420,"। মুহাম্মাদ ইবনু ইসহাক (রহঃ) সূত্রে বর্ণিত। তিনি বলেন, আমি মাঈয ইবনু মালিকের ঘটনা আসিম ইবনু উমার ইবনু কাতাদাহর নিকট উল্লেখ করলাম। তিনি আমাকে বললেন, হাসান ইবনু মুহাম্মাদ ইবনু আলী ইবনু আবূ তালিব আমাকে বলেছেন, এরা আসলাম গোত্রের কতক লোক যাদেরকে আমি দোষারোপ করি না এবং যাদের নিকট থেকে তুমি আমার নিকট রাসূলুল্লাহ সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম-এর বাণীঃ ‘‘তোমরা তাকে ছেড়ে দিলে না কেন’’ বর্ণনা করেছো আমি এ হাদীস হৃদয়ঙ্গম করতে পারিনি। অতএব আমি তাকে জাবির ইবনু আব্দুল্লাহ (রাঃ)-এর নিকট এসে বললাম, আসলাম গোত্রের কয়েকজন লোক বর্ণনা করছে যে, পাথর নিক্ষেপের মারাত্মক চোট পেয়ে মাঈযের হতবুদ্ধি হয়ে যাওয়ার ঘটনা রাসূলুল্লাহ সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম-এর নিকট আলোচনা করাতে তিনি বলেনঃ ‘‘তোমরা তাকে ছেড়ে দিলে না কেন?’’ অথচ আমি তো এ হাদীস সম্পর্কে জানি না। জাবির বললেন, হে ভাতিজা! এ হাদীস সম্পর্কিত ঘটনা আমি অধিক জ্ঞাত। কেননা আমিও লোকটিকে পাথর মারার জন্য নিয়োজিত ব্যক্তিদের অন্যতম। আমরা যখন তাকে নিয়ে বেরিয়ে গিয়ে পাথর মারা শুরু করলাম তখন পাথর নিক্ষেপের মারাত্মক চোট পেয়ে সে আমাদের নিকট চিৎকার করে বলতে লাগলো, হে লোক সকল! তোমরা আমাকে রাসূলুল্লাহ সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম-এর নিকট ফিরিয়ে নিয়ে চলো। আমার আপনজনেরাই আমাকে হত্যার জন্য দায়ী। তারা আমার সঙ্গে প্রতারণা করেছে। তারা আমাকে বলেছে যে, রাসূলুল্লাহ সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম আমাকে হত্যা করবেন না। তথাপি আমরা তাকে হত্যা না করে ছাড়িনি। অতঃপর আমরা যখন ফিরে এসে রাসূলুল্লাহ সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম-এর নিকট এসব কথা বললাম, তখন তিনি বললেনঃ তোমরা তাকে ছেড়ে দিলে না কেন এবং আমার নিকট নিয়ে এলে না কেন? যাতে রাসূলুল্লাহ সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম তার অনুতাপ কবূল করতেন। কিন্তু তিনি হাদ্দ পরিত্যাগ করার জন্য একথা বলেননি। বর্ণনাকারী বলেন, এবার আমি এ হাদীসের মর্ম বুঝতে পারলাম।[1] হাসান।","حَدَّثَنَا عُبَيْدُ اللَّهِ بْنُ عُمَرَ بْنِ مَيْسَرَةَ، حَدَّثَنَا يَزِيدُ بْنُ زُرَيْعٍ، عَنْ مُحَمَّدِ بْنِ إِسْحَاقَ، قَالَ ذَكَرْتُ لِعَاصِمِ بْنِ عُمَرَ بْنِ قَتَادَةَ قِصَّةَ مَاعِزِ بْنِ مَالِكٍ فَقَالَ لِي حَدَّثَنِي حَسَنُ بْنُ مُحَمَّدِ بْنِ عَلِيِّ بْنِ أَبِي طَالِبٍ، قَالَ حَدَّثَنِي ذَلِكَ، مِنْ قَوْلِ رَسُولِ اللَّهِ صلى الله عليه وسلم ‏\"‏ فَهَلاَّ تَرَكْتُمُوهُ ‏\"‏ ‏.‏ مَنْ شِئْتُمْ مِنْ رِجَالِ أَسْلَمَ مِمَّنْ لاَ أَتَّهِمُ ‏.‏ قَالَ وَلَمْ أَعْرِفْ هَذَا الْحَدِيثَ قَالَ فَجِئْتُ جَابِرَ بْنَ عَبْدِ اللَّهِ فَقُلْتُ إِنَّ رِجَالاً مِنْ أَسْلَمَ يُحَدِّثُونَ أَنَّ رَسُولَ اللَّهِ صلى الله عليه وسلم قَالَ لَهُمْ حِينَ ذَكَرُوا لَهُ جَزَعَ مَاعِزٍ مِنَ الْحِجَارَةِ حِينَ أَصَابَتْهُ ‏\"‏ أَلاَّ تَرَكْتُمُوهُ ‏\"‏ ‏.‏ وَمَا أَعْرِفُ الْحَدِيثَ قَالَ يَا ابْنَ أَخِي أَنَا أَعْلَمُ النَّاسِ بِهَذَا الْحَدِيثِ كُنْتُ فِيمَنْ رَجَمَ الرَّجُلَ إِنَّا لَمَّا خَرَجْنَا بِهِ فَرَجَمْنَاهُ فَوَجَدَ مَسَّ الْحِجَارَةِ صَرَخَ بِنَا يَا قَوْمِ رُدُّونِي إِلَى رَسُولِ اللَّهِ صلى الله عليه وسلم فَإِنَّ قَوْمِي قَتَلُونِي وَغَرُّونِي مِنْ نَفْسِي وَأَخْبَرُونِي أَنَّ رَسُولَ اللَّهِ صلى الله عليه وسلم غَيْرُ قَاتِلِي فَلَمْ نَنْزِعْ عَنْهُ حَتَّى قَتَلْنَاهُ فَلَمَّا رَجَعْنَا إِلَى رَسُولِ اللَّهِ صلى الله عليه وسلم وَأَخْبَرْنَاهُ قَالَ ‏\"‏ فَهَلاَّ تَرَكْتُمُوهُ وَجِئْتُمُونِي بِهِ ‏\"‏ ‏.‏ لِيَسْتَثْبِتَ رَسُولُ اللَّهِ صلى الله عليه وسلم مِنْهُ فَأَمَّا لِتَرْكِ حَدٍّ فَلاَ قَالَ فَعَرَفْتُ وَجْهَ الْحَدِيثِ ‏.‏","Narrated Jabir ibn Abdullah: Muhammad ibn Ishaq said: I mentioned the story of Ma'iz ibn Malik to Asim ibn Umar ibn Qatadah. He said to me: Hasan ibn Muhammad ibn Ali ibn AbuTalib said to me: Some men of the tribe of Aslam whom I do not blame and whom you like have transmitted to me the saying of the Messenger of Allah (ﷺ): Why did you not leave him alone? He said: But I did not understand this tradition. So I went to Jabir ibn Abdullah and said (to him): Some men of the tribe of Aslam narrate that the Messenger of Allah (ﷺ) said when they mentioned to him the anxiety of Ma'iz when the stones hurt him: \"Why did you not leave him alone?' But I do not know this tradition. He said: My cousin, I know this tradition more than the people. I was one of those who had stoned the man. When we came out with him, stoned him and he felt the effect of the stones, he cried: O people! return me to the Messenger of Allah (ﷺ). My people killed me and deceived me; they told me that the Messenger of Allah (ﷺ) would not kill me. We did not keep away from him till we killed him. When we returned to the Messenger of Allah (ﷺ) we informed him of it. He said: Why did you not leave him alone and bring him to me? and he said this so that the Messenger of Allah (ﷺ) might ascertain it from him. But he did not say this to abandon the prescribed punishment. He said: I then understood the intent of the tradition","","Hasan"],[4421,4421,4421,"। ইবনু আব্বাস (রাঃ) সূত্রে বর্ণিত। একদা মাঈয ইবনু মালিক নবী সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম-এর নিকট এসে বললো যে, সে যেনা করেছে। একথা শুনে নবী সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম তার থেকে মুখ ফিরিয়ে নিলেন। সে কয়েকবার একথা বললো, আর তিনি প্রতিবার মুখ ফিরিয়ে নিলেন। অতঃপর তিনি তার গোত্রের লোকদের প্রশ্ন করলেনঃ সে কি পাগল? তারা বললো, তার তো কোনো সমস্যা নেই। তিনি তাকে প্রশ্ন করলেনঃ তুমি কি তার সঙ্গে এটা করেছো? সে বললো, হ্যাঁ। অতএব তিনি তাকে পাথর মেরে হত্যা করার আদেশ দিলেন। অতঃপর তাকে নিয়ে যাওয়া হলো এবং পাথর নিক্ষেপে হত্যা করা হলো। আর তিনি (সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম) তাঁর জানাযার সালাত পড়েননি।[1] সনদ সহীহ।","حَدَّثَنَا أَبُو كَامِلٍ، حَدَّثَنَا يَزِيدُ بْنُ زُرَيْعٍ، حَدَّثَنَا خَالِدٌ، - يَعْنِي الْحَذَّاءَ - عَنْ عِكْرِمَةَ، عَنِ ابْنِ عَبَّاسٍ، أَنَّ مَاعِزَ بْنَ مَالِكٍ، أَتَى النَّبِيَّ صلى الله عليه وسلم فَقَالَ إِنَّهُ زَنَى ‏.‏ فَأَعْرَضَ عَنْهُ فَأَعَادَ عَلَيْهِ مِرَارًا فَأَعْرَضَ عَنْهُ فَسَأَلَ قَوْمَهُ ‏\"‏ أَمَجْنُونٌ هُوَ ‏\"‏ ‏.‏ قَالُوا لَيْسَ بِهِ بَأْسٌ ‏.‏ قَالَ ‏\"‏ أَفَعَلْتَ بِهَا ‏\"‏ ‏.‏ قَالَ نَعَمْ ‏.‏ فَأَمَرَ بِهِ أَنْ يُرْجَمَ فَانْطُلِقَ بِهِ فَرُجِمَ وَلَمْ يُصَلِّ عَلَيْهِ ‏.‏","Narrated Abdullah ibn Abbas: Ma'iz ibn Malik came to the Prophet (ﷺ) and said that he had committed fornication and he (the Prophet) turned away from him. He repeated it many times, but he (the Prophet) turned away from him. He asked his people: Is he mad? They replied: There is no defect in him. He asked: Have you done it with her? He replied: Yes. so he ordered that he should be stoned to death. He was taken out and stoned to death, and he (the Prophet) did not pray over him","","Sahih Isnaad"],[4422,4422,4422,"। জাবির ইবনু সামুরাহ (রাঃ) সূত্রে বর্ণিত। তিনি বলেন, আমি মাঈয ইবনু মালিককে দেখেছি, যখন তাকে নবী সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম-এর নিকট হাযির করা হয়। সে ছিলো বেটে, মাংসল ও বলিষ্ঠ গড়নের লোক, তার দেহে কোনো চাঁদর ছিলো না। সে নিজের বিরুদ্ধে চারবার সাক্ষ্য দিয়ে বলে যে, সে যেনা করেছে। রাসূলুল্লাহ সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম বললেনঃ সম্ভবত তুমি তাকে চুমু দিয়েছ। সে বললো, না, আল্লাহর কসম! এ দুর্ভাগা নিশ্চয়ই যেনা করেছে। বর্ণনাকারী বলেন, অতঃপর তাকে পাথর নিক্ষেপে হত্যা করা হয়। অতঃপর তিনি (সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম) ভাষন দিতে গিয়ে বলেনঃ জেনে রাখো! আমরা যখনই আল্লাহর রাস্তায় জিহাদে যাই, আর এদিকে যদি তাদের কেউ পিছনে গিয়ে পাঠা ছাগলের ন্যায় ভ্যাভ্যা করে এবং কোনো নারীকে যৎকিঞ্চিৎ বীর্য দান করে, জেনে রাখো! আল্লাহ যদি আমাকে তাদের কারো উপর নিয়ন্ত্রণ ক্ষমতা দেন, তবে তাকে দৃষ্টান্তমূলক শাস্তি দিয়ে নারীদের থেকে প্রতিহত করবো।[1] সহীহ।","حَدَّثَنَا مُسَدَّدٌ، حَدَّثَنَا أَبُو عَوَانَةَ، عَنْ سِمَاكٍ، عَنْ جَابِرِ بْنِ سَمُرَةَ، قَالَ رَأَيْتُ مَاعِزَ بْنَ مَالِكٍ حِينَ جِيءَ بِهِ إِلَى النَّبِيِّ صلى الله عليه وسلم رَجُلاً قَصِيرًا أَعْضَلَ لَيْسَ عَلَيْهِ رِدَاءٌ فَشَهِدَ عَلَى نَفْسِهِ أَرْبَعَ مَرَّاتٍ أَنَّهُ قَدْ زَنَى ‏.‏ فَقَالَ رَسُولُ اللَّهِ صلى الله عليه وسلم ‏\"‏ فَلَعَلَّكَ قَبَّلْتَهَا ‏\"‏ ‏.‏ قَالَ لاَ وَاللَّهِ إِنَّهُ قَدْ زَنَى الآخِرُ ‏.‏ قَالَ فَرَجَمَهُ ثُمَّ خَطَبَ فَقَالَ ‏\"‏ أَلاَ كُلَّمَا نَفَرْنَا فِي سَبِيلِ اللَّهِ عَزَّ وَجَلَّ خَلَفَ أَحَدُهُمْ لَهُ نَبِيبٌ كَنَبِيبِ التَّيْسِ يَمْنَحُ إِحْدَاهُنَّ الْكُثْبَةَ أَمَا إِنَّ اللَّهَ إِنْ يُمَكِّنِّي مِنْ أَحَدٍ مِنْهُمْ إِلاَّ نَكَلْتُهُ عَنْهُنَّ ‏\"‏ ‏.‏","Jabir b. Samurah said:I saw Ma’iz b. Malik when he was brought to the Prophet (ﷺ). He was a small and muscular man. He did not wear the loose outer garment. He made confession about him four times that he committed fornication. The Messenger of Allah (ﷺ) said: Perhaps you kissed her. He said that this most discarded man has committed fornication. He said: So he had him stoned to death and gave an address, saying: Beware, whenever we go out on an expedition in the path of Allah, one of them (I.e. the people) lags behind with a bleating sound like that of a he-goat, and gives modicum of his milk(i.e. sperm) to one of the women. If Allah gives control over any of them, I shall deter him from them (i.e. women) by punishing him severely","","Sahih"],[4423,4423,4423,"। সিমাক (রহঃ) সূত্রে বর্ণিত। তিনি বলেন, আমি জাবির ইবনু সামুরাহ (রাঃ)-কে উপরোক্ত হাদীস বর্ণনা করতে শুনেছি। তবে পূর্বোক্ত বর্ণনাটি পূর্ণাঙ্গ। তিনি বলেন, সে দু’বার এ কথা বলেছে। সিমাক বলেন, আমি সাঈদ ইবনু জুবাইরের নিকট এ হাদীস বর্ণনা করলে তিনি বলেন, সে বরং চারবার একথা বলেছে।[1] সহীহ।","حَدَّثَنَا مُحَمَّدُ بْنُ الْمُثَنَّى، عَنْ مُحَمَّدِ بْنِ جَعْفَرٍ، عَنْ شُعْبَةَ، عَنْ سِمَاكٍ، قَالَ سَمِعْتُ جَابِرَ بْنَ سَمُرَةَ، بِهَذَا الْحَدِيثِ وَالأَوَّلُ أَتَمُّ قَالَ فَرَدَّهُ مَرَّتَيْنِ ‏.‏ قَالَ سِمَاكٌ فَحَدَّثْتُ بِهِ سَعِيدَ بْنَ جُبَيْرٍ فَقَالَ إِنَّهُ رَدَّهُ أَرْبَعَ مَرَّاتٍ ‏.‏","Simak said:I heard this tradition from Jabir b. Samurah. But the first version is more perfect. This version has: He repeated twice, Simak said: I narrated to Sa’id b. Jubair. He said: He repeated it four times","","Sahih"],[4424,4424,4424,"। শূ‘বাহ (রহঃ) বলেন, আমি সিমাককে ‘কুসবাহ’ এর অর্থ বললাম। তিনি বললেন, অল্প দুধ।[1] সহীহ।","حَدَّثَنَا عَبْدُ الْغَنِيِّ بْنُ أَبِي عَقِيلٍ الْمِصْرِيُّ، حَدَّثَنَا خَالِدٌ، - يَعْنِي ابْنَ عَبْدِ الرَّحْمَنِ - قَالَ قَالَ شُعْبَةُ فَسَأَلْتُ سِمَاكًا عَنِ الْكُثْبَةِ فَقَالَ اللَّبَنُ الْقَلِيلُ ‏.‏","Shu’bah said:I asked Simak about the meaning of KUTHBAH. He said: A small quantity of milk","","Sahih Maqtu"],[4425,4425,4425,"। ইবনু আব্বাস (রাঃ) সূত্রে বর্ণিত। তিনি বলেন, রাসূলুল্লাহ সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম মাঈয ইবনু মালিককে ডেকে বললেনঃ তোমার সম্বন্ধে যে সংবাদ আমার কানে পৌঁছেছে তা কি সত্য? সে বললো, আমার সম্বন্ধে আপনার নিকট কিরূপ সংবাদ পৌঁছেছে? তিনি বললেনঃ তুমি নাকি অমুক গোত্রের জনৈক বাঁদীর সঙ্গে যেনা করেছো? সে বললো, হ্যাঁ। অতঃপর সে চারবার একথার স্বীকারোক্তি করে। সুতরাং তিনি তাকে পাথর নিক্ষেপে হত্যা করার আদেশ দেন। অতঃপর তাকে পাথর মারা হয়।[1] সহীহ।","حَدَّثَنَا مُسَدَّدٌ، حَدَّثَنَا أَبُو عَوَانَةَ، عَنْ سِمَاكِ بْنِ حَرْبٍ، عَنْ سَعِيدِ بْنِ جُبَيْرٍ، عَنِ ابْنِ عَبَّاسٍ، قَالَ قَالَ رَسُولُ اللَّهِ صلى الله عليه وسلم لِمَاعِزِ بْنِ مَالِكٍ ‏\"‏ أَحَقٌّ مَا بَلَغَنِي عَنْكَ ‏\"‏ ‏.‏ قَالَ وَمَا بَلَغَكَ عَنِّي قَالَ ‏\"‏ بَلَغَنِي عَنْكَ أَنَّكَ وَقَعْتَ عَلَى جَارِيَةِ بَنِي فُلاَنٍ ‏\"‏ ‏.‏ قَالَ نَعَمْ ‏.‏ فَشَهِدَ أَرْبَعَ شَهَادَاتٍ فَأَمَرَ بِهِ فَرُجِمَ ‏.‏","Ibn ‘Abbas said:The Messenger of Allah (ﷺ) asked Ma’iz b. Malik : Is what I have heard about you is true? He said: What have you heard about me? He said: I have heard that you have had intercourse with a girl belonging to the family of so and so. He said: Yes. He then testified four times. He (The prophet) then gave order regarding him and he was stoned to death","","Sahih"],[4426,4426,4426,"। ইবনু আব্বাস (রাঃ) সূত্রে বর্ণিত। তিনি বলেন, একদা মাঈয ইবনু মালিক নবী সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম-এর নিকট এসে যেনা করেছে বলে দু’বার সাক্ষ্য দেয়। তিনি তাকে তাড়িয়ে দিলে সে আবারো এসে দু’বার যেনার স্বীকারোক্তি করে। অতঃপর তিনি (সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম) বলেনঃ তুমি নিজের বিরুদ্ধে চারবার সাক্ষ্য দিয়েছে। তোমরা একে নিয়ে যাও এবং ‘রজম’ করো।[1] সহীহ।","حَدَّثَنَا نَصْرُ بْنُ عَلِيٍّ، أَخْبَرَنَا أَبُو أَحْمَدَ، أَخْبَرَنَا إِسْرَائِيلُ، عَنْ سِمَاكِ بْنِ حَرْبٍ، عَنْ سَعِيدِ بْنِ جُبَيْرٍ، عَنِ ابْنِ عَبَّاسٍ، قَالَ جَاءَ مَاعِزُ بْنُ مَالِكٍ إِلَى النَّبِيِّ صلى الله عليه وسلم فَاعْتَرَفَ بِالزِّنَا مَرَّتَيْنِ فَطَرَدَهُ ثُمَّ جَاءَ فَاعْتَرَفَ بِالزِّنَا مَرَّتَيْنِ فَقَالَ ‏ \"‏ شَهِدْتَ عَلَى نَفْسِكَ أَرْبَعَ مَرَّاتٍ اذْهَبُوا بِهِ فَارْجُمُوهُ ‏\"‏ ‏.‏","Narrated Abdullah ibn Abbas: Ma'iz ibn Malik came to the Prophet (ﷺ) and admitted fornication twice. But he drove him away. He then came and admitted fornication twice. But he drove him away. He then came and admitted fornication twice. He (the Prophet) said: You have testified to yourself four times. Take him away and stone him to death","","Sahih"],[4427,4427,4427,"। ইবনু আব্বাস (রাঃ) সূত্রে বর্ণিত। নবী সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম মাঈয ইবনু মালিককে বললেনঃ তুমি সম্ভবতঃ চুমু খেয়েছো অথবা হাতে স্পর্শ করেচো অথবা তাকিয়েছো? সে বললো, না। তিনি বললেনঃ তবে কি তুমি যেনা করেছো? সে বললো, হ্যাঁ। বর্ণনাকারী বলেন, সে একথা বলতেই তিনি তাকে পাথর মেরে হত্যা করার আদেশ দেন। বর্ণনাকারী মূসা (রহঃ) ইবনু আব্বাস (রাঃ) থেকে বর্ণনা করেননি, বরং এটি ওয়াহবের বর্ণনা।[1] সহীহ।","حَدَّثَنَا مُوسَى بْنُ إِسْمَاعِيلَ، حَدَّثَنَا جَرِيرٌ، حَدَّثَنِي يَعْلَى، عَنْ عِكْرِمَةَ، أَنَّ النَّبِيَّ صلى الله عليه وسلم ح وَحَدَّثَنَا زُهَيْرُ بْنُ حَرْبٍ وَعُقْبَةُ بْنُ مُكْرَمٍ قَالاَ حَدَّثَنَا وَهْبُ بْنُ جَرِيرٍ حَدَّثَنَا أَبِي قَالَ سَمِعْتُ يَعْلَى بْنَ حَكِيمٍ يُحَدِّثُ عَنْ عِكْرِمَةَ عَنِ ابْنِ عَبَّاسٍ أَنَّ النَّبِيَّ صلى الله عليه وسلم قَالَ لِمَاعِزِ بْنِ مَالِكٍ ‏\"‏ لَعَلَّكَ قَبَّلْتَ أَوْ غَمَزْتَ أَوْ نَظَرْتَ ‏\"‏ ‏.‏ قَالَ لاَ ‏.‏ قَالَ ‏\"‏ أَفَنِكْتَهَا ‏\"‏ ‏.‏ قَالَ نَعَمْ ‏.‏ قَالَ فَعِنْدَ ذَلِكَ أَمَرَ بِرَجْمِهِ ‏.‏ وَلَمْ يَذْكُرْ مُوسَى عَنِ ابْنِ عَبَّاسٍ وَهَذَا لَفْظُ وَهْبٍ ‏.‏","Narrated Abdullah ibn Abbas: The Prophet (ﷺ) said to Ma'iz ibn Malik: Perhaps you kissed, or squeezed, or looked. He said: No. He then said: Did you have intercourse with her? He said: Yes. On the (reply) he (the Prophet) gave order that he should be stoned to death. The narrator did not mention \"on the authority of Ibn 'Abbas\". This is Wahb's version","","Sahih"],[4428,4428,4428,"। আবূ হুরাইরাহ (রাঃ) বলেছেন, একদা আসলাম গোত্রীয় এক লোক নবী সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম-এর নিকট এসে নিজের বিরুদ্ধে চারবার সাক্ষ্য দেয় যে, সে জনৈকা নারীর সঙ্গে হারাম কাজ করেছে। প্রতিবারই নবী সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম তার থেকে মুখ ফিরিয়ে নিলেন। পঞ্চমবার সে একথা বললে তিনি তার দিকে ফিরে প্রশ্ন করলেনঃ তুমি কি তার সঙ্গে যেনা করেছো? সে বললো, হ্যাঁ। তিনি প্রশ্ন করলেনঃ তোমার লজ্জাস্থান কি তার লজ্জাস্থানে ঢুকেছে? সে বললো, হ্যাঁ। তিনি বললেনঃ যেরূপ সুরমা শলাকা সুরমা দানীতে ঢুকে যায় এবং রশি যেরূপ কূপের মধ্যে ঢুকে পড়ে? সে বললো, হ্যাঁ। তিনি প্রশ্ন করলেনঃ তুমি কি জানো, যেনা কি? সে বললো, হ্যাঁ। কোনো ব্যক্তি তার স্ত্রীর সঙ্গে বৈধ সহবাস করে, আমি ঐ নারীর সঙ্গে অবৈধভাবে তা করেছি। তিনি বললেনঃ তোমার এ কথা বলার উদ্দেশ্য কি? সে বললো, আপনি আমাকে পবিত্র করবেন, এটাই আমার উদ্দেশ্য। অতঃপর তিনি আদেশ দিলেন তাকে পাথর মেরে হত্যা করা হলো। অতঃপর আল্লাহর নবী সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম শুনতে পান যে, তাঁর দু’ জন সাহাবী একে অপরকে বলছেন লোকটিকে দেখো, আল্লাহ যার অপরাধ গোপন রাখলেন, অথচ নিজেকেই সে রক্ষা করতে পারলো না, অতঃপর কুকুরের মতো তাকে পাথর মেরে হত্যা করা হলো। তিনি তাদের এ কথা শুনে চুপ থাকলেন এবং কিছু সময় চলার পর একটি গাধার লাশের নিকট এলেন যার পা উপরের দিকে উঠেছিল। তিনি বললেনঃ অমুক অমুক কোথায়? তারা বললো, হে আল্লাহর রাসূল! আমরা এখানে। তিনি বললেনঃ তোমরা দু’জন নেমে গিয়ে এ গাধার গোশত খাও। তারা বললো, হে আল্লাহর নবী! এটা কি কেউ খেতে পারে? তিনি বললেনঃ তোমরা এখন তোমাদের এক ভাইয়ের মর্যাদা নিয়ে যেরূপ মন্তব্য করেছো, তা এর গোশত খাওয়ার চাইতেও গুরুতর। সেই সত্তার কসম যাঁর হাতে আমার প্রাণ! নিশ্চয়ই সে এখন জান্নাতের ঝর্ণাসমূহে আনন্দে ডুব দিচ্ছে।[1] দুর্বলঃ ইরওয়া হা/ ২৩৫৪, যঈফাহ হা/ ২৯৫৭।","حَدَّثَنَا الْحَسَنُ بْنُ عَلِيٍّ، حَدَّثَنَا عَبْدُ الرَّزَّاقِ، عَنِ ابْنِ جُرَيْجٍ، قَالَ أَخْبَرَنِي أَبُو الزُّبَيْرِ، أَنَّ عَبْدَ الرَّحْمَنِ بْنَ الصَّامِتِ ابْنَ عَمِّ أَبِي هُرَيْرَةَ، أَخْبَرَهُ أَنَّهُ، سَمِعَ أَبَا هُرَيْرَةَ، يَقُولُ جَاءَ الأَسْلَمِيُّ إِلَى نَبِيِّ اللَّهِ صلى الله عليه وسلم فَشَهِدَ عَلَى نَفْسِهِ أَنَّهُ أَصَابَ امْرَأَةً حَرَامًا أَرْبَعَ مَرَّاتٍ كُلُّ ذَلِكَ يُعْرِضُ عَنْهُ النَّبِيُّ صلى الله عليه وسلم فَأَقْبَلَ فِي الْخَامِسَةِ فَقَالَ ‏\"‏ أَنِكْتَهَا ‏\"‏ ‏.‏ قَالَ نَعَمْ ‏.‏ قَالَ ‏\"‏ حَتَّى غَابَ ذَلِكَ مِنْكَ فِي ذَلِكَ مِنْهَا ‏\"‏ ‏.‏ قَالَ نَعَمْ ‏.‏ قَالَ ‏\"‏ كَمَا يَغِيبُ الْمِرْوَدُ فِي الْمُكْحُلَةِ وَالرِّشَاءُ فِي الْبِئْرِ ‏\"‏ ‏.‏ قَالَ نَعَمْ ‏.‏ قَالَ ‏\"‏ فَهَلْ تَدْرِي مَا الزِّنَا ‏\"‏ ‏.‏ قَالَ نَعَمْ أَتَيْتُ مِنْهَا حَرَامًا مَا يَأْتِي الرَّجُلُ مِنِ امْرَأَتِهِ حَلاَلاً ‏.‏ قَالَ ‏\"‏ فَمَا تُرِيدُ بِهَذَا الْقَوْلِ ‏\"‏ ‏.‏ قَالَ أُرِيدُ أَنْ تُطَهِّرَنِي ‏.‏ فَأَمَرَ بِهِ فَرُجِمَ فَسَمِعَ النَّبِيُّ صلى الله عليه وسلم رَجُلَيْنِ مِنْ أَصْحَابِهِ يَقُولُ أَحَدُهُمَا لِصَاحِبِهِ انْظُرْ إِلَى هَذَا الَّذِي سَتَرَ اللَّهُ عَلَيْهِ فَلَمْ تَدَعْهُ نَفْسُهُ حَتَّى رُجِمَ رَجْمَ الْكَلْبِ ‏.‏ فَسَكَتَ عَنْهُمَا ثُمَّ سَارَ سَاعَةً حَتَّى مَرَّ بِجِيفَةِ حِمَارٍ شَائِلٍ بِرِجْلِهِ فَقَالَ ‏\"‏ أَيْنَ فُلاَنٌ وَفُلاَنٌ ‏\"‏ ‏.‏ فَقَالاَ نَحْنُ ذَانِ يَا رَسُولَ اللَّهِ ‏.‏ قَالَ ‏\"‏ انْزِلاَ فَكُلاَ مِنْ جِيفَةِ هَذَا الْحِمَارِ ‏\"‏ ‏.‏ فَقَالاَ يَا نَبِيَّ اللَّهِ مَنْ يَأْكُلُ مِنْ هَذَا قَالَ ‏\"‏ فَمَا نِلْتُمَا مِنْ عِرْضِ أَخِيكُمَا آنِفًا أَشَدُّ مِنْ أَكْلٍ مِنْهُ وَالَّذِي نَفْسِي بِيَدِهِ إِنَّهُ الآنَ لَفِي أَنْهَارِ الْجَنَّةِ يَنْقَمِسُ فِيهَا ‏\"‏ ‏.‏","Narrated AbuHurayrah: A man of the tribe of Aslam came to the Prophet (ﷺ) and testified four times against himself that he had had illicit intercourse with a woman, while all the time the Prophet (ﷺ) was turning away from him. Then when he confessed a fifth time, he turned round and asked: Did you have intercourse with her? He replied: Yes. He asked: Have you done it so that your sexual organ penetrated hers? He replied: Yes. He asked: Have you done it like a collyrium stick when enclosed in its case and a rope in a well? He replied: Yes. He asked: Do you know what fornication is? He replied: Yes. I have done with her unlawfully what a man may lawfully do with his wife. He then asked: What do you want from what you have said? He said: I want you to purify me. So he gave orders regarding him and he was stoned to death. Then the Prophet (ﷺ) heard one of his companions saying to another: Look at this man whose fault was concealed by Allah but who would not leave the matter alone, so that he was stoned like a dog. He said nothing to them but walked on for a time till he came to the corpse of an ass with its legs in the air. He asked: Where are so and so? They said: Here we are, Messenger of Allah (ﷺ)! He said: Go down and eat some of this ass's corpse. They replied: Messenger of Allah! Who can eat any of this? He said: The dishonour you have just shown to your brother is more serious than eating some of it. By Him in Whose hand my soul is, he is now among the rivers of Paradise and plunging into them","","Daif"],[4429,4429,4429,"। আবূ হুরাইরাহ (রাঃ) সূত্রে অনুরূপ হাদীস বর্ণিত। এতে আরো রয়েছেঃ হাসান ইবনু আলী বলেন, বর্ণনাকারী বিভিন্ন শব্দে হাদীসটি আমার নিকট বর্ণনা করেছেন। কেউ বলেছেন, লোকজন মাঈযকে গাছের সঙ্গে বেঁধেছিল আবার কেউ বলেছেন, তাকে দাঁড় করিয়ে রাখা হয়েছিল।[1] দুর্বল।","حَدَّثَنَا الْحَسَنُ بْنُ عَلِيٍّ، حَدَّثَنَا أَبُو عَاصِمٍ، حَدَّثَنَا ابْنُ جُرَيْجٍ، قَالَ أَخْبَرَنَا أَبُو الزُّبَيْرِ، عَنِ ابْنِ عَمِّ أَبِي هُرَيْرَةَ، عَنْ أَبِي هُرَيْرَةَ، بِنَحْوِهِ زَادَ وَاخْتَلَفُوا فَقَالَ بَعْضُهُمْ رُبِطَ إِلَى شَجَرَةٍ وَقَالَ بَعْضُهُمْ وَقَفَ ‏.‏","A similar tradition has also been transmitted by Abu Hurrairah through a different chain of narrators. This version adds:The narrator Hasan b. “All said: The transmitters have differed in the wordings (of this tradition) reported to me. Some said: He (Ma’iz) was tied to a tree, and others said: He was made to stand","","Daif"],[4430,4430,4430,"। জাবির ইবনু আব্দুল্লাহ (রাঃ) সূত্রে বর্ণিত। একদা আসলাম গোত্রের জনৈক ব্যক্তি রাসূলুল্লাহ সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম-এর নিকট এসে যেনার কথা স্বীকার করলে তিনি তার থেকে মুখ ফিরিয়ে নিলেন। সে আবারো সাক্ষ্য দিলো। তিনি তার থেকে মুখ ফিরিয়ে নেন। এরূপে সে চারবার নিজের বিরুদ্ধে সাক্ষ্য দিলো। অতঃপর নবী সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম তাকে প্রশ্ন করেনঃ তোমার পাগলামী রোগ আছে নাকি? সে বললো, না। তিনি পুনরায় প্রশ্ন করলেনঃ তুমি কি বিবাহিত? সে বললো, হ্যাঁ। বর্ণনাকারী বলেন, নবী সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম তাকে পাথর মারার আদেশ দিলেন। ঈদগাহে তাকে পাথর মারা হয়। পাথরের আঘাত যখন তাকে সন্ত্রস্ত করে তুললো সে পালাতে লাগলো। অতঃপর তাকে ধরে এনে পাথর মেরে হত্যা করা হলো। নবী সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম তার সম্পর্কে উত্তম কথা বলেছেন, তবে তার জানাযা পড়েননি।[1] সহীহ।","حَدَّثَنَا مُحَمَّدُ بْنُ الْمُتَوَكِّلِ الْعَسْقَلاَنِيُّ، وَالْحَسَنُ بْنُ عَلِيٍّ، قَالاَ حَدَّثَنَا عَبْدُ الرَّزَّاقِ، أَخْبَرَنَا مَعْمَرٌ، عَنِ الزُّهْرِيِّ، عَنْ أَبِي سَلَمَةَ، عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ، أَنَّ رَجُلاً، مِنْ أَسْلَمَ جَاءَ إِلَى رَسُولِ اللَّهِ صلى الله عليه وسلم فَاعْتَرَفَ بِالزِّنَا فَأَعْرَضَ عَنْهُ ثُمَّ اعْتَرَفَ فَأَعْرَضَ عَنْهُ حَتَّى شَهِدَ عَلَى نَفْسِهِ أَرْبَعَ شَهَادَاتٍ فَقَالَ لَهُ النَّبِيُّ صلى الله عليه وسلم ‏\"‏ أَبِكَ جُنُونٌ ‏\"‏ ‏.‏ قَالَ لاَ ‏.‏ قَالَ ‏\"‏ أَحْصَنْتَ ‏\"‏ ‏.‏ قَالَ نَعَمْ ‏.‏ قَالَ فَأَمَرَ بِهِ النَّبِيُّ صلى الله عليه وسلم فَرُجِمَ فِي الْمُصَلَّى فَلَمَّا أَذْلَقَتْهُ الْحِجَارَةُ فَرَّ فَأُدْرِكَ فَرُجِمَ حَتَّى مَاتَ فَقَالَ لَهُ النَّبِيُّ صلى الله عليه وسلم خَيْرًا وَلَمْ يُصَلِّ عَلَيْهِ ‏.‏","Jabir b. ‘Abd Allah said:A man of the tribe of Asalam came to the Messenger of Allah (ﷺ) and made confession of fornication. He (the prophet) turned away from him. When he testified against him four times, the Prophet (ﷺ) said: Are you mad? He said: No. he asked: Are you married? He replied: Yes. The Prophet (ﷺ) then commanded regarding him and he was stoned in the place of prayer. Then when the stones hurt him, he fled, but was overtaken and stoned to death. The Prophet (ﷺ) then spoke well of him and did not pray over him","","Sahih"],[4431,4431,4431,"। আবূ সাঈদ (রাঃ) সূত্রে বর্ণিত। তিনি বলেন, নবী সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম মাঈয ইবনু মালিককে পাথর মারার আদেশ করলে আমরা তাকে নিয়ে আল-বাকী’ নামক স্থানে যাই। আল্লাহর কসম! আমরা তাকে বাঁধিওনি এবং তার জন্য গর্তও খনন করিনি; কিন্তু তবু সে দাঁড়িয়ে থাকে। আবূ কামিল বললেন, আবূ সাঈদ বলেছেন, অতঃপর আমরা তার শরীরে হাড়, মাটির ঢিলা ও কংকর নিক্ষেপ করতে লাগলাম। সে দৌড়াতে লাগলো, আমরাও তার পিছনে দৌড়াতে লাগলাম। অবশেষে সে সেই প্রস্তরময় প্রান্তরের এক প্রান্তে গিয়ে আমাদের জন্য দাঁড়িয়ে গেলো। আমরা তাকে পাথর নিক্ষেপ করলাম। অবশেষে সে চুপ হয়ে গেলো (মৃত্যুবরণ করলো)। বর্ণনাকারী বলেন, তিনি তার জন্য ক্ষমা প্রার্থনাও করেননি, তাকে গালিও দেননি।[1] সহীহ।","حَدَّثَنَا أَبُو كَامِلٍ، حَدَّثَنَا يَزِيدُ، - يَعْنِي ابْنَ زُرَيْعٍ - ح وَحَدَّثَنَا أَحْمَدُ بْنُ مَنِيعٍ، عَنْ يَحْيَى بْنِ زَكَرِيَّا، - وَهَذَا لَفْظُهُ - عَنْ دَاوُدَ، عَنْ أَبِي نَضْرَةَ، عَنْ أَبِي سَعِيدٍ، قَالَ لَمَّا أَمَرَ النَّبِيُّ صلى الله عليه وسلم بِرَجْمِ مَاعِزِ بْنِ مَالِكٍ خَرَجْنَا بِهِ إِلَى الْبَقِيعِ فَوَاللَّهِ مَا أَوْثَقْنَاهُ وَلاَ حَفَرْنَا لَهُ وَلَكِنَّهُ قَامَ لَنَا ‏.‏ - قَالَ أَبُو كَامِلٍ قَالَ - فَرَمَيْنَاهُ بِالْعِظَامِ وَالْمَدَرِ وَالْخَزَفِ فَاشْتَدَّ وَاشْتَدَدْنَا خَلْفَهُ حَتَّى أَتَى عُرْضَ الْحَرَّةِ فَانْتَصَبَ لَنَا فَرَمَيْنَاهُ بِجَلاَمِيدِ الْحَرَّةِ حَتَّى سَكَتَ - قَالَ - فَمَا اسْتَغْفَرَ لَهُ وَلاَ سَبَّهُ ‏.‏","Abu Sa’id said:When the Prophet (May peace e upon him) commanded to stone Ma’iz b. Malik, we took him out to Baql. I swear by Allah, we did not tie him, nor did we dig a pit for him. But he was standing before us. The narrator Abu Kamil said: So we threw at him bones, clods of mud and pieces of earthenware. He ran away and we ran after him till he came to a side of the Harrah. He stood there before us and we threw at him big stones of the Harrah until he died. He (the Prophet) did not ask forgiveness for him, nor did he speak ill of him","","Sahih"],[4432,4432,4432,"। আবূ নাদরাহ (রহঃ) সূত্রে বর্ণিত। তিনি বলেন, একদা এক লোক নবী সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম-এর নিকট হাযির হলো। অতঃপর অনুরূপ সমার্থবোধক হাদীস বর্ণনা করেন, তবে অপূর্ণাঙ্গভাবে। তিনি বলেন, উপস্থিত জনতা লোকটিকে গালি দিতে শুরু করলে তিনি তাদের নিষেধ করলেন। বর্ণনাকারী বলেন, তারা তার জন্য ক্ষমা প্রার্থনা করতে লাগলে তিনি তাদের নিষেধ করে বললেনঃ লোকটি গুনাহ করেছে, আল্লাহই তার হিসাব গ্রহণের জন্য যথেষ্ট।[1] যঈফ মুরসালঃ ইরওয়া (৭/২৫৫-২৫৬)।","حَدَّثَنَا مُؤَمَّلُ بْنُ هِشَامٍ، حَدَّثَنَا إِسْمَاعِيلُ، عَنِ الْجُرَيْرِيِّ، عَنْ أَبِي نَضْرَةَ، قَالَ جَاءَ رَجُلٌ إِلَى النَّبِيِّ صلى الله عليه وسلم نَحْوَهُ وَلَيْسَ بِتَمَامِهِ قَالَ ذَهَبُوا يَسُبُّونَهُ فَنَهَاهُمْ قَالَ ذَهَبُوا يَسْتَغْفِرُونَ لَهُ فَنَهَاهُمْ قَالَ ‏ \"‏ هُوَ رَجُلٌ أَصَابَ ذَنْبًا حَسِيبُهُ اللَّهُ ‏\"‏ ‏.‏","Abu Nadrah said:A man came to Prophet (ﷺ). He then mentioned a similar tradition but not completely. This version has: People began to speak ill of him but he (the Prophet) forbade them. Then they began to ask forgiveness from him, but he forbade them by saying. He is a man who had committed a sin. Allah will call him to account himself","","Daif"],[4433,4433,4433,"। ইবনু বুরাইদাহ (রহঃ) থেকে তার পিতার সূত্রে বর্ণিত। নবী সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম মাঈযের মুখের গন্ধ শুঁকলেন, (নেশাগ্রস্ত কিনা জানার জন্য)।[1] সহীহ।","حَدَّثَنَا مُحَمَّدُ بْنُ أَبِي بَكْرِ بْنِ أَبِي شَيْبَةَ، حَدَّثَنَا يَحْيَى بْنُ يَعْلَى بْنِ الْحَارِثِ، حَدَّثَنَا أَبِي، عَنْ غَيْلاَنَ، عَنْ عَلْقَمَةَ بْنِ مَرْثَدٍ، عَنِ ابْنِ بُرَيْدَةَ، عَنْ أَبِيهِ، أَنَّ النَّبِيَّ صلى الله عليه وسلم اسْتَنْكَهَ مَاعِزًا ‏.‏","Buraidah said. :The Prophet (ﷺ) smelt the breath of Ma’iz","","Sahih"],[4434,4434,4434,"। আব্দুল্লাহ ইবনু বুরাইদাহ (রহঃ) থেকে তার পিতার সূত্রে বর্ণিত। তিনি বলেন, আমরা রাসূলুল্লাহ সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম-এর সাহাবীগণ পরস্পর আলোচনা করতাম যে, ‘গামিদ’ গোত্রের ঐ নারী এবং মাঈয ইবনু মালিক যদি তাদের স্বীকারোক্তি প্রত্যাহার করতো অথবা তিনি বলেন, তারা স্বীকারোক্তির পর যদি তার পুনরাবৃত্তি না করতো, তবে তিনি (সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম) তাদের তলব করতেন না। তিনি তাদেরকে পাথর মেরেছেন চারবার স্বীকারোক্তির পর।[1] দুর্বলঃ ইরওয়া হা/ ২৩৫৯।","حَدَّثَنَا أَحْمَدُ بْنُ إِسْحَاقَ الأَهْوَازِيُّ، حَدَّثَنَا أَبُو أَحْمَدَ، حَدَّثَنَا بَشِيرُ بْنُ الْمُهَاجِرِ، حَدَّثَنِي عَبْدُ اللَّهِ بْنُ بُرَيْدَةَ، عَنْ أَبِيهِ، قَالَ كُنَّا أَصْحَابَ رَسُولِ اللَّهِ نَتَحَدَّثُ أَنَّ الْغَامِدِيَّةَ وَمَاعِزَ بْنَ مَالِكٍ لَوْ رَجَعَا بَعْدَ اعْتِرَافِهِمَا أَوْ قَالَ لَوْ لَمْ يَرْجِعَا بَعْدَ اعْتِرَافِهِمَا لَمْ يَطْلُبْهُمَا وَإِنَّمَا رَجَمَهُمَا عِنْدَ الرَّابِعَةِ ‏.‏","Narrated Buraydah ibn al-Hasib: We, the Companions of the Messenger of Allah (ﷺ), used to talk mutually: Would that al-Ghamidiyyah and Ma'iz ibn Malik had withdrawn after their confession; or he said: Had they not withdrawn after their confession, he would not have pursued them (for punishment). He had them stoned after the fourth (confession)","","Daif"],[4435,4435,4435,"। খালিদ ইবনু লাজলাজ (রাঃ) সূত্রে বর্ণিত। তিনি বাজারে বসে কাজে ব্যস্ত ছিলেন। এমন সময় এক মহিলা একটি শিশুসহ এ পথ দিয়ে যাচ্ছিল। কিছু লোকেরা তার সঙ্গে ভীড় করছিল এবং আমিও তাদের অন্তর্ভুক্ত ছিলাম। সে নবী সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম-এর নিকট পৌঁছলে তিনি প্রশ্ন করলেনঃ তোমার সঙ্গের এ শিশুর পিতা কে? সে চুপ থাকলো। তার পাশে দাঁড়ানো এক যুবক বললো, হে আল্লাহর রাসূল! আমিই এ শিশুটির পিতা। তিনি মহিলার দিকে মুখ করে বললেনঃ তোমার সঙ্গের এ শিশুটির পিতা কে? যুবকটি বললো, হে আল্লাহর রাসূল! আমি এর পিতা। একথা শুনে রাসূলুল্লাহ সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম তার চারপাশের লোকজনের নিকট তার সম্পর্কে জানতে চাইলে তারা বললো, তাকে আমরা ভালো লোক বলেই জানি। অতঃপর নবী সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম তাকেই প্রশ্ন করলেনঃ তুমি কি বিবাহিত? সে বললো, হ্যাঁ। অতঃপর তাঁর হুকুমে লোকটিকে পাথর মারা হয়। বর্ণনাকারী বলেন, আমরা তাকে নিয়ে বেরিয়ে পড়লাম, তার জন্য গর্ত খনন করে তাকে তাতে রাখলাম এবং তাকে রজম করলাম। ফলে সে মারা গেলো। একজন লোক এসে পাথর নিক্ষেপে নিহত ব্যক্তি সম্পর্কে প্রশ্ন করতে লাগলো। আমরা তাকে নিয়ে নবী সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম-এর নিকট হাযির হয়ে বললাম, এ লোকটি এসে অপবিত্র ব্যক্তি সম্পর্কে প্রশ্ন করেছে। রাসূলুল্লাহ সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম বললেনঃ সে তো মহান আল্লাহর নিকট মৃগনাভীর চেয়েও অধিক সুগন্ধযুক্ত। পরে দেখা গেলো যে, আগন্তুক লোকটি নিহত ব্যক্তির পিতা। অতঃপর আমরা তাকে এর গোসল, কাফন ও দাফন করতে সাহায্য করি। খালিদ বলেন, তার জানাযার সালাত পড়া হয়েছিল কিনা এ সম্পর্কে আমি জানি না।[1] সনদ হাসান।","حَدَّثَنَا عَبْدَةُ بْنُ عَبْدِ اللَّهِ، وَمُحَمَّدُ بْنُ دَاوُدَ بْنِ صُبَيْحٍ، قَالَ عَبْدَةُ أَخْبَرَنَا حَرَمِيُّ بْنُ حَفْصٍ، قَالَ حَدَّثَنَا مُحَمَّدُ بْنُ عَبْدِ اللَّهِ بْنِ عُلاَثَةَ، حَدَّثَنَا عَبْدُ الْعَزِيزِ بْنُ عُمَرَ بْنِ عَبْدِ الْعَزِيزِ، أَنَّ خَالِدَ بْنَ اللَّجْلاَجِ، حَدَّثَهُ أَنَّ اللَّجْلاَجَ أَبَاهُ أَخْبَرَهُ أَنَّهُ، كَانَ قَاعِدًا يَعْتَمِلُ فِي السُّوقِ فَمَرَّتِ امْرَأَةٌ تَحْمِلُ صَبِيًّا فَثَارَ النَّاسُ مَعَهَا وَثُرْتُ فِيمَنْ ثَارَ فَانْتَهَيْتُ إِلَى النَّبِيِّ صلى الله عليه وسلم وَهُوَ يَقُولُ ‏\"‏ مَنْ أَبُو هَذَا مَعَكِ ‏\"‏ ‏.‏ فَسَكَتَتْ فَقَالَ شَابٌّ حَذْوَهَا أَنَا أَبُوهُ يَا رَسُولَ اللَّهِ ‏.‏ فَأَقْبَلَ عَلَيْهَا فَقَالَ ‏\"‏ مَنْ أَبُو هَذَا مَعَكِ ‏\"‏ ‏.‏ قَالَ الْفَتَى أَنَا أَبُوهُ يَا رَسُولَ اللَّهِ ‏.‏ فَنَظَرَ رَسُولُ اللَّهِ صلى الله عليه وسلم إِلَى بَعْضِ مَنْ حَوْلَهُ يَسْأَلُهُمْ عَنْهُ فَقَالُوا مَا عَلِمْنَا إِلاَّ خَيْرًا ‏.‏ فَقَالَ لَهُ النَّبِيُّ صلى الله عليه وسلم ‏\"‏ أَحْصَنْتَ ‏\"‏ ‏.‏ قَالَ نَعَمْ ‏.‏ فَأَمَرَ بِهِ فَرُجِمَ ‏.‏ قَالَ فَخَرَجْنَا بِهِ فَحَفَرْنَا لَهُ حَتَّى أَمْكَنَّا ثُمَّ رَمَيْنَاهُ بِالْحِجَارَةِ حَتَّى هَدَأَ فَجَاءَ رَجُلٌ يَسْأَلُ عَنِ الْمَرْجُومِ فَانْطَلَقْنَا بِهِ إِلَى النَّبِيِّ صلى الله عليه وسلم فَقُلْنَا هَذَا جَاءَ يَسْأَلُ عَنِ الْخَبِيثِ ‏.‏ فَقَالَ رَسُولُ اللَّهِ صلى الله عليه وسلم ‏\"‏ لَهُوَ أَطْيَبُ عِنْدَ اللَّهِ مِنْ رِيحِ الْمِسْكِ ‏\"‏ ‏.‏ فَإِذَا هُوَ أَبُوهُ فَأَعَنَّاهُ عَلَى غُسْلِهِ وَتَكْفِينِهِ وَدَفْنِهِ وَمَا أَدْرِي قَالَ وَالصَّلاَةِ عَلَيْهِ أَمْ لاَ ‏.‏ وَهَذَا حَدِيثُ عَبْدَةَ وَهُوَ أَتَمُّ ‏.‏","Narrated Al-Lajlaj al-Amiri: I was working in the market. A woman passed carrying a child. The people rushed towards her, and I also rushed along with them. I then went to the Prophet (ﷺ) while he was asking: Who is the father of this (child) who is with you? She remained silent. A young man by her side said: I am his father, Messenger of Allah! He then turned towards her and asked: Who is the father of this child with you? The young man said: I am his father, Messenger of Allah! The Messenger of Allah (ﷺ) then looked at some of those who were around him and asked them about him. They said: We only know good (about him). The Prophet (ﷺ) said to him: Are you married? He said: Yes. So he gave orders regarding him and he was stoned to death. He (the narrator) said: We took him out, dug a pit for him and put him in it. We then threw stones at him until he died. A man then came asking about the man who was stoned. We brought him to the Prophet (ﷺ) and said: This man has come asking about the wicked man. The Messenger of Allah (ﷺ) said: He is more agreeable than the fragrance of musk in the eyes of Allah. The man was his father. We then helped him in washing, shrouding and burying him. (The narrator said:) I do not know whether he said or did not say \"in praying over him.\" This is the tradition of Abdah, and it is more accurate","","Hasan Isnaad"],[4436,4436,4436,"। খালিদ ইবনুল লাজলাজ (রাঃ) থেকে তার পিতা থেকে নবী সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম-এর উপরোক্ত হাদীসের অংশবিশেষ বর্ণিত।[1] সনদ হাসান।","حَدَّثَنَا هِشَامُ بْنُ عَمَّارٍ، حَدَّثَنَا صَدَقَةُ بْنُ خَالِدٍ، ح وَحَدَّثَنَا نَصْرُ بْنُ عَاصِمٍ الأَنْطَاكِيُّ، حَدَّثَنَا الْوَلِيدُ، جَمِيعًا قَالاَ حَدَّثَنَا مُحَمَّدٌ، - قَالَ هِشَامٌ مُحَمَّدُ بْنُ عَبْدِ اللَّهِ الشُّعَيْثِيُّ - عَنْ مَسْلَمَةَ بْنِ عَبْدِ اللَّهِ الْجُهَنِيِّ، عَنْ خَالِدِ بْنِ اللَّجْلاَجِ، عَنْ أَبِيهِ، عَنِ النَّبِيِّ صلى الله عليه وسلم بِبَعْضِ هَذَا الْحَدِيثِ ‏.‏","A part of tradition has also been transmitted by al-Lajlaj from the Prophet (ﷺ) through a different chain of narrators","","Hasan Isnaad"],[4437,4437,4437,"। সাহল ইবনু সা‘দ (রাঃ) সূত্রে বর্ণিত। এক ব্যক্তি নবী সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম-এর নিকট এসে স্বীকারোক্তি করলো যে, সে এক নারীর সঙ্গে যেনা করেছে। সে তাঁর নিকট সেই নারীর নামও বলেছে। অতএব রাসূলুল্লাহ সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম সেই নারীর নিকট লোক পাঠিয়ে এ বিষয়ে প্রশ্ন করলে সে তা অস্বীকার কলে। অতএব তিনি পুরুষ লোকটির উপর বেত্রাঘাতের হাদ্দ কার্যকর করেন এবং নারীকে রেহাই দেন।[1] সহীহ।","حَدَّثَنَا عُثْمَانُ بْنُ أَبِي شَيْبَةَ، حَدَّثَنَا طَلْقُ بْنُ غَنَّامٍ، حَدَّثَنَا عَبْدُ السَّلاَمِ بْنُ حَفْصٍ، حَدَّثَنَا أَبُو حَازِمٍ، عَنْ سَهْلِ بْنِ سَعْدٍ، عَنِ النَّبِيِّ صلى الله عليه وسلم أَنَّ رَجُلاً أَتَاهُ فَأَقَرَّ عِنْدَهُ أَنَّهُ زَنَى بِامْرَأَةٍ سَمَّاهَا لَهُ فَبَعَثَ رَسُولُ اللَّهِ صلى الله عليه وسلم إِلَى الْمَرْأَةِ فَسَأَلَهَا عَنْ ذَلِكَ فَأَنْكَرَتْ أَنْ تَكُونَ زَنَتْ فَجَلَدَهُ الْحَدَّ وَتَرَكَهَا ‏.‏","Narrated Sahl ibn Sa'd: A man came to the Prophet (ﷺ) and confessed before him that he had committed fornication with a woman whom he named. The Messenger of Allah (ﷺ) sent for the woman and asked her about it. But she denied that she had committed fornication. So he inflicted the prescribed punishment of flogging on him, and let her go","","Sahih"],[4438,4438,4438,"। জাবির (রাঃ) সূত্রে বর্ণিত। জনৈক ব্যক্তি এক মহিলার সঙ্গে যেনা করে। রাসূলুল্লাহ সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম-এর আদেশে তাকে বেত্রাঘাত করা হয়। অতঃপর তাঁকে অবহিত করা হয় যে, সে বিবাহিত; কাজেই তিনি নির্দেশ দিলে তাকে পাথর মারা হয়। ইমাম আবূ দাঊদ (রহঃ) বলেন, মুহাম্মাদ ইবনু বাকর আল-বুরসানী এ হাদীস ইবনু জুরাইজ থেকে জাবির (রাঃ) সূত্রে মাওকুফভাবে বর্ণনা করেছেন। আবূ ‘আসিম এ হাদীস ইবনু জুরাইজ সূত্রে ইবনু ওয়াহবের মতই বর্ণনা করেছেন এবং নবী সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম-এর উল্লেখ করেননি। বর্ণনাকারী বলেন, এক ব্যক্তি যেনা করলো, কিন্তু সে বিবাহিত কিনা তা জানা গেলো না। অতএব তাকে বেত্রাঘাত করা হয়। পরে তার বৈবাহিক অবস্থা জানা গেলে তাকে রজম করা হয়।[1] সনদ দুর্বল।","حَدَّثَنَا قُتَيْبَةُ بْنُ سَعِيدٍ، قَالَ حَدَّثَنَا ح، وَحَدَّثَنَا ابْنُ السَّرْحِ، - الْمَعْنَى - قَالَ أَخْبَرَنَا عَبْدُ اللَّهِ بْنُ وَهْبٍ، عَنِ ابْنِ جُرَيْجٍ، عَنْ أَبِي الزُّبَيْرِ، عَنْ جَابِرٍ، أَنَّ رَجُلاً، زَنَى بِامْرَأَةٍ فَأَمَرَ بِهِ النَّبِيُّ صلى الله عليه وسلم فَجُلِدَ الْحَدَّ ثُمَّ أُخْبِرَ أَنَّهُ مُحْصَنٌ فَأَمَرَ بِهِ فَرُجِمَ ‏.‏ قَالَ أَبُو دَاوُدَ رَوَى هَذَا الْحَدِيثَ مُحَمَّدُ بْنُ بَكْرٍ الْبُرْسَانِيُّ عَنِ ابْنِ جُرَيْجٍ مَوْقُوفًا عَلَى جَابِرٍ ‏.‏ وَرَوَاهُ أَبُو عَاصِمٍ عَنِ ابْنِ جُرَيْجٍ بِنَحْوِ ابْنِ وَهْبٍ لَمْ يَذْكُرِ النَّبِيَّ صلى الله عليه وسلم قَالَ إِنَّ رَجُلاً زَنَى فَلَمْ يَعْلَمْ بِإِحْصَانِهِ فَجُلِدَ ثُمَّ عَلِمَ بِإِحْصَانِهِ فَرُجِمَ ‏.‏","Narrated Jabir ibn Abdullah: A man committed fornication with a woman. So the Messenger of Allah (ﷺ) ordered regarding him and the prescribed punishment of flogging was inflicted on him. He was then informed that he was married. So he commanded regarding him and he was stoned to death. Abu Dawud said: This tradition has been transmitted by Muhammad b. Bakr al-Barsani from Ibn Juraij as a statement of Jabir, and Abu 'Asim has transmitted it from Ibn Juraid similar to that of Ibn Wahb. He did not mention the Prophet (ﷺ). But he said: A man committed fornication, but did not know that he was married ; so he was flogged. It was then known that he was married, so he was stoned to death","","Daif Isnaad"],[4439,4439,4439,"। জাবির (রাঃ) সূত্রে বর্ণিত। এক লোক জনৈকা স্ত্রীলোকের সঙ্গে ব্যভিচার করে। পুরুষটি বিবাহিত কি না তা জানা যায়নি। সুতরাং তাকে বেত্রাঘাত করা হয়। অতঃপর তার বৈবাহিক অবস্থা জানা গেলে তাকে পাথর নিক্ষেপে হত্যা করা হয়।[1] দুর্বল মাওকুফ।","حَدَّثَنَا مُحَمَّدُ بْنُ عَبْدِ الرَّحِيمِ أَبُو يَحْيَى الْبَزَّازُ، أَخْبَرَنَا أَبُو عَاصِمٍ، عَنِ ابْنِ جُرَيْجٍ، عَنْ أَبِي الزُّبَيْرِ، عَنْ جَابِرٍ، أَنَّ رَجُلاً، زَنَى بِامْرَأَةٍ فَلَمْ يَعْلَمْ بِإِحْصَانِهِ فَجُلِدَ ثُمَّ عَلِمَ بِإِحْصَانِهِ فَرُجِمَ ‏.‏","Jabir said:A man committed fornication with a woman. It was not known that he was married. So he was flogged. It was then known that he was married, so he was stoned to death","","Daif Muquf"],[4440,4440,4440,"। ইমরান ইবনু হুসাইন (রাঃ) সূত্রে বর্ণিত। একদা জুহাইনাহ গোত্রের জনৈকা মহিলা নবী সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম-এর নিকট এসে বললো, সে যেনা করেছে এবং অন্তঃসত্তা হয়েছে। রাসূলুল্লাহ সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম তার অভিভাবককে ডেকে এনে বলেনঃ এর সঙ্গে উত্তম আচরণ করো। আর যখন সে সন্তান প্রসব করবে, তাকে আমার নিকট নিয়ে এসো। অতঃপর সে সন্তান প্রসব করলে অভিবাবক তাকে নিয়ে এলো। নবী সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম-এর আদেশে তাকে কাপড় দিয়ে বেঁধে পাথর নিক্ষেপে হত্যা করা হয়। অতঃপর তিনি সাহাবীদের আদেশ দিলেন তার জানাযার সালাত পড়তে। উমার (রাঃ) বললেন, হে আল্লাহর রাসূল! আপনি তার জানাযার সালাত পড়বেন? সে তো যেনা করেছে। তিনি বললেনঃ যার হাতে আমার প্রাণ তাঁর কসম! সে এরূপ তওবা করেছে, যা মদীনাবাসীদের সত্তরজনের মধ্যে বণ্টন করে দিলেও তাদের জন্য তা যথেষ্ট হবে। তুমি তার চাইতে উত্তম কোনো ব্যক্তিকে পাবে যে নিজের সত্তাকে উৎসর্গ করে দিলো। আবান সূত্রে বর্ণিত হাদীসে কাপড় দিয়ে বাঁধার কথাটুকু নেই।[1] সহীহ।","حَدَّثَنَا مُسْلِمُ بْنُ إِبْرَاهِيمَ، أَنَّ هِشَامًا الدَّسْتَوَائِيَّ، وَأَبَانَ بْنَ يَزِيدَ، حَدَّثَاهُمُ - الْمَعْنَى، - عَنْ يَحْيَى، عَنْ أَبِي قِلاَبَةَ، عَنْ أَبِي الْمُهَلَّبِ، عَنْ عِمْرَانَ بْنِ حُصَيْنٍ، أَنَّ امْرَأَةً، - قَالَ فِي حَدِيثِ أَبَانَ مِنْ جُهَيْنَةَ - أَتَتِ النَّبِيَّ صلى الله عليه وسلم فَقَالَتْ إِنَّهَا زَنَتْ وَهِيَ حُبْلَى ‏.‏ فَدَعَا النَّبِيُّ صلى الله عليه وسلم وَلِيًّا لَهَا فَقَالَ لَهُ رَسُولُ اللَّهِ صلى الله عليه وسلم ‏\"‏ أَحْسِنْ إِلَيْهَا فَإِذَا وَضَعَتْ فَجِئْ بِهَا ‏\"‏ ‏.‏ فَلَمَّا أَنْ وَضَعَتْ جَاءَ بِهَا فَأَمَرَ بِهَا النَّبِيُّ صلى الله عليه وسلم فَشُكَّتْ عَلَيْهَا ثِيَابُهَا ثُمَّ أَمَرَ بِهَا فَرُجِمَتْ ثُمَّ أَمَرَهُمْ فَصَلَّوْا عَلَيْهَا فَقَالَ عُمَرُ يَا رَسُولَ اللَّهِ تُصَلِّي عَلَيْهَا وَقَدْ زَنَتْ قَالَ ‏\"‏ وَالَّذِي نَفْسِي بِيَدِهِ لَقَدْ تَابَتْ تَوْبَةً لَوْ قُسِّمَتْ بَيْنَ سَبْعِينَ مِنْ أَهْلِ الْمَدِينَةِ لَوَسِعَتْهُمْ وَهَلْ وَجَدْتَ أَفْضَلَ مِنْ أَنْ جَادَتْ بِنَفْسِهَا ‏\"‏ ‏.‏ لَمْ يَقُلْ عَنْ أَبَانَ فَشُكَّتْ عَلَيْهَا ثِيَابُهَا ‏.‏","Narrated Imran ibn Husayn: A woman belonging to the tribe of Juhaynah (according to the version of Aban) came to the Prophet (ﷺ) and said that she had committed fornication and that she was pregnant. The Messenger of Allah (ﷺ) called her guardian. Then the Messenger of Allah (ﷺ) said to him: Be good to her, and when she bears a child, bring her (to me). When she gave birth to the child, he brought her (to him). The Prophet (ﷺ) gave orders regarding her, and her clothes were tied to her. He then commanded regarding her and she was stoned to death. He commanded the people (to pray) and they prayed over her. Thereupon Umar said: Are you praying over her, Messenger of Allah, when she has committed fornication? He said: By Him in Whose hand my soul is, she has repented to such an extent that if it were divided among the seventy people of Medina, it would have been enough for them all. And what do you find better than the fact that she gave her life. Aban did not say in his version: Then her clothes were tied to her","","Sahih"],[4441,4441,4441,"। আওযাঈ (রহঃ) থেকে বর্ণিত। তিনি বলেন, তাকে তার কাপড় শক্তভাবে পরানো হয়।[1] সহীহ।","حَدَّثَنَا مُحَمَّدُ بْنُ الْوَزِيرِ الدِّمَشْقِيُّ، حَدَّثَنَا الْوَلِيدُ، عَنِ الأَوْزَاعِيِّ، قَالَ فَشُكَّتْ عَلَيْهَا ثِيَابُهَا ‏.‏ يَعْنِي فَشُدَّتْ ‏.‏","Al-Auza’i said:The word shukkta means tied, meaning her clothes were tied on her","আওযাঈ (রহঃ","Sahih"],[4442,4442,4442,"। আব্দুল্লাহ ইবনু বুরাইদাহ (রহঃ) থেকে তার পিতার সূত্রে বর্ণিত। গামিদ গোত্রের এক নারী নবী সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম-এর নিকট এসে বললো, আমি ব্যভিচার করেছি, তিনি বললেনঃ ফিরে যাও। সে ফিরে চলে গেলো। পরদিনে সকালে সে আবার তাঁর নিকট এসে বললো, আপনি যেরূপ মাঈয ইবনু মালিককে ফিরিয়ে দিয়েছিলেন, সম্ভবত আমাকেও সেরূপ ফিরিয়ে দিতে চান। আল্লাহর কসম! আমি নিশ্চয়ই গর্ভবতী। তিনি এবারো তাকে ফিরিয়ে যেতে বললে সে চলে গেলো। পরদিন সে পুনরায় আসতেই তিনি বললেনঃ তুমি ফির যাও, যতক্ষণ না সন্তান প্রসব করো। সে ফিরে গেলো। যখন সে পুত্র সন্তান প্রসব করলো, তখন সেই শিশুটিকে কোলে করে নিয়ে এসে বললো, এই শিশুটিকে আমি প্রসব করেছি। তিনি বললেনঃ তুমি ফিরে যাও এবং দুধ ছাড়ানো পর্যন্ত তাকে দুধ পান করাতে থাকো। অবশেষে দুধ ছাড়ানো হলে শিশুটিকে নিয়ে সে হাযির হলো। শিশুটি খাদ্য হাতে নিয়ে খাচ্ছিল। তিনি একজন মুসলিমে তার ছেলেটিকে নিয়ে যাওয়ার আদেশ দিলেন। অতঃপর তার জন্য গর্ত খনন করতে আদেশ দিলেন তা খনন করা হলো এবং পাথর মেরে হত্যার আদেশ দিলে তাকে এভাবে হত্যা করা হলো। তাকে পাথর মারার জন্য নিয়োজিত ব্যক্তিদের মধ্যে খালিদ (রাঃ)-ও ছিলেন। তিনি তাকে পাথর মারলে এক ফোঁটা রক্ত ছিটে এসে তাঁর গাড়ে পড়তেই তিনি তাকে গালি দেন। নবী সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম তাকে বললেনঃ হে খালিদ! অনুগ্রহ করো। যাঁর হাতে আমার প্রাণ তাঁর কসম! সে এরূপ তওবা করেছে যে, কোনো যালিম কর আদায়কারীও যদি সেরূপ তওবা করতো, তাহলে অবশ্যই তাকে মাফ করা হতো। অতঃপর তাঁর আদেশে তার জানাযার সালাত পড়া হয় এবং তাকে দাফন করা হয়।[1] সহীহ।","حَدَّثَنَا إِبْرَاهِيمُ بْنُ مُوسَى الرَّازِيُّ، أَخْبَرَنَا عِيسَى بْنُ يُونُسَ، عَنْ بَشِيرِ بْنِ الْمُهَاجِرِ، حَدَّثَنَا عَبْدُ اللَّهِ بْنُ بُرَيْدَةَ، عَنْ أَبِيهِ، أَنَّ امْرَأَةً، - يَعْنِي مِنْ غَامِدَ - أَتَتِ النَّبِيَّ صلى الله عليه وسلم فَقَالَتْ إِنِّي قَدْ فَجَرْتُ ‏.‏ فَقَالَ ‏\"‏ ارْجِعِي ‏\"‏ ‏.‏ فَرَجَعَتْ فَلَمَّا كَانَ الْغَدُ أَتَتْهُ فَقَالَتْ لَعَلَّكَ أَنْ تَرُدَّنِي كَمَا رَدَدْتَ مَاعِزَ بْنَ مَالِكٍ فَوَاللَّهِ إِنِّي لَحُبْلَى ‏.‏ فَقَالَ لَهَا ‏\"‏ ارْجِعِي ‏\"‏ ‏.‏ فَرَجَعَتْ فَلَمَّا كَانَ الْغَدُ أَتَتْهُ فَقَالَ لَهَا ‏\"‏ ارْجِعِي حَتَّى تَلِدِي ‏\"‏ ‏.‏ فَرَجَعَتْ فَلَمَّا وَلَدَتْ أَتَتْهُ بِالصَّبِيِّ فَقَالَتْ هَذَا قَدْ وَلَدْتُهُ ‏.‏ فَقَالَ لَهَا ‏\"‏ ارْجِعِي فَأَرْضِعِيهِ حَتَّى تَفْطِمِيهِ ‏\"‏ ‏.‏ فَجَاءَتْ بِهِ وَقَدْ فَطَمَتْهُ وَفِي يَدِهِ شَىْءٌ يَأْكُلُهُ فَأَمَرَ بِالصَّبِيِّ فَدُفِعَ إِلَى رَجُلٍ مِنَ الْمُسْلِمِينَ وَأَمَرَ بِهَا فَحُفِرَ لَهَا وَأَمَرَ بِهَا فَرُجِمَتْ وَكَانَ خَالِدٌ فِيمَنْ يَرْجُمُهَا فَرَجَمَهَا بِحَجَرٍ فَوَقَعَتْ قَطْرَةٌ مِنْ دَمِهَا عَلَى وَجْنَتِهِ فَسَبَّهَا فَقَالَ لَهُ النَّبِيُّ صلى الله عليه وسلم ‏\"‏ مَهْلاً يَا خَالِدُ فَوَالَّذِي نَفْسِي بِيَدِهِ لَقَدْ تَابَتْ تَوْبَةً لَوْ تَابَهَا صَاحِبُ مَكْسٍ لَغُفِرَ لَهُ ‏\"‏ ‏.‏ وَأَمَرَ بِهَا فَصُلِّيَ عَلَيْهَا فَدُفِنَتْ ‏.‏","Buraidah said:A woman of Ghamid came to the Prophet (ﷺ) and said: I have committed fornication. He said: Go back. She returned, and on the next day she came to him again, and said: Perhaps you want to send me back as you did to Ma’iz b. Malik. I swear by Allah, I am pregnant. He said to her: Go back. She then returned and came to him the next day. He said to her: Go back until you give birth to a child. She then returned. When she gave birth to a child, she brought the child to him, and said: Here it is! I have given birth to it. He said: Go back, and suckle him until you wean him. When she had weaned him, she brought him (the boy) to him with something in his hand which he was eating. The boy was then given to a certain man of the Muslims and he (the Prophet) commanded regarding her. So a pit was dug for her, and he gave orders about her and she was stoned to death. Khalid was one of those who were throwing stones at her. He threw a stone at her. When a drop blood fell on his cheeks, he abused her. The Prophet (ﷺ) said to him: Gently, Khalid. By Him in whose hand my soul is, she has reported to such an extent that if one who wrongfully takes extra tax were to repent to a like extent, he would be forgiven. Then giving command regarding her, prayed over her and she was buried","","Sahih"],[4443,4443,4443,"। ইবনু আবূ বাকরাহ (রহঃ) থেকে তার পিতার সূত্রে বর্ণিত। নবী সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম জনৈকা মহিলাকে রজম করেন। তার জন্য বুক পর্যন্ত গর্ত খনন করা হয়। ইমাম আবূ দাঊদ (রহঃ) বলেন, এক লোক উসমান সূত্রে বর্ণনা করে এ হাদীস আমাকে বুঝিয়ে দেন। ইমাম আবূ দাঊদ (রহঃ) বলেন, গাসসানী বলেছেন, জুহাইনা গামিদ ও বারিক একই গোত্র।[1] সহীহ।","حَدَّثَنَا عُثْمَانُ بْنُ أَبِي شَيْبَةَ، حَدَّثَنَا وَكِيعُ بْنُ الْجَرَّاحِ، عَنْ زَكَرِيَّا أَبِي عِمْرَانَ، قَالَ سَمِعْتُ شَيْخًا، يُحَدِّثُ عَنِ ابْنِ أَبِي بَكْرَةَ، عَنْ أَبِيهِ، أَنَّ النَّبِيَّ صلى الله عليه وسلم رَجَمَ امْرَأَةً فَحُفِرَ لَهَا إِلَى الثَّنْدُوَةِ ‏.‏ قَالَ أَبُو دَاوُدَ أَفْهَمَنِي رَجُلٌ عَنْ عُثْمَانَ ‏.‏ قَالَ أَبُو دَاوُدَ قَالَ الْغَسَّانِيُّ جُهَيْنَةُ وَغَامِدٌ وَبَارِقٌ وَاحِدٌ ‏.‏","Narrated Zakariya Abi 'Imran: I heard an old man who transmitted from Abu Bakrah on this father's authority that the Prophet (ﷺ) had a woman stoned and a pit was dug up to her breasts. Abu Dawud said: A man made me understand it from 'Uthman (b. Abi Shaibah) Abu Dawud said: Al-Ghassani said: Juhainah, Ghamid and Bariq as the same","","Sahih"],[4444,4444,4444,"। যাকারিয়া ইবনু সুলাইম সূত্রে অনুরূপ হাদীস বর্ণিত। তাতে আরো আছেঃ অতঃপর তাকে চানাবুটের ক্ষুদ্র কংকর নিক্ষেপ করেছেন। তিনি বলেনঃ তার মুখমন্ডল বাদ দিয়ে পাথর নিক্ষেপ করো। সে যখন মারা গেলো, তাকে গর্ত থেকে বের করলেন এবং তার জানাযা পড়লেন। তার তওবা সম্পর্কে বুরাইদাহ বর্ণিত হাদীসের মতই বলেছেন।[1] সনদ দুর্বল।","قَالَ أَبُو دَاوُدَ حُدِّثْتُ عَنْ عَبْدِ الصَّمَدِ بْنِ عَبْدِ الْوَارِثِ، قَالَ حَدَّثَنَا زَكَرِيَّا بْنُ سُلَيْمٍ، بِإِسْنَادِهِ نَحْوَهُ زَادَ ثُمَّ رَمَاهَا بِحَصَاةٍ مِثْلَ الْحُمُّصَةِ ثُمَّ قَالَ ‏ \"‏ ارْمُوا وَاتَّقُوا الْوَجْهَ ‏\"‏ ‏.‏ فَلَمَّا طَفِئَتْ أَخْرَجَهَا فَصَلَّى عَلَيْهَا وَقَالَ فِي التَّوْبَةِ نَحْوَ حَدِيثِ بُرَيْدَةَ ‏.‏","Abu Dawud said:A similar tradition has been transmitted by Zakariya b. Salim through a different chain of narrators. This version adds: He (the Prophet) then threw a pebble like a gram at her. He then said: Throw at her and avoid her face. When se died, he took her out and prayed over her. About repentance he said similar to the tradition on Buraidah","","Daif Isnaad"],[4445,4445,4445,"। উবাইদুল্লাহ ইবনু আব্দুল্লাহ ইবনু উতবাহ ইবনু মাসঊদ (রহঃ) সূত্রে বর্ণিত। আবূ হুরাইরাহ এবং যায়িদ ইবনু খালিদ আল-জুহানী (রাঃ) তার নিকট বর্ণনা করেছেন যে, দু’ বিবাদমান ব্যক্তি রাসূলুল্লাহ সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম-এর নিকট আসলো। তাদের একজন বললো, হে আল্লাহর রাসূল! কুরআন অনুসারে আমাদের মাঝে ফায়সালা করে দিন। দ্বিতীয়জন বললো, সে ছিলো তাদের দু’ জনের মধ্যে অধিক বুদ্ধিমান, হ্যাঁ ঠিক আছে, হে আল্লাহর রাসূল! আমাদের মাঝে আল্লাহর কিতাব অনুসারে ফায়সালা করে দিন, আর আমাকে কিছু বলার অনুমতি দিন। তিনি বললেনঃ বলো। সে বললো, আমার ছেলে এই লোকটির শ্রমিক ছিলো। সে তার স্ত্রীর সঙ্গে যেনা করেছে। কতক লোক আমাকে জানিয়েছে, আমার ছেলের দন্ড হলো পাথর নিক্ষেপে হত্যা। সুতরাং আমি তার পক্ষ থেকে একশী বকরী ও আমার একটি দাসী জরিমানা দেই। পুনরায় আমি এ ব্যাপারে জ্ঞানীদের প্রশ্ন করলে তারা আমাকে বলেন যে, আমার ছেলের শাস্তি হলো একশো বেত্রাঘাত ও এক বছরের নির্বাসন, আর এই লোকটির স্ত্রীর শাস্তি হলো পাথর নিক্ষেপে হত্যা করা। এ ঘটনা শুনে রাসূলুল্লাহ সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম বলেনঃ জেনে রাখো, যে পবিত্র সত্তার হাতে আমার প্রাণ, তাঁর কসম! আমি অবশ্যই তোমাদের মাঝে মহান আল্লাহর কিতাব মোতাবেক ফায়সালা করবো। তোমার বকরী ও দাসী তুমি ফিরে পাবে। অতঃপর তিনি তার ছেলেকে একশো বেত্রাঘাত করেন এবং এক বছরের নির্বাসন দেন এবং উনাইস আল-আসলামীকে আদেশ দেন অপর লোকটির স্ত্রীর নিকট যেতে এবং সে যদি স্বীকারোক্তি করে তাহলে তাকে রজম করতে। অতএব সে স্বীকারোক্তি করলে তিনি তাকে রজম করলেন।[1] সহীহ।","حَدَّثَنَا عَبْدُ اللَّهِ بْنُ مَسْلَمَةَ الْقَعْنَبِيُّ، عَنْ مَالِكٍ، عَنِ ابْنِ شِهَابٍ، عَنْ عُبَيْدِ اللَّهِ بْنِ عَبْدِ اللَّهِ بْنِ عُتْبَةَ بْنِ مَسْعُودٍ، عَنْ أَبِي هُرَيْرَةَ، وَزَيْدِ بْنِ خَالِدٍ الْجُهَنِيِّ، أَنَّهُمَا أَخْبَرَاهُ أَنَّ رَجُلَيْنِ اخْتَصَمَا إِلَى رَسُولِ اللَّهِ صلى الله عليه وسلم فَقَالَ أَحَدُهُمَا يَا رَسُولَ اللَّهِ اقْضِ بَيْنَنَا بِكِتَابِ اللَّهِ ‏.‏ وَقَالَ الآخَرُ وَكَانَ أَفْقَهَهُمَا أَجَلْ يَا رَسُولَ اللَّهِ فَاقْضِ بَيْنَنَا بِكِتَابِ اللَّهِ وَائْذَنْ لِي أَنْ أَتَكَلَّمَ ‏.‏ قَالَ ‏\"‏ تَكَلَّمْ ‏\"‏ ‏.‏ قَالَ إِنَّ ابْنِي كَانَ عَسِيفًا عَلَى هَذَا - وَالْعَسِيفُ الأَجِيرُ - فَزَنَى بِامْرَأَتِهِ فَأَخْبَرُونِي أَنَّمَا عَلَى ابْنِي الرَّجْمَ فَافْتَدَيْتُ مِنْهُ بِمِائَةِ شَاةٍ وَبِجَارِيَةٍ لِي ثُمَّ إِنِّي سَأَلْتُ أَهْلَ الْعِلْمِ فَأَخْبَرُونِي أَنَّمَا عَلَى ابْنِي جَلْدُ مِائَةٍ وَتَغْرِيبُ عَامٍ وَإِنَّمَا الرَّجْمُ عَلَى امْرَأَتِهِ ‏.‏ فَقَالَ رَسُولُ اللَّهِ صلى الله عليه وسلم ‏\"‏ أَمَا وَالَّذِي نَفْسِي بِيَدِهِ لأَقْضِيَنَّ بَيْنَكُمَا بِكِتَابِ اللَّهِ أَمَّا غَنَمُكَ وَجَارِيَتُكَ فَرَدٌّ إِلَيْكَ ‏\"‏ ‏.‏ وَجَلَدَ ابْنَهُ مِائَةً وَغَرَّبَهُ عَامًا وَأَمَرَ أُنَيْسًا الأَسْلَمِيَّ أَنْ يَأْتِيَ امْرَأَةَ الآخَرِ فَإِنِ اعْتَرَفَتْ رَجَمَهَا فَاعْتَرَفَتْ فَرَجَمَهَا ‏.‏","Abu Hurairah and Zaid b. Khalid al-Juhani said:Two men brought a dispute before the Messenger of Allah (ﷺ). One of them said: Pronounce judgement between us in accordance with Allah’s Book, Messenger of Allah! The other who had more understanding said: Yes, Messenger of Allah! Pronounce judgement between us in accordance with Allah’s Book, and allow me to speak. He (the Prophet) said: Speak, He then said: My son who was a hired servant with this(man) committed fornication with his wife, and when I was told that my son must be stoned to death, I ransomed him with a hundred sheep and a slave girl of mine; but when I asked the learned, they told me that my son should receive a hundred lashes and be banished for a year, and that stoning to death applied only to man’s wife. The apostle of Allah (ﷺ) replied: By him in whose hand my soul is, I shall certainly pronounce judgment between you in accordance with Allah’s Book. Your sheep and your slave girl must be returned to you, and your son shall receive a hundred lashes and be banished for a year. And he commanded Unias al-Aslami go to that man’s wife, and if she confessed, he should stone her to death. She confessed and he stoned her","","Sahih"],[4446,4446,4446,"। ইবনু উমার (রাঃ) সূত্রে বর্ণিত। তিনি বলেন, একদা ইয়াহুদীরা নবী সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম-এর নিকট এসে বললো, তাদের একজোড়া নারী-পুরুষ যেনা করেছে। রাসূলুল্লাহ সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম তাদের বললেনঃ তাওরাতে তোমরা যেনা সম্বন্ধে কি হুকুম পেয়েছো? তারা বললো, আমরা তো অপমান করি এবং তাদেরকে বেত্রাঘাত করা হয়। একথা শুনে আব্দুল্লাহ ইবনু সালাম (রাঃ) বলেন, তোমরা মিথ্যা বলেছো। নিশ্চয়ই তাতে রজম করার হুকুম বিদ্যমান। অতঃপর তারা তাওরাত কিতাব নিয়ে আসে এবং তা খোলে। তাদের একজন তার একটি হাত রজমের আয়াতের উপর রেখে দিয়ে এর পূর্বাপর পড়তে থাকে। আব্দুল্লাহ ইবনু সালাম (রাঃ) তাকে হাত উঠিয়ে নিতে আদেশ দেন। সে হাত উঠিয়ে নিতেই দেখা গেলো যে, তাতে রজমের আয়াত রয়েছে। তারা বললো, হে মুহাম্মাদ! তিনি সত্যিই বলেছেন, নিশ্চয়ই তাতে রজমের আয়াত আছে। অতঃপর রাসূলুল্লাহ সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম-এর আদেশে দু’ জনকেই রজম করা হলো। আব্দুল্লাহ ইবনু উমার (রাঃ) বলেন, আমি দেখলাম, পুরুষটি ঐ নারীকে পাথরের আঘাত থেকে রক্ষার জন্য তার দিকে ধাবিত হচ্ছে।[1] সহীহ।","حَدَّثَنَا عَبْدُ اللَّهِ بْنُ مَسْلَمَةَ، قَالَ قَرَأْتُ عَلَى مَالِكِ بْنِ أَنَسٍ عَنْ نَافِعٍ، عَنِ ابْنِ عُمَرَ، أَنَّهُ قَالَ إِنَّ الْيَهُودَ جَاءُوا إِلَى النَّبِيِّ صلى الله عليه وسلم فَذَكَرُوا لَهُ أَنَّ رَجُلاً مِنْهُمْ وَامْرَأَةً زَنَيَا فَقَالَ لَهُمْ رَسُولُ اللَّهِ صلى الله عليه وسلم ‏ \"‏ مَا تَجِدُونَ فِي التَّوْرَاةِ فِي شَأْنِ الزِّنَا ‏\"‏ ‏.‏ فَقَالُوا نَفْضَحُهُمْ وَيُجْلَدُونَ ‏.‏ فَقَالَ عَبْدُ اللَّهِ بْنُ سَلاَمٍ كَذَبْتُمْ إِنَّ فِيهَا الرَّجْمَ ‏.‏ فَأَتَوْا بِالتَّوْرَاةِ فَنَشَرُوهَا فَجَعَلَ أَحَدُهُمْ يَدَهُ عَلَى آيَةِ الرَّجْمِ ثُمَّ جَعَلَ يَقْرَأُ مَا قَبْلَهَا وَمَا بَعْدَهَا فَقَالَ لَهُ عَبْدُ اللَّهِ بْنُ سَلاَمٍ ارْفَعْ يَدَكَ ‏.‏ فَرَفَعَهَا فَإِذَا فِيهَا آيَةُ الرَّجْمِ فَقَالُوا صَدَقَ يَا مُحَمَّدُ فِيهَا آيَةُ الرَّجْمِ ‏.‏ فَأَمَرَ بِهِمَا رَسُولُ اللَّهِ صلى الله عليه وسلم فَرُجِمَا ‏.‏ قَالَ عَبْدُ اللَّهِ بْنُ عُمَرَ فَرَأَيْتُ الرَّجُلَ يَحْنِي عَلَى الْمَرْأَةِ يَقِيهَا الْحِجَارَةَ ‏.‏","Ibn ‘Umar said:some jews came to the Messenger of Allah (ﷺ) and mentioned to him that a man and a women of their number had committed fornication. The Messenger of Allah (ﷺ) asked them: What do you find in the Torah about stoning? They replied: We disgrace them and they should be flogged. ‘Abd Allah b. Salam said: You lie; it contains (instruction for) stoning. So they brought the Torah and spread it out, and one of them put his hand over the verse of stoning and read what preceded it and what followed it. ‘Abd Allah b. Salam said to him: Lift your hand. When he did so, the verse of stoning was seen to be in it. They then said: He has spoken the truth, Muhammad, the verse of stoning is in it. The Messenger of Allah (ﷺ) then gave command regarding them, and they were stoned to death. ‘Abd Allah b. ‘Umar said: I saw the man leaning on the woman protecting her from the stones","","Sahih"],[4447,4447,4447,"। আল-বারাআ ইবনু আযিব (রাঃ) সূত্রে বর্ণিত। তিনি বলেন, একদা কালিমা মাখা মুখ বিশিষ্ট এক ইয়াহুদীকে রাসূলুল্লাহ সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম-এর সামনে দিয়ে নিয়ে যাওয়া হচ্ছিল। তাকে জনসমক্ষে ঘুরানো হচ্ছিল। তিনি তাদের কসম দিয়ে বলেন, তাদের কিতাবে যেনাকারীর হাদ্দ কি? বর্ণনাকারী বলেন, তারা তাঁকে তাদের মধ্যকার একজনকে দেখিয়ে দিলো। নবী সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম তাকে প্রশ্ন করেনঃ তোমাদের কিতাবে যেনাকারীর হাদ্দ ঘটলে তাদের শাস্তি থেকে রেহাই দেয়া এবং অন্যদের শাস্তি দেয়া আমরা পছন্দ করলাম না। অতএব আমরা উপরোক্ত শাস্তি বাতিল করে দিয়েছি। রাসূলুল্লাহ সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম নির্দেশ দিলে অপরাধীকে রজম করা হয়। অতঃপর তিনি বলেনঃ হে আল্লাহ! তারা তোমার কিতাবের যে অংশের মৃত্যু ঘটিয়েছিল আমিই প্রথম তা পুনর্জীবিত করলাম।[1] সহীহ।","حَدَّثَنَا مُسَدَّدٌ، حَدَّثَنَا عَبْدُ الْوَاحِدِ بْنُ زِيَادٍ، عَنِ الأَعْمَشِ، عَنْ عَبْدِ اللَّهِ بْنِ مُرَّةَ، عَنِ الْبَرَاءِ بْنِ عَازِبٍ، قَالَ مَرُّوا عَلَى رَسُولِ اللَّهِ صلى الله عليه وسلم بِيَهُودِيٍّ قَدْ حُمِّمَ وَجْهُهُ وَهُوَ يُطَافُ بِهِ فَنَاشَدَهُمْ مَا حَدُّ الزَّانِي فِي كِتَابِهِمْ قَالَ فَأَحَالُوهُ عَلَى رَجُلٍ مِنْهُمْ فَنَشَدَهُ النَّبِيُّ صلى الله عليه وسلم ‏\"‏ مَا حَدُّ الزَّانِي فِي كِتَابِكُمْ ‏\"‏ ‏.‏ فَقَالَ الرَّجْمُ وَلَكِنْ ظَهَرَ الزِّنَا فِي أَشْرَافِنَا فَكَرِهْنَا أَنْ يُتْرَكَ الشَّرِيفُ وَيُقَامَ عَلَى مَنْ دُونَهُ فَوَضَعْنَا هَذَا عَنَّا ‏.‏ فَأَمَرَ بِهِ رَسُولُ اللَّهِ صلى الله عليه وسلم فَرُجِمَ ثُمَّ قَالَ ‏\"‏ اللَّهُمَّ إِنِّي أَوَّلُ مَنْ أَحْيَا مَا أَمَاتُوا مِنْ كِتَابِكَ ‏\"‏ ‏.‏","Al-Bara’ b. Azib said:The people passed by the Messenger of Allah (ﷺ) with a jew whose face blackened with charcoal and he was being taken around. He adjured them by Allah and asked: What is the prescribed punishment for a fornicator in your Divine book? He (the narrator) said: They referred him to a man of them. The Prophet (ﷺ) adjured him and asked: What is the punishment for a fornication in your Divine Book? He replied: Stoning. But fornication spread among our people of rank, so we disliked that a person of rank should be left alone and the punishment be inflicted on one who is lower in rank than him. So we suspended it for us. The Messenger of Allah (ﷺ) then commanded regarding him and he was stoned to death. He then said: O Allah! I am the first to give life to a command of Thy Book which they had killed","","Sahih"],[4448,4448,4448,"। আল-বারাআ ইবনু আযিব (রাঃ) সূত্রে বর্ণিত। তিনি বলেন, বেত্রাঘাতকৃত জনৈক ইয়াহুদীর মুখমন্ডল কালিমালিপ্ত করে রাসূলুল্লাহ সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম-এর পাশ দিয়ে নিয়ে যাওয়া হচ্ছিল। তিনি তাদের ডেকে প্রশ্ন করলেনঃ তোমরা কি যেনাকারীর এরূপ শাস্তির হুকুম পেয়েছ? তারা বললো, হ্যাঁ। অতএব তিনি তাদের একজন আলিমকে ডেকে বললেনঃ তোমাকে সেই আল্লাহর কসম করে বলছি যিনি মূসা (আঃ)-এর উপর তাওরাত কিতাব নাযিল করেছেন! তোমাদের কিতাবে যেনাকারীদের এরূপ শাস্তির কথা উল্লেখ পেয়েছে কি? সে বললো, হে আল্লাহ! না। আপনি যদি এ বিষয়ে আমাকে আল্লাহর কসম না দিতেন, তাহলে আমি অবশ্যই আপনাকে বলতাম না। আমরা আমাদের কিতাবে যেনাকারীর শাস্তি রজমের উল্লেখ পেয়েছি। কিন্তু আমাদের অভিজাত সমাজে যেনার বিস্তার ঘটলে আমরা কোনো মর্যাদাসম্পন্ন লোককে এ অপরাধে ধরতে পারলেও ছেড়ে দিতাম; তবে দুর্বলদের কাউকে পেলে তার উপর শাস্তি বাস্তবায়িত করতাম। অতঃপর আমরা সকলকে আহবান করে বললাম, চলুন, আমরা যেনার শাস্তির ব্যাপারে সকলে ঐকমত্যে পৌঁছে এমন একটি সিদ্ধান্তে উপনীত হই, যাতে সকল শ্রেণীর লোকদের উপর তা বাস্তবায়িত করা যায়। অতঃপর আমরা এর শাস্তিস্বরূপ মুখমন্ডল কালিমালিপ্ত করে অপমান করা এবং বেত্রাঘাত করাতে একমত হই এবং ‘রজম’ পরিত্যাগ করি। রাসূলুল্লাহ সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম বললেনঃ হে আল্লাহ! আমিই প্রথম ব্যক্তি যে তোমার নির্দেশকে পুনর্জীবন দান করেছি, তারা একে প্রাণহীন করার পর। অতঃপর তাঁর নির্দেশে অপরাধীকে রজম করা হয়। অতঃপর মহান আল্লাহ ইয়াহুদীদের সম্পর্কে এ আয়াতগুলো নাযিল করেনঃ ‘‘হে রাসূল! তোমাকে যেন দুঃখ না দেয় যারা কুফরীর দিকে দ্রুত ধাবিত হয় ... তারা বলে, তোমাদেরকে এরূপ বিধান দেয়া হলে তোমরা তা গ্রহণ করো অন্যথায় তোমরা বর্জন করো ... আল্লাহ যা নাযিল করেছেন তদনুসারে যারা বিধান দেয় না, তারাই কাফির (ইয়াহুদীদের সম্পর্কে বলা হয়েছে) ... আল্লাহ যা নাযিল করেছেন তদনুসারে যারা বিধান দেয় না তারাই যালিম (ইয়াহুদীদের সম্পর্কে বলা হয়েছে) ... আল্লাহ যা নাযিল করেছেন তদনুসারে যারা বিধান দেয় না তারা পাপাচারী’’ (সূরা আল-মায়িদাহঃ ৪১-৪৭)। তিনি বলেন, এ আয়াতগুলো কাফির অবাধ্যদের সম্পর্কে নাযিল হয়েছে।[1] সহীহ।","حَدَّثَنَا مُحَمَّدُ بْنُ الْعَلاَءِ، حَدَّثَنَا أَبُو مُعَاوِيَةَ، عَنِ الأَعْمَشِ، عَنْ عَبْدِ اللَّهِ بْنِ مُرَّةَ، عَنِ الْبَرَاءِ بْنِ عَازِبٍ، قَالَ مُرَّ عَلَى رَسُولِ اللَّهِ صلى الله عليه وسلم بِيَهُودِيٍّ مُحَمَّمٍ مَجْلُودٍ فَدَعَاهُمْ فَقَالَ ‏\"‏ هَكَذَا تَجِدُونَ حَدَّ الزَّانِي ‏\"‏ ‏.‏ فَقَالُوا نَعَمْ ‏.‏ فَدَعَا رَجُلاً مِنْ عُلَمَائِهِمْ قَالَ لَهُ ‏\"‏ نَشَدْتُكَ بِاللَّهِ الَّذِي أَنْزَلَ التَّوْرَاةَ عَلَى مُوسَى هَكَذَا تَجِدُونَ حَدَّ الزَّانِي فِي كِتَابِكُمْ ‏\"‏ ‏.‏ فَقَالَ اللَّهُمَّ لاَ وَلَوْلاَ أَنَّكَ نَشَدْتَنِي بِهَذَا لَمْ أُخْبِرْكَ نَجِدُ حَدَّ الزَّانِي فِي كِتَابِنَا الرَّجْمَ وَلَكِنَّهُ كَثُرَ فِي أَشْرَافِنَا فَكُنَّا إِذَا أَخَذْنَا الرَّجُلَ الشَّرِيفَ تَرَكْنَاهُ وَإِذَا أَخَذْنَا الرَّجُلَ الضَّعِيفَ أَقَمْنَا عَلَيْهِ الْحَدَّ فَقُلْنَا تَعَالَوْا فَنَجْتَمِعَ عَلَى شَىْءٍ نُقِيمُهُ عَلَى الشَّرِيفِ وَالْوَضِيعِ فَاجْتَمَعْنَا عَلَى التَّحْمِيمِ وَالْجَلْدِ وَتَرَكْنَا الرَّجْمَ ‏.‏ فَقَالَ رَسُولُ اللَّهِ صلى الله عليه وسلم ‏\"‏ اللَّهُمَّ إِنِّي أَوَّلُ مَنْ أَحْيَا أَمْرَكَ إِذْ أَمَاتُوهُ ‏\"‏ ‏.‏ فَأَمَرَ بِهِ فَرُجِمَ فَأَنْزَلَ اللَّهُ عَزَّ وَجَلَّ ‏{‏ يَا أَيُّهَا الرَّسُولُ لاَ يَحْزُنْكَ الَّذِينَ يُسَارِعُونَ فِي الْكُفْرِ ‏}‏ إِلَى قَوْلِهِ ‏{‏ يَقُولُونَ إِنْ أُوتِيتُمْ هَذَا فَخُذُوهُ وَإِنْ لَمْ تُؤْتَوْهُ فَاحْذَرُوا ‏}‏ إِلَى قَوْلِهِ ‏{‏ وَمَنْ لَمْ يَحْكُمْ بِمَا أَنْزَلَ اللَّهُ فَأُولَئِكَ هُمُ الْكَافِرُونَ ‏}‏ فِي الْيَهُودِ إِلَى قَوْلِهِ ‏{‏ وَمَنْ لَمْ يَحْكُمْ بِمَا أَنْزَلَ اللَّهُ فَأُولَئِكَ هُمُ الظَّالِمُونَ ‏}‏ فِي الْيَهُودِ إِلَى قَوْلِهِ ‏{‏ وَمَنْ لَمْ يَحْكُمْ بِمَا أَنْزَلَ اللَّهُ فَأُولَئِكَ هُمُ الْفَاسِقُونَ ‏}‏ قَالَ هِيَ فِي الْكُفَّارِ كُلُّهَا يَعْنِي هَذِهِ الآيَةَ ‏.‏","Narrated Al-Bara' ibn Azib: The people passed by the Messenger of Allah (ﷺ) with a Jew who was blackened with charcoal and who was being flogged. He called them and said: Is this the prescribed punishment for a fornicator? They said: Yes. He then called on a learned man among them and asked him: I adjure you by Allah Who revealed the Torah to Moses, do you find this prescribed punishment for a fornicator in your divine Book? He said: By Allah, no. If you had not adjured me about this, I should not have informed you. We find stoning to be prescribed punishment for a fornicator in our Divine Book. But it (fornication) became frequent in our people of rank; so when we seized a person of rank, we left him alone, and when we seized a weak person, we inflicted the prescribed punishment on him. So we said: Come, let us agree on something which may be enforced equally on people of higher and lower rank. So we agreed to blacken the face of a criminal with charcoal, and flog him, and we abandoned stoning. The Messenger of Allah (ﷺ) then said: O Allah, I am the first to give life to Thy command which they have killed. So he commanded regarding him (the Jew) and he was stoned to death. Allah Most High then sent down: \"O Apostle, let not those who race one another into unbelief, make thee grieve...\" up to \"They say: If you are given this, take it, but if not, beware!....\" up to \"And if any do fail to judge by (the light of) what Allah hath revealed, they are (no better than) unbelievers,\" about Jews, up to \"And if any do fail to judge by (the right of) what Allah hath revealed, they are no better than) wrong-doers\" about Jews: and revealed the verses up to \"And if any do fail to judge by (the light of) what Allah hath revealed, they are (no better than) those who rebel.\" About this he said: This whole verse was revealed about the infidels","","Sahih"],[4449,4449,4449,"। ইবনু উমার (রাঃ) সূত্রে বর্ণিত। তিনি বলেন, একদা একদল ইয়াহুদী এসে রাসূলুল্লাহ সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম-কে ‘কুফ’ নামক উপত্যকায় ততে আবেদন জানালো। তিনি তাদের এক পাঠাগারে উপস্থিত হলেন। তারা বললো, হে আবুল কাসিম! আমাদের এক ব্যক্তি জনৈকা মহিলার সঙ্গে যেনা করেছে। সুতরাং আপনি এদের সম্পর্কে ফায়সালা দিন। তারা রাসূলুল্লাহ সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম-এর জন্য একটি বালিশ পেতে দিলো। তিনি তাতে বসে তাদের বললেনঃ তোমরা একখানি তাওরাত নিয়ে এসো। তাওরাত নিয়ে আসা হলে তিনি তাঁর নীচে বিছানো বালিশ টেনে নিয়ে তার উপর তাওরাত রাখলেন এবং বললেনঃ আমি তোমার প্রতি এবং তোমায় যিনি নাযিল করেছেন তার প্রতি ঈমান এনেছি। অতঃপর তিনি বললেনঃ তোমাদের মধ্যকার অধিক জ্ঞানী ব্যক্তিকে নিয়ে এসো। অতএব এক যুবককে আনা হলো। অতঃপর তিনি (ইবনু উমার) নাফি থেকে মালিক সূত্রে বর্ণিত হাদীসের অনুরূপ ‘রজম’ সম্পর্কিত ঘটনা বর্ণনা করেন।[1] হাসান।","حَدَّثَنَا أَحْمَدُ بْنُ سَعِيدٍ الْهَمْدَانِيُّ، حَدَّثَنَا ابْنُ وَهْبٍ، حَدَّثَنِي هِشَامُ بْنُ سَعْدٍ، أَنَّ زَيْدَ بْنَ أَسْلَمَ، حَدَّثَهُ عَنِ ابْنِ عُمَرَ، قَالَ أَتَى نَفَرٌ مِنْ يَهُودَ فَدَعَوْا رَسُولَ اللَّهِ صلى الله عليه وسلم إِلَى الْقُفِّ فَأَتَاهُمْ فِي بَيْتِ الْمِدْرَاسِ فَقَالُوا يَا أَبَا الْقَاسِمِ إِنَّ رَجُلاً مِنَّا زَنَى بِامْرَأَةٍ فَاحْكُمْ بَيْنَهُمْ فَوَضَعُوا لِرَسُولِ اللَّهِ صلى الله عليه وسلم وِسَادَةً فَجَلَسَ عَلَيْهَا ثُمَّ قَالَ ‏\"‏ ائْتُونِي بِالتَّوْرَاةِ ‏\"‏ ‏.‏ فَأُتِيَ بِهَا فَنَزَعَ الْوِسَادَةَ مِنْ تَحْتِهِ فَوَضَعَ التَّوْرَاةَ عَلَيْهَا ثُمَّ قَالَ ‏\"‏ آمَنْتُ بِكِ وَبِمَنْ أَنْزَلَكِ ‏\"‏ ‏.‏ ثُمَّ قَالَ ‏\"‏ ائْتُونِي بِأَعْلَمِكُمْ ‏\"‏ ‏.‏ فَأُتِيَ بِفَتًى شَابٍّ ثُمَّ ذَكَرَ قِصَّةَ الرَّجْمِ نَحْوَ حَدِيثِ مَالِكٍ عَنْ نَافِعٍ ‏.‏","Narrated Abdullah Ibn Umar: A group of Jews came and invited the Messenger of Allah (ﷺ) to Quff. So he visited them in their school. They said: AbulQasim, one of our men has committed fornication with a woman; so pronounce judgment upon them. They placed a cushion for the Messenger of Allah (ﷺ) who sat on it and said: Bring the Torah. It was then brought. He then withdrew the cushion from beneath him and placed the Torah on it saying: I believed in thee and in Him Who revealed thee. He then said: Bring me one who is learned among you. Then a young man was brought. The transmitter then mentioned the rest of the tradition of stoning similar to the one transmitted by Malik from Nafi'(No)","","Hasan"],[4450,4450,4450,"। মুহাম্মাদ ইবনু মুসলিম (রহঃ) বলেন, আমি মুযাইনাহ গোত্রের এমন এক ব্যক্তিকে হাদীস বর্ণনা করতে শুনেছি যিনি ছিলেন জ্ঞানপিপাসু ও সংরক্ষণকারী। একদা আমরা সাঈদ ইবনুল মুসাইয়্যাব (রহঃ)-এর নিকট ছিলাম। তিনি আমাদের নিকট হাদীস বর্ণনা করেছেন আবূ হুরাইরাহ (রাঃ) সূত্রে। এটা মা‘মার বর্ণিত হাদীস এবং এটি সর্বাধিক পূর্ণাঙ্গ। তিনি বলেন, ইয়াহুদীদের মধ্যকার একজোড়া নারী-পুরুষ যেনা করেলো। তারা পরস্পরকে বললো, চলো আমরা এই নবী সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম-এর নিকট যাই। তাঁকে তো সহজতর বিধানসহ পাঠানো হয়েছে। তিনি যদি আমাদের এ ব্যাপারে রজম করার পরিবর্তে লঘু শাস্তির বিধান দেন, তাহলে আমরা তা গ্রহণ করবো এবং আল্লাহর নিকট এর মাধ্যমে বাহানা দাঁড় করাবো এবং বললো, হে আল্লাহ! এটা তো আপনার এক নবী প্রদত্ত ফায়সালা। বর্ণনাকারী বলেন, অতঃপর তারা নবী সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম-এর নিকট আসে। এ সময় তিনি সাহাবীদের সঙ্গে মসজিদে বসা ছিলেন। তারা বললো, হে আবুল কাসিম! যেনাকারী নারী ও পুরুষের সম্পর্কে আপনার কি অভিমত? তিনি তাদের পাঠাগারে আসার পূর্ব পর্যন্ত তাদের সঙ্গে কথাও বলেননি। অতঃপর পাঠাগারে দরজায় দাঁড়িয়ে তিনি বললেনঃ তোমাদেরকে সেই আল্লাহর কসম দিয়ে বলছি যিনি মূসা (আঃ)-এর প্রতি তাওরাত কিতাব নাযিল করেছেন! বিবাহিত লোক যেনা করলে তার কি হুকুম তোমরা তাওরাতে পাচ্ছো? তারা বললো, চুল-কালিতে মুখমন্ডল রাঙিয়ে তাজ্বীহ করা হয় এবং বেত্রাঘাত করা হয়। তাজ্বীহ অর্থ হলো, যেনার অপরাধীদ্বয়কে গাধার পিঠে উঠিয়ে উভয়ে পিঠ পরস্পর মিশিয়ে এলাকা জুড়ে চক্কর দেয়া। বর্ণনাকারী বলেন, এ সময় এক যুবককে চুপ করে থাকতে দেখে নবী সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম তাকে কসম দিয়ে অনুরোধ করলে সে বললো, আল্লাহর কসম! আপনি যেহেতু আমাদের কসম দিলেন, আমরা তো তাওরাতে রজমের বিধান পাচ্ছি। অতঃপর নবী সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম তাদের প্রশ্ন করলেনঃ তাহলে তোমরা আল্লাহর বিধানকে এতো হালকা ভাবলে কেন? সে বললো, আমাদের কোনো এক রাজার জনৈক নিকটাত্মীয় যেনার অপরাধী সাব্যস্ত হয়; তিনি তাকে রজমের শাস্তি থেকে অব্যাহতি দিলেন। অতঃপর সাধারণ পরিবারের জনৈক ব্যক্তি যেনা করার অপরাধে দোষী সাব্যস্ত হওয়াতে তিনি তাকে রজম করার ইচ্ছা করেন; কিন্তু দোষী লোকটির পক্ষের লোকেরা তাতে বাধা দিলো। তারা বললো, আপনার আত্মীয়টিকে এনে রজম না করা পর্যন্ত আমাদের এ ব্যক্তিকে রজম করা যাবে না। অতঃপর তারা এ শাস্তির উপর ফায়সালা করে। তখন নবী সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম বললেনঃ আমি নিশ্চয়ই তাওরাতে বিদ্যমান বিধান অনুযায়ী ফায়সালা করবো। অতঃপর তাঁর নির্দেশে তাদেরকে রজম করা হলো। যুহরী (রহঃ) বলেন, আমরা জানতে পেরেছি যে, নিম্নোক্ত আয়াত ইয়াহুদীদের সম্পর্কে নাযিল হয়েছেঃ ‘‘নিশ্চয়ই আমি তাওরাত নাযিল করেছি, যাতে হিদায়াত ও আলো বিদ্যমান ছিলো। আল্লাহর অনুগত নবীগণ এর মাধ্যমে ইয়াহুদীদেরকে বিধান দিতো’’ (সূরা আল-মায়িদাহঃ ৪৪) নবী সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম-ও অনুগত নবীদের অন্তর্ভুক্ত।[1] দুর্বলঃ ইরওয়া হা/ ১২৫৩।","حَدَّثَنَا مُحَمَّدُ بْنُ يَحْيَى، حَدَّثَنَا عَبْدُ الرَّزَّاقِ، أَخْبَرَنَا مَعْمَرٌ، عَنِ الزُّهْرِيِّ، قَالَ حَدَّثَنَا رَجُلٌ، مِنْ مُزَيْنَةَ ح وَحَدَّثَنَا أَحْمَدُ بْنُ صَالِحٍ، حَدَّثَنَا عَنْبَسَةُ، حَدَّثَنَا يُونُسُ، قَالَ قَالَ مُحَمَّدُ بْنُ مُسْلِمٍ سَمِعْتُ رَجُلاً، مِنْ مُزَيْنَةَ مِمَّنْ يَتَّبِعُ الْعِلْمَ وَيَعِيهِ - ثُمَّ اتَّفَقَا - وَنَحْنُ عِنْدَ سَعِيدِ بْنِ الْمُسَيَّبِ فَحَدَّثَنَا عَنْ أَبِي هُرَيْرَةَ - وَهَذَا حَدِيثُ مَعْمَرٍ وَهُوَ أَتَمُّ - قَالَ زَنَى رَجُلٌ مِنَ الْيَهُودِ وَامْرَأَةٌ فَقَالَ بَعْضُهُمْ لِبَعْضٍ اذْهَبُوا بِنَا إِلَى هَذَا النَّبِيِّ فَإِنَّهُ نَبِيٌّ بُعِثَ بِالتَّخْفِيفِ فَإِنْ أَفْتَانَا بِفُتْيَا دُونَ الرَّجْمِ قَبِلْنَاهَا وَاحْتَجَجْنَا بِهَا عِنْدَ اللَّهِ قُلْنَا فُتْيَا نَبِيٍّ مِنْ أَنْبِيَائِكَ - قَالَ - فَأَتَوُا النَّبِيَّ صلى الله عليه وسلم وَهُوَ جَالِسٌ فِي الْمَسْجِدِ فِي أَصْحَابِهِ فَقَالُوا يَا أَبَا الْقَاسِمِ مَا تَرَى فِي رَجُلٍ وَامْرَأَةٍ زَنَيَا فَلَمْ يُكَلِّمْهُمْ كَلِمَةً حَتَّى أَتَى بَيْتَ مِدْرَاسِهِمْ فَقَامَ عَلَى الْبَابِ فَقَالَ ‏\"‏ أَنْشُدُكُمْ بِاللَّهِ الَّذِي أَنْزَلَ التَّوْرَاةَ عَلَى مُوسَى مَا تَجِدُونَ فِي التَّوْرَاةِ عَلَى مَنْ زَنَى إِذَا أُحْصِنَ ‏\"‏ ‏.‏ قَالُوا يُحَمَّمُ وَيُجَبَّهُ وَيُجْلَدُ - وَالتَّجْبِيَةُ أَنْ يُحْمَلَ الزَّانِيَانِ عَلَى حِمَارٍ وَتُقَابَلَ أَقْفِيَتُهُمَا وَيُطَافَ بِهِمَا - قَالَ وَسَكَتَ شَابٌّ مِنْهُمْ فَلَمَّا رَآهُ النَّبِيُّ صلى الله عليه وسلم سَكَتَ أَلَظَّ بِهِ النِّشْدَةَ فَقَالَ اللَّهُمَّ إِذْ نَشَدْتَنَا فَإِنَّا نَجِدُ فِي التَّوْرَاةِ الرَّجْمَ ‏.‏ فَقَالَ النَّبِيُّ صلى الله عليه وسلم ‏\"‏ فَمَا أَوَّلُ مَا ارْتَخَصْتُمْ أَمْرَ اللَّهِ ‏\"‏ ‏.‏ قَالَ زَنَى ذُو قَرَابَةٍ مَعَ مَلِكٍ مِنْ مُلُوكِنَا فَأَخَّرَ عَنْهُ الرَّجْمَ ثُمَّ زَنَى رَجُلٌ فِي أُسْرَةٍ مِنَ النَّاسِ فَأَرَادَ رَجْمَهُ فَحَالَ قَوْمُهُ دُونَهُ وَقَالُوا لاَ يُرْجَمُ صَاحِبُنَا حَتَّى تَجِيءَ بِصَاحِبِكَ فَتَرْجُمَهُ فَاصْطَلَحُوا عَلَى هَذِهِ الْعُقُوبَةِ بَيْنَهُمْ ‏.‏ فَقَالَ النَّبِيُّ صلى الله عليه وسلم ‏\"‏ فَإِنِّي أَحْكُمُ بِمَا فِي التَّوْرَاةِ ‏\"‏ ‏.‏ فَأَمَرَ بِهِمَا فَرُجِمَا ‏.‏ قَالَ الزُّهْرِيُّ فَبَلَغَنَا أَنَّ هَذِهِ الآيَةَ نَزَلَتْ فِيهِمْ ‏{‏ إِنَّا أَنْزَلْنَا التَّوْرَاةَ فِيهَا هُدًى وَنُورٌ يَحْكُمُ بِهَا النَّبِيُّونَ الَّذِينَ أَسْلَمُوا ‏}‏ كَانَ النَّبِيُّ صلى الله عليه وسلم مِنْهُمْ ‏.‏","Narrated AbuHurayrah: (This is Ma'mar's version which is more accurate.) A man and a woman of the Jews committed fornication. Some of them said to the others: Let us go to this Prophet, for he has been sent with an easy law. If he gives a judgment lighter than stoning, we shall accept it, and argue about it with Allah, saying: It is a judgment of one of your prophets. So they came to the Prophet (ﷺ) who was sitting in the mosque among his companions. They said: AbulQasim, what do you think about a man and a woman who committed fornication? He did not speak to them a word till he went to their school. He stood at the gate and said: I adjure you by Allah Who revealed the Torah to Moses, what (punishment) do you find in the Torah for a person who commits fornication, if he is married? They said: He shall be blackened with charcoal, taken round a donkey among the people, and flogged. A young man among them kept silent. When the Prophet (ﷺ) emphatically adjured him, he said: By Allah, since you have adjured us (we inform you that) we find stoning in the Torah (is the punishment for fornication). The Prophet (ﷺ) said: So when did you lessen the severity of Allah's command? He said: A relative of one of our kings had committed fornication, but his stoning was suspended. Then a man of a family of common people committed fornication. He was to have been stoned, but his people intervened and said: Our man shall not be stoned until you bring your man and stone him. So they made a compromise on this punishment between them. The Prophet (ﷺ) said: So I decide in accordance with what the Torah says. He then commanded regarding them and they were stoned to death. Az-Zuhri said: We have been informed that this verse was revealed about them: \"It was We Who revealed the Law (to Moses): therein was guidance and light. By its standard have been judged the Jews, by the Prophet who bowed (as in Islam) to Allah's will","","Daif"],[4451,4451,4451,"। আয-যুহরী (রহঃ) সূত্রে বর্ণিত। তিনি বলেন, আমি মুযাইনাহ গোত্রের জনৈক ব্যক্তিকে সাঈদ ইবনুল মুসাইয়াব (রহঃ) সূত্রে আবূ হুরাইরাহ (রাঃ) বর্ণিত হাদীস বর্ণনা করতে শুনেছি। তিনি বলেন, একজোড়া বিবাহিত ইয়াহুদী নারী-পুরুষ যেনা করে। এ সময় রাসূলুল্লাহ সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম হিজরাত করে মদীনায় আসেন। যেনার শাস্তির ব্যাপারে তাওরাত কিতাবে রজমের বিধান বিদ্যমান ছিলো, কিন্তু ইয়াহুদীরা তা পরিত্যাগ করে ‘তাজবীহ’ নামক শাস্তি চালু করে। তাজবীহ হলো, পাকানো রশি দিয়ে একশোবার প্রহার করা এবং মুখমন্ডলে চুন-কালি মেখে গাধার উপর এমনভাবে বসিয়ে দেয়া যে, অপরাধীর মুখ গাধার পিছন দিকে থাকে। এমনিভাবে তাকে এলাকা জুড়ে চক্কর দেয়া। অতঃপর তাদের ‘আলিমদের একটি দল একত্র হলো এবং অপর একটি দলকে রাসূলুল্লাহ সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম-এর নিকট পাঠিয়ে দিলো এবং তাদের বলে দিলো যে, তাঁকে গিয়ে যেনার শাস্তি সম্পর্কে প্রশ্ন করবে। এভাবে হাদীস বর্ণিত হয়েছে। এ হাদীসে আরো আছেঃ যারা তাঁর ধর্মের অনুসারী নয়, তিনি তাদের মাঝেও ফায়সালা করতেন। অতঃপর এ ব্যাপারে তাঁকে স্বাধীনতা দিয়ে আল্লাহ বলেনঃ ‘‘তারা যদি আপনার নিকট আসে, তবে আপনি তাদের বিচার মীমাংসা করুন অথবা তাদের উপেক্ষা করুন’’ (সূরা আল-মায়িদাহঃ ৪২)।[1] দুর্বল।","حَدَّثَنَا عَبْدُ الْعَزِيزِ بْنُ يَحْيَى أَبُو الأَصْبَغِ الْحَرَّانِيُّ، قَالَ حَدَّثَنِي مُحَمَّدٌ، - يَعْنِي ابْنَ سَلَمَةَ - عَنْ مُحَمَّدِ بْنِ إِسْحَاقَ، عَنِ الزُّهْرِيِّ، قَالَ سَمِعْتُ رَجُلاً، مِنْ مُزَيْنَةَ يُحَدِّثُ سَعِيدَ بْنَ الْمُسَيَّبِ عَنْ أَبِي هُرَيْرَةَ، قَالَ زَنَى رَجُلٌ وَامْرَأَةٌ مِنَ الْيَهُودِ وَقَدْ أُحْصِنَا حِينَ قَدِمَ رَسُولُ اللَّهِ صلى الله عليه وسلم الْمَدِينَةَ وَقَدْ كَانَ الرَّجْمُ مَكْتُوبًا عَلَيْهِمْ فِي التَّوْرَاةِ فَتَرَكُوهُ وَأَخَذُوا بِالتَّجْبِيَةِ يُضْرَبُ مِائَةً بِحَبْلٍ مَطْلِيٍّ بِقَارٍ وَيُحْمَلُ عَلَى حِمَارٍ وَجْهُهُ مِمَّا يَلِي دُبُرَ الْحِمَارِ فَاجْتَمَعَ أَحْبَارٌ مِنْ أَحْبَارِهِمْ فَبَعَثُوا قَوْمًا آخَرِينَ إِلَى رَسُولِ اللَّهِ صلى الله عليه وسلم فَقَالُوا سَلُوهُ عَنْ حَدِّ الزَّانِي ‏.‏ وَسَاقَ الْحَدِيثَ قَالَ فِيهِ قَالَ وَلَمْ يَكُونُوا مِنْ أَهْلِ دِينِهِ فَيَحْكُمَ بَيْنَهُمْ فَخُيِّرَ فِي ذَلِكَ قَالَ ‏{‏ فَإِنْ جَاءُوكَ فَاحْكُمْ بَيْنَهُمْ أَوْ أَعْرِضْ عَنْهُمْ ‏}‏ ‏.‏","Abu Hurairah said:A man and a woman of the Jews who were married committed fornication at the time when the Messenger of Allah (ﷺ) came to Medina. Stoning was a prescribed punishment for them in accordance with the Torah, but they abandoned it and followed tajbiyyah, meaning, the man was beaten a hundred times with a rope painted with tar and was seated on a donkey with his face towards the tail of the donkey. Their rabbis then assembled and sent some people to the Messenger of Allah (ﷺ). They said to them: Ask him about the prescribed punishment for fornication. The transmitter then mentioned the rest of the tradition. They version adds: They were not the followers of his religion, and he (the prophet) was to pronounce judgment between them. So he was given a choice in this verse:”If they do come to thee, either judge between them, or decline to interfere","","Daif"],[4452,4452,4452,"। জাবির ইবনু আব্দুল্লাহ (রাঃ) সূত্রে বর্ণিত। তিনি বলেন, একদল ইয়াহুদী তাদের মধ্যকার যেনার অপরাধী পুরুষ-নারীকে নিয়ে নবী সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম-এর নিকট হাযির হলো। তিনি বলেনঃ তোমাদের মধ্যকার সব চাইতে বিজ্ঞ দু’ জন লোক নিয়ে এসো। অতএব তারা ‘সূরিয়ার’ দু’ পুত্রকে তাঁর নিকট হাযির করলো। তিনি তাদেরকে আল্লাহর কসম দিয়ে প্রশ্ন করেনঃ তোমরা এদের ব্যাপারে তাওরাতে কিরূপ বিধান দেখতে পাও? তারা বললো, আমরা তাওরাতে দেখতে পাই, চারজন সাক্ষী যদি সাক্ষ্য দেয় যে, তারা পুরুষটির গুপ্তাঙ্গ স্ত্রী গুপ্তাঙ্গে এরূপভাবে ঢুকানো অবস্থায় দেখেছে, যেরূপ সুরমা শলাকা সুরমাদানিতে ঢুকানো হয়। তাহলে তাদের উভয়কে রজম করা হবে। তিনি প্রশ্ন করলেনঃ তাহলে কোন্ জিনিসটা তোমাদেরকে তাদেরকে রজম করতে বাঁধা দিচ্ছে? তারা উভয়ে বললো, আমাদের শাসনক্ষমতা লোপ পেয়েছে। সুতরাং হত্যা করাকে আমরা অনুমোদন করি না। অতঃপর রাসূলুল্লাহ সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম সাক্ষীদের নিয়ে আসতে ডাকলেন। তারা চারজন সাক্ষী নিয়ে এলো। তারা সাক্ষ্য দিলো যে, সুরমা শলাকা যেরূপ সুরমাদানির ভিতরে ঢুকে যায় ঠিক সেরূপই তারা পুরুষটির গুপ্তাঙ্গ স্ত্রী লোকটির গুপ্তাঙ্গের মধ্যে ঢুকানোর অবস্থায় দেখেছে। অতঃপর নবী সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম তাদের রজম করার নির্দেশ দেন।[1] সহীহ।","حَدَّثَنَا يَحْيَى بْنُ مُوسَى الْبَلْخِيُّ، حَدَّثَنَا أَبُو أُسَامَةَ، قَالَ مُجَالِدٌ أَخْبَرَنَا عَنْ عَامِرٍ، عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ، قَالَ جَاءَتِ الْيَهُودُ بِرَجُلٍ وَامْرَأَةٍ مِنْهُمْ زَنَيَا فَقَالَ ائْتُونِي بِأَعْلَمِ رَجُلَيْنِ مِنْكُمْ فَأَتَوْهُ بِابْنَىْ صُورِيَا فَنَشَدَهُمَا ‏\"‏ كَيْفَ تَجِدَانِ أَمْرَ هَذَيْنِ فِي التَّوْرَاةِ ‏\"‏ ‏.‏ قَالاَ نَجِدُ فِي التَّوْرَاةِ إِذَا شَهِدَ أَرْبَعَةٌ أَنَّهُمْ رَأَوْا ذَكَرَهُ فِي فَرْجِهَا مِثْلَ الْمِيلِ فِي الْمُكْحُلَةِ رُجِمَا ‏.‏ قَالَ ‏\"‏ فَمَا يَمْنَعُكُمَا أَنْ تَرْجُمُوهُمَا ‏\"‏ ‏.‏ قَالاَ ذَهَبَ سُلْطَانُنَا فَكَرِهْنَا الْقَتْلَ فَدَعَا رَسُولُ اللَّهِ صلى الله عليه وسلم بِالشُّهُودِ فَجَاءُوا بِأَرْبَعَةٍ فَشَهِدُوا أَنَّهُمْ رَأَوْا ذَكَرَهُ فِي فَرْجِهَا مِثْلَ الْمِيلِ فِي الْمُكْحُلَةِ فَأَمَرَ رَسُولُ اللَّهِ صلى الله عليه وسلم بِرَجْمِهِمَا ‏.‏","Jabir b. ‘Abd Allah said:The Jews brought a man and a woman of them who had committed fornication. He said: Bring me two learned men or yours. So they brought the two sons of Suriya. He adjured them and said: How do you think about the matter if these two persons bear witness to the effect that they have seen his sexual organ in her female organ (penetrated) like a collyrium stick when enclosed in its case, they will be stoned to death. He asked: What is there which prevents you from stoning them: They replied : Our rule has gone, so we disapproved of killing. The Messenger of Allah (ﷺ) then called four witnesses. They brought four witnesses. Who testified that they had seen his sexual organ (penetrated) in her female organ like a collyrium stick when enclosed in its case. The Prophet (ﷺ) then gave orders for stoning them","","Sahih"],[4453,4453,4453,"। ইবরাহীম ও আশ-শা‘বী (রহঃ) থেকে নবী সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম সূত্রে অনুরূপ হাদীস বর্ণিত। তবে এতে ‘‘তিনি সাক্ষীদের হাযির করতে বললেন। অতএব তারা এসে সাক্ষী দিলো’’- এ কথাটি উল্লেখ নেই।[1] সহীহ।","حَدَّثَنَا وَهْبُ بْنُ بَقِيَّةَ، عَنْ هُشَيْمٍ، عَنْ مُغِيرَةَ، عَنْ إِبْرَاهِيمَ، وَالشَّعْبِيِّ، عَنِ النَّبِيِّ صلى الله عليه وسلم نَحْوَهُ لَمْ يَذْكُرْ فَدَعَا بِالشُّهُودِ فَشَهِدُوا ‏.‏","A similar tradition has also been transmitted by Ibrahim and al-Sha’bi from the Prophet (ﷺ) through a different chain of narrators. But this version does not mention the words:He called the witnesses who testified","","Sahih"],[4454,4454,4454,"। আশ-শা‘বী (রহঃ) সূত্রে অনুরূপ হাদীস বর্ণিত। আমি এটি সহীহ এবং যঈফেও পাইনি।","حَدَّثَنَا وَهْبُ بْنُ بَقِيَّةَ، عَنْ هُشَيْمٍ، عَنِ ابْنِ شُبْرُمَةَ، عَنِ الشَّعْبِيِّ، بِنَحْوٍ مِنْهُ ‏.‏","A similar tradition has also been transmitted by al-Sha’bi through a different chain of narrators","","Daif"],[4455,4455,4455,"। জাবির ইবনু আব্দুল্লাহ (রাঃ) বলেন, একজোড়া ইয়াহুদী নারী-পুরুষ যেনা করলে নবী সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম তাদের রজম করার নির্দেশ দেন।[1] সহীহ।","حَدَّثَنَا إِبْرَاهِيمُ بْنُ حَسَنٍ الْمِصِّيصِيُّ، حَدَّثَنَا حَجَّاجُ بْنُ مُحَمَّدٍ، قَالَ حَدَّثَنَا ابْنُ جُرَيْجٍ، أَنَّهُ سَمِعَ أَبَا الزُّبَيْرِ، سَمِعَ جَابِرَ بْنَ عَبْدِ اللَّهِ، يَقُولُ رَجَمَ النَّبِيُّ صلى الله عليه وسلم رَجُلاً مِنَ الْيَهُودِ وَامْرَأَةً زَنَيَا ‏.‏","Jabir bin ‘Abd Allah said:The Prophet (ﷺ) had a man and a woman of the Jews who had committed fornication stoned to death","","Sahih"],[4456,4456,4456,"। আল-বারা‘আ ইবন আযিব (রাঃ) সূত্রে বর্ণিত। তিনি বলেন, একদা আমি আমার একটি হারানো উট খোঁজ করতে বেরিয়েছি, এমন সময় একদল আরোহী অথবা অশ্বারোহী আমার সামনে এসে উপস্থিত হয়। তাদের নিকট একটি পতাকা ছিলো। এই বেদুঈনরা নবী সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম-এর প্রিয় পাত্র হিসেবে আমার চারদিকে ঘুরতে থাকে। যখন তারা একটি গম্বুজ সদৃশ স্থাপনার নিকট এসে এর ভিতর থেকে একটি লোককে বের করে হত্যা করে তখন আমি তাদেরকে তার সম্পর্কে বললাম। তারা বললো, লোকটি তার পিতার স্ত্রীকে (সৎ মাকে) সঙ্গম করেছিল।[1] সহীহ।","حَدَّثَنَا مُسَدَّدٌ، حَدَّثَنَا خَالِدُ بْنُ عَبْدِ اللَّهِ، حَدَّثَنَا مُطَرِّفٌ، عَنْ أَبِي الْجَهْمِ، عَنِ الْبَرَاءِ بْنِ عَازِبٍ، قَالَ بَيْنَا أَنَا أَطُوفُ، عَلَى إِبِلٍ لِي ضَلَّتْ إِذْ أَقْبَلَ رَكْبٌ أَوْ فَوَارِسُ مَعَهُمْ لِوَاءٌ فَجَعَلَ الأَعْرَابُ يُطِيفُونَ بِي لِمَنْزِلَتِي مِنَ النَّبِيِّ صلى الله عليه وسلم إِذْ أَتَوْا قُبَّةً فَاسْتَخْرَجُوا مِنْهَا رَجُلاً فَضَرَبُوا عُنُقَهُ فَسَأَلْتُ عَنْهُ فَذَكَرُوا أَنَّهُ أَعْرَسَ بِامْرَأَةِ أَبِيهِ ‏.‏","Narrated Al-Bara' ibn Azib: while I was wandering in search of my camels which had strayed, a caravan or some horsemen carrying a standard came forward. The bedouin began to go round me for my position with the Prophet (ﷺ). They came to a domed structure, took out a man from it, and struck his neck. I asked about him. They told me that he had married his father's wife","","Sahih"],[4457,4457,4457,"। ইয়াযীদ ইবনু বারাআ (রহঃ) থেকে তার পিতার সূত্রে বর্ণিত। তিনি বলেন, আমি আমার চাচার সঙ্গে সাক্ষাৎ করি। তখন তার সঙ্গে একটি ঝান্ডা ছিলো। আমি তাকে বলি, কোথায় যাচ্ছেন? তিনি বলেন, রাসূলুল্লাহ সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম আমাকে এক ব্যক্তির নিকট পাঠিয়েছেন, যে তার পিতার স্ত্রীকে (সৎ মাকে) বিয়ে করেছে। তিনি আমাকে আদেশ দিয়েছেন তাকে হত্যা করতে এবং তার সম্পদ নিয়ে আসতে।[1] সহীহ।","حَدَّثَنَا عَمْرُو بْنُ قُسَيْطٍ الرَّقِّيُّ، حَدَّثَنَا عُبَيْدُ اللَّهِ بْنُ عَمْرٍو، عَنْ زَيْدِ بْنِ أَبِي أُنَيْسَةَ، عَنْ عَدِيِّ بْنِ ثَابِتٍ، عَنْ يَزِيدَ بْنِ الْبَرَاءِ، عَنْ أَبِيهِ، قَالَ لَقِيتُ عَمِّي وَمَعَهُ رَايَةٌ فَقُلْتُ لَهُ أَيْنَ تُرِيدُ قَالَ بَعَثَنِي رَسُولُ اللَّهِ صلى الله عليه وسلم إِلَى رَجُلٍ نَكَحَ امْرَأَةَ أَبِيهِ فَأَمَرَنِي أَنْ أَضْرِبَ عُنُقَهُ وَآخُذَ مَالَهُ ‏.‏","Narrated Al-Bara' ibn Azib: I met my uncle who was carrying a standard. I asked him: Where are you going? He said: The Messenger of Allah (ﷺ) has sent me to a man who has married his father's wife. He has ordered me to cut off his head and take his property","","Sahih"],[4458,4458,4458,"। হাবিব ইবনু সালিম (রহঃ) সূত্রে বর্ণিত। আব্দুর রাহমান ইবনু হুনাইন নামক জনৈক ব্যক্তি তার স্ত্রীর দাসীর সঙ্গে সঙ্গম করে। বিষয়টি কূফার গভর্ণর নু‘মান ইবনু বাশীর (রাঃ)-এর নিকট পেশ করা হলে তিনি বলেন, আমি অবশ্যই তোমার সম্পর্কে রাসূলুল্লাহ সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম-এর ফায়সালার মতোই ফায়সালা করবো। তোমার স্ত্রী যদি এ বাঁদীকে তোমার জন্য বৈধ করে দিয়ে থাকে, তবে আমি তোমাকে একশো বেত্রাঘাত করবো, আর যদি তোমার জন্য বৈধ না করে থাকে তাহলে তোমাকে পাথর নিক্ষেপ করে হত্যা করবো। পরে তারা খোঁজ নিয়ে জানতে পারে যে, তার স্ত্রী বাঁদীকে তার জন্য বৈধ করে দিয়েছেন। কাজেই তিনি তাকে একশো বেত্রাঘাত করেন। কাতাদাহ (রহঃ) বলেন, আমি হাবিব ইবনু সালিমের নিকট চিঠি লিখলে তিনি এ হাদীসটি লিখে পাঠান।[1] দুর্বল।","حَدَّثَنَا مُوسَى بْنُ إِسْمَاعِيلَ، حَدَّثَنَا أَبَانُ، حَدَّثَنَا قَتَادَةُ، عَنْ خَالِدِ بْنِ عُرْفُطَةَ، عَنْ حَبِيبِ بْنِ سَالِمٍ، أَنَّ رَجُلاً، يُقَالُ لَهُ عَبْدُ الرَّحْمَنِ بْنُ حُنَيْنٍ وَقَعَ عَلَى جَارِيَةِ امْرَأَتِهِ فَرُفِعَ إِلَى النُّعْمَانِ بْنِ بَشِيرٍ وَهُوَ أَمِيرٌ عَلَى الْكُوفَةِ فَقَالَ لأَقْضِيَنَّ فِيكَ بِقَضِيَّةِ رَسُولِ اللَّهِ صلى الله عليه وسلم إِنْ كَانَتْ أَحَلَّتْهَا لَكَ جَلَدْتُكَ مِائَةً وَإِنْ لَمْ تَكُنْ أَحَلَّتْهَا لَكَ رَجَمْتُكَ بِالْحِجَارَةِ ‏.‏ فَوَجَدُوهُ قَدْ أَحَلَّتْهَا لَهُ فَجَلَدَهُ مِائَةً ‏.‏ قَالَ قَتَادَةُ كَتَبْتُ إِلَى حَبِيبِ بْنِ سَالِمٍ فَكَتَبَ إِلَىَّ بِهَذَا ‏.‏","Narrated An-Nu'man ibn Bashir: Habib ibn Salim said: A man called AbdurRahman ibn Hunayn had intercourse with his wife's slave-girl. The matter was brought to an-Nu'man ibn Bashir who was the Governor of Kufah. He said: I shall decide between you in accordance with the decision of the Messenger of Allah (ﷺ). If she made her lawful for you, I shall flog you one hundred lashes. If she did not make her lawful for you, I shall stone you to death. So they found that she had made her lawful for him. He, therefore, flogged him one hundred lashes. Qatadah said: I wrote to Habib b. Salim; so he wrote this (tradition) to me","","Daif"],[4459,4459,4459,"। নু‘মান ইবনু বাশীর (রাঃ) সূত্রে বর্ণিত। কোনো ব্যক্তি তার স্ত্রীর দাসীর সঙ্গে সঙ্গম করলে, তার স্ত্রী যদি তাকে তার জন্য বৈধ করে দিয়ে থাকে তবে একশো বেত্রাঘাত করা হবে; আর যদি বৈধ করে না দিয়ে থাকে, তবে তাকে আমি রজম করবো।[1] দুর্বল।","حَدَّثَنَا مُحَمَّدُ بْنُ بَشَّارٍ، حَدَّثَنَا مُحَمَّدُ بْنُ جَعْفَرٍ، عَنْ شُعْبَةَ، عَنْ أَبِي بِشْرٍ، عَنْ خَالِدِ بْنِ عُرْفُطَةَ، عَنْ حَبِيبِ بْنِ سَالِمٍ، عَنِ النُّعْمَانِ بْنِ بَشِيرٍ، عَنِ النَّبِيِّ صلى الله عليه وسلم فِي الرَّجُلِ يَأْتِي جَارِيَةَ امْرَأَتِهِ قَالَ ‏ \"‏ إِنْ كَانَتْ أَحَلَّتْهَا لَهُ جُلِدَ مِائَةً وَإِنْ لَمْ تَكُنْ أَحَلَّتْهَا لَهُ رَجَمْتُهُ ‏\"‏ ‏.‏","Narrated An-Nu'man ibn Bashir: The Prophet (ﷺ) said: about a man who had (unlawful) intercourse with his wife's slave girl: If she made her lawful for him, he will be flogged one hundred lashes; if she did not make her lawful for him, I shall stone him","","Daif"],[4460,4460,4460,"। সালামাহ ইবনুল মুহাব্বিক (রাঃ) সূত্রে বর্ণিত। জনৈক ব্যক্তি তার স্ত্রীর দাসীর সঙ্গে সঙ্গম করলো। রাসূলুল্লাহ সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম তার ব্যাপারে ফায়সালা দিলেন, সে যদি তার সঙ্গে জোরপূর্বক এ কাজ করে থাকে, তাহলে দাসী আযাদ এবং তার কর্তব্য হলো, তার মতো একটি দাসী তার মনিবকে (স্ত্রীকে) দেয়া। আর যদি আপোষে তা হয়ে থাকে, তাহলে সে তার মালিকানায় চলে যাবে এবং দাসীর মনিবকে তার মতো একটি দাসী প্রদান করা স্বামীর কর্তব্য হবে। ইমাম আবূ দাঊদ (রহঃ) বলেন, ইউনুস ইবনু উবাইদ, আমর ইবনু দীনার, মানসূর ইবনু যাযান ও সাল্লাম (রহঃ) আল হাসান সূত্রে এ হাদীস পূর্বোক্ত হাদীসের অর্থানুরূপ বর্ণনা করেন। ইউনুস ও মানসুর (রহঃ) কাবীসাহর (রাঃ) উল্লেখ করেননি।[1] দুর্বল।","حَدَّثَنَا أَحْمَدُ بْنُ صَالِحٍ، حَدَّثَنَا عَبْدُ الرَّزَّاقِ، أَخْبَرَنَا مَعْمَرٌ، عَنْ قَتَادَةَ، عَنِ الْحَسَنِ، عَنْ قَبِيصَةَ بْنِ حُرَيْثٍ، عَنْ سَلَمَةَ بْنِ الْمُحَبَّقِ، أَنَّ رَسُولَ اللَّهِ صلى الله عليه وسلم قَضَى فِي رَجُلٍ وَقَعَ عَلَى جَارِيَةِ امْرَأَتِهِ إِنْ كَانَ اسْتَكْرَهَهَا فَهِيَ حُرَّةٌ وَعَلَيْهِ لِسَيِّدَتِهَا مِثْلُهَا فَإِنْ كَانَتْ طَاوَعَتْهُ فَهِيَ لَهُ وَعَلَيْهِ لِسَيِّدَتِهَا مِثْلُهَا ‏.‏ قَالَ أَبُو دَاوُدَ رَوَاهُ يُونُسُ بْنُ عُبَيْدٍ وَعَمْرُو بْنُ دِينَارٍ وَمَنْصُورُ بْنُ زَاذَانَ وَسَلاَّمٌ عَنِ الْحَسَنِ هَذَا الْحَدِيثَ بِمَعْنَاهُ لَمْ يَذْكُرْ يُونُسُ وَمَنْصُورٌ قَبِيصَةَ ‏.‏","Narrated Salamah ibn al-Muhabbaq: The Messenger of Allah (ﷺ) made a decision about a man who had intercourse with his wife's slave-girl as follows. If he forced her, she is free, and he shall give her mistress a slave-girl similar to her; if she asked him to have intercourse voluntarily, she will belong to him, and he shall give her mistress a slave-girl similar to her. Abu Dawud said: This tradition has been transmitted by Yunus b. 'Ubaid, 'Amr b. Dinar, Mansur b. Zadhan and Salam from al-Hasan to the same effect. But yunus and Mansur did not mention Qabisah","","Daif"],[4461,4461,4461,"। সালাম ইবনু মুহাব্বিক (রাঃ) নবী সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম সূত্রে অনুরূপ হাদীস বর্ণনা করেন। তবে এ হাদীসে তিনি বলেনঃ দাসী যদি এ কাজে সম্মতি দিয়ে থাকে, তবে সেও তার মতো আরো একটি দাসী নিজ মাল দ্বারা ক্রয় করে দাসীর মনিবকে প্রদান করবে।[1] দুর্বল।","حَدَّثَنَا عَلِيُّ بْنُ الْحَسَنِ الدِّرْهَمِيُّ، حَدَّثَنَا عَبْدُ الأَعْلَى، عَنْ سَعِيدٍ، عَنْ قَتَادَةَ، عَنِ الْحَسَنِ، عَنْ سَلَمَةَ بْنِ الْمُحَبَّقِ، عَنِ النَّبِيِّ صلى الله عليه وسلم نَحْوَهُ إِلاَّ أَنَّهُ قَالَ وَإِنْ كَانَتْ طَاوَعَتْهُ فَهِيَ حُرَّةٌ وَمِثْلُهَا مِنْ مَالِهِ لِسَيِّدَتِهَا ‏.‏","Narrated Salamah ibn al-Muhabbaq: A similar tradition (to the No. 4445) has also been transmitted by Salamah ibn al-Muhabbaq from the Prophet (ﷺ). This version has: If she asked her to have intercourse with her voluntarily, then she and a similar slave-girl would be given to her mistress from his property","","Daif"],[4462,4462,4462,"। ইবনু আব্বাস (রাঃ) সূত্রে বর্ণিত। তিনি বলেন, রাসূলুল্লাহ সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম বলেছেনঃ তোমরা কাউকে যদি লূত গোত্রের মতই কুর্কমে লিপ্ত দেখতে পাও তাহলে কর্তা ও যার সঙ্গে করা হয়েছে তাদের উভয়কে হত্যা করো।[1] হাসান সহীহ।","حَدَّثَنَا عَبْدُ اللَّهِ بْنُ مُحَمَّدِ بْنِ عَلِيٍّ النُّفَيْلِيُّ، حَدَّثَنَا عَبْدُ الْعَزِيزِ بْنُ مُحَمَّدٍ، عَنْ عَمْرِو بْنِ أَبِي عَمْرٍو، عَنْ عِكْرِمَةَ، عَنِ ابْنِ عَبَّاسٍ، قَالَ قَالَ رَسُولُ اللَّهِ صلى الله عليه وسلم ‏ \"‏ مَنْ وَجَدْتُمُوهُ يَعْمَلُ عَمَلَ قَوْمِ لُوطٍ فَاقْتُلُوا الْفَاعِلَ وَالْمَفْعُولَ بِهِ ‏\"‏ ‏.‏ قَالَ أَبُو دَاوُدَ رَوَاهُ سُلَيْمَانُ بْنُ بِلاَلٍ عَنْ عَمْرِو بْنِ أَبِي عَمْرٍو مِثْلَهُ وَرَوَاهُ عَبَّادُ بْنُ مَنْصُورٍ عَنْ عِكْرِمَةَ عَنِ ابْنِ عَبَّاسٍ رَفَعَهُ وَرَوَاهُ ابْنُ جُرَيْجٍ عَنْ إِبْرَاهِيمَ عَنْ دَاوُدَ بْنِ الْحُصَيْنِ عَنْ عِكْرِمَةَ عَنِ ابْنِ عَبَّاسٍ رَفَعَهُ ‏.‏","Narrated Abdullah ibn Abbas: The Prophet (ﷺ) said: If you find anyone doing as Lot's people did, kill the one who does it, and the one to whom it is done. Abu Dawud said: A similar tradition has also been transmitted by Sulaiman b. Bilal from 'Amr b. Abi 'Umar. And 'Abbad b. Mansur transmitted it from 'Ikrimah on the authority of Ibn 'Abbas who transmitted it from the Prophet (ﷺ). It has also been transmitted by Ibn Juraij from Ibrahim from Dawud b. Al-Husain from 'Ikrimah on the authority of Ibn 'Abbas who transmitted it from the Prophet (ﷺ)","","Hasan Sahih"],[4463,4463,4463,"। ইবনু আব্বাস (রাঃ) সূত্রে বর্ণিত। তিনি বলেন, অবিবাহিতদের লাওয়াতাতে (পায়ুকামে) লিপ্ত পাওয়া গেলে রজম করা হবে। ইমাম আবূ দাঊদ (রহঃ) বলেন, ‘আসিম (রহঃ) সূত্রে বর্ণিত হাদীস আমর ইবনু আবূ আমরের হাদীসকে দুর্বল প্রমাণিত করে।[1] সনদ সহীহ মাওকুফ।","حَدَّثَنَا إِسْحَاقُ بْنُ إِبْرَاهِيمَ بْنِ رَاهَوَيْهِ، حَدَّثَنَا عَبْدُ الرَّزَّاقِ، أَخْبَرَنَا ابْنُ جُرَيْجٍ، أَخْبَرَنِي ابْنُ خُثَيْمٍ، قَالَ سَمِعْتُ سَعِيدَ بْنَ جُبَيْرٍ، وَمُجَاهِدًا، يُحَدِّثَانِ عَنِ ابْنِ عَبَّاسٍ، فِي الْبِكْرِ يُوجَدُ عَلَى اللُّوطِيَّةِ قَالَ يُرْجَمُ ‏.‏ قَالَ أَبُو دَاوُدَ حَدِيثُ عَاصِمٍ يُضَعِّفُ حَدِيثَ عَمْرِو بْنِ أَبِي عَمْرٍو ‏.‏","Narrated Abdullah ibn Abbas: If a man who is not married is seized committing sodomy, he will be stoned to death. Abu Dawud said: The tradition of 'Asim proved the tradition of 'Amir b. Abi 'Amr as weak","","Sahih Isnaad Mauquf"],[4464,4464,4464,"। ইবনু আব্বাস (রাঃ) সূত্রে বর্ণিত। তিনি বলেন, রাসূলুল্লাহ সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম বলেছেনঃ কোনো ব্যক্তি পশুর সঙ্গে সঙ্গম করলে তাকে এবং পশুটিকেও তার সঙ্গে হত্যা করো। তিনি (ইকরিমাহ) বলেন, আমি তাকে (ইবনু আব্বাসকে) বললাম, পশুটির অন্যায় কি? তিনি বলেন, আমার মতে যে পশুর সঙ্গে সঙ্গম করা হয়েছে নিশ্চয়ই তিনি তার গোশত খাওয়া অপছন্দ করেছেন। ইমাম আবূ দাঊদ (রহঃ) বলেন, এটি তেমন শক্তিশালী হাদীস নয়।[1] হাসান সহীহ।","حَدَّثَنَا عَبْدُ اللَّهِ بْنُ مُحَمَّدٍ النُّفَيْلِيُّ، حَدَّثَنَا عَبْدُ الْعَزِيزِ بْنُ مُحَمَّدٍ، حَدَّثَنِي عَمْرُو بْنُ أَبِي عَمْرٍو، عَنْ عِكْرِمَةَ، عَنِ ابْنِ عَبَّاسٍ، قَالَ قَالَ رَسُولُ اللَّهِ صلى الله عليه وسلم ‏ \"‏ مَنْ أَتَى بَهِيمَةً فَاقْتُلُوهُ وَاقْتُلُوهَا مَعَهُ ‏\"‏ ‏.‏ قَالَ قُلْتُ لَهُ مَا شَأْنُ الْبَهِيمَةِ قَالَ مَا أُرَاهُ إِلاَّ قَالَ ذَلِكَ أَنَّهُ كَرِهَ أَنْ يُؤْكَلَ لَحْمُهَا وَقَدْ عُمِلَ بِهَا ذَلِكَ الْعَمَلُ ‏.‏ قَالَ أَبُو دَاوُدَ لَيْسَ هَذَا بِالْقَوِيِّ ‏.‏","Narrated Abdullah ibn Abbas: The Prophet (ﷺ) said: If anyone has sexual intercourse with an animal, kill him and kill it along with him. I (Ikrimah) said: I asked him (Ibn Abbas): What offence can be attributed to the animal/ He replied: I think he (the Prophet) disapproved of its flesh being eaten when such a thing had been done to it. Abu Dawud said: This is not a strong tradition","","Hasan Sahih"],[4465,4465,4465,"। ইবনু আব্বাস (রাঃ) সূত্রে বর্ণিত। তিনি বলেন, পশুর সঙ্গে সঙ্গমকারী হাদ্দের আওতাভুক্ত নয়। ইমাম আবূ দাঊদ (রহঃ) বলেন, আতাও এরূপই বলেছেন। হাকাম বলেন, আমি মনে করি তাকে বেত্রাঘাত করা উচিত; কিন্তু তা হাদ্দের সীমা (একশো বেত্রাঘাত) পর্যন্ত পৌঁছা উচিত নয়। হাসান বাসরী (রহঃ) বলেন, সে যেনাকারীর সমতুল্য। ইমাম আবূ দাঊদ (রহঃ) বলেন, আসিম কর্তৃক বর্ণিত হাদীস আমর ইবনু আবূ আমরের হাদীসকে দুর্বল প্রমাণিত করে।[1] হাসান।","حَدَّثَنَا أَحْمَدُ بْنُ يُونُسَ، أَنَّ شَرِيكًا، وَأَبَا الأَحْوَصِ، وَأَبَا، بَكْرِ بْنَ عَيَّاشٍ حَدَّثُوهُمْ عَنْ عَاصِمٍ، عَنْ أَبِي رَزِينٍ، عَنِ ابْنِ عَبَّاسٍ، قَالَ لَيْسَ عَلَى الَّذِي يَأْتِي الْبَهِيمَةَ حَدٌّ ‏.‏ قَالَ أَبُو دَاوُدَ كَذَا قَالَ عَطَاءٌ وَقَالَ الْحَكَمُ أَرَى أَنْ يُجْلَدَ وَلاَ يَبْلُغَ بِهِ الْحَدَّ ‏.‏ وَقَالَ الْحَسَنُ هُوَ بِمَنْزِلَةِ الزَّانِي ‏.‏ قَالَ أَبُو دَاوُدَ حَدِيثُ عَاصِمٍ يُضَعِّفُ حَدِيثَ عَمْرِو بْنِ أَبِي عَمْرٍو ‏.‏","Asim reported from Abu Razin on the authority of Ibn 'Abbas saying:There is no prescribed punishment for one who has sexual intercourse with an animal. Abu Dawud said: 'Ata is also so. Al Hakam said: I think he should be flogged, but the number should not reach the one of the prescribed punishment. Al-Hasan said: He is like a fornicator. Abu Dawud said: THe tradition of 'Asim proves the tradition of 'Amr b. Abi 'Amr as weak","","Hasan"],[4466,4466,4466,"। সাহল ইবনু সা‘দ (রাঃ) নবী সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম সূত্রে বর্ণনা করেনঃ জনৈক ব্যক্তি তাঁর নিকট এসে স্বীকারোক্তি করলো যে, সে এক স্ত্রীলোকের সঙ্গে যেনা করেছে এবং সে তার নামও বলেছে। রাসূলুল্লাহ সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম তার নিকট লোক পাঠিয়ে এ ব্যাপারে প্রশ্ন করলে সে যেনার কথা অস্বীকার করলো। কাজেই তিনি পুরুষটিকে বেত্রাঘাতের শাস্তি দিলেন এবং স্ত্রীলোকটিকে মুক্তি দিলেন।[1] সহীহ।","حَدَّثَنَا عُثْمَانُ بْنُ أَبِي شَيْبَةَ، حَدَّثَنَا طَلْقُ بْنُ غَنَّامٍ، حَدَّثَنَا عَبْدُ السَّلاَمِ بْنُ حَفْصٍ، حَدَّثَنَا أَبُو حَازِمٍ، عَنْ سَهْلِ بْنِ سَعْدٍ، عَنِ النَّبِيِّ صلى الله عليه وسلم أَنَّ رَجُلاً أَتَاهُ فَأَقَرَّ عِنْدَهُ أَنَّهُ زَنَى بِامْرَأَةٍ سَمَّاهَا لَهُ فَبَعَثَ رَسُولُ اللَّهِ صلى الله عليه وسلم إِلَى الْمَرْأَةِ فَسَأَلَهَا عَنْ ذَلِكَ فَأَنْكَرَتْ أَنْ تَكُونَ زَنَتْ فَجَلَدَهُ الْحَدَّ وَتَرَكَهَا ‏.‏","Narrated Sahl ibn Sa'd: A man came to the Prophet (ﷺ) and made acknowledgment before him that he had committed fornication with a woman whom he named. The Messenger of Allah (ﷺ) sent someone to the woman and he asked her about it. She denied that she had committed fornication. So he gave him the prescribed punishment of lashes and left her","","Sahih"],[4467,4467,4467,"। ইবনু আব্বাস (রাঃ) সূত্রে বর্ণিত। বাকর ইবনু লাইস গোত্রের জনৈক ব্যক্তি নবী সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম-এর নিকট এসে চারবার স্বীকারোক্তি করলো যে, সে জনৈকা স্ত্রীলোকের সঙ্গে যেনা করেছে। সে অবিবাহিত ছিলো বিধায় তিনি তাকে একশো বেত্রাঘাত করেন। অতঃপর তিনি স্ত্রীলোকটির বিরুদ্ধে পর্যাপ্ত সাক্ষী আনার জন্য তাকে আদেশ দেন। স্ত্রীলোকটি বললো, হে আল্লাহর রাসূল! আল্লাহর কসম! সে মিথ্যা বলছে। সুতরাং তিনি পুরুষটিকে যেনার মিথ্যা অপবাদ আরোপের অপরাধে আরো আশিটি বেত্রাঘাত করেন।[1] মুনকারঃ মিশকাত হা/ ৩৫৭৮।","حَدَّثَنَا مُحَمَّدُ بْنُ يَحْيَى بْنِ فَارِسٍ، حَدَّثَنَا مُوسَى بْنُ هَارُونَ الْبُرْدِيُّ، حَدَّثَنَا هِشَامُ بْنُ يُوسُفَ، عَنِ الْقَاسِمِ بْنِ فَيَّاضٍ الأَبْنَاوِيِّ، عَنْ خَلاَّدِ بْنِ عَبْدِ الرَّحْمَنِ، عَنِ ابْنِ الْمُسَيَّبِ، عَنِ ابْنِ عَبَّاسٍ، أَنَّ رَجُلاً، مِنْ بَكْرِ بْنِ لَيْثٍ أَتَى النَّبِيَّ صلى الله عليه وسلم فَأَقَرَّ أَنَّهُ زَنَى بِامْرَأَةٍ أَرْبَعَ مَرَّاتٍ فَجَلَدَهُ مِائَةً وَكَانَ بِكْرًا ثُمَّ سَأَلَهُ الْبَيِّنَةَ عَلَى الْمَرْأَةِ فَقَالَتْ كَذَبَ وَاللَّهِ يَا رَسُولَ اللَّهِ فَجَلَدَهُ حَدَّ الْفِرْيَةِ ثَمَانِينَ ‏.‏","Narrated Abdullah ibn Abbas: A man of Bakr ibn Layth came to the Prophet (ﷺ) and made confession four times that he had committed fornication with a woman, so he had a hundred lashes administered to him. The man had not been married. He then asked him to produce proof against the woman, and she said: I swear by Allah, Messenger of Allah, that he has lied. Then he was given the punishment of eighty lashes of falsehood","","Munkar"],[4468,4468,4468,"। আব্দুল্লাহ (রাঃ) বলেন, জনৈক ব্যক্তি নবী সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম-এর নিকট এসে বললো, আমি মদীনার উপকণ্ঠে জনৈকা নারীর সঙ্গে সঙ্গম ছাড়া সব কিছুই করেছি। এখন আমি এখানে উপস্থিত। আপনি যা ইচ্ছা আমাকে শাস্তি দিন। উমার (রাঃ) বলেন, আল্লাহ তোমার এ অপরাধ গোপন রেখেছিলেন, তুমিও যদি তা তোমার নিকট গোপন রাখতে! নবী সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম তার কথার কোনো উত্তর দেননি। কাজেই লোকটি ফিরে গেলো। নবী সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম তার পিছনে একজন লোক পাঠিয়ে তাকে ডেকে আনলেন এবং এ আয়াত তিলাওয়াত করলেনঃ ‘‘দিনের দু’ প্রান্তে ও রাতের প্রথমাংশে তুমি সালাত কায়িম করো, নিশ্চয়ই সৎ কাজসমূহ গুনাহসমূহকে মুছে দেয়। উপদেশ গ্রহণকারীদের জন্য এটা এক নাসীহাত।’’ (সূরা হুদঃ ১১৪)। উপস্থিত লোকদের মধ্য থেকে এক লোক বললো, হে আল্লাহর রাসূল! এ আয়াত কি শুধু তার জন্য নির্দিষ্ট, নাকি সবার জন্য? তিনি বললেনঃ বরং তা সকল মানুষের জন্য।[1] হাসান সহীহ।","حَدَّثَنَا مُسَدَّدُ بْنُ مُسَرْهَدٍ، حَدَّثَنَا أَبُو الأَحْوَصِ، حَدَّثَنَا سِمَاكٌ، عَنْ إِبْرَاهِيمَ، عَنْ عَلْقَمَةَ، وَالأَسْوَدِ، قَالاَ قَالَ عَبْدُ اللَّهِ جَاءَ رَجُلٌ إِلَى النَّبِيِّ صلى الله عليه وسلم فَقَالَ إِنِّي عَالَجْتُ امْرَأَةً مِنْ أَقْصَى الْمَدِينَةِ فَأَصَبْتُ مِنْهَا مَا دُونَ أَنْ أَمَسَّهَا فَأَنَا هَذَا فَأَقِمْ عَلَىَّ مَا شِئْتَ ‏.‏ فَقَالَ عُمَرُ قَدْ سَتَرَ اللَّهُ عَلَيْكَ لَوْ سَتَرْتَ عَلَى نَفْسِكَ ‏.‏ فَلَمْ يَرُدَّ عَلَيْهِ النَّبِيُّ صلى الله عليه وسلم شَيْئًا فَانْطَلَقَ الرَّجُلُ فَأَتْبَعَهُ النَّبِيُّ صلى الله عليه وسلم رَجُلاً فَدَعَاهُ فَتَلاَ عَلَيْهِ ‏{‏ وَأَقِمِ الصَّلاَةَ طَرَفَىِ النَّهَارِ وَزُلَفًا مِنَ اللَّيْلِ ‏}‏ إِلَى آخِرِ الآيَةِ فَقَالَ رَجُلٌ مِنَ الْقَوْمِ يَا رَسُولَ اللَّهِ أَلَهُ خَاصَّةً أَمْ لِلنَّاسِ كَافَّةً فَقَالَ ‏\"‏ بَلْ لِلنَّاسِ كَافَّةً ‏\"‏ ‏.‏","‘Abd Allah (b. Mas’ud) said:A man came to the Prophet (ﷺ) and said: I contacted directly a women at the furthest part of the city (i.e., Medina), and I did with her everything except sexual intercourse. So here I am; inflict any punishment you wish. Thereupon ‘Umar said: Allah has concealed your fault; it would have been better if you also had concealed it yourself. The Prophet (ﷺ) sent a men after him. (When he came) he recited the verse: “And establish regular prayers at the two ends of the day and at the approaches of the night. . .” up to the end of the verse. A man from the people got up and asked: Is it particular to him, Messenger of Allah, or for the people in general? He replied: It is all the people","","Hasan Sahih"],[4469,4469,4469,"। আবূ হুরাইরাহ (রাঃ) ও যায়িদ ইবনু খালিদ আল জুহানী (রাঃ) সূত্রে বর্ণিত। রাসূলুল্লাহ সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম-কে অবিবাহিত দাসী সম্পর্কে প্রশ্ন করা হলো যে, সে যেনা করেছে। তিনি বলেনঃ সে যেনা করলে বেত্রাঘাত করো, আবারো যেনা করলে আবারো বেত্রাঘাত করো, পুনরায় যেনা করলে আবারো বেত্রাঘাত করো। অতঃপর আবারো যেনা করলে একটি রশির বিনিময়ে হলেও তাকে বিক্রি করে দাও। ইবনু শিহাব (রহঃ) বলেন, আমি অবহিত নই যে, তিনি তিনবার নাকি চারবার (বিক্রির কথা) বলেছেন।[1] সহীহ।","حَدَّثَنَا عَبْدُ اللَّهِ بْنُ مَسْلَمَةَ، عَنْ مَالِكٍ، عَنِ ابْنِ شِهَابٍ، عَنْ عُبَيْدِ اللَّهِ بْنِ عَبْدِ اللَّهِ بْنِ عُتْبَةَ، عَنْ أَبِي هُرَيْرَةَ، وَزَيْدِ بْنِ خَالِدٍ الْجُهَنِيِّ، أَنَّ رَسُولَ اللَّهِ صلى الله عليه وسلم سُئِلَ عَنِ الأَمَةِ إِذَا زَنَتْ وَلَمْ تُحْصَنْ قَالَ ‏ \"‏ إِنْ زَنَتْ فَاجْلِدُوهَا ثُمَّ إِنْ زَنَتْ فَاجْلِدُوهَا ثُمَّ إِنْ زَنَتْ فَاجْلِدُوهَا ثُمَّ إِنْ زَنَتْ فَبِيعُوهَا وَلَوْ بِضَفِيرٍ ‏\"‏ ‏.‏ قَالَ ابْنُ شِهَابٍ لاَ أَدْرِي فِي الثَّالِثَةِ أَوِ الرَّابِعَةِ وَالضَّفِيرُ الْحَبْلُ ‏.‏","Abu Hurairah and Zaid b. Khalid al-Juhani said:The Messenger of Allah (ﷺ) was asked about a slave-woman who commits fornication, and she is not married: If she commits fornication, flog her: if she commits fornication again flog her; if only for a rope of hair (dafir). Ibn Shihab: I do not know whether he (the Prophet) said it is a third or a fourth time","","Sahih"],[4470,4470,4470,"। আবূ হুরাইরাহ (রাঃ) সূত্রে বর্ণিত। নবী সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম বলেনঃ তোমাদের কারো দাসী যেনা করলে সে তাকে যেন শাস্তি দেয়, তিরস্কার করেই ছেড়ে দিবে না। এরূপ তিনবার করবে। চতুর্থবার যদি সে যেনা করে তাহলে তাকে বেত্রাঘাত করবে এবং একটি রশি বা পশমের তৈরী রশির বিনিময়ে হলেও তাকে বিক্রি করে দিবে।[1] সহীহ।","حَدَّثَنَا مُسَدَّدٌ، حَدَّثَنَا يَحْيَى، عَنْ عُبَيْدِ اللَّهِ، حَدَّثَنِي سَعِيدُ بْنُ أَبِي سَعِيدٍ الْمَقْبُرِيُّ، عَنْ أَبِي هُرَيْرَةَ، عَنِ النَّبِيِّ صلى الله عليه وسلم قَالَ ‏ \"‏ إِذَا زَنَتْ أَمَةُ أَحَدِكُمْ فَلْيَحُدَّهَا وَلاَ يُعَيِّرْهَا ثَلاَثَ مِرَارٍ فَإِنْ عَادَتْ فِي الرَّابِعَةِ فَلْيَجْلِدْهَا وَلْيَبِعْهَا بِضَفِيرٍ أَوْ بِحَبْلٍ مِنْ شَعْرٍ ‏\"‏ ‏.‏","Abu Hurairah reported the Prophet (ﷺ) as saying:When the slave-woman of any of you commits fornication, he should inflict the prescribed punishment on her, but not hurl reproaches at her. This is to be done up to three times. If she a fourth time, he should flog her, and sell her even if only for a rope of hair","","Sahih"],[4471,4471,4471,"। আবূ হুরাইরাহ (রাঃ) সূত্রে বর্ণিত। নবী সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম বলেনঃ প্রতিবার তাকে আল্লাহর নির্ধারিত শাস্তি প্রদান করবে, কেবল তিরস্কার করেই ছেড়ে দিবে না। চতুর্থবার যদি সে এরূপ করে, তাহলে তাকে আল্লাহর নির্ধারিত শাস্তি দেয়ার পর একটি পশমের রশির বিনিময়ে হলেও বিক্রি করে দাও।[1] সহীহ।","حَدَّثَنَا ابْنُ نُفَيْلٍ، حَدَّثَنَا مُحَمَّدُ بْنُ سَلَمَةَ، عَنْ مُحَمَّدِ بْنِ إِسْحَاقَ، عَنْ سَعِيدِ بْنِ أَبِي سَعِيدٍ الْمَقْبُرِيِّ، عَنْ أَبِيهِ، عَنْ أَبِي هُرَيْرَةَ، عَنِ النَّبِيِّ صلى الله عليه وسلم بِهَذَا الْحَدِيثِ قَالَ فِي كُلِّ مَرَّةٍ ‏\"‏ فَلْيَضْرِبْهَا كِتَابُ اللَّهِ وَلاَ يُثَرِّبْ عَلَيْهَا ‏\"‏ ‏.‏ وَقَالَ فِي الرَّابِعَةِ ‏\"‏ فَإِنْ عَادَتْ فَلْيَضْرِبْهَا كِتَابُ اللَّهِ ثُمَّ لْيَبِعْهَا وَلَوْ بِحَبْلٍ مِنْ شَعْرٍ ‏\"‏ ‏.‏","This tradition has been transmitted by Abu Hurairah from the Prophet (ﷺ). This version has:He said each time: He should give her the appropriate beating according to Allah’s Book, but not Hurl reproaches at her. He said a fourth time: If she does it again, he should give her the appropriate beating according to Allah’s Book, and then should sell her even if only for a rope of hair","","Sahih"],[4472,4472,4472,"। আবূ উমামাহ ইবনু সাহল ইবনু হুনাইফ (রাঃ) রাসূলুল্লাহ সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম-এর কতক আনসারী সাহাবীর সূত্রে বর্ণনা করেন যে, তাদের একজন রোগী আক্রান্ত হয়ে হাড্ডিসার হয়ে যায়। এমতাবস্থায় তাদের কারো এক দাসী তার নিকট এলে সে শিহরিত হয়ে তার সঙ্গে সঙ্গম করে। তার গোত্রের লোকজন তাকে দেখলে এলে, সে তাদেরকে তা অবহিত করে এবং বলে, তোমরা আমার ব্যাপারে রাসূলুল্লাহ সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম-এর নিকট গিয়ে এ বিষয়ে ফাতাওয়া চাইবে যে, আমার নিকট আগত দাসীর সঙ্গে আমি যেনা করেছি। তারা রাসূলুল্লাহ সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম-এর নিকট গিয়ে এই ঘটনা জানালো এবং বললো, রোগে শুকিয়ে তার মতো হাড্ডিসার হতে আমরা কোনো লোককে দেখিনি। তাকে যদি আপনার নিকট বহন করে আনি তবে তার হাড়গোড় আলাদা হয়ে যাবে। তার হাড়ে চামড়া ছাড়া আর কিছুই নেই। রাসূলুল্লাহ সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম তাদেরকে আদেশ দিলেনঃ তারা যেন একশো পাতা বিশিষ্ট একটি ডাল নিয়ে তদ্বারা তাকে একবার প্রহার করে।[1] সহীহ।","حَدَّثَنَا أَحْمَدُ بْنُ سَعِيدٍ الْهَمْدَانِيُّ، حَدَّثَنَا ابْنُ وَهْبٍ، أَخْبَرَنِي يُونُسُ، عَنِ ابْنِ شِهَابٍ، قَالَ أَخْبَرَنِي أَبُو أُمَامَةَ بْنُ سَهْلِ بْنِ حُنَيْفٍ، أَنَّهُ أَخْبَرَهُ بَعْضُ، أَصْحَابِ رَسُولِ اللَّهِ صلى الله عليه وسلم مِنَ الأَنْصَارِ أَنَّهُ اشْتَكَى رَجُلٌ مِنْهُمْ حَتَّى أُضْنِيَ فَعَادَ جِلْدَةً عَلَى عَظْمٍ فَدَخَلَتْ عَلَيْهِ جَارِيَةٌ لِبَعْضِهِمْ فَهَشَّ لَهَا فَوَقَعَ عَلَيْهَا فَلَمَّا دَخَلَ عَلَيْهِ رِجَالُ قَوْمِهِ يَعُودُونَهُ أَخْبَرَهُمْ بِذَلِكَ وَقَالَ اسْتَفْتُوا لِي رَسُولَ اللَّهِ صلى الله عليه وسلم فَإِنِّي قَدْ وَقَعْتُ عَلَى جَارِيَةٍ دَخَلَتْ عَلَىَّ ‏.‏ فَذَكَرُوا ذَلِكَ لِرَسُولِ اللَّهِ صلى الله عليه وسلم وَقَالُوا مَا رَأَيْنَا بِأَحَدٍ مِنَ النَّاسِ مِنَ الضُّرِّ مِثْلَ الَّذِي هُوَ بِهِ لَوْ حَمَلْنَاهُ إِلَيْكَ لَتَفَسَّخَتْ عِظَامُهُ مَا هُوَ إِلاَّ جِلْدٌ عَلَى عَظْمٍ فَأَمَرَ رَسُولُ اللَّهِ صلى الله عليه وسلم أَنْ يَأْخُذُوا لَهُ مِائَةَ شِمْرَاخٍ فَيَضْرِبُوهُ بِهَا ضَرْبَةً وَاحِدَةً ‏.‏","Narrated Abu Umamah b. Sahl Hunaif: AbuUmamah ibn Sahl ibn Hunayf said that some companions of the Messenger of Allah (ﷺ) told that one of their men suffered so much from some illness that he pined away until he was skin and bone (i.e. only a skeleton). A slave-girl of someone visited him, and he was cheered by her and had unlawful intercourse with her. When his people came to visit the patient, he told them about it. He said: Ask the Messenger of Allah (ﷺ) about the legal verdict for me, for I have had unlawful intercourse with a slave-girl who visited me. So they mentioned it to the Messenger of Allah (ﷺ) saying: We have never seen anyone (so weak) from illness as he is. If we bring him to you, his bones will disintegrate. He is only skin and bone. So the Messenger of Allah (ﷺ) commanded them to take one hundred twigs and strike him once","","Sahih"],[4473,4473,4473,"। আলী (রাঃ) সূত্রে বর্ণিত। তিনি বলেন, একদা রাসূলুল্লাহ সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম-এর পরিবারের এক দাসী ব্যভিচার করলো। তখন তিনি আলী (রাঃ)-কে ডেকে বললেনঃ হে আলী! তুমি তাকে নিয়ে যাও এবং তার উপর হাদ্দ কার্যকর করো। আমি (আলী) তার নিকট গিয়ে দেখি বিরামহীনভাবে তার রক্তক্ষরণ হচ্ছে। কাজেই আমি তাঁর কাছে ফিরে আসলাম। তিনি বললেনঃ হে আলী! তুমি কি কাজ সেরে এসেছো? আমি বললাম, আমি তার নিকট গিয়ে দেখি, তার অবিরাম রক্তক্ষরণ হচ্ছে। তিনি বললেনঃ রক্ত বন্ধ হওয়া পর্যন্ত তাকে রেখে দাও, অতঃপর তার উপর হাদ্দ কার্যকর করো। আর তোমাদের ডান হাতের মালিকানায় যারা আছে (দাস-দাসী) তাদের উপর হাদ্দ কায়িম করো। শু‘বাহ (রহঃ) আব্দুল আলা থেকে বর্ণনা করেন যে, তিনি বলেছেনঃ প্রসব করার পূর্ব পর্যন্ত তাকে প্রহার করো না। তবে প্রথম বর্ণনাটি অধিক সহীহ।[1] সহীহ।","حَدَّثَنَا مُحَمَّدُ بْنُ كَثِيرٍ، أَخْبَرَنَا إِسْرَائِيلُ، حَدَّثَنَا عَبْدُ الأَعْلَى، عَنْ أَبِي جَمِيلَةَ، عَنْ عَلِيٍّ، رضى الله عنه قَالَ فَجَرَتْ جَارِيَةٌ لآلِ رَسُولِ اللَّهِ صلى الله عليه وسلم فَقَالَ ‏\"‏ يَا عَلِيُّ انْطَلِقْ فَأَقِمْ عَلَيْهَا الْحَدَّ ‏\"‏ ‏.‏ فَانْطَلَقْتُ فَإِذَا بِهَا دَمٌ يَسِيلُ لَمْ يَنْقَطِعْ فَأَتَيْتُهُ فَقَالَ ‏\"‏ يَا عَلِيُّ أَفَرَغْتَ ‏\"‏ ‏.‏ قُلْتُ أَتَيْتُهَا وَدَمُهَا يَسِيلُ ‏.‏ فَقَالَ ‏\"‏ دَعْهَا حَتَّى يَنْقَطِعَ دَمُهَا ثُمَّ أَقِمْ عَلَيْهَا الْحَدَّ وَأَقِيمُوا الْحُدُودَ عَلَى مَا مَلَكَتْ أَيْمَانُكُمْ ‏\"‏ ‏.‏ قَالَ أَبُو دَاوُدَ وَكَذَلِكَ رَوَاهُ أَبُو الأَحْوَصِ عَنْ عَبْدِ الأَعْلَى وَرَوَاهُ شُعْبَةُ عَنْ عَبْدِ الأَعْلَى فَقَالَ فِيهِ ‏\"‏ لاَ تَضْرِبْهَا حَتَّى تَضَعَ ‏\"‏ ‏.‏ وَالأَوَّلُ أَصَحُّ ‏.‏","Narrated Ali ibn AbuTalib: A slave-girl belonging to the house of the Messenger of Allah (ﷺ) committed fornication. He (the Prophet) said: Rush up, Ali, and inflict the prescribed punishment on her. I then hurried up, and saw that blood was flowing from her, and did not stop. So I came to him and he said: Have you finished inflicting (punishment on her)? I said: I went to her while her blood was flowing. He said: Leave her alone till her bleeding stops; then inflict the prescribed punishment on her. And inflict the prescribed punishment on those whom your right hands possess (i.e. slaves). Abu Dawud said: A similar tradition has been transmitted by Abu al-Ahwas from 'Abd al-A'la, and also by Shu'bah from 'Abd al-A'la. This version has: He said: Do not give her beating until she gives birth to a child. But the former (version) is sounder","","Sahih"],[4474,4474,4474,"। আয়িশাহ (রাঃ) সূত্রে বর্ণিত। তিনি বলেন, আমার সমর্থনে যখন আয়াত অবতীর্ণ হলো, নবী সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম মিম্বারে দাঁড়িয়ে বিষয়টি উল্লেখ করেন এবং কুরআনের আয়াত তিলাওয়াত করেন। অতঃপর তিনি মিম্বার থেকে নেমে এসে দু’ জন পুরুষ ও একজন নারী সম্পর্কে নির্দেশ দিলে তাদের উপর হাদ্দ কার্যকর করা হয়।[1] হাসান।","حَدَّثَنَا قُتَيْبَةُ بْنُ سَعِيدٍ الثَّقَفِيُّ، وَمَالِكُ بْنُ عَبْدِ الْوَاحِدِ الْمِسْمَعِيُّ، - وَهَذَا حَدِيثُهُ - أَنَّ ابْنَ أَبِي عَدِيٍّ، حَدَّثَهُمْ عَنْ مُحَمَّدِ بْنِ إِسْحَاقَ، عَنْ عَبْدِ اللَّهِ بْنِ أَبِي بَكْرٍ، عَنْ عَمْرَةَ، عَنْ عَائِشَةَ، رضى الله عنها قَالَتْ لَمَّا نَزَلَ عُذْرِي قَامَ النَّبِيُّ صلى الله عليه وسلم عَلَى الْمِنْبَرِ فَذَكَرَ ذَاكَ وَتَلاَ - تَعْنِي الْقُرْآنَ - فَلَمَّا نَزَلَ مِنَ الْمِنْبَرِ أَمَرَ بِالرَّجُلَيْنِ وَالْمَرْأَةِ فَضُرِبُوا حَدَّهُمْ ‏.‏","Narrated Aisha, Ummul Mu'minin: When my vindication came down, the Prophet (ﷺ) mounted the pulpit and mentioned that, and recited the Qur'an. Then when he came down from the pulpit he ordered regarding the two men and the woman, and they were given the prescribed punishment","","Hasan"],[4475,4475,4475,"। মুহাম্মাদ ইবনু ইসহাক (রহঃ) সূত্রে অনুরূপ হাদীস বর্ণিত। তবে তিনি আয়িশাহ (রাঃ)-এর নাম উল্লেখ করেননি। তিনি বলেছেনঃ যারা অশ্লীল কথা রটিয়েছিল, তিনি তাদের মধ্যে দু’ জন পুরুষ ও একজন নারী সম্পর্কে আদেশ দেন। পুরুষ দু’ জন হলোঃ হাসান ইবনু সাবিত ও মিসতাহ ইবনু উসাসাহ। নুফাইলী বলেনঃ তারা বলতেনঃ মহিলাটি হলো হামনা বিনতু জাহশ।[1] হাসান।","حَدَّثَنَا النُّفَيْلِيُّ، حَدَّثَنَا مُحَمَّدُ بْنُ سَلَمَةَ، عَنْ مُحَمَّدِ بْنِ إِسْحَاقَ، بِهَذَا الْحَدِيثِ لَمْ يَذْكُرْ عَائِشَةَ قَالَ فَأَمَرَ بِرَجُلَيْنِ وَامْرَأَةٍ مِمَّنْ تَكَلَّمَ بِالْفَاحِشَةِ حَسَّانَ بْنِ ثَابِتٍ وَمِسْطَحِ بْنِ أُثَاثَةَ ‏.‏ قَالَ النُّفَيْلِيُّ وَيَقُولُونَ الْمَرْأَةُ حَمْنَةُ بِنْتُ جَحْشٍ ‏.‏","The tradition mentioned above (No. 4459) has also been transmitted by Muhammad ibn Ishaq through a different chain of narrators. But he did not mention Aisha. This version has:He (the Prophet) commanded regarding the two men and the woman who spoke obscenity were Hassan ibn Thabit and Mistah ibn Uthathah. An-Nufayl said: It is said that the woman was Hammah daughter of Jahsh","","Hasan"],[4476,4476,4476,"। ইবনু আব্বাস (রাঃ) সূত্রে বর্ণিত। নবী সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম মাদক গ্রহণের শাস্তিস্বরূপ হাদ্দ নির্দিষ্ট করেননি। ইবনু আব্বাস (রাঃ) বলেন, জনৈক ব্যক্তি মদ পান করে মাতাল হয়। এ সময় তাকে রাস্তায় দুলতে দেখে নবী সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম-এর নিকট নিয়ে আসা হয়। সে আব্বাস (রাঃ)-এর ঘর বরাবর এলে জ্ঞান ফিরে পায় এবং আব্বাস (রাঃ)-এর নিকট গিয়ে (শাস্তির ভয়ে) তাকে জড়িয়ে ধরে। নবী সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম-এর নিকট এ ঘটনা বর্ণনা করা হলে তিনি হেসে বললেনঃ সে কি তাই করেছে? তিনি তার ব্যাপারে কোনো আদেশ দেননি।[1] দুর্বলঃ মিশকাত হা/ ৩৬২২।","حَدَّثَنَا الْحَسَنُ بْنُ عَلِيٍّ، وَمُحَمَّدُ بْنُ الْمُثَنَّى، - وَهَذَا حَدِيثُهُ - قَالاَ حَدَّثَنَا أَبُو عَاصِمٍ، عَنِ ابْنِ جُرَيْجٍ، عَنْ مُحَمَّدِ بْنِ عَلِيِّ بْنِ رُكَانَةَ، عَنْ عِكْرِمَةَ، عَنِ ابْنِ عَبَّاسٍ، أَنَّ رَسُولَ اللَّهِ صلى الله عليه وسلم لَمْ يَقِتْ فِي الْخَمْرِ حَدًّا ‏.‏ وَقَالَ ابْنُ عَبَّاسٍ شَرِبَ رَجُلٌ فَسَكِرَ فَلُقِيَ يَمِيلُ فِي الْفَجِّ فَانْطُلِقَ بِهِ إِلَى النَّبِيِّ صلى الله عليه وسلم فَلَمَّا حَاذَى بِدَارِ الْعَبَّاسِ انْفَلَتَ فَدَخَلَ عَلَى الْعَبَّاسِ فَالْتَزَمَهُ فَذُكِرَ ذَلِكَ لِلنَّبِيِّ صلى الله عليه وسلم فَضَحِكَ وَقَالَ ‏ \"‏ أَفَعَلَهَا ‏\"‏ ‏.‏ وَلَمْ يَأْمُرْ فِيهِ بِشَىْءٍ ‏.‏ قَالَ أَبُو دَاوُدَ هَذَا مِمَّا تَفَرَّدَ بِهِ أَهْلُ الْمَدِينَةِ حَدِيثُ الْحَسَنِ بْنِ عَلِيٍّ هَذَا ‏.‏","Narrated Abdullah ibn Abbas: The Prophet (ﷺ) did not prescribe any punishment for drinking wine. Ibn Abbas said: A man who had drunk wine and become intoxicated was found staggering on the road, so he was taken to the Prophet (ﷺ). When he was opposite al-Abbas's house, he escaped, and going in to al-Abbas, he grasped hold of him. When that was mentioned to the Prophet (ﷺ), he laughed and said: Did he do that? and he gave no command regarding him. Abu Dawud said: This tradition of al-Hasan b. 'Ali has been transmitted only by the people of Medina","","Daif"],[4477,4477,4477,"। আবূ হুরাইরাহ (রাঃ) সূত্রে বর্ণিত। জনৈক মাতাল ব্যক্তিকে রাসূলুল্লাহ সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম-এর নিকট আনা হলে তিনি বলেনঃ তোমরা একে প্রহার করো। আবূ হুরাইরাহ (রাঃ) বলেন, আমাদের মাঝ থেকে কেউ তাকে হাত দিয়ে মেরেছে, কেউ বা জুতা পেটা করেছে আর কেউ বা কাপড় দিয়ে মেরেছে। অতঃপর সে চলে যাওয়ার সময় উপস্থিত লোকজনের কেউ বললো, আল্লাহ তোমাকে অপদস্থ করেছেন। এ কথা শুনে রাসূলুল্লাহ সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম বললেনঃ তোমরা এভাবে বলো না, তার বিরুদ্ধে শয়তানকে সহযোগিতা করো না।[1] সহীহ।","حَدَّثَنَا قُتَيْبَةُ بْنُ سَعِيدٍ، حَدَّثَنَا أَبُو ضَمْرَةَ، عَنْ يَزِيدَ بْنِ الْهَادِ، عَنْ مُحَمَّدِ بْنِ إِبْرَاهِيمَ، عَنْ أَبِي سَلَمَةَ، عَنْ أَبِي هُرَيْرَةَ، أَنَّ رَسُولَ اللَّهِ صلى الله عليه وسلم أُتِيَ بِرَجُلٍ قَدْ شَرِبَ فَقَالَ ‏\"‏ اضْرِبُوهُ ‏\"‏ ‏.‏ قَالَ أَبُو هُرَيْرَةَ فَمِنَّا الضَّارِبُ بِيَدِهِ وَالضَّارِبُ بِنَعْلِهِ وَالضَّارِبُ بِثَوْبِهِ فَلَمَّا انْصَرَفَ قَالَ بَعْضُ الْقَوْمِ أَخْزَاكَ اللَّهُ ‏.‏ فَقَالَ رَسُولُ اللَّهِ صلى الله عليه وسلم ‏\"‏ لاَ تَقُولُوا هَكَذَا لاَ تُعِينُوا عَلَيْهِ الشَّيْطَانَ ‏\"‏ ‏.‏","Abu Hurairah said:When a man who had drunk wine was brought to the Messenger of Allah (ﷺ), he said: Beat him. Abu Hurairah said: Some struck him with their hands, some with their garment. When he turned his face, some people said: Allah put you shame! The Messenger of Allah (ﷺ) said: Do not say like that and help the devil to get power over him","","Sahih"],[4478,4478,4478,"। ইবনুল হাদ (রহঃ) সূত্রে অনুরূপ সমার্থবোধক হাদীস বর্ণিত। তিনি বলেন, তাকে প্রহারের পর রাসূলুল্লাহ সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম তাঁর সাহাবীদের বললেনঃ তোমরা তাকে মৌখিক ধমক দিয়ে নসীহত করো। সুতরাং তারা তার নিকট এসে বললেন, তুমি আল্লাহকে ভয় করনি, তুমি আল্লাহকে ভয় করনি এবং তুমি রাসূলুল্লাহ সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম থেকে লজ্জিত হওনি। অতঃপর তারা তাকে ছেড়ে দিলেন। হাদীসের শেষাংশে তিনি বলেনঃ বরং তোমরা বলো, হে আল্লাহ! তাকে ক্ষমা করে দাও, হে আল্লাহ! তার উপর করুণা বর্ষণ করো।[1] সহীহ।","حَدَّثَنَا مُحَمَّدُ بْنُ دَاوُدَ بْنِ أَبِي نَاجِيَةَ الإِسْكَنْدَرَانِيُّ، حَدَّثَنَا ابْنُ وَهْبٍ، أَخْبَرَنِي يَحْيَى بْنُ أَيُّوبَ، وَحَيْوَةُ بْنُ شُرَيْحٍ، وَابْنُ، لَهِيعَةَ عَنِ ابْنِ الْهَادِ، بِإِسْنَادِهِ وَمَعْنَاهُ قَالَ فِيهِ بَعْدَ الضَّرْبِ ثُمَّ قَالَ رَسُولُ اللَّهِ صلى الله عليه وسلم لأَصْحَابِهِ ‏\"‏ بَكِّتُوهُ ‏\"‏ ‏.‏ فَأَقْبَلُوا عَلَيْهِ يَقُولُونَ مَا اتَّقَيْتَ اللَّهَ مَا خَشِيتَ اللَّهَ وَمَا اسْتَحَيْتَ مِنْ رَسُولِ اللَّهِ صلى الله عليه وسلم ثُمَّ أَرْسَلُوهُ وَقَالَ فِي آخِرِهِ ‏\"‏ وَلَكِنْ قُولُوا اللَّهُمَّ اغْفِرْ لَهُ اللَّهُمَّ ارْحَمْهُ ‏\"‏ ‏.‏ وَبَعْضُهُمْ يَزِيدُ الْكَلِمَةَ وَنَحْوَهَا ‏.‏","The tradition mentioned above has also been transmitted by Ibn al- Had through a different chain of narrators to the same effect. He said after the word “beating”:The Messenger of Allah (ﷺ) then said to his Companions: Reproach him, and they faced him and said: You have not respected Allah, you have not feared Allah and you have not shown shame before the Messenger of Allah (ﷺ). Then they released him. Some have also added similar words","","Sahih"],[4479,4479,4479,"। আনাস ইবনু মালিক (রাঃ) সূত্রে বর্ণিত। নবী সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম মাদক গ্রহণের অপরাধে (এক ব্যক্তিকে) খেজুরের ডাল ও জুতা দিয়ে আঘাত করেন। আর আবূ বাকর (রাঃ) চল্লিশটি বেত্রাঘাত করেন। অতঃপর উমার (রাঃ) যখন খলীফা হন, তিনি লোকদেরকে ডেকে বললেনঃ অনেক লোক পানির উৎসসমূহে ও গ্রামাঞ্চলে ছড়িয়ে পড়েছে। কাজেই এখন আপনারা মাদক গ্রহণের হাদ্দ প্রসঙ্গে কি বলেন? তখন আব্দুর রাহমান ইবনু আওফ (রাঃ) বলেন, আমরা হাদ্দের আওতায় লঘু শাস্তি দেয়ার মত দিচ্ছি। সুতরাং তিনি এর শাস্তি হিসেবে আশিটি বেত্রাঘাত নির্ধারিত করেন। ইমাম আবূ দাঊদ (রহঃ) বলেন, ইবনু আবূ আরুবাহ কাতাদাহর সূত্রে বর্ণনা করেন যে, নবী সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম মদ্যপায়ীদের খেজুরের ডাল ও জুতা দিয়ে চল্লিশ ঘা প্রহার করেছেন। শু‘বাহ (রহঃ) কাতাদাহ থেকে আনাস (রাঃ) সূত্রে নবী সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম থেকে বর্ণনা করে বলেন, তিনি দু’টি খেজুরের ডাল দিয়ে প্রায় চল্লিশ ঘা প্রহার করেছেন।[1] সহীহ।","حَدَّثَنَا مُسْلِمُ بْنُ إِبْرَاهِيمَ، حَدَّثَنَا هِشَامٌ، ح وَحَدَّثَنَا مُسَدَّدٌ، حَدَّثَنَا يَحْيَى، عَنْ هِشَامٍ، - الْمَعْنَى - عَنْ قَتَادَةَ، عَنْ أَنَسِ بْنِ مَالِكٍ، أَنَّ النَّبِيَّ صلى الله عليه وسلم جَلَدَ فِي الْخَمْرِ بِالْجَرِيدِ وَالنِّعَالِ وَجَلَدَ أَبُو بَكْرٍ رضى الله عنه أَرْبَعِينَ فَلَمَّا وَلِيَ عُمَرُ دَعَا النَّاسَ فَقَالَ لَهُمْ إِنَّ النَّاسَ قَدْ دَنَوْا مِنَ الرِّيفِ - وَقَالَ مُسَدَّدٌ مِنَ الْقُرَى وَالرِّيفِ - فَمَا تَرَوْنَ فِي حَدِّ الْخَمْرِ فَقَالَ لَهُ عَبْدُ الرَّحْمَنِ بْنُ عَوْفٍ نَرَى أَنْ تَجْعَلَهُ كَأَخَفِّ الْحُدُودِ ‏.‏ فَجَلَدَ فِيهِ ثَمَانِينَ ‏.‏ قَالَ أَبُو دَاوُدَ رَوَاهُ ابْنُ أَبِي عَرُوبَةَ عَنْ قَتَادَةَ عَنِ النَّبِيِّ صلى الله عليه وسلم أَنَّهُ جَلَدَ بِالْجَرِيدِ وَالنِّعَالِ أَرْبَعِينَ ‏.‏ وَرَوَاهُ شُعْبَةُ عَنْ قَتَادَةَ عَنْ أَنَسٍ عَنِ النَّبِيِّ صلى الله عليه وسلم قَالَ ضَرَبَ بِجَرِيدَتَيْنِ نَحْوَ الأَرْبَعِينَ ‏.‏","Anas b. Malik said:The Prophet (ﷺ) gave a beating with palm-branches and sandals for drinking wine and Abu Bakr gave lashes. When ‘Umar came to power, he called upon people and said to them: The people are living now near watering placing, and, according to Musaddad’s version, “near villages and watering places, so what do you say about the punishment for (drinking) wine? ‘Abd al-Rahman b. ‘Awf said: We think that you should prescribe the lightest punishment. So he fixed eight lashes for it. Abu Dawud said: It has also been transmitted by Ibn Al 'Arubah from Qatadah from the Prophet (ﷺ) to the effect that he gave a beating forty times with palm branches and sandals. And Shu'bah narrated it from Qatadah on the authority of Anas from Prophet (ﷺ). This version has: He gave a beating with two palm-branches about forty times","","Sahih"],[4480,4480,4480,"। হুসাইন ইবনুল মুনযির আর-রাকাশী ওরফে আবূ সাসান (রহঃ) বলেন, একদা আমি উসমান ইবনু আফফান (রাঃ)-এর নিকট উপস্থিত ছিলাম। তখন ওয়ালীদ ইবনু উকবাহকে ধরে আনা হলো। হুমরান এবং অপর এক ব্যক্তি তার বিরুদ্ধে সাক্ষ্য দিলো। তাদের একজন সাক্ষ্য দিলো যে, সে তাকে মদ খেতে দেখেছে। অপর ব্যক্তি সাক্ষ্য দিলো যে, সে তাকে মদ বমি করে ফেলতে দেখেছে। উসমান (রাঃ) বললেন, মদ পান না করলে তা বমি করতে পারে না। তাই তিনি আলী (রাঃ)-কে তার উপর শাস্তি বাস্তবায়িত করতে নির্দেশ দিলেন। আলী (রাঃ) হাসান (রাঃ)-কে বললেন, তুমি তাকে শাস্তি দাও। হাসান (রাঃ) বলেন, যিনি খিলাফাতের সুবিধা ভোগ করছেন তিনি ভার বহন করবেন। অতঃপর আলী (রাঃ) আব্দুল্লাহ ইবনু জা‘ফারকে বললেন, তুমি তার উপর হাদ্দ কার্যকর করো। অতএব তিনি একটি চাবুক নিয়ে তাকে প্রহার করতে শুরু করলেন। আর আলী (রাঃ) তা গণনা করতে থাকলেন। যখন তিনি চল্লিশে পৌঁছলেন আলী (রাঃ) বললেন, থামো, যথেষ্ট হয়েছে। নবী সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম চল্লিশটি বেত্রাঘাত করেছেন। আমি মনে করি, আবূ বাকরও চল্লিশটি বেত্রাঘাত করেছেন, কিন্তু উমার আশিটি বেত্রাঘাত করেছেন। এর প্রতিটি সুন্নাত। তবে আমি চল্লিশটি পছন্দ করি।[1] সহীহ।","حَدَّثَنَا مُسَدَّدُ بْنُ مُسَرْهَدٍ، وَمُوسَى بْنُ إِسْمَاعِيلَ، - الْمَعْنَى - قَالاَ حَدَّثَنَا عَبْدُ الْعَزِيزِ بْنُ الْمُخْتَارِ، حَدَّثَنَا عَبْدُ اللَّهِ الدَّانَاجُ، حَدَّثَنِي حُضَيْنُ بْنُ الْمُنْذِرِ الرَّقَاشِيُّ، - هُوَ أَبُو سَاسَانَ - قَالَ شَهِدْتُ عُثْمَانَ بْنَ عَفَّانَ وَأُتِيَ بِالْوَلِيدِ بْنِ عُقْبَةَ فَشَهِدَ عَلَيْهِ حُمْرَانُ وَرَجُلٌ آخَرُ فَشَهِدَ أَحَدُهُمَا أَنَّهُ رَآهُ شَرِبَهَا - يَعْنِي الْخَمْرَ - وَشَهِدَ الآخَرُ أَنَّهُ رَآهُ يَتَقَيَّأُهَا فَقَالَ عُثْمَانُ إِنَّهُ لَمْ يَتَقَيَّأْهَا حَتَّى شَرِبَهَا ‏.‏ فَقَالَ لِعَلِيٍّ رضى الله عنه أَقِمْ عَلَيْهِ الْحَدَّ ‏.‏ فَقَالَ عَلِيٌّ لِلْحَسَنِ أَقِمْ عَلَيْهِ الْحَدَّ ‏.‏ فَقَالَ الْحَسَنُ وَلِّ حَارَّهَا مَنْ تَوَلَّى قَارَّهَا ‏.‏ فَقَالَ عَلِيٌّ لِعَبْدِ اللَّهِ بْنِ جَعْفَرٍ أَقِمْ عَلَيْهِ الْحَدَّ ‏.‏ قَالَ فَأَخَذَ السَّوْطَ فَجَلَدَهُ وَعَلِيٌّ يَعُدُّ فَلَمَّا بَلَغَ أَرْبَعِينَ قَالَ حَسْبُكَ جَلَدَ النَّبِيُّ صلى الله عليه وسلم أَرْبَعِينَ - أَحْسِبُهُ قَالَ - وَجَلَدَ أَبُو بَكْرٍ أَرْبَعِينَ وَعُمَرُ ثَمَانِينَ وَكُلٌّ سُنَّةٌ وَهَذَا أَحَبُّ إِلَىَّ ‏.‏","Hudayn ibn al-Mundhir ar-Ruqashi, who was AbuSasan, said:I was present with Uthman ibn Affan when al-Walid ibn Uqbah was brought to him. Humran and another man bore witness against him (for drinking wine). One of them testified that he had seen him drinking wine, and the other testified that he had seen him vomiting it. Uthman said: He could not vomit it, unless he did not drink it. He said to Ali: Inflict the prescribed punishment on him. Ali said to al-Hasan: Inflict the prescribed punishment on him. Al-Hasan said: He who has enjoyed its pleasure should also bear its burden. So Ali said to Abdullah ibn Ja'far: Inflict the prescribed punishment on him. He took a whip and struck him with it while Ali was counting. When he reached (struck) forty (lashes), he said: It is sufficient. The Prophet (ﷺ) gave forty lashes. I think he also said: \"And AbuBakr gave forty lashes, and Uthman eighty. This is all sunnah (standard practice). And this is dearer to me","","Sahih"],[4481,4481,4481,"। আলী (রাঃ) সূত্রে বর্ণিত। তিনি বলেন, রাসূলুল্লাহ সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম ও আবূ বাকর (রাঃ) মদ পানের অপরাধে চল্লিশটি বেত্রাঘাত করেছেন, আর উমার (রাঃ) তা আশিতে পূর্ণ করেছেন। এর প্রতিটি সুন্নাত। ইমাম আবূ দাঊদ (রহঃ) বলেন, আল-আসমাঈ ‘‘এর শীতলতা উপভোগকারী এর উত্তাপ সহ্য করবে’’ বাগধারার ব্যাখ্যায় বলেন, যিনি খিলাফাতের সুবিধা ভোগ করেছেন তাকেই এর ভার বহন করতে হবে। ইমাম আবূ দাঊদ (রহঃ) বলেন, আবূ সাসান হুসাইন ইবনু মুনযির ছিলেন তার গোত্রের সরদার।[1] সহীহ।","حَدَّثَنَا مُسَدَّدٌ، حَدَّثَنَا يَحْيَى، عَنِ ابْنِ أَبِي عَرُوبَةَ، عَنِ الدَّانَاجِ، عَنْ حُضَيْنِ بْنِ الْمُنْذِرِ، عَنْ عَلِيٍّ، رضى الله عنه قَالَ جَلَدَ رَسُولُ اللَّهِ صلى الله عليه وسلم فِي الْخَمْرِ وَأَبُو بَكْرٍ أَرْبَعِينَ وَكَمَّلَهَا عُمَرُ ثَمَانِينَ وَكُلٌّ سُنَّةٌ ‏.‏ قَالَ أَبُو دَاوُدَ وَقَالَ الأَصْمَعِيُّ وَلِّ حَارَّهَا مَنْ تَوَلَّى قَارَّهَا وَلِّ شَدِيدَهَا مَنْ تَوَلَّى هَيِّنَهَا ‏.‏ قَالَ أَبُو دَاوُدَ هَذَا كَانَ سَيِّدَ قَوْمِهِ حُضَيْنُ بْنُ الْمُنْذِرِ أَبُو سَاسَانَ ‏.‏","Narrated Ali ibn AbuTalib: The Messenger of Allah (ﷺ) and AbuBakr gave forty lashes for drinking wine and Umar made it eighty. And all this is sunnah, the model and standard practice. Abu Dawud said: Al-Asma'i explaning the maxim, \"He who enjoys its cold should bear its heat,\" said: He who enjoys the easy if it should also take the responsibility of the hard of it. Abu Dawud said: Hudain b. al-Mundhir Abu Sasan was the leader of his tribe","","Sahih"],[4482,4482,4482,"। মুআবিয়াহ ইবনু আবূ সুফিয়ান (রাঃ) সূত্রে বর্ণিত। তিনি বলেন, রাসূলুল্লাহ সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম বলেছেনঃ লোকেরা মদ পান করলে, তাদের বেত্রাঘাত করো। পুনরায় পান করলে বেত্রাঘাত করো। আবারো পান করলে বেত্রাঘাত করো, পুনরায় পান করলে বেত্রাঘাত করো, আবারো পান করলে তাদের হত্যা করো।[1] হাসান সহীহ।","حَدَّثَنَا مُوسَى بْنُ إِسْمَاعِيلَ، حَدَّثَنَا أَبَانُ، عَنْ عَاصِمٍ، عَنْ أَبِي صَالِحٍ، ذَكْوَانَ عَنْ مُعَاوِيَةَ بْنِ أَبِي سُفْيَانَ، قَالَ قَالَ رَسُولُ اللَّهِ صلى الله عليه وسلم ‏ \"‏ إِذَا شَرِبُوا الْخَمْرَ فَاجْلِدُوهُمْ ثُمَّ إِنْ شَرِبُوا فَاجْلِدُوهُمْ ثُمَّ إِنْ شَرِبُوا فَاجْلِدُوهُمْ ثُمَّ إِنْ شَرِبُوا فَاقْتُلُوهُمْ ‏\"‏ ‏.‏","Narrated Mu'awiyah ibn AbuSufyan: The Prophet (ﷺ) said: If they (the people) drink wine, flog them, again if they drink it, flog them. Again if they drink it, kill them","","Hasan Sahih"],[4483,4483,4483,"। ইবনু উমার (রাঃ) সূত্রে বর্ণিত। রাসূলুল্লাহ সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম বলেনঃ ... উপরের হাদীসের সমার্থবোধক। এতে রয়েছেঃ আমার ধারণা, তিনি পঞ্চমবারে বলেছেনঃ আবারো যদি সে মদ পান করে তবে তাকে হত্যা করো। ইমাম আবূ দাঊদ (রহঃ) বলেন, আবূ গুতাইফ বর্ণিত হাদীসেরও পঞ্চমবারের কথা উল্লেখ আছে।[1] সনদ দুর্বল।","حَدَّثَنَا مُوسَى بْنُ إِسْمَاعِيلَ، حَدَّثَنَا حَمَّادٌ، عَنْ حُمَيْدِ بْنِ يَزِيدَ، عَنْ نَافِعٍ، عَنِ ابْنِ عُمَرَ، أَنَّ رَسُولَ اللَّهِ صلى الله عليه وسلم قَالَ بِهَذَا الْمَعْنَى قَالَ وَأَحْسِبُهُ قَالَ فِي الْخَامِسَةِ ‏ \"‏ إِنْ شَرِبَهَا فَاقْتُلُوهُ ‏\"‏ ‏.‏ قَالَ أَبُو دَاوُدَ وَكَذَا فِي حَدِيثِ أَبِي غُطَيْفٍ فِي الْخَامِسَةِ ‏.‏","The tradition mentioned above has also been transmitted by Ibn ‘Umar through a different chain of narrators to the same effect. This version has :I think he said for the fifth time: If he drinks it, kill him. Abu Dawud said: And similarly the word “a fifth time” occurs in the tradition of Abu Ghutaif","","Daif Isnaad"],[4484,4484,4484,"। আবূ হুরাইরাহ (রাঃ) সূত্রে বর্ণিত। তিনি বলেন, রাসূলুল্লাহ সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম বলেছেনঃ কেউ মাতাল হলে তাকে বেত্রাঘাত করো। আবার মাতাল হলে তাকে বেত্রাঘাত করো, আবার মাতাল হলে বেত্রাঘাত করো, চতুর্থবারও যদি এর পুনরাবৃত্তি হয়, তবে তাকে হত্যা করো। ইমাম আবূ দাঊদ (রহঃ) বলেন, উমার ইবনু আবূ সালামাহও পর্যায়ক্রমে তার পিতা ও আবূ হুরাইরাহ সূত্রে নবী সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম থেকে এরূপ বর্ণনা করেছেনঃ কেউ মদ পান করলে তাকে বেত্রাঘাত করো। চতুর্থবারও যদি এরূপ করে তবে তাকে হত্যা করো। ইমাম আবূ দাঊদ (রহঃ) বলেন, অনুরূপভাবে সুহাইল পর্যায়ক্রমে আবূ সালিহ ও আবূ হুরাইরাহ সূত্রে নবী সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম থেকে এরূপ বর্ণনা করেছেনঃ চতুর্থবার যদি তারা মদ পান করে তাহলে তাদের হত্যা করো। একইভাবে ইবনু আবূ নুআইম ইবনু উমারের সূত্রে নবী সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম থেকে এরূপ বর্ণনা করেছেন। আর আব্দুল্লাহ ইবনু উমার (রাঃ) এবং আশ-শারীদ (রাঃ) নবী সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম সূত্রে অনুরূপ বর্ণনা করেছেন। তবে আল জাদলী মুআবিয়াহ (রাঃ)-এর সূত্রে নবী সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম থেকে বর্ণনা করেন যে, তিনি বলেছেনঃ সে তৃতীয় বার বা চতুর্থবার মদ পান করলে তাকে হত্যা করো।[1] হাসান সহীহ।","حَدَّثَنَا نَصْرُ بْنُ عَاصِمٍ الأَنْطَاكِيُّ، حَدَّثَنَا يَزِيدُ بْنُ هَارُونَ الْوَاسِطِيُّ، حَدَّثَنَا ابْنُ أَبِي ذِئْبٍ، عَنِ الْحَارِثِ بْنِ عَبْدِ الرَّحْمَنِ، عَنْ أَبِي سَلَمَةَ، عَنْ أَبِي هُرَيْرَةَ، قَالَ قَالَ رَسُولُ اللَّهِ صلى الله عليه وسلم ‏\"‏ إِذَا سَكِرَ فَاجْلِدُوهُ ثُمَّ إِنْ سَكِرَ فَاجْلِدُوهُ ثُمَّ إِنْ سَكِرَ فَاجْلِدُوهُ فَإِنْ عَادَ الرَّابِعَةَ فَاقْتُلُوهُ ‏\"‏ ‏.‏ قَالَ أَبُو دَاوُدَ وَكَذَا حَدِيثُ عُمَرَ بْنِ أَبِي سَلَمَةَ عَنْ أَبِيهِ عَنْ أَبِي هُرَيْرَةَ عَنِ النَّبِيِّ صلى الله عليه وسلم ‏\"‏ إِذَا شَرِبَ الْخَمْرَ فَاجْلِدُوهُ فَإِنْ عَادَ الرَّابِعَةَ فَاقْتُلُوهُ ‏\"‏ ‏.‏ قَالَ أَبُو دَاوُدَ وَكَذَا حَدِيثُ سُهَيْلٍ عَنْ أَبِي صَالِحٍ عَنْ أَبِي هُرَيْرَةَ عَنِ النَّبِيِّ صلى الله عليه وسلم ‏\"‏ إِنْ شَرِبُوا الرَّابِعَةَ فَاقْتُلُوهُمْ ‏\"‏ ‏.‏ وَكَذَا حَدِيثُ ابْنِ أَبِي نُعْمٍ عَنِ ابْنِ عُمَرَ عَنِ النَّبِيِّ صلى الله عليه وسلم وَكَذَا حَدِيثُ عَبْدِ اللَّهِ بْنِ عَمْرٍو عَنِ النَّبِيِّ صلى الله عليه وسلم وَالشَّرِيدِ عَنِ النَّبِيِّ صلى الله عليه وسلم وَفِي حَدِيثِ الْجَدَلِيِّ عَنْ مُعَاوِيَةَ أَنَّ النَّبِيَّ صلى الله عليه وسلم قَالَ ‏\"‏ فَإِنْ عَادَ فِي الثَّالِثَةِ أَوِ الرَّابِعَةِ فَاقْتُلُوهُ ‏\"‏ ‏.‏","Narrated AbuHurayrah: The Prophet (ﷺ) said: If he is intoxicated, flog him; again if he is intoxicated, flog him; again if he is intoxicated, flog him if he does it again a fourth time, kill him. Abu Dawud said: And there is a similar tradition of Umar ibn AbuSalamah, from his father, on the authority of AbuHurayrah, from the Prophet (ﷺ): If he drinks wine, flog him if he does it so again, a fourth time, kill him. Abu Dawud said: And there is similar tradition of Suhail from Abu Salih on the authority of Abu Hurairah, from the Prophet (ﷺ): It they drink a fourth time, kill them. And there is similar tradition of Ibn Abi Nu'm on the authority of Ibn 'Umar from Prophet (ﷺ). There is also similar tradition of 'Abd Allah b. 'Amr from the Prophet (ﷺ), and from Sharid from the Prophet (ﷺ). And in the tradition of al-Jadli from Mu'awiyah, the Prophet (ﷺ) said: If he does so again third or fourth time, kill him","","Hasan Sahih"],[4485,4485,4485,"। কাবিসাহ ইবনু যুওয়াইব (রাঃ) সূত্রে বর্ণিত। নবী সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম বলেনঃ যে ব্যক্তি মদ পান করে তাকে বেত্রাঘাত করো। আবারো পান করলে তাকে বেত্রাঘাত করো। আবারো পান করলে তাকে বেত্রাঘাত করো। তৃতীয় কিংবা চতুর্থবার যদি সে এরূপ করে তবে তাকে হত্যা করো। অতঃপর মদ পানের অপরাধে জনৈক ব্যক্তিকে ধরে আনা হলে তিনি তাকে বেত্রাঘাত করেন। পুনরায় তাকে এ অপরাধে নিয়ে আসা হলে তিনি তাকে বেত্রাঘাত করেন। অতঃপর একই অপরাধে তাকে নিয়ে আসা হলে তিনি বেত্রাঘাত করেন আর হত্যা পরিহার করেন। তা ছিলো অবকাশ। সুফিয়ান বলেন, যুহরী (রহঃ) মানসূর ইবনুল মুতামির ও মুখাওয়াল ইবনু রাশিদের উপস্থিতিতে এ হাদীস বর্ণনা করে বলেনঃ তোমরা দু’ জন প্রতিনিধি হিসেবে ইরাকবাসীদের নিকট গিয়ে এ হাদীস বর্ণনা করো। ইমাম আবূ দাঊদ (রহঃ) বলেন, আশ-শাদীদ ইবনু সুওয়াইদ ও সুরাহবিল ইবনু আওস, আব্দুল্লাহ ইবনু আমর, আব্দুল্লাহ ইবনু উমার, আবূ গুতাইফ আল কিন্দী এবং আবূ সালামাহ ইবনু আব্দুর রাহমান (রাঃ) আবূ হুরাইরাহ (রাঃ) সূত্রে এ হাদীস বর্ণনা করেছে।[1] যঈফ মুরসাল।","حَدَّثَنَا أَحْمَدُ بْنُ عَبْدَةَ الضَّبِّيُّ، حَدَّثَنَا سُفْيَانُ، قَالَ الزُّهْرِيُّ أَخْبَرَنَا عَنْ قَبِيصَةَ بْنِ ذُؤَيْبٍ، أَنَّ النَّبِيَّ صلى الله عليه وسلم قَالَ ‏ \"‏ مَنْ شَرِبَ الْخَمْرَ فَاجْلِدُوهُ فَإِنْ عَادَ فَاجْلِدُوهُ فَإِنْ عَادَ فَاجْلِدُوهُ فَإِنْ عَادَ فِي الثَّالِثَةِ أَوِ الرَّابِعَةِ فَاقْتُلُوهُ ‏\"‏ ‏.‏ فَأُتِيَ بِرَجُلٍ قَدْ شَرِبَ فَجَلَدَهُ ثُمَّ أُتِيَ بِهِ فَجَلَدَهُ ثُمَّ أُتِيَ بِهِ فَجَلَدَهُ ثُمَّ أُتِيَ بِهِ فَجَلَدَهُ وَرَفَعَ الْقَتْلَ فَكَانَتْ رُخْصَةً ‏.‏ قَالَ سُفْيَانُ حَدَّثَ الزُّهْرِيُّ بِهَذَا الْحَدِيثِ وَعِنْدَهُ مَنْصُورُ بْنُ الْمُعْتَمِرِ وَمُخَوَّلُ بْنُ رَاشِدٍ فَقَالَ لَهُمَا كُونَا وَافِدَىْ أَهْلِ الْعِرَاقِ بِهَذَا الْحَدِيثِ ‏.‏ قَالَ أَبُو دَاوُدَ رَوَى هَذَا الْحَدِيثَ الشَّرِيدُ بْنُ سُوَيْدٍ وَشُرَحْبِيلُ بْنُ أَوْسٍ وَعَبْدُ اللَّهِ بْنُ عَمْرٍو وَعَبْدُ اللَّهِ بْنُ عُمَرَ وَأَبُو غُطَيْفٍ الْكِنْدِيُّ وَأَبُو سَلَمَةَ بْنُ عَبْدِ الرَّحْمَنِ عَنْ أَبِي هُرَيْرَةَ ‏.‏","Narrated Qabisah ibn Dhuwayb: The Prophet (ﷺ) said: If anyone drinks wine, flog him; if he repeats it, flog him, and if he repeats it, flog him. If he does it again a third or a fourth time, kill him. A man who had drunk wine was brought (to him) and he gave him lashes. He was again brought to him, and he flogged him. He was again brought to him and he flogged him. He was again brought to him and he flogged him. The punishment of killing (for drinking) was repealed, and a concession was allowed. Sufyan said: Al-Zuhri transmitted this tradition when Mansur b. al-Mu'tamir amd Mukhawwal b. Rashid were present with him. He said to them: Take this tradition as a present to the people of Iraq. Abu Dawud said: This tradition has been transmitted by al-Sharid b. Suwaid, Sharahbil b. Aws, 'Abd Allah b. 'Amr, 'Abd Allah b. 'Umar, Abu Ghutaif al-Kindi, and Abu Salamah b. 'Abd al-Rahman from Abu Hurairah","","Daif"],[4486,4486,4486,"। আলী (রাঃ) সূত্রে বর্ণিত। তিনি বলেন, আমি কারো উপর হাদ্দ কার্যকর করলে এবং তাতে সে মারা গেলে আমি তার ক্ষতিপূরণ পরিশোধ করবো না, মদ পানের অপরাধী ব্যতীত। কেননা রাসূলুল্লাহ সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম এ ব্যাপারে কোনো নির্দিষ্ট নিয়ম দেননি। এর যা কিছু শাস্তি প্রচলিত আছে তা আমরা নিজেরা নির্ধারণ করেছি।[1] সহীহ।","حَدَّثَنَا إِسْمَاعِيلُ بْنُ مُوسَى الْفَزَارِيُّ، حَدَّثَنَا شَرِيكٌ، عَنْ أَبِي حُصَيْنٍ، عَنْ عُمَيْرِ بْنِ سَعِيدٍ، عَنْ عَلِيٍّ، رضى الله عنه قَالَ لاَ أَدِي - أَوْ مَا كُنْتُ لأَدِيَ - مَنْ أَقَمْتُ عَلَيْهِ حَدًّا إِلاَّ شَارِبَ الْخَمْرِ فَإِنَّ رَسُولَ اللَّهِ صلى الله عليه وسلم لَمْ يَسُنَّ فِيهِ شَيْئًا إِنَّمَا هُوَ شَىْءٌ قُلْنَاهُ نَحْنُ ‏.‏","’Ali said:I shall not pay blood-money or (he said) : I am not going to pay blood-money for him on whom I inflicted the prescribed punishment except for the one who drank wine, for the Messenger of Allah (ﷺ) did not prescribe anything definite. It is a thing which we have decided (by agreement) ourselves","","Sahih"],[4487,4487,4487,"। আব্দুর রাহমান ইবনু আযহার (রাঃ) সূত্রে বর্ণিত। তিনি বলেন, আমি যেন এখনো দেখছি যে, রাসূলুল্লাহ সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম সৈন্যশিবিরের মধ্যে খালিদ ইবনু ওয়ালিদের শিবির খুঁজছেন। এমতাবস্থায় জনৈক মদ্দপায়ীকে ধরে আনা হলো। তিনি লোকদের বললেনঃ তোমরা একে প্রহার করো। অতএব তাদের কেউ জুতা দিয়ে, কেউ বা লাঠি দিয়ে আর কেউ বা ‘মিতাখাহ’ দিয়ে তাকে প্রহার করলো। ইবনু ওয়াহব বলেন, ‘মিতাখাহ’ অর্থ খেজুরের কাঁচা ডাল। অতঃপর রাসূলুল্লাহ সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম জমিন থেকে কিছু মাটি নিয়ে তার মুখমন্ডলে ছুঁড়ে মারলেন।[1] হাসান সহীহ।","حَدَّثَنَا سُلَيْمَانُ بْنُ دَاوُدَ الْمَهْرِيُّ الْمِصْرِيُّ ابْنُ أَخِي، رِشْدِينَ بْنِ سَعْدٍ أَخْبَرَنَا ابْنُ وَهْبٍ، أَخْبَرَنَا أُسَامَةُ بْنُ زَيْدٍ، أَنَّ ابْنَ شِهَابٍ، حَدَّثَهُ عَنْ عَبْدِ الرَّحْمَنِ بْنِ أَزْهَرَ، قَالَ كَأَنِّي أَنْظُرُ إِلَى رَسُولِ اللَّهِ صلى الله عليه وسلم الآنَ وَهُوَ فِي الرِّحَالِ يَلْتَمِسُ رَحْلَ خَالِدِ بْنِ الْوَلِيدِ فَبَيْنَمَا هُوَ كَذَلِكَ إِذْ أُتِيَ بِرَجُلٍ قَدْ شَرِبَ الْخَمْرَ فَقَالَ لِلنَّاسِ ‏ \"‏ اضْرِبُوهُ ‏\"‏ ‏.‏ فَمِنْهُمْ مَنْ ضَرَبَهُ بِالنِّعَالِ وَمِنْهُمْ مَنْ ضَرَبَهُ بِالْعَصَا وَمِنْهُمْ مَنْ ضَرَبَهُ بِالْمِيتَخَةِ - قَالَ ابْنُ وَهْبٍ الْجَرِيدَةُ الرَّطْبَةُ - ثُمَّ أَخَذَ رَسُولُ اللَّهِ صلى الله عليه وسلم تُرَابًا مِنَ الأَرْضِ فَرَمَى بِهِ فِي وَجْهِهِ ‏.‏","Narrated AbdurRahman ibn Azhar: I can still picture myself looking at the Messenger of Allah (ﷺ) who was among the camps of the Companions seeking the camp of Khalid ibn al-Walid, when a man who had drunk wine was brought before him. He asked the people: Beat him. Some struck him with sandals, some with sticks and some with fresh branches of the palm-tree (mitakhah). Ibn Wahb said: This (mitakhah) means green palm fronds. Then the apostle of Allah (ﷺ) took some dust from the ground and threw it on his face","","Hasan Sahih"],[4488,4488,4488,"। আব্দুর রাহমান ইবনু আযহার (রাঃ) সূত্রে বর্ণিত। তিনি বলেন, রাসূলুল্লাহ সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম হুনাইনে অবস্থানকালে জনৈক মাতালকে তাঁর নিকট আনা হলো। তিনি তার মুখমন্ডলে মাটি ছুঁড়ে মারলেন এবং তাকে প্রহার করতে সাহাবীদের নির্দেশ দিলেন। তারা তাদের জুতা ও হাতে যা কিছু ছিলো তা দিয়ে তাকে প্রহার করতে লাগলেন, যতক্ষণ না তিনি তাদের বললেন যে, থামো। অতঃপর তারা প্রহার বন্ধ করলেন। রাসূলুল্লাহ সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম-এর ইন্তেকালের পর আবূ বাকর (রাঃ) মদ পানের জন্য চল্লিশটি বেত্রাঘাত করেন। অতঃপর উমারও তার খিলাফাতের প্রথম পর্যায়ে চল্লিশটি বেত্রাঘাত করেন এবং পরবর্তী পর্যায়ে আশিটি বেত্রাঘাত করেন। অতঃপর উসমান (রাঃ) আশি এবং চল্লিশ দু’ ধরণের শাস্তিই প্রয়োগ করেন। অতঃপর মু‘আবিয়াহ (রাঃ) মদ পানের শাস্তি আশি বেত্রাঘাত নির্ধারণ করেন।[1] সহীহ।","حَدَّثَنَا ابْنُ السَّرْحِ، قَالَ وَجَدْتُ فِي كِتَابِ خَالِي عَبْدِ الرَّحْمَنِ بْنِ عَبْدِ الْحَمِيدِ عَنْ عُقَيْلٍ أَنَّ ابْنَ شِهَابٍ أَخْبَرَهُ أَنَّ عَبْدَ اللَّهِ بْنَ عَبْدِ الرَّحْمَنِ بْنِ الأَزْهَرِ أَخْبَرَهُ عَنْ أَبِيهِ قَالَ أُتِيَ النَّبِيُّ صلى الله عليه وسلم بِشَارِبٍ وَهُوَ بِحُنَيْنٍ فَحَثَى فِي وَجْهِهِ التُّرَابَ ثُمَّ أَمَرَ أَصْحَابَهُ فَضَرَبُوهُ بِنِعَالِهِمْ وَمَا كَانَ فِي أَيْدِيهِمْ حَتَّى قَالَ لَهُمُ ‏ \"‏ ارْفَعُوا ‏\"‏ ‏.‏ فَرَفَعُوا فَتُوُفِّيَ رَسُولُ اللَّهِ صلى الله عليه وسلم ثُمَّ جَلَدَ أَبُو بَكْرٍ فِي الْخَمْرِ أَرْبَعِينَ ثُمَّ جَلَدَ عُمَرُ أَرْبَعِينَ صَدْرًا مِنْ إِمَارَتِهِ ثُمَّ جَلَدَ ثَمَانِينَ فِي آخِرِ خِلاَفَتِهِ ثُمَّ جَلَدَ عُثْمَانُ الْحَدَّيْنِ كِلَيْهِمَا ثَمَانِينَ وَأَرْبَعِينَ ثُمَّ أَثْبَتَ مُعَاوِيَةُ الْحَدَّ ثَمَانِينَ ‏.‏","Narrated AbdurRahman ibn al-Azhar: A man who had drunk wine was brought before the Prophet (ﷺ) when he was in Hunayn. He threw some dust on his face. He then ordered his Companions and they beat him with their sandals and whatever they had in their hands. He then said to them: Leave him, and they left him. The Messenger of Allah (ﷺ) then died, and AbuBakr gave forty lashes for drinking wine, and then Umar in the beginning of his Caliphate inflicted forty stripes and at the end of his Caliphate he inflicted eighty stripes. Uthman (after him) inflicted both punishments, eighty and forty stripes, and finally Mu'awiyah established eighty stripes","","Sahih"],[4489,4489,4489,"। আব্দুর রাহমান ইবনু আযহার (রাঃ) সূত্রে বর্ণিত। তিনি বলেন, আমি মক্কা বিজয়ের দিন সকালবেলা রাসূলুল্লাহ সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম-কে জনতার ভীড়ের মধ্যে পদব্রজে খালিদ ইবনুল ওয়ালীদ (রাঃ)-এর শিবিরের সন্ধান করতে দেখি। আমি তখন উঠতি বয়সের যুবক। তাঁর নিকট এক মদ্যপায়ীকে উপস্থিত করা হলে তাঁর নির্দেশে লোকজন তাকে তাদের হাতের নিকট সহজলভ্য জিনিস দ্বারা প্রহার করে। আর রাসূলুল্লাহ সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম তার প্রতি ধূলা নিক্ষেপ করেন। আবূ বাকর (রাঃ)-এর সময় এক মদপায়ীকে উপস্থিত করা হলে তিনি লোকজনকে প্রশ্ন করেন যে, নবী সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম উক্ত ব্যক্তিকে কয়টি বেত্রাঘাত করেছেন? তারা চল্লিশ বার বেত্রাঘাতের কথা উল্লেখ করে। অতএব আবূ বাকর (রাঃ) চল্লিশটি বেত্রাঘাত করেন। উমার (রাঃ) খলীফাহ হলে খালিদ ইবনুল ওয়ালীদ (রাঃ) তাকে লিখে পাঠান যে, লোকজন মাদক গ্রহণের নিষেধাজ্ঞাকে উপেক্ষা করছে এবং হাদ্দ ও শাস্তির ভয়কে পরোয়া করছে না। উমার (রাঃ) বলেন, আপনার নিকট যারা আছে তাদের প্রশ্ন করুন। তার সঙ্গে ছিলেন সর্বাগ্রে ইসলাম গ্রহণকারী মুহাজিরগণ। তিনি তাদের নিকট প্রশ্ন করলে তারা আশিটি বেত্রাঘাত সম্পর্কে ঐকমত্য হন। বর্ণনাকারী বলেন, ‘আলী (রাঃ) বলেছেন, কোনো ব্যক্তি মাদক গ্রহণ করলে সে মিথ্যা কথা বলে। অতএব আমি মনে করি, তাকে মিথ্যা বলার শাস্তির মতই শাস্তি দেয়া উচিত।[1] হাসান।","حَدَّثَنَا الْحَسَنُ بْنُ عَلِيٍّ، حَدَّثَنَا عُثْمَانُ بْنُ عُمَرَ، حَدَّثَنَا أُسَامَةُ بْنُ زَيْدٍ، عَنِ الزُّهْرِيِّ، عَنْ عَبْدِ الرَّحْمَنِ بْنِ أَزْهَرَ، قَالَ رَأَيْتُ رَسُولَ اللَّهِ صلى الله عليه وسلم غَدَاةَ الْفَتْحِ وَأَنَا غُلاَمٌ شَابٌّ يَتَخَلَّلُ النَّاسَ يَسْأَلُ عَنْ مَنْزِلِ خَالِدِ بْنِ الْوَلِيدِ فَأُتِيَ بِشَارِبٍ فَأَمَرَهُمْ فَضَرَبُوهُ بِمَا فِي أَيْدِيهِمْ فَمِنْهُمْ مَنْ ضَرَبَهُ بِالسَّوْطِ وَمِنْهُمْ مَنْ ضَرَبَهُ بِعَصًا وَمِنْهُمْ مَنْ ضَرَبَهُ بِنَعْلِهِ وَحَثَى رَسُولُ اللَّهِ صلى الله عليه وسلم التُّرَابَ فَلَمَّا كَانَ أَبُو بَكْرٍ أُتِيَ بِشَارِبٍ فَسَأَلَهُمْ عَنْ ضَرْبِ النَّبِيِّ صلى الله عليه وسلم الَّذِي ضَرَبَهُ فَحَزَرُوهُ أَرْبَعِينَ فَضَرَبَ أَبُو بَكْرٍ أَرْبَعِينَ فَلَمَّا كَانَ عُمَرُ كَتَبَ إِلَيْهِ خَالِدُ بْنُ الْوَلِيدِ إِنَّ النَّاسَ قَدِ انْهَمَكُوا فِي الشُّرْبِ وَتَحَاقَرُوا الْحَدَّ وَالْعُقُوبَةَ ‏.‏ قَالَ هُمْ عِنْدَكَ فَسَلْهُمْ ‏.‏ وَعِنْدَهُ الْمُهَاجِرُونَ الأَوَّلُونَ فَسَأَلَهُمْ فَأَجْمَعُوا عَلَى أَنْ يَضْرِبَ ثَمَانِينَ ‏.‏ قَالَ وَقَالَ عَلِيٌّ إِنَّ الرَّجُلَ إِذَا شَرِبَ افْتَرَى فَأَرَى أَنْ يَجْعَلَهُ كَحَدِّ الْفِرْيَةِ ‏.‏ قَالَ أَبُو دَاوُدَ أَدْخَلَ عُقَيْلُ بْنُ خَالِدٍ بَيْنَ الزُّهْرِيِّ وَبَيْنَ ابْنِ الأَزْهَرِ فِي هَذَا الْحَدِيثِ عَبْدَ اللَّهِ بْنَ عَبْدِ الرَّحْمَنِ بْنِ الأَزْهَرِ عَنْ أَبِيهِ ‏.‏","Narrated AbdurRahman ibn Azhar: I saw the Messenger of Allah (ﷺ) on the morning of the conquest of Mecca when I was a young boy. He was walking among the people, seeking the camp of Khalid ibn al-Walid. A man who had drunk wine was brought (before him) and he ordered them (to beat him). So they beat him with what they had in their hands. Some struck him with whips, some with sticks and some with sandals. The Messenger of Allah (ﷺ) threw some dust on his face. When a man who had drunk wine was brought before AbuBakr, he asked them (i.e. the people) about the number of beatings which they gave him. They numbered it forty. So AbuBakr gave him forty lashes. When Umar came to power, Khalid ibn al-Walid wrote to him: The people have become addicted to drinking wine and they look down upon the prescribed punishment and its penalty. He said: They are with you, ask them. The immigrants who embraced Islam in the beginning were with him. He asked them and they agreed on the fact that (a drunkard) should be given eighty lashes. Ali said: When a man drinks wine, he tells lies. I, therefore, think that he should be prescribed punishment that is prescribed for telling lies.. Abu Dawud said: 'Uqail b. Khalid included in the chain of this tradition: \"Abd Allah b. Abd al-Rahman b. al-Azhar from his father\" between al-Zuhri and Ibn al-Azhar","","Hasan"],[4490,4490,4490,"। হাকীম ইবনু হিযাম (রাঃ) সূত্রে বর্ণিত। তিনি বলেন, রাসূলুল্লাহ সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম মসজিদের ভিতরে কিসাস গ্রহণ করতে, কবিতা আবৃত্তি করতে এবং হাদ্দ কার্যকর করতে নিষেধ করেছেন।[1] হাসান।","حَدَّثَنَا هِشَامُ بْنُ عَمَّارٍ، حَدَّثَنَا صَدَقَةُ، - يَعْنِي ابْنَ خَالِدٍ - حَدَّثَنَا الشُّعَيْثِيُّ، عَنْ زُفَرَ بْنِ وَثِيمَةَ، عَنْ حَكِيمِ بْنِ حِزَامٍ، أَنَّهُ قَالَ نَهَى رَسُولُ اللَّهِ صلى الله عليه وسلم أَنْ يُسْتَقَادَ فِي الْمَسْجِدِ وَأَنْ تُنْشَدَ فِيهِ الأَشْعَارُ وَأَنْ تُقَامَ فِيهِ الْحُدُودُ ‏.‏","Narrated Hakim ibn Hizam: The Messenger of Allah (ﷺ) forbade to take retaliation in the mosque, to recite verses in it and to inflict the prescribed punishments in it","","Hasan"],[4491,4491,4491,"। আবূ বুরদাহ (রাঃ) সূত্রে বর্ণিত। রাসূলুল্লাহ সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম বলতেনঃ আল্লাহর নির্ধারিত হাদ্দ ছাড়া কাউকে দশ বেত্রাঘাতের অধিক শাস্তি দেয়া যাবে না।[1] সহীহ।","حَدَّثَنَا قُتَيْبَةُ بْنُ سَعِيدٍ، حَدَّثَنَا اللَّيْثُ، عَنْ يَزِيدَ بْنِ أَبِي حَبِيبٍ، عَنْ بُكَيْرِ بْنِ عَبْدِ اللَّهِ بْنِ الأَشَجِّ، عَنْ سُلَيْمَانَ بْنِ يَسَارٍ، عَنْ عَبْدِ الرَّحْمَنِ بْنِ جَابِرِ بْنِ عَبْدِ اللَّهِ، عَنْ أَبِي بُرْدَةَ، أَنَّ رَسُولَ اللَّهِ صلى الله عليه وسلم قَالَ ‏ \"‏ لاَ يُجْلَدُ فَوْقَ عَشْرِ جَلَدَاتٍ إِلاَّ فِي حَدٍّ مِنْ حُدُودِ اللَّهِ عَزَّ وَجَلَّ ‏\"‏ ‏.‏","Abu Burdah reported the Messenger of Allah (ﷺ) as saying:No more than ten lashes are to be given, except in the case of one of the punishment prescribed by Allah, the Exalted","","Sahih"],[4492,4492,4492,"। আল বুরদাহ আল-আনসারী (রাঃ) সূত্রে বর্ণিত। তিনি বলেন, আমি রাসূলুল্লাহ সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম-কে বলতে শুনেছিঃ ... অতঃপর পূর্বোক্ত হাদীসের সমার্থবোধক হাদীস। আমি এটি সহীহ এবং যঈফেও পাইনি।","حَدَّثَنَا أَحْمَدُ بْنُ صَالِحٍ، حَدَّثَنَا ابْنُ وَهْبٍ، أَخْبَرَنِي عَمْرٌو، أَنَّ بُكَيْرَ بْنَ الأَشَجِّ، حَدَّثَهُ عَنْ سُلَيْمَانَ بْنِ يَسَارٍ، قَالَ حَدَّثَنِي عَبْدُ الرَّحْمَنِ بْنُ جَابِرٍ، أَنَّ أَبَاهُ، حَدَّثَهُ أَنَّهُ، سَمِعَ أَبَا بُرْدَةَ الأَنْصَارِيَّ، يَقُولُ سَمِعْتُ رَسُولَ اللَّهِ صلى الله عليه وسلم يَقُولُ فَذَكَرَ مَعْنَاهُ ‏.‏","The tradition mentioned above has also been transmitted by Abu Burdah al-Ansari through a different chain of narrators. This version has:I heard the Messenger of Allah (ﷺ) say. . . He then mentioned the tradition to the same effect","","Daif"],[4493,4493,4493,"। আবূ হুরাইরাহ (রাঃ) সূত্রে বর্ণিত। নবী সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম বলেনঃ তোমাদের কেউ প্রহার করার সময় যেন মুখমন্ডল থেকে বিরত থাকে।[1] সহীহ।","حَدَّثَنَا أَبُو كَامِلٍ، حَدَّثَنَا أَبُو عَوَانَةَ، عَنْ عُمَرَ، - يَعْنِي ابْنَ أَبِي سَلَمَةَ - عَنْ أَبِيهِ، عَنْ أَبِي هُرَيْرَةَ، عَنِ النَّبِيِّ صلى الله عليه وسلم قَالَ ‏ \"‏ إِذَا ضَرَبَ أَحَدُكُمْ فَلْيَتَّقِ الْوَجْهَ ‏\"‏ ‏.‏","Narrated AbuHurayrah: The Prophet (ﷺ) said: When one of you inflicts a beating, he should avoid striking the face","","Sahih"]];
